export type OrderStatus = 'pendente' | 'em_criacao' | 'aprovacao' | 'concluido' | 'cancelado';
export type PaymentStatus = 'pago' | 'parcial' | 'pendente';
export type InvitationCategory = 'Casamento' | '15 Anos' | 'Infantil' | 'Batizado' | 'Corporativo' | 'Bodas';

export interface InvitationTemplate {
  id: string;
  title: string;
  category: InvitationCategory;
  price: number;
  imageUrl: string;
  description: string;
  tags: string[];
  timesUsed: number;
}

export interface Order {
  id: string;
  clientName: string;
  clientWhatsapp: string;
  templateId?: string;
  templateTitle: string;
  category: InvitationCategory;
  quantity: number;
  totalValue: number;
  paidValue: number;
  eventDate: string;
  deadlineDate: string;
  status: OrderStatus;
  paymentStatus: PaymentStatus;
  notes?: string;
  createdAt: string;
}

import React from 'react';
import { DollarSign, Layers, PlusCircle, Sparkles, FolderHeart } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface NavbarProps {
  currentTab: 'dashboard' | 'orders' | 'templates';
  setCurrentTab: (tab: 'dashboard' | 'orders' | 'templates') => void;
  onOpenNewOrder: () => void;
  onOpenNewTemplate: () => void;
  pendingOrdersCount: number;
}

export function Navbar({
  currentTab,
  setCurrentTab,
  onOpenNewOrder,
  onOpenNewTemplate,
  pendingOrdersCount,
}: NavbarProps) {
  return (
    <header className="sticky top-0 z-30 w-full border-b border-[#201c18] bg-[#141210]/90 backdrop-blur-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between gap-4">
        {/* Brand / Logo */}
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setCurrentTab('dashboard')}>
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#f59e0b] to-[#e2725b] p-0.5 shadow-lg shadow-[#f59e0b]/20">
            <div className="w-full h-full bg-[#141210] rounded-[10px] flex items-center justify-center">
              <Sparkles className="w-5 h-5 text-[#f59e0b]" />
            </div>
          </div>
          <div>
            <div className="font-extrabold text-base tracking-tight text-[#f5f0e8] flex items-center gap-1.5">
              <span>Ateliê</span>
              <span className="text-[#f59e0b]">Convites</span>
            </div>
            <p className="text-[11px] text-[#f5f0e8]/50">Gestão de Ganhos & Encomendas</p>
          </div>
        </div>

        {/* Navegação Principal */}
        <nav className="hidden md:flex items-center gap-1 bg-[#201c18] p-1.5 rounded-xl border border-white/5">
          <button
            onClick={() => setCurrentTab('dashboard')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all ${
              currentTab === 'dashboard'
                ? 'bg-[#f59e0b] text-[#141210] shadow-md shadow-[#f59e0b]/20'
                : 'text-[#f5f0e8]/70 hover:text-[#f5f0e8] hover:bg-white/5'
            }`}
          >
            <DollarSign className="w-4 h-4" />
            <span>Meus Ganhos</span>
          </button>

          <button
            onClick={() => setCurrentTab('orders')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all relative ${
              currentTab === 'orders'
                ? 'bg-[#f59e0b] text-[#141210] shadow-md shadow-[#f59e0b]/20'
                : 'text-[#f5f0e8]/70 hover:text-[#f5f0e8] hover:bg-white/5'
            }`}
          >
            <Layers className="w-4 h-4" />
            <span>Pedidos & Prazos</span>
            {pendingOrdersCount > 0 && (
              <span
                className={`ml-1 text-[10px] px-1.5 py-0.2 rounded-full font-bold ${
                  currentTab === 'orders' ? 'bg-[#141210] text-[#f59e0b]' : 'bg-[#e2725b] text-white'
                }`}
              >
                {pendingOrdersCount}
              </span>
            )}
          </button>

          <button
            onClick={() => setCurrentTab('templates')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all ${
              currentTab === 'templates'
                ? 'bg-[#f59e0b] text-[#141210] shadow-md shadow-[#f59e0b]/20'
                : 'text-[#f5f0e8]/70 hover:text-[#f5f0e8] hover:bg-white/5'
            }`}
          >
            <FolderHeart className="w-4 h-4" />
            <span>Meus Modelos</span>
          </button>
        </nav>

        {/* Ações Rápidas */}
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={onOpenNewTemplate}
            className="border-[#f59e0b]/30 text-[#f5f0e8] hover:border-[#f59e0b] hover:bg-[#f59e0b]/10 text-xs hidden sm:flex items-center gap-1.5"
          >
            <PlusCircle className="w-3.5 h-3.5 text-[#f59e0b]" />
            <span>Novo Modelo</span>
          </Button>

          <Button
            size="sm"
            onClick={onOpenNewOrder}
            className="bg-gradient-to-r from-[#f59e0b] to-[#e2725b] hover:opacity-95 text-[#141210] font-bold shadow-md shadow-[#f59e0b]/20 text-xs flex items-center gap-1.5"
          >
            <PlusCircle className="w-3.5 h-3.5" />
            <span>Novo Pedido</span>
          </Button>
        </div>
      </div>

      {/* Navegação Mobile Inferior */}
      <div className="flex md:hidden border-t border-[#201c18] bg-[#141210] px-4 py-2 justify-around">
        <button
          onClick={() => setCurrentTab('dashboard')}
          className={`flex flex-col items-center text-[10px] gap-1 ${
            currentTab === 'dashboard' ? 'text-[#f59e0b] font-bold' : 'text-[#f5f0e8]/60'
          }`}
        >
          <DollarSign className="w-4 h-4" />
          <span>Ganhos</span>
        </button>

        <button
          onClick={() => setCurrentTab('orders')}
          className={`flex flex-col items-center text-[10px] gap-1 relative ${
            currentTab === 'orders' ? 'text-[#f59e0b] font-bold' : 'text-[#f5f0e8]/60'
          }`}
        >
          <Layers className="w-4 h-4" />
          <span>Pedidos</span>
          {pendingOrdersCount > 0 && (
            <span className="absolute -top-1 -right-2 bg-[#e2725b] text-white text-[9px] w-4 h-4 rounded-full flex items-center justify-center">
              {pendingOrdersCount}
            </span>
          )}
        </button>

        <button
          onClick={() => setCurrentTab('templates')}
          className={`flex flex-col items-center text-[10px] gap-1 ${
            currentTab === 'templates' ? 'text-[#f59e0b] font-bold' : 'text-[#f5f0e8]/60'
          }`}
        >
          <FolderHeart className="w-4 h-4" />
          <span>Modelos</span>
        </button>
      </div>
    </header>
  );
}

import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Search,
  Filter,
  Calendar,
  Phone,
  Clock,
  CheckCircle2,
  AlertCircle,
  FileText,
  DollarSign,
  Plus,
} from 'lucide-react';

interface OrdersManagerProps {
  orders: Order[];
  onUpdateStatus: (orderId: string, newStatus: OrderStatus) => void;
  onUpdatePayment: (orderId: string, newPaymentStatus: PaymentStatus, newPaidValue: number) => void;
  onOpenNewOrder: () => void;
}

export function OrdersManager({
  orders,
  onUpdateStatus,
  onUpdatePayment,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | OrderStatus>('all');

  const filteredOrders = orders.filter((order) => {
    const matchesSearch =
      order.clientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.category.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return (
          <Badge variant="outline" className="border-amber-500/40 text-amber-300 bg-amber-500/10">
            Aguardando Início
          </Badge>
        );
      case 'em_criacao':
        return (
          <Badge variant="outline" className="border-blue-500/40 text-blue-300 bg-blue-500/10">
            Em Criação
          </Badge>
        );
      case 'aprovacao':
        return (
          <Badge variant="outline" className="border-purple-500/40 text-purple-300 bg-purple-500/10">
            Em Aprovação
          </Badge>
        );
      case 'concluido':
        return (
          <Badge variant="success" className="bg-emerald-500/20 text-emerald-300 border-emerald-500/40">
            Entregue & Concluído
          </Badge>
        );
      case 'cancelado':
        return (
          <Badge variant="destructive" className="bg-rose-500/20 text-rose-300 border-rose-500/40">
            Cancelado
          </Badge>
        );
      default:
        return null;
    }
  };

  const getPaymentBadge = (status: PaymentStatus) => {
    switch (status) {
      case 'pago':
        return <span className="text-[11px] font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-md">Pago Integral</span>;
      case 'parcial':
        return <span className="text-[11px] font-bold text-[#f59e0b] bg-[#f59e0b]/10 px-2 py-0.5 rounded-md">Sinal Pago (50%)</span>;
      case 'pendente':
        return <span className="text-[11px] font-bold text-[#e2725b] bg-[#e2725b]/10 px-2 py-0.5 rounded-md">Pagamento Pendente</span>;
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header com busca e ações */}
      <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-[#f5f0e8] tracking-tight flex items-center gap-2">
            <span>Gestão de Pedidos e Prazos</span>
            <span className="text-xs font-normal text-[#f5f0e8]/50 bg-white/5 px-2.5 py-1 rounded-full">
              {orders.length} pedidos
            </span>
          </h2>
          <p className="text-xs text-[#f5f0e8]/60 mt-0.5">
            Acompanhe cada etapa de produção dos convites e nunca perca a data limite do cliente.
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-gradient-to-r from-[#f59e0b] to-[#e2725b] text-[#141210] font-bold shadow-lg shadow-[#f59e0b]/20"
        >
          <Plus className="w-4 h-4 mr-1.5" />
          <span>Cadastrar Novo Pedido</span>
        </Button>
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col md:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#f5f0e8]/40" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, modelo ou categoria..."
            className="pl-10 bg-[#201c18] border-white/10 text-xs text-[#f5f0e8]"
          />
        </div>

        {/* Botões de Filtro por Status */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          <button
            onClick={() => setStatusFilter('all')}
            className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'all'
                ? 'bg-[#f59e0b] text-[#141210]'
                : 'bg-[#201c18] text-[#f5f0e8]/70 hover:bg-white/5'
            }`}
          >
            Todos ({orders.length})
          </button>
          <button
            onClick={() => setStatusFilter('em_criacao')}
            className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'em_criacao'
                ? 'bg-[#f59e0b] text-[#141210]'
                : 'bg-[#201c18] text-[#f5f0e8]/70 hover:bg-white/5'
            }`}
          >
            Em Criação
          </button>
          <button
            onClick={() => setStatusFilter('aprovacao')}
            className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'aprovacao'
                ? 'bg-[#f59e0b] text-[#141210]'
                : 'bg-[#201c18] text-[#f5f0e8]/70 hover:bg-white/5'
            }`}
          >
            Em Aprovação
          </button>
          <button
            onClick={() => setStatusFilter('concluido')}
            className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'concluido'
                ? 'bg-[#f59e0b] text-[#141210]'
                : 'bg-[#201c18] text-[#f5f0e8]/70 hover:bg-white/5'
            }`}
          >
            Concluídos
          </button>
        </div>
      </div>

      {/* Lista de Pedidos */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-[#201c18]/50 border-dashed border-white/10 py-12 text-center">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-[#f59e0b]/10 text-[#f59e0b] mx-auto flex items-center justify-center">
              <FileText className="w-6 h-6" />
            </div>
            <h3 className="text-base font-bold text-[#f5f0e8]">Nenhum pedido encontrado</h3>
            <p className="text-xs text-[#f5f0e8]/60 max-w-sm mx-auto">
              Nenhum pedido corresponde aos filtros aplicados. Clique no botão abaixo para adicionar uma nova encomenda.
            </p>
            <Button size="sm" onClick={onOpenNewOrder} className="bg-[#f59e0b] text-[#141210] font-semibold mt-2">
              Criar Pedido Agora
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredOrders.map((order) => {
            const saldoDevedor = order.totalValue - order.paidValue;

            return (
              <Card
                key={order.id}
                className="bg-[#201c18] border-white/5 hover:border-[#f59e0b]/30 transition-all flex flex-col justify-between shadow-lg"
              >
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <div className="text-xs font-medium text-[#f59e0b] uppercase tracking-wider">
                        {order.category}
                      </div>
                      <CardTitle className="text-lg font-bold text-[#f5f0e8] mt-0.5">
                        {order.clientName}
                      </CardTitle>
                      <div className="text-xs text-[#f5f0e8]/60 mt-0.5 flex items-center gap-1.5">
                        <Phone className="w-3 h-3 text-[#f5f0e8]/40" />
                        <span>{order.clientWhatsapp || 'WhatsApp não informado'}</span>
                      </div>
                    </div>
                    {getStatusBadge(order.status)}
                  </div>
                </CardHeader>

                <CardContent className="space-y-4 text-xs">
                  {/* Modelo e Quantidade */}
                  <div className="p-3 rounded-xl bg-white/[0.02] border border-white/5 space-y-1">
                    <div className="flex items-center justify-between text-[#f5f0e8]">
                      <span className="font-semibold">{order.templateTitle}</span>
                      <span className="text-[#f59e0b] font-bold">{order.quantity} unidades</span>
                    </div>
                    {order.notes && (
                      <p className="text-[11px] text-[#f5f0e8]/60 italic mt-1 border-t border-white/5 pt-1">
                        "{order.notes}"
                      </p>
                    )}
                  </div>

                  {/* Datas do Evento e Prazo */}
                  <div className="grid grid-cols-2 gap-2 text-[11px]">
                    <div className="p-2.5 rounded-lg bg-white/[0.02] border border-white/5 flex items-center gap-2">
                      <Clock className="w-4 h-4 text-[#e2725b]" />
                      <div>
                        <div className="text-[#f5f0e8]/50">Prazo de Entrega</div>
                        <div className="font-semibold text-[#f5f0e8]">{order.deadlineDate}</div>
                      </div>
                    </div>

                    <div className="p-2.5 rounded-lg bg-white/[0.02] border border-white/5 flex items-center gap-2">
                      <Calendar className="w-4 h-4 text-[#f59e0b]" />
                      <div>
                        <div className="text-[#f5f0e8]/50">Data do Evento</div>
                        <div className="font-semibold text-[#f5f0e8]">{order.eventDate}</div>
                      </div>
                    </div>
                  </div>

                  {/* Valores & Pagamento */}
                  <div className="pt-2 border-t border-white/5 flex items-center justify-between">
                    <div>
                      <div className="flex items-center gap-2">
                        {getPaymentBadge(order.paymentStatus)}
                      </div>
                      <div className="text-[11px] text-[#f5f0e8]/60 mt-1">
                        Recebido: <span className="text-emerald-400 font-bold">R$ {order.paidValue}</span> / Total: R$ {order.totalValue}
                      </div>
                    </div>

                    <div className="text-right">
                      <div className="text-xs text-[#f5f0e8]/50">Saldo Restante</div>
                      <div className={`text-sm font-black ${saldoDevedor > 0 ? 'text-[#e2725b]' : 'text-emerald-400'}`}>
                        {saldoDevedor > 0 ? `R$ ${saldoDevedor}` : 'Quitado ✓'}
                      </div>
                    </div>
                  </div>

                  {/* Ações de Status Rápido */}
                  <div className="pt-2 flex items-center gap-2">
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateStatus(order.id, e.target.value as OrderStatus)}
                      className="bg-[#141210] border border-white/10 rounded-lg px-2.5 py-1.5 text-xs text-[#f5f0e8] flex-1 focus:outline-none focus:border-[#f59e0b]"
                    >
                      <option value="pendente">Aguardando Início</option>
                      <option value="em_criacao">Em Criação</option>
                      <option value="aprovacao">Em Aprovação</option>
                      <option value="concluido">Entregue (Concluído)</option>
                      <option value="cancelado">Cancelado</option>
                    </select>

                    {saldoDevedor > 0 && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => onUpdatePayment(order.id, 'pago', order.totalValue)}
                        className="text-[11px] h-8 border-emerald-500/40 text-emerald-400 hover:bg-emerald-500/10"
                        title="Marcar pedido como 100% pago"
                      >
                        <DollarSign className="w-3 h-3 mr-1" />
                        Quitar Saldo
                      </Button>
                    )}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Sparkles,
  Plus,
  Search,
  Tag,
  DollarSign,
  TrendingUp,
  Image as ImageIcon,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOpenNewTemplate: () => void;
  onSelectTemplateToOrder: (template: InvitationTemplate) => void;
}

export function TemplatesCatalog({
  templates,
  onOpenNewTemplate,
  onSelectTemplateToOrder,
}: TemplatesCatalogProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');

  const categories: ('all' | InvitationCategory)[] = [
    'all',
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
  ];

  const filteredTemplates = templates.filter((item) => {
    const matchesCategory = selectedCategory === 'all' || item.category === selectedCategory;
    const matchesSearch =
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.tags.some((t) => t.toLowerCase().includes(searchTerm.toLowerCase()));

    return matchesCategory && matchesSearch;
  });

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-[#f5f0e8] tracking-tight flex items-center gap-2">
            <span>Meus Modelos de Convites</span>
            <span className="text-xs font-normal text-[#f5f0e8]/50 bg-white/5 px-2.5 py-1 rounded-full">
              {templates.length} modelos cadastrados
            </span>
          </h2>
          <p className="text-xs text-[#f5f0e8]/60 mt-0.5">
            Seu portfólio de designs exclusivos. Apresente aos clientes e crie pedidos em 1 clique!
          </p>
        </div>

        <Button
          onClick={onOpenNewTemplate}
          className="bg-gradient-to-r from-[#f59e0b] to-[#e2725b] text-[#141210] font-bold shadow-lg shadow-[#f59e0b]/20"
        >
          <Plus className="w-4 h-4 mr-1.5" />
          <span>Cadastrar Novo Modelo</span>
        </Button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col md:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#f5f0e8]/40" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar modelo por nome, tag ou estilo..."
            className="pl-10 bg-[#201c18] border-white/10 text-xs text-[#f5f0e8]"
          />
        </div>

        {/* Categorias Pills */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#f59e0b] text-[#141210]'
                  : 'bg-[#201c18] text-[#f5f0e8]/70 hover:bg-white/5'
              }`}
            >
              {cat === 'all' ? 'Todos os Estilos' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos de Convite */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-[#201c18]/50 border-dashed border-white/10 py-12 text-center">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-[#f59e0b]/10 text-[#f59e0b] mx-auto flex items-center justify-center">
              <ImageIcon className="w-6 h-6" />
            </div>
            <h3 className="text-base font-bold text-[#f5f0e8]">Nenhum modelo nesta categoria</h3>
