}

import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { X, Check } from 'lucide-react';

interface NewOrderModalProps {
  isOpen: boolean;
  onClose: () => void;
  templates: InvitationTemplate[];
  preSelectedTemplate?: InvitationTemplate | null;
  onSaveOrder: (newOrder: Order) => void;
}

export function NewOrderModal({
  isOpen,
  onClose,
  templates,
  preSelectedTemplate,
  onSaveOrder,
}: NewOrderModalProps) {
  if (!isOpen) return null;

  const [clientName, setClientName] = useState('');
  const [clientWhatsapp, setClientWhatsapp] = useState('');
  const [selectedTemplateId, setSelectedTemplateId] = useState(
    preSelectedTemplate?.id || (templates[0]?.id ?? '')
  );
  const [category, setCategory] = useState<InvitationCategory>(
    preSelectedTemplate?.category || 'Casamento'
  );
  const [quantity, setQuantity] = useState(100);
  const [totalValue, setTotalValue] = useState(preSelectedTemplate ? preSelectedTemplate.price * 2.5 : 850);
  const [paidValue, setPaidValue] = useState(425);
  const [deadlineDate, setDeadlineDate] = useState('2025-06-15');
  const [eventDate, setEventDate] = useState('2025-07-20');
  const [notes, setNotes] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!clientName.trim()) {
      alert('Por favor, informe o nome do cliente ou noivos.');
      return;
    }

    const templateObj = templates.find((t) => t.id === selectedTemplateId);

    const paymentStatus =
      paidValue >= totalValue ? 'pago' : paidValue > 0 ? 'parcial' : 'pendente';

    const newOrder: Order = {
      id: `ord-${Date.now()}`,
      clientName,
      clientWhatsapp,
      templateId: selectedTemplateId,
      templateTitle: templateObj?.title || 'Modelo Personalizado Exclusivo',
      category: templateObj?.category || category,
      quantity: Number(quantity) || 1,
      totalValue: Number(totalValue) || 0,
      paidValue: Number(paidValue) || 0,
      eventDate,
      deadlineDate,
      status: 'em_criacao',
      paymentStatus,
      notes,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSaveOrder(newOrder);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-xl w-full bg-[#1c1815] border-[#f59e0b]/30 shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
        <CardHeader className="border-b border-white/5 flex flex-row items-center justify-between pb-4">
          <div>
            <CardTitle className="text-lg text-[#f5f0e8] font-bold">
              Novo Pedido de Convite
            </CardTitle>
            <p className="text-xs text-[#f5f0e8]/60 mt-0.5">
              Registre a encomenda, valor contratado e prazos de entrega
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-lg hover:bg-white/10 text-[#f5f0e8]/70 hover:text-white"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        <CardContent className="overflow-y-auto p-6 space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4 text-xs">
            {/* Nome do Cliente e Contato */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Nome do Cliente / Casal *
                </label>
                <Input
                  required
                  placeholder="Ex: Amanda & Thiago"
                  value={clientName}
                  onChange={(e) => setClientName(e.target.value)}
                  className="bg-[#141210] border-white/10 text-[#f5f0e8]"
                />
              </div>

              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  WhatsApp de Contato
                </label>
                <Input
                  placeholder="(11) 99999-9999"
                  value={clientWhatsapp}
                  onChange={(e) => setClientWhatsapp(e.target.value)}
                  className="bg-[#141210] border-white/10 text-[#f5f0e8]"
                />
              </div>
            </div>

            {/* Modelo Escolhido */}
            <div>
              <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                Modelo de Convite Vinculado
              </label>
              <select
                value={selectedTemplateId}
                onChange={(e) => {
                  setSelectedTemplateId(e.target.value);
                  const found = templates.find((t) => t.id === e.target.value);
                  if (found) {
                    setCategory(found.category);
                    setTotalValue(found.price * 2.5);
                    setPaidValue(found.price * 1.25);
                  }
                }}
                className="w-full h-10 px-3 rounded-xl bg-[#141210] border border-white/10 text-xs text-[#f5f0e8] focus:outline-none focus:border-[#f59e0b]"
              >
                {templates.map((tpl) => (
                  <option key={tpl.id} value={tpl.id}>
                    {tpl.title} — {tpl.category} (R$ {tpl.price})
                  </option>
                ))}
              </select>
            </div>

            {/* Quantidade e Prazos */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Quantidade (unid.)
                </label>
                <Input
                  type="number"
                  min="1"
                  value={quantity}
                  onChange={(e) => setQuantity(Number(e.target.value))}
                  className="bg-[#141210] border-white/10 text-[#f5f0e8]"
                />
              </div>

              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Prazo de Entrega
                </label>
                <Input
                  type="date"
                  value={deadlineDate}
                  onChange={(e) => setDeadlineDate(e.target.value)}
                  className="bg-[#141210] border-white/10 text-[#f5f0e8]"
                />
              </div>

              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Data do Evento
                </label>
                <Input
                  type="date"
                  value={eventDate}
                  onChange={(e) => setEventDate(e.target.value)}
                  className="bg-[#141210] border-white/10 text-[#f5f0e8]"
                />
              </div>
            </div>

            {/* Valores Financeiros */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3.5 rounded-xl bg-white/[0.02] border border-white/5">
              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Valor Total do Pedido (R$) *
                </label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={totalValue}
                  onChange={(e) => setTotalValue(Number(e.target.value))}
                  className="bg-[#141210] border-white/10 text-emerald-400 font-bold"
                />
              </div>

              <div>
                <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                  Valor Já Pago / Sinal (R$)
                </label>
                <Input
                  type="number"
                  step="0.01"
                  value={paidValue}
                  onChange={(e) => setPaidValue(Number(e.target.value))}
                  className="bg-[#141210] border-white/10 text-[#f59e0b] font-bold"
                />
              </div>
            </div>

            {/* Observações */}
            <div>
              <label className="block text-[#f5f0e8]/80 mb-1 font-semibold">
                Detalhes de Acabamento & Observações
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Fita terracota nº 3, papel linho 250g, monograma dourado..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="w-full p-2.5 rounded-xl bg-[#141210] border border-white/10 text-xs text-[#f5f0e8] focus:outline-none focus:border-[#f59e0b]"
              />
            </div>

            {/* Botões */}
            <div className="pt-2 flex items-center justify-end gap-2">
              <Button type="button" variant="ghost" onClick={onClose} className="text-[#f5f0e8]/70">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-gradient-to-r from-[#f59e0b] to-[#e2725b] text-[#141210] font-bold shadow-lg shadow-[#f59e0b]/20"
              >
                <Check className="w-4 h-4 mr-1.5" />
                Salvar Pedido
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from 'react';
