            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'concluido'
                ? 'bg-pink-400 text-white shadow-sm'
                : 'bg-white text-pink-800/70 border border-pink-100 hover:bg-pink-50'
            }`}
          >
            Entregues
          </button>
        </div>
      </div>

      {/* Grade de Pedidos */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-white border-dashed border-pink-200 py-12 text-center rounded-2xl shadow-sm">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-pink-50 text-pink-400 mx-auto flex items-center justify-center">
              <Heart className="w-6 h-6 fill-pink-200" />
            </div>
            <h3 className="text-base font-bold text-pink-950">Nenhum pedido encontrado</h3>
            <p className="text-xs text-pink-900/60 max-w-sm mx-auto">
              Nenhuma encomenda corresponde ao filtro selecionado. Que tal cadastrar um novo pedido?
            </p>
            <Button
              size="sm"
              onClick={onOpenNewOrder}
              className="bg-pink-400 hover:bg-pink-500 text-white font-semibold rounded-xl text-xs"
            >
              Criar Pedido Agora
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredOrders.map((order) => {
            const saldoDevedor = Math.max(0, order.totalValue - order.paidValue);

            return (
              <Card
                key={order.id}
                className="bg-white border-pink-100 hover:border-pink-300 transition-all flex flex-col justify-between shadow-[0_2px_15px_rgba(244,114,182,0.06)] rounded-2xl"
              >
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <div className="text-xs text-pink-400 font-semibold uppercase tracking-wider">
                        {order.category}
                      </div>
                      <CardTitle className="text-base text-pink-950 mt-0.5 font-bold">
                        {order.clientName}
                      </CardTitle>
                      <p className="text-xs text-pink-900/60 font-medium">
                        {order.templateTitle}
                      </p>
                    </div>
                    {getStatusBadge(order.status)}
                  </div>
                </CardHeader>

                <CardContent className="space-y-4 pt-0">
                  {/* Informações detalhadas */}
                  <div className="grid grid-cols-2 gap-2 text-xs p-3 rounded-xl bg-pink-50/50 border border-pink-100/60">
                    <div className="space-y-1">
                      <div className="flex items-center gap-1.5 text-pink-900/60 text-[11px] font-medium">
                        <Calendar className="w-3.5 h-3.5 text-pink-400" />
                        <span>Entrega:</span>
                      </div>
                      <span className="font-bold text-pink-950">{order.deadlineDate}</span>
                    </div>

                    <div className="space-y-1">
                      <div className="flex items-center gap-1.5 text-pink-900/60 text-[11px] font-medium">
                        <Clock className="w-3.5 h-3.5 text-pink-400" />
                        <span>Evento:</span>
                      </div>
                      <span className="font-bold text-pink-950">{order.eventDate}</span>
                    </div>

                    <div className="space-y-1 pt-1">
                      <span className="text-pink-900/60 text-[11px] font-medium block">Quantidade:</span>
                      <span className="font-bold text-pink-950">{order.quantity} convites</span>
                    </div>

                    <div className="space-y-1 pt-1">
                      <span className="text-pink-900/60 text-[11px] font-medium block">WhatsApp:</span>
                      <a
                        href={`https://wa.me/55${order.clientWhatsapp?.replace(/\D/g, '')}`}
                        target="_blank"
                        rel="noreferrer"
                        className="font-bold text-pink-600 hover:underline flex items-center gap-1 text-[11px]"
                      >
                        <Phone className="w-3 h-3" />
                        {order.clientWhatsapp || 'Não inf.'}
                      </a>
                    </div>
                  </div>

                  {/* Financeiro do Pedido */}
                  <div className="p-3 rounded-xl bg-white border border-pink-100 space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-xs text-pink-900/70 font-medium">Financeiro</span>
                      {getPaymentBadge(order.paymentStatus)}
                    </div>

                    <div className="flex items-center justify-between text-xs pt-1 border-t border-pink-50">
                      <div>
                        <span className="text-[11px] text-pink-900/50 block">Valor Total:</span>
                        <span className="font-bold text-pink-950 text-sm">
                          R$ {order.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>

                      <div className="text-right">
                        <span className="text-[11px] text-pink-900/50 block">Recebido:</span>
                        <span className="font-bold text-emerald-600">
                          R$ {order.paidValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>

                      <div className="text-right">
                        <span className="text-[11px] text-pink-900/50 block">Falta receber:</span>
                        <span className={`font-bold ${saldoDevedor > 0 ? 'text-rose-500' : 'text-emerald-600'}`}>
                          R$ {saldoDevedor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>
                    </div>
                  </div>

                  {order.notes && (
                    <p className="text-[11px] text-pink-900/70 italic bg-pink-50/30 p-2 rounded-lg border border-pink-100/50">
                      "{order.notes}"
                    </p>
                  )}

                  {/* Ações de Status e Quitação */}
                  <div className="pt-2 border-t border-pink-100 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-1.5">
                      <span className="text-[11px] text-pink-900/60 font-medium">Mudar etapa:</span>
                      <select
                        value={order.status}
                        onChange={(e) => onUpdateStatus(order.id, e.target.value as OrderStatus)}
