                      >
                        <option value="pendente">Aguardando Início</option>
                        <option value="em_criacao">Em Confecção</option>
                        <option value="aprovacao">Em Aprovação</option>
                        <option value="concluido">Entregue</option>
                        <option value="cancelado">Cancelado</option>
                      </select>
                    </div>

                    {saldoDevedor > 0 && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => onUpdatePayment(order.id, 'pago', order.totalValue)}
                        className="h-8 text-[11px] border-emerald-300 text-emerald-700 hover:bg-emerald-50 rounded-lg"
                      >
                        Quitar Restante (R$ {saldoDevedor})
                      </Button>
                    )}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

