import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { X, Check, Sparkles } from 'lucide-react';

interface NewTemplateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSaveTemplate: (newTemplate: InvitationTemplate) => void;
}

export function NewTemplateModal({
  isOpen,
  onClose,
  onSaveTemplate,
}: NewTemplateModalProps) {
  if (!isOpen) return null;

  const [title, setTitle] = useState('');
  const [category, setCategory] = useState<InvitationCategory>('Casamento');
  const [price, setPrice] = useState(240);
  const [imageUrl, setImageUrl] = useState(
    'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80'
  );
  const [description, setDescription] = useState('');
  const [tagsInput, setTagsInput] = useState('Papel Algodão, Foil Rosé, Floral');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      alert('Por favor, informe o título do modelo.');
      return;
    }

    const tags = tagsInput
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);

    const newTemplate: InvitationTemplate = {
      id: `tmpl-${Date.now()}`,
      title,
      category,
      price: Number(price) || 0,
      imageUrl: imageUrl.trim() || 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80',
      description,
      tags,
      timesUsed: 0,
    };

    onSaveTemplate(newTemplate);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-pink-950/40 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-lg w-full bg-white border-pink-200 shadow-2xl rounded-3xl overflow-hidden max-h-[90vh] flex flex-col">
        <CardHeader className="border-b border-pink-100 flex flex-row items-center justify-between pb-4 bg-pink-50/50">
          <div>
            <CardTitle className="text-lg text-pink-950 font-bold flex items-center gap-1.5">
              <Sparkles className="w-4 h-4 text-pink-400" />
              <span>Cadastrar Modelo de Convite</span>
            </CardTitle>
            <p className="text-xs text-pink-900/60 font-medium mt-0.5">
              Adicione fotos e especificações ao seu portfólio delicado
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-pink-100 text-pink-600 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        <CardContent className="overflow-y-auto p-6 space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4 text-xs">
            <div>
              <label className="block text-pink-950 mb-1 font-semibold">
                Título do Modelo *
              </label>
              <Input
                required
                placeholder="Ex: Convite Romântico Floral Rosé Gold"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="bg-pink-50/40 border-pink-200 text-pink-950 rounded-xl"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-pink-950 mb-1 font-semibold">
                  Categoria
                </label>
                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value as InvitationCategory)}
                  className="w-full h-10 px-3 rounded-xl bg-pink-50/40 border border-pink-200 text-xs text-pink-950 font-medium focus:outline-none focus:ring-1 focus:ring-pink-400"
                >
                  <option value="Casamento">Casamento</option>
                  <option value="15 Anos">15 Anos</option>
                  <option value="Infantil">Infantil</option>
                  <option value="Batizado">Batizado</option>
                  <option value="Corporativo">Corporativo</option>
                  <option value="Bodas">Bodas</option>
                </select>
              </div>

              <div>
                <label className="block text-pink-950 mb-1 font-semibold">
                  Preço Base Sugerido (R$) *
                </label>
                <Input
                  type="number"
                  step="1"
                  required
                  value={price}
                  onChange={(e) => setPrice(Number(e.target.value))}
                  className="bg-pink-50/40 border-pink-200 text-pink-700 font-bold rounded-xl"
                />
              </div>
            </div>

            <div>
              <label className="block text-pink-950 mb-1 font-semibold">
                Link da Foto de Prévia (URL)
              </label>
              <Input
                placeholder="https://exemplo.com/foto-do-convite.jpg"
                value={imageUrl}
                onChange={(e) => setImageUrl(e.target.value)}
                className="bg-pink-50/40 border-pink-200 text-pink-950 rounded-xl"
              />
            </div>

            <div>
              <label className="block text-pink-950 mb-1 font-semibold">
                Descrição do Acabamento e Papel
              </label>
              <textarea
                rows={3}
                placeholder="Ex: Papel vegetal translúcido 180g, lacre de cera rosa perolado e ramos secos..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full p-2.5 rounded-xl bg-pink-50/40 border border-pink-200 text-xs text-pink-950 focus:outline-none focus:ring-1 focus:ring-pink-400"
              />
            </div>

            <div>
              <label className="block text-pink-950 mb-1 font-semibold">
                Tags (separadas por vírgula)
              </label>
              <Input
                placeholder="Floral, Rosé, Delicado, Fita de Seda"
                value={tagsInput}
                onChange={(e) => setTagsInput(e.target.value)}
                className="bg-pink-50/40 border-pink-200 text-pink-950 rounded-xl"
              />
            </div>

            <div className="pt-2 flex items-center justify-end gap-2">
              <Button type="button" variant="ghost" onClick={onClose} className="text-pink-800 rounded-xl">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-gradient-to-r from-pink-400 to-rose-400 hover:from-pink-500 hover:to-rose-500 text-white font-semibold rounded-xl shadow-md shadow-pink-200"
              >
                <Check className="w-4 h-4 mr-1.5" />
                Salvar Modelo
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

