import React, { useState, useEffect } from 'react';
import { initialOrders, initialTemplates } from '@/data/initialData';
import { Order, InvitationTemplate, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { OrdersManager } from '@/components/OrdersManager';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';

export default function App() {
  // Estado com persistência em localStorage para guardar pedidos e modelos
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('atelie_orders');
    return saved ? JSON.parse(saved) : initialOrders;
  });

  const [templates, setTemplates] = useState<InvitationTemplate[]>(() => {
    const saved = localStorage.getItem('atelie_templates');
    return saved ? JSON.parse(saved) : initialTemplates;
  });

  // Salvar no localStorage sempre que houver alteração
  useEffect(() => {
    localStorage.setItem('atelie_orders', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('atelie_templates', JSON.stringify(templates));
  }, [templates]);

  // Aba ativa: 'dashboard' | 'orders' | 'templates'
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('dashboard');

  // Modais
  const [isOrderModalOpen, setIsOrderModalOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  // Manipulação de Pedidos
  const handleUpdateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
    );
  };

  const handleUpdatePayment = (
    orderId: string,
    newPaymentStatus: PaymentStatus,
    newPaidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId
          ? { ...order, paymentStatus: newPaymentStatus, paidValue: newPaidValue }
          : order
      )
    );
  };

  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);

    // Incrementar contagem de uso do modelo
    if (newOrder.templateId) {
      setTemplates((prev) =>
        prev.map((t) =>
          t.id === newOrder.templateId ? { ...t, timesUsed: (t.timesUsed || 0) + 1 } : t
        )
      );
    }
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleSelectTemplateToOrder = (template: InvitationTemplate) => {
    setSelectedTemplateForOrder(template);
    setIsOrderModalOpen(true);
  };

  const pendingOrdersCount = orders.filter(
    (o) => o.status !== 'concluido' && o.status !== 'cancelado'
  ).length;

  return (
    <div className="min-h-screen bg-[#141210] text-[#f5f0e8] flex flex-col selection:bg-[#f59e0b]/30 selection:text-[#f59e0b]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        onOpenNewOrder={() => {
          setSelectedTemplateForOrder(null);
          setIsOrderModalOpen(true);
        }}
        onOpenNewTemplate={() => setIsTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal Dinâmico */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdatePayment}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenNewTemplate={() => setIsTemplateModalOpen(true)}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
          />
        )}
      </main>

      {/* Footer Minimalista */}
      <footer className="border-t border-[#201c18] py-6 text-center text-xs text-[#f5f0e8]/40">
        <p>Ateliê de Convites & Finanças — Organização, Gestão de Prazos e Portfólio Criativo</p>
      </footer>

      {/* Modais */}
      <NewOrderModal
        isOpen={isOrderModalOpen}
        onClose={() => setIsOrderModalOpen(false)}
        templates={templates}
        preSelectedTemplate={selectedTemplateForOrder}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isTemplateModalOpen}
        onClose={() => setIsTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

