import React from 'react';
import { Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Heart,
  DollarSign,
  Clock,
  CheckCircle2,
  Calendar,
  Sparkles,
  ShoppingBag,
  ArrowRight,
} from 'lucide-react';

interface EarningsDashboardProps {
  orders: Order[];
  onOpenNewOrder: () => void;
}

export function EarningsDashboard({ orders, onOpenNewOrder }: EarningsDashboardProps) {
  // Cálculos estritamente REAIS baseados apenas nos pedidos cadastrados
  const totalRecebido = (orders || []).reduce((acc, order) => acc + (order?.paidValue || 0), 0);
  const totalFaturado = (orders || []).reduce((acc, order) => acc + (order?.totalValue || 0), 0);
  const totalPendente = Math.max(0, totalFaturado - totalRecebido);

  const concluidos = (orders || []).filter((o) => o?.status === 'concluido').length;
  const emProducao = (orders || []).filter((o) => o?.status !== 'concluido' && o?.status !== 'cancelado').length;
  const totalQuantidadeConvites = (orders || []).reduce((acc, o) => acc + (o?.quantity || 0), 0);

  // Agrupamento estritamente real dos pedidos por Categoria existente
  const categoryCounts = (orders || []).reduce<Record<string, { count: number; total: number }>>((acc, order) => {
    const cat = order?.category || 'Geral';
    if (!acc[cat]) {
      acc[cat] = { count: 0, total: 0 };
    }
    acc[cat].count += 1;
    acc[cat].total += order?.totalValue || 0;
    return acc;
  }, {});

  const categoriesList = Object.entries(categoryCounts);

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Banner Principal Fofo e Acolhedor */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-pink-100 via-rose-50 to-pink-50 border border-pink-200/80 p-6 md:p-8 shadow-[0_4px_25px_rgba(244,114,182,0.1)]">
        <div className="relative z-10 max-w-2xl space-y-3">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/90 border border-pink-200 text-pink-600 text-xs font-semibold shadow-sm">
            <Heart className="w-3.5 h-3.5 fill-pink-400 text-pink-400" />
            <span>Finanças Reais do Seu Ateliê</span>
          </div>

          <h1 className="text-2xl md:text-3xl font-extrabold text-pink-950 tracking-tight">
            Você já recebeu um total de{' '}
            <span className="text-pink-600 font-black">
              R$ {totalRecebido.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </span>
          </h1>

          <p className="text-xs sm:text-sm text-pink-900/70 leading-relaxed font-medium">
            Você tem <strong className="text-pink-950">{emProducao} pedidos ativos</strong> para produzir.
            {totalPendente > 0 ? (
              <>
                {' '}Ainda restam{' '}
                <strong className="text-rose-600">
                  R$ {totalPendente.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </strong>{' '}
                a serem recebidos conforme os convites forem entregues.
              </>
            ) : (
              ' Todos os pedidos cadastrados estão totalmente quitados!'
            )}
          </p>

          <div className="pt-2">
            <Button
              onClick={onOpenNewOrder}
              size="sm"
              className="bg-gradient-to-r from-pink-400 to-rose-400 hover:from-pink-500 hover:to-rose-500 text-white font-semibold rounded-xl text-xs shadow-md shadow-pink-200 gap-1.5"
            >
              <Heart className="w-3.5 h-3.5 fill-white" />
              <span>Registrar Nova Encomenda</span>
            </Button>
          </div>
        </div>

        {/* Efeito decorativo sutil */}
        <div className="absolute right-4 -bottom-6 w-36 h-36 bg-pink-200/40 rounded-full blur-2xl pointer-events-none" />
      </div>

      {/* 4 Cards de Métricas Reais */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Card 1: Já Recebido */}
        <Card className="bg-white border-pink-100 hover:border-pink-300 transition-all shadow-[0_2px_12px_rgba(244,114,182,0.06)] rounded-2xl">
          <CardHeader className="pb-2 flex flex-row items-center justify-between">
            <span className="text-xs font-semibold text-pink-900/60 uppercase tracking-wider">Total Já Recebido</span>
            <div className="w-8 h-8 rounded-xl bg-pink-50 text-pink-500 flex items-center justify-center">
              <DollarSign className="w-4 h-4" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black text-pink-600">
              R$ {totalRecebido.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </div>
            <p className="mt-1 text-[11px] text-pink-900/60 font-medium">
              Dinheiro que já entrou no seu bolso
            </p>
          </CardContent>
        </Card>

        {/* Card 2: A Receber */}
        <Card className="bg-white border-pink-100 hover:border-rose-300 transition-all shadow-[0_2px_12px_rgba(244,114,182,0.06)] rounded-2xl">
          <CardHeader className="pb-2 flex flex-row items-center justify-between">
            <span className="text-xs font-semibold text-pink-900/60 uppercase tracking-wider">A Receber</span>
            <div className="w-8 h-8 rounded-xl bg-rose-50 text-rose-500 flex items-center justify-center">
              <Clock className="w-4 h-4" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black text-rose-500">
              R$ {totalPendente.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </div>
            <p className="mt-1 text-[11px] text-pink-900/60 font-medium">
              Saldos restantes dos pedidos em aberto
            </p>
          </CardContent>
        </Card>

        {/* Card 3: Valor Total de Contratos */}
        <Card className="bg-white border-pink-100 hover:border-pink-300 transition-all shadow-[0_2px_12px_rgba(244,114,182,0.06)] rounded-2xl">
          <CardHeader className="pb-2 flex flex-row items-center justify-between">
            <span className="text-xs font-semibold text-pink-900/60 uppercase tracking-wider">Valor Contratado</span>
            <div className="w-8 h-8 rounded-xl bg-purple-50 text-purple-500 flex items-center justify-center">
              <ShoppingBag className="w-4 h-4" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black text-purple-600">
              R$ {totalFaturado.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </div>
            <p className="mt-1 text-[11px] text-pink-900/60 font-medium">
              Soma total de todos os {orders.length} pedidos
            </p>
          </CardContent>
        </Card>

        {/* Card 4: Convites e Produção */}
        <Card className="bg-white border-pink-100 hover:border-pink-300 transition-all shadow-[0_2px_12px_rgba(244,114,182,0.06)] rounded-2xl">
          <CardHeader className="pb-2 flex flex-row items-center justify-between">
            <span className="text-xs font-semibold text-pink-900/60 uppercase tracking-wider">Convites Pedidos</span>
            <div className="w-8 h-8 rounded-xl bg-emerald-50 text-emerald-500 flex items-center justify-center">
              <CheckCircle2 className="w-4 h-4" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-black text-pink-950">
              {totalQuantidadeConvites} <span className="text-xs font-normal text-pink-900/60">unidades</span>
            </div>
            <p className="mt-1 text-[11px] text-pink-900/60 font-medium">
              {concluidos} pedidos entregues / {emProducao} em confecção
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Seção 2: Distribuição Real por Categoria + Lista de Pedidos Atuais */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Distribuição por Categoria Real */}
        <Card className="bg-white border-pink-100 shadow-[0_2px_15px_rgba(244,114,182,0.05)] rounded-2xl">
          <CardHeader className="pb-3">
            <CardTitle className="text-base text-pink-950 flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-pink-500" />
              <span>Ganhos por Tipo de Convite</span>
            </CardTitle>
            <p className="text-xs text-pink-900/60 font-medium">
              Divisão real dos seus pedidos cadastrados
            </p>
          </CardHeader>
          <CardContent className="space-y-3">
            {categoriesList.length === 0 ? (
              <p className="text-xs text-pink-900/50 italic py-4 text-center">Nenhum pedido cadastrado ainda.</p>
            ) : (
              categoriesList.map(([cat, data]) => {
                const percent = totalFaturado > 0 ? Math.round((data.total / totalFaturado) * 100) : 0;
                return (
                  <div key={cat} className="space-y-1.5 p-2.5 rounded-xl bg-pink-50/40 border border-pink-100/60">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-pink-950">{cat}</span>
                      <span className="font-bold text-pink-600">
                        R$ {data.total.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                    </div>
                    <div className="flex items-center justify-between text-[11px] text-pink-900/60">
                      <span>{data.count} {data.count === 1 ? 'pedido' : 'pedidos'}</span>
                      <span>{percent}% do faturamento</span>
                    </div>
                    {/* Barra de progresso real */}
                    <div className="w-full bg-pink-100 rounded-full h-1.5 overflow-hidden">
                      <div
                        className="bg-pink-400 h-1.5 rounded-full transition-all duration-500"
                        style={{ width: `${percent}%` }}
                      />
                    </div>
                  </div>
                );
              })
            )}
          </CardContent>
        </Card>

        {/* Lista dos Pedidos e Situação Financeira Real */}
        <Card className="lg:col-span-2 bg-white border-pink-100 shadow-[0_2px_15px_rgba(244,114,182,0.05)] rounded-2xl">
          <CardHeader className="pb-3 flex flex-row items-center justify-between">
            <div>
              <CardTitle className="text-base text-pink-950 flex items-center gap-2">
                <Calendar className="w-4 h-4 text-pink-500" />
                <span>Situação dos Pedidos Atuais</span>
              </CardTitle>
              <p className="text-xs text-pink-900/60 font-medium">
                Prazos e recebimentos de cada cliente
              </p>
            </div>
            <Badge className="bg-pink-100 text-pink-700 border-none font-semibold text-xs">
              {orders.length} cadastrados
            </Badge>
          </CardHeader>
          <CardContent className="space-y-2.5">
            {orders.length === 0 ? (
              <p className="text-xs text-pink-900/50 italic py-6 text-center">Nenhum pedido registrado.</p>
            ) : (
              orders.slice(0, 5).map((order) => {
                const pendente = order.totalValue - order.paidValue;
                const estaPago = pendente <= 0;

                return (
                  <div
                    key={order.id}
                    className="flex flex-col sm:flex-row sm:items-center justify-between p-3 rounded-xl bg-pink-50/30 hover:bg-pink-50/70 border border-pink-100/60 transition-all gap-2"
                  >
                    <div className="space-y-0.5">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-xs text-pink-950">{order.clientName}</span>
                        <span className="text-[10px] px-2 py-0.5 rounded-full bg-white text-pink-600 border border-pink-200 font-semibold">
                          {order.category}
                        </span>
                      </div>
                      <p className="text-[11px] text-pink-900/60 font-medium">
                        {order.templateTitle} • {order.quantity} unidades • Entrega: {order.deadlineDate}
                      </p>
                    </div>

                    <div className="flex items-center justify-between sm:justify-end gap-3 text-right">
                      <div>
                        <div className="text-xs font-bold text-pink-950">
                          R$ {order.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </div>
                        <div className="text-[11px] font-semibold">
                          {estaPago ? (
                            <span className="text-emerald-600">✓ Pago 100%</span>
                          ) : (
                            <span className="text-rose-500">
                              Resta R$ {pendente.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Search,
  Calendar,
  Phone,
  Clock,
  CheckCircle2,
  AlertCircle,
  FileText,
  DollarSign,
  Plus,
  Heart,
} from 'lucide-react';

interface OrdersManagerProps {
  orders: Order[];
  onUpdateStatus: (orderId: string, newStatus: OrderStatus) => void;
  onUpdatePayment: (orderId: string, newPaymentStatus: PaymentStatus, newPaidValue: number) => void;
  onOpenNewOrder: () => void;
}

export function OrdersManager({
  orders,
  onUpdateStatus,
  onUpdatePayment,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | OrderStatus>('all');

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.category?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return (
          <Badge className="bg-amber-100 text-amber-800 border-amber-200">
            Aguardando Início
          </Badge>
        );
      case 'em_criacao':
        return (
          <Badge className="bg-pink-100 text-pink-700 border-pink-200">
            Em Confecção
          </Badge>
        );
      case 'aprovacao':
        return (
          <Badge className="bg-purple-100 text-purple-700 border-purple-200">
            Em Aprovação
          </Badge>
        );
      case 'concluido':
        return (
          <Badge className="bg-emerald-100 text-emerald-700 border-emerald-200">
            Pronto & Entregue
          </Badge>
        );
      case 'cancelado':
        return (
          <Badge className="bg-rose-100 text-rose-700 border-rose-200">
            Cancelado
          </Badge>
        );
      default:
        return null;
    }
  };

  const getPaymentBadge = (status: PaymentStatus) => {
    switch (status) {
      case 'pago':
        return (
          <span className="text-[11px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2.5 py-0.5 rounded-full">
            Pago Integralmente
          </span>
        );
      case 'parcial':
        return (
          <span className="text-[11px] font-bold text-pink-700 bg-pink-50 border border-pink-200 px-2.5 py-0.5 rounded-full">
            Sinal Pago (50%)
          </span>
        );
      case 'pendente':
        return (
          <span className="text-[11px] font-bold text-rose-600 bg-rose-50 border border-rose-200 px-2.5 py-0.5 rounded-full">
            Pagamento Pendente
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Cabeçalho */}
      <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-pink-950 tracking-tight flex items-center gap-2">
            <span>Gestão dos Seus Pedidos</span>
            <span className="text-xs font-normal text-pink-700 bg-pink-100 px-2.5 py-0.5 rounded-full">
              {orders.length} pedidos
            </span>
          </h2>
          <p className="text-xs text-pink-900/60 font-medium mt-0.5">
            Organize cada cliente, etapas da criação e nunca perca o prazo de entrega.
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-gradient-to-r from-pink-400 to-rose-400 hover:from-pink-500 hover:to-rose-500 text-white font-semibold rounded-xl shadow-md shadow-pink-200 text-xs flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" />
          <span>Cadastrar Novo Pedido</span>
        </Button>
      </div>

      {/* Busca e Filtros Fofos */}
      <div className="flex flex-col md:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-pink-400" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, modelo ou categoria..."
            className="pl-10 bg-white border-pink-200 focus-visible:ring-pink-400 text-xs text-pink-950 placeholder:text-pink-900/40 rounded-xl"
          />
        </div>

        {/* Abas de Filtros */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          <button
            onClick={() => setStatusFilter('all')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'all'
                ? 'bg-pink-400 text-white shadow-sm'
                : 'bg-white text-pink-800/70 border border-pink-100 hover:bg-pink-50'
            }`}
          >
            Todos ({orders.length})
          </button>
          <button
            onClick={() => setStatusFilter('em_criacao')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'em_criacao'
                ? 'bg-pink-400 text-white shadow-sm'
                : 'bg-white text-pink-800/70 border border-pink-100 hover:bg-pink-50'
            }`}
          >
            Em Confecção
          </button>
          <button
            onClick={() => setStatusFilter('aprovacao')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'aprovacao'
                ? 'bg-pink-400 text-white shadow-sm'
                : 'bg-white text-pink-800/70 border border-pink-100 hover:bg-pink-50'
            }`}
          >
            Em Aprovação
          </button>
          <button
            onClick={() => setStatusFilter('concluido')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'concluido'
                ? 'bg-pink-400 text-white shadow-sm'
                : 'bg-white text-pink-800/70 border border-pink-100 hover:bg-pink-50'
            }`}
          >
            Entregues
          </button>
        </div>
      </div>

      {/* Grade de Pedidos */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-white border-dashed border-pink-200 py-12 text-center rounded-2xl shadow-sm">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-pink-50 text-pink-400 mx-auto flex items-center justify-center">
              <Heart className="w-6 h-6 fill-pink-200" />
            </div>
            <h3 className="text-base font-bold text-pink-950">Nenhum pedido encontrado</h3>
            <p className="text-xs text-pink-900/60 max-w-sm mx-auto">
              Nenhuma encomenda corresponde ao filtro selecionado. Que tal cadastrar um novo pedido?
            </p>
            <Button
              size="sm"
              onClick={onOpenNewOrder}
              className="bg-pink-400 hover:bg-pink-500 text-white font-semibold rounded-xl text-xs"
            >
              Criar Pedido Agora
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredOrders.map((order) => {
            const saldoDevedor = Math.max(0, order.totalValue - order.paidValue);

            return (
              <Card
                key={order.id}
                className="bg-white border-pink-100 hover:border-pink-300 transition-all flex flex-col justify-between shadow-[0_2px_15px_rgba(244,114,182,0.06)] rounded-2xl"
              >
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <div className="text-xs text-pink-400 font-semibold uppercase tracking-wider">
                        {order.category}
                      </div>
                      <CardTitle className="text-base text-pink-950 mt-0.5 font-bold">
                        {order.clientName}
                      </CardTitle>
                      <p className="text-xs text-pink-900/60 font-medium">
                        {order.templateTitle}
                      </p>
                    </div>
                    {getStatusBadge(order.status)}
                  </div>
                </CardHeader>

                <CardContent className="space-y-4 pt-0">
                  {/* Informações detalhadas */}
                  <div className="grid grid-cols-2 gap-2 text-xs p-3 rounded-xl bg-pink-50/50 border border-pink-100/60">
                    <div className="space-y-1">
                      <div className="flex items-center gap-1.5 text-pink-900/60 text-[11px] font-medium">
                        <Calendar className="w-3.5 h-3.5 text-pink-400" />
                        <span>Entrega:</span>
                      </div>
                      <span className="font-bold text-pink-950">{order.deadlineDate}</span>
                    </div>

                    <div className="space-y-1">
                      <div className="flex items-center gap-1.5 text-pink-900/60 text-[11px] font-medium">
                        <Clock className="w-3.5 h-3.5 text-pink-400" />
                        <span>Evento:</span>
                      </div>
                      <span className="font-bold text-pink-950">{order.eventDate}</span>
                    </div>

                    <div className="space-y-1 pt-1">
                      <span className="text-pink-900/60 text-[11px] font-medium block">Quantidade:</span>
                      <span className="font-bold text-pink-950">{order.quantity} convites</span>
                    </div>

                    <div className="space-y-1 pt-1">
                      <span className="text-pink-900/60 text-[11px] font-medium block">WhatsApp:</span>
                      <a
                        href={`https://wa.me/55${order.clientWhatsapp?.replace(/\D/g, '')}`}
                        target="_blank"
                        rel="noreferrer"
                        className="font-bold text-pink-600 hover:underline flex items-center gap-1 text-[11px]"
                      >
                        <Phone className="w-3 h-3" />
                        {order.clientWhatsapp || 'Não inf.'}
                      </a>
                    </div>
                  </div>

                  {/* Financeiro do Pedido */}
                  <div className="p-3 rounded-xl bg-white border border-pink-100 space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-xs text-pink-900/70 font-medium">Financeiro</span>
                      {getPaymentBadge(order.paymentStatus)}
                    </div>

                    <div className="flex items-center justify-between text-xs pt-1 border-t border-pink-50">
                      <div>
                        <span className="text-[11px] text-pink-900/50 block">Valor Total:</span>
                        <span className="font-bold text-pink-950 text-sm">
                          R$ {order.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>

                      <div className="text-right">
                        <span className="text-[11px] text-pink-900/50 block">Recebido:</span>
                        <span className="font-bold text-emerald-600">
                          R$ {order.paidValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>

                      <div className="text-right">
                        <span className="text-[11px] text-pink-900/50 block">Falta receber:</span>
                        <span className={`font-bold ${saldoDevedor > 0 ? 'text-rose-500' : 'text-emerald-600'}`}>
                          R$ {saldoDevedor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>
                    </div>
                  </div>

                  {order.notes && (
                    <p className="text-[11px] text-pink-900/70 italic bg-pink-50/30 p-2 rounded-lg border border-pink-100/50">
                      "{order.notes}"
                    </p>
                  )}

                  {/* Ações de Status e Quitação */}
                  <div className="pt-2 border-t border-pink-100 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-1.5">
                      <span className="text-[11px] text-pink-900/60 font-medium">Mudar etapa:</span>
                      <select
                        value={order.status}
                        onChange={(e) => onUpdateStatus(order.id, e.target.value as OrderStatus)}
                        className="h-8 px-2 rounded-lg bg-pink-50 border border-pink-200 text-xs text-pink-950 font-medium focus:outline-none focus:ring-1 focus:ring-pink-400"
                      >
                        <option value="pendente">Aguardando Início</option>
                        <option value="em_criacao">Em Confecção</option>
                        <option value="aprovacao">Em Aprovação</option>
                        <option value="concluido">Entregue</option>
                        <option value="cancelado">Cancelado</option>
                      </select>
                    </div>

                    {saldoDevedor > 0 && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => onUpdatePayment(order.id, 'pago', order.totalValue)}
                        className="h-8 text-[11px] border-emerald-300 text-emerald-700 hover:bg-emerald-50 rounded-lg"
                      >
                        Quitar Restante (R$ {saldoDevedor})
                      </Button>
                    )}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

