        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdateOrderPayment}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenNewTemplate={() => setIsTemplateModalOpen(true)}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
          />
        )}
      </main>

      {/* Rodapé Fofo & Delicado */}
      <footer className="border-t border-pink-100 bg-white/70 py-6 mt-12 text-center text-xs text-pink-900/60 font-medium">
