import React, { useState } from 'react';
import { Order, InvitationTemplate, OrderStatus, PaymentStatus } from '@/types';
import { initialOrders, initialTemplates } from '@/data/initialData';
import { Navbar } from '@/components/Navbar';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { OrdersManager } from '@/components/OrdersManager';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { Sparkles } from 'lucide-react';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('dashboard');

  // Estado dos Pedidos e Modelos
  const [orders, setOrders] = useState<Order[]>(initialOrders);
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);

  // Modais
  const [isOrderModalOpen, setIsOrderModalOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  // Quantidade de pedidos pendentes
  const pendingOrdersCount = orders.filter((o) => o.status !== 'concluido' && o.status !== 'cancelado').length;

  // Ações de Pedidos
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
    if (newOrder.templateId) {
      setTemplates((prev) =>
        prev.map((t) => (t.id === newOrder.templateId ? { ...t, timesUsed: t.timesUsed + 1 } : t))
      );
    }
  };

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
    );
  };

  const handleUpdatePayment = (orderId: string, newPaymentStatus: PaymentStatus, newPaidValue: number) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId
          ? { ...order, paymentStatus: newPaymentStatus, paidValue: newPaidValue }
          : order
      )
    );
  };

  // Ações de Modelos
  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleSelectTemplateToOrder = (template: InvitationTemplate) => {
    setSelectedTemplateForOrder(template);
    setIsOrderModalOpen(true);
  };

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Navbar com o nome Keh Convites e menu remodelado */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        onOpenNewOrder={() => {
          setSelectedTemplateForOrder(null);
          setIsOrderModalOpen(true);
        }}
        onOpenNewTemplate={() => setIsTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-10">
        {currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePayment={handleUpdatePayment}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenNewTemplate={() => setIsTemplateModalOpen(true)}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
          />
        )}
      </main>

      {/* Rodapé Elegante Keh Convites */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ebdccb]/40 py-6 mt-12">
        <div className="max-w-7xl mx-auto px-4 text-center space-y-1">
          <p className="text-xs font-serif font-bold text-[#4B2E20] flex items-center justify-center gap-1.5">
            <span>Keh Convites</span>
            <span className="w-1 h-1 rounded-full bg-[#D4AF37]" />
            <span>Ateliê de Convites & Gestão Financeira</span>
          </p>
          <p className="text-[11px] text-[#4B2E20]/60">
            Cores de luxo aplicadas: Marrom Nobre (#4B2E20) • Dourado (#D4AF37) • Creme Nobre (#F7EBDD)
          </p>
        </div>
      </footer>

      {/* Modais */}
      <NewOrderModal
        isOpen={isOrderModalOpen}
        onClose={() => {
          setIsOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        templates={templates}
        preSelectedTemplate={selectedTemplateForOrder}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isTemplateModalOpen}
        onClose={() => setIsTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

