import React, { useState, useEffect } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { OrdersManager } from '@/components/OrdersManager';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Lock, Sparkles, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(() => {
    const saved = localStorage.getItem('keh_convites_templates');
    return saved ? JSON.parse(saved) : initialTemplates;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('keh_convites_orders');
    return saved ? JSON.parse(saved) : initialOrders;
  });

  // Autenticação da Área Administrativa (senha: 41526378)
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(() => {
    return sessionStorage.getItem('keh_admin_auth') === 'true';
  });
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);

  // Modais de cadastro
  const [isNewOrderOpen, setIsNewOrderOpen] = useState(false);
  const [isNewTemplateOpen, setIsNewTemplateOpen] = useState(false);
  const [preSelectedTemplate, setPreSelectedTemplate] = useState<InvitationTemplate | null>(null);

  // Persistência
  useEffect(() => {
    localStorage.setItem('keh_convites_templates', JSON.stringify(templates));
  }, [templates]);

  useEffect(() => {
    localStorage.setItem('keh_convites_orders', JSON.stringify(orders));
  }, [orders]);

  const handleAdminSuccess = () => {
    setIsAdminAuthenticated(true);
    sessionStorage.setItem('keh_admin_auth', 'true');
    setIsAdminModalOpen(false);
    setCurrentTab('dashboard');
  };

  const handleAdminLogout = () => {
    setIsAdminAuthenticated(false);
    sessionStorage.removeItem('keh_admin_auth');
    setCurrentTab('templates');
  };

  const handleSelectTab = (tab: 'dashboard' | 'orders' | 'templates') => {
    if ((tab === 'dashboard' || tab === 'orders') && !isAdminAuthenticated) {
      setIsAdminModalOpen(true);
      return;
    }
    setCurrentTab(tab);
  };

  // Funções de Pedidos
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);

    if (newOrder.templateId) {
      setTemplates((prev) =>
        prev.map((t) =>
          t.id === newOrder.templateId ? { ...t, timesUsed: t.timesUsed + 1 } : t
        )
      );
    }
  };

  const handleUpdateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
    );
  };

  const handleUpdateOrderPayment = (
    orderId: string,
    newPaymentStatus: PaymentStatus,
    newPaidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId
          ? { ...order, paymentStatus: newPaymentStatus, paidValue: newPaidValue }
          : order
      )
    );
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleSelectTemplateToOrder = (template: InvitationTemplate) => {
    if (!isAdminAuthenticated) {
      setIsAdminModalOpen(true);
      return;
    }
    setPreSelectedTemplate(template);
    setIsNewOrderOpen(true);
  };

  const pendingOrdersCount = orders.filter(
    (o) => o.status !== 'concluido' && o.status !== 'cancelado'
  ).length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={handleSelectTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminModalOpen(true)}
        onLogoutAdmin={handleAdminLogout}
        onOpenNewOrder={() => {
          if (!isAdminAuthenticated) {
            setIsAdminModalOpen(true);
          } else {
            setPreSelectedTemplate(null);
            setIsNewOrderOpen(true);
          }
        }}
        onOpenNewTemplate={() => {
          if (!isAdminAuthenticated) {
            setIsAdminModalOpen(true);
          } else {
            setIsNewTemplateOpen(true);
          }
        }}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Faixa indicativa caso esteja na Área Administrativa autenticada */}
      {isAdminAuthenticated && (
        <div className="bg-[#4B2E20] text-[#F7EBDD] py-1.5 px-4 text-center text-xs border-b border-[#D4AF37]/30 flex items-center justify-center gap-2">
          <ShieldCheck className="w-3.5 h-3.5 text-[#D4AF37]" />
          <span>Área Administrativa Conectada • Painel de Gestão e Ganhos liberado</span>
        </div>
      )}

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-fade-in">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenNewTemplate={() => {
              if (!isAdminAuthenticated) {
                setIsAdminModalOpen(true);
              } else {
                setIsNewTemplateOpen(true);
              }
            }}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
          />
        )}

        {currentTab === 'orders' && (
          isAdminAuthenticated ? (
            <OrdersManager
              orders={orders}
              onUpdateStatus={handleUpdateOrderStatus}
              onUpdatePayment={handleUpdateOrderPayment}
              onOpenNewOrder={() => {
                setPreSelectedTemplate(null);
                setIsNewOrderOpen(true);
              }}
            />
          ) : (
            <div className="text-center py-16 space-y-4">
              <div className="w-14 h-14 rounded-2xl bg-[#ecdccb] text-[#4B2E20] flex items-center justify-center mx-auto border border-[#D4AF37]/40 shadow-sm">
                <Lock className="w-7 h-7 text-[#D4AF37]" />
              </div>
              <h2 className="text-xl font-serif font-bold text-[#4B2E20]">Área Restrita aos Pedidos</h2>
              <p className="text-xs text-[#4B2E20]/70 max-w-md mx-auto">
                Para gerenciar pedidos e prazos, digite a senha de acesso administrativo.
              </p>
              <Button
                onClick={() => setIsAdminModalOpen(true)}
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs rounded-xl"
              >
                Digitar Senha de Acesso
              </Button>
            </div>
          )
        )}

        {currentTab === 'dashboard' && (
          isAdminAuthenticated ? (
            <EarningsDashboard
              orders={orders}
              onOpenNewOrder={() => {
                setPreSelectedTemplate(null);
                setIsNewOrderOpen(true);
              }}
            />
          ) : (
            <div className="text-center py-16 space-y-4">
              <div className="w-14 h-14 rounded-2xl bg-[#ecdccb] text-[#4B2E20] flex items-center justify-center mx-auto border border-[#D4AF37]/40 shadow-sm">
                <Lock className="w-7 h-7 text-[#D4AF37]" />
              </div>
              <h2 className="text-xl font-serif font-bold text-[#4B2E20]">Área Restrita de Ganhos</h2>
              <p className="text-xs text-[#4B2E20]/70 max-w-md mx-auto">
                O balanço financeiro e métricas de faturamento exigem autenticação prévia.
              </p>
              <Button
                onClick={() => setIsAdminModalOpen(true)}
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs rounded-xl"
              >
                Digitar Senha de Acesso
              </Button>
            </div>
          )
        )}
      </main>

      {/* Rodapé Elegante */}
      <footer className="border-t border-[#D4AF37]/25 bg-[#F7EBDD]/80 py-6 mt-12 text-center text-xs text-[#4B2E20]/75">
        <div className="max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <span className="font-serif font-bold text-[#4B2E20]">Keh Convites</span>
            <span className="text-[#D4AF37]">•</span>
            <span>Ateliê de Convites Artesanais</span>
          </div>
          <div className="flex items-center gap-3">
            {!isAdminAuthenticated ? (
              <button
                onClick={() => setIsAdminModalOpen(true)}
                className="text-[#4B2E20]/70 hover:text-[#4B2E20] transition-colors flex items-center gap-1"
              >
                <Lock className="w-3 h-3 text-[#D4AF37]" />
                <span>Acesso Administrativo</span>
              </button>
            ) : (
              <button
                onClick={handleAdminLogout}
                className="text-[#855729] hover:text-[#4B2E20] transition-colors"
              >
                Desconectar Admin
              </button>
            )}
          </div>
        </div>
      </footer>

      {/* Modal de Senha da Área Administrativa */}
      <AdminLoginModal
        isOpen={isAdminModalOpen}
        onClose={() => setIsAdminModalOpen(false)}
        onSuccess={handleAdminSuccess}
      />

      {/* Modais de Ação */}
      <NewOrderModal
        isOpen={isNewOrderOpen}
        onClose={() => setIsNewOrderOpen(false)}
        templates={templates}
        preSelectedTemplate={preSelectedTemplate}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isNewTemplateOpen}
        onClose={() => setIsNewTemplateOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

