            <span>Modelos de Convite Keh Convites</span>
            <span className="text-xs font-sans font-semibold text-[#4B2E20] bg-[#D4AF37]/20 border border-[#D4AF37]/40 px-2.5 py-0.5 rounded-full">
              {templates.length} modelos
            </span>
          </h2>
          <p className="text-xs text-[#4B2E20]/70 font-medium mt-0.5">
            Seu portfólio exclusivo de convites artesanais e sob medida.
          </p>
        </div>

        <Button
          onClick={onOpenNewTemplate}
          className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-1.5 border border-[#D4AF37]/40 shadow-sm"
        >
          <Plus className="w-4 h-4 text-[#D4AF37]" />
          <span>Cadastrar Novo Modelo</span>
        </Button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col md:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por nome, tag ou estilo de papel..."
            className="pl-10 bg-[#fcf8f3] border-[#D4AF37]/40 focus-visible:ring-[#D4AF37] text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 rounded-xl"
          />
        </div>

        {/* Categorias */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ebdccb]'
              }`}
            >
              {cat === 'all' ? 'Todos os Estilos' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-[#fcf8f3] border-dashed border-[#D4AF37]/50 py-12 text-center rounded-2xl shadow-sm">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] mx-auto flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-[#D4AF37]" />
            </div>
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum modelo nesta categoria</h3>
            <p className="text-xs text-[#4B2E20]/70 max-w-sm mx-auto">
              Adicione os convites que você confecciona para enriquecer o catálogo do ateliê.
            </p>
            <Button
              size="sm"
              onClick={onOpenNewTemplate}
              className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs"
            >
              Adicionar Modelo
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => (
            <Card
              key={template.id}
              className="bg-[#fcf8f3] border-[#D4AF37]/30 hover:border-[#D4AF37] transition-all flex flex-col justify-between overflow-hidden group shadow-[0_2px_15px_rgba(75,46,32,0.06)] rounded-2xl"
            >
              {/* Foto do Convite */}
              <div className="relative aspect-[4/3] w-full overflow-hidden bg-[#ecdccb]">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                  onError={(e) => {
                    (e.target as HTMLImageElement).src =
                      'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80';
                  }}
                />
                <div className="absolute top-3 left-3">
                  <Badge className="bg-[#4B2E20]/90 backdrop-blur-md text-[#F7EBDD] border border-[#D4AF37]/50 shadow-sm font-semibold text-xs">
                    {template.category}
                  </Badge>
                </div>
                <div className="absolute top-3 right-3 bg-[#F7EBDD]/95 backdrop-blur-md px-2.5 py-1 rounded-full text-xs font-black text-[#4B2E20] border border-[#D4AF37]/50 shadow-sm">
                  R$ {template.price}
                </div>
                <div className="absolute bottom-2 right-2 bg-[#4B2E20]/80 backdrop-blur-sm px-2 py-0.5 rounded-full text-[10px] text-[#D4AF37] flex items-center gap-1 font-semibold">
                  <Sparkles className="w-2.5 h-2.5 text-[#D4AF37]" />
                  <span>{template.timesUsed} pedidos confeccionados</span>
                </div>
              </div>

              {/* Informações */}
              <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                <div className="space-y-2">
                  <h3 className="font-serif font-bold text-[#4B2E20] text-base group-hover:text-[#855729] transition-colors">
                    {template.title}
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed font-normal">
                    {template.description}
                  </p>

                  {/* Tags */}
                  <div className="flex flex-wrap gap-1.5 pt-1">
                    {template.tags?.map((tag) => (
                      <span
                        key={tag}
                        className="text-[10px] px-2 py-0.5 rounded-md bg-[#ecdccb]/60 text-[#4B2E20] border border-[#D4AF37]/30 font-medium flex items-center gap-1"
                      >
                        <Tag className="w-2.5 h-2.5 text-[#D4AF37]" />
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>

                {/* Botão de Ação */}
                <div className="pt-3 border-t border-[#D4AF37]/20 flex items-center justify-between">
                  <span className="text-xs text-[#4B2E20]/70 font-semibold">
                    Valor sugerido: <strong className="text-[#4B2E20]">R$ {template.price}</strong>
                  </span>

                  <Button
                    size="sm"
                    onClick={() => onSelectTemplateToOrder(template)}
                    className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40"
                  >
                    Gerar Pedido
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

