import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { OrdersManager } from '@/components/OrdersManager';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Heart, Sparkles, MessageCircle, Instagram, ShieldCheck } from 'lucide-react';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle de Autenticação da Área Administrativa (Senha 41526378)
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState<boolean>(false);

  // Controle dos modais de inserção
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [templateForNewOrder, setTemplateForNewOrder] = useState<InvitationTemplate | null>(null);

  // Abertura do Login Admin
  const handleOpenAdminAuth = () => {
    setIsAdminLoginOpen(true);
  };

  // Sucesso no login administrativo
  const handleAdminLoginSuccess = () => {
    setIsAdminAuthenticated(true);
    setIsAdminLoginOpen(false);
    setCurrentTab('dashboard');
  };

  // Logout do Admin
  const handleAdminLogout = () => {
    setIsAdminAuthenticated(false);
    setCurrentTab('templates');
  };

  // Adicionar novo modelo ao catálogo
  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  // Adicionar novo pedido
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
    if (newOrder.templateId) {
      setTemplates((prev) =>
        prev.map((tpl) =>
          tpl.id === newOrder.templateId ? { ...tpl, timesUsed: tpl.timesUsed + 1 } : tpl
        )
      );
    }
  };

  // Atualizar status do pedido
  const handleUpdateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
    );
  };

  // Atualizar status e valor pago
  const handleUpdatePaymentStatus = (
    orderId: string,
    newPaymentStatus: PaymentStatus,
    newPaidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId
          ? { ...order, paymentStatus: newPaymentStatus, paidValue: newPaidValue }
          : order
      )
    );
  };

  // Selecionar modelo para criar pedido
  const handleSelectTemplateToOrder = (template: InvitationTemplate) => {
    setTemplateForNewOrder(template);
    setIsNewOrderModalOpen(true);
  };

  // Quantidade de pedidos pendentes
  const pendingOrdersCount = orders.filter(
    (o) => o.status !== 'concluido' && o.status !== 'cancelado'
  ).length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={handleOpenAdminAuth}
        onLogoutAdmin={handleAdminLogout}
        onOpenNewOrder={() => {
          setTemplateForNewOrder(null);
          setIsNewOrderModalOpen(true);
        }}
        onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-fade-in">
        {/* Seção Pública: Catálogo de Convites */}
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
            onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
            isAdminAuthenticated={isAdminAuthenticated}
          />
        )}

        {/* Seções Restritas da Área Administrativa */}
        {isAdminAuthenticated && (
          <>
            {currentTab === 'dashboard' && (
              <EarningsDashboard
                orders={orders}
                onOpenNewOrder={() => {
                  setTemplateForNewOrder(null);
                  setIsNewOrderModalOpen(true);
                }}
              />
            )}

            {currentTab === 'orders' && (
              <OrdersManager
                orders={orders}
                onUpdateStatus={handleUpdateOrderStatus}
                onUpdatePayment={handleUpdatePaymentStatus}
                onOpenNewOrder={() => {
                  setTemplateForNewOrder(null);
                  setIsNewOrderModalOpen(true);
                }}
              />
            )}
          </>
        )}
      </main>

      {/* Rodapé Elegante com Marca Keh Convites */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#F7EBDD]/90 mt-12 py-8">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row items-center justify-between gap-4 text-xs text-[#4B2E20]/80">
          <div className="flex items-center gap-2">
            <span className="font-serif font-bold text-[#4B2E20] text-sm">Keh Convites</span>
            <span>• Ateliê de Convites & Papelaria Fina</span>
          </div>

          <div className="flex items-center gap-4 text-xs font-medium">
            <a
              href="https://instagram.com"
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-1.5 hover:text-[#4B2E20] transition-colors"
            >
              <Instagram className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>@kehconvites</span>
            </a>
            <a
              href="https://wa.me/"
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-1.5 hover:text-[#4B2E20] transition-colors"
            >
              <MessageCircle className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Atendimento WhatsApp</span>
            </a>
            {!isAdminAuthenticated && (
              <button
                onClick={handleOpenAdminAuth}
                className="text-[#4B2E20] hover:underline font-semibold flex items-center gap-1"
              >
                <ShieldCheck className="w-3.5 h-3.5 text-[#D4AF37]" />
                Área Restrita
              </button>
            )}
          </div>
        </div>
      </footer>

      {/* Modal de Autenticação da Área Administrativa */}
      <AdminLoginModal
        isOpen={isAdminLoginOpen}
        onClose={() => setIsAdminLoginOpen(false)}
        onSuccess={handleAdminLoginSuccess}
      />

      {/* Modais de Ações Administrativas */}
      {isAdminAuthenticated && (
        <>
          <NewOrderModal
            isOpen={isNewOrderModalOpen}
            onClose={() => {
              setIsNewOrderModalOpen(false);
              setTemplateForNewOrder(null);
            }}
            templates={templates}
            preSelectedTemplate={templateForNewOrder}
            onSaveOrder={handleSaveOrder}
          />

          <NewTemplateModal
            isOpen={isNewTemplateModalOpen}
            onClose={() => setIsNewTemplateModalOpen(false)}
            onSaveTemplate={handleSaveTemplate}
          />
        </>
      )}
    </div>
  );
}

