import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Search,
  Sparkles,
  Heart,
  Plus,
  Eye,
  CheckCircle,
  MessageCircle,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplateToOrder: (template: InvitationTemplate) => void;
  onOpenNewTemplate: () => void;
  isAdminAuthenticated?: boolean;
}

export function TemplatesCatalog({
  templates,
  onSelectTemplateToOrder,
  onOpenNewTemplate,
  isAdminAuthenticated = false,
}: TemplatesCatalogProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  const categories: (string | InvitationCategory)[] = [
    'all',
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesSearch =
      tpl.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tpl.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tpl.tags?.some((tag) => tag.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchesCategory =
      selectedCategory === 'all' || tpl.category === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const handleWhatsAppContact = (tpl: InvitationTemplate) => {
    const message = encodeURIComponent(
      `Olá, Keh Convites! Adorei o modelo "${tpl.title}" (${tpl.category}) e gostaria de solicitar um orçamento para o meu evento.`
    );
    window.open(`https://wa.me/?text=${message}`, '_blank');
  };

  return (
    <div className="space-y-6">
      {/* Banner de Apresentação do Ateliê */}
      <div className="relative overflow-hidden rounded-3xl bg-[#fcf8f3] border border-[#D4AF37]/40 p-6 sm:p-8 shadow-sm">
        <div className="max-w-2xl space-y-2.5">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#D4AF37]/15 border border-[#D4AF37]/30 text-[#4B2E20] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Coleções Exclusivas & Papelaria Fina</span>
          </div>
          <h2 className="text-2xl sm:text-3xl font-serif font-bold text-[#4B2E20] tracking-tight">
            Catálogo de Modelos Keh Convites
          </h2>
          <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-normal">
            Descubra os designs de convites e papelaria criados especialmente para tornar cada momento inesquecível. Escolha o seu modelo favorito para personalizar com a gente!
          </p>
        </div>

        {/* Botão de Novo Modelo visível SOMENTE para o Admin */}
        {isAdminAuthenticated && (
          <div className="mt-4 pt-3 border-t border-[#D4AF37]/20 flex items-center justify-between">
            <span className="text-[11px] font-semibold text-[#4B2E20]/70 flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-[#D4AF37] animate-pulse" />
              Painel do Ateliê: você está logada como administradora
            </span>
            <Button
              onClick={onOpenNewTemplate}
              size="sm"
              className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-1.5 border border-[#D4AF37]/40 shadow-sm"
            >
              <Plus className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Cadastrar Novo Modelo</span>
            </Button>
          </div>
        )}
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por estilo, papel, acabamento..."
            className="pl-10 bg-[#fcf8f3] border-[#D4AF37]/40 focus-visible:ring-[#D4AF37] text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 rounded-xl"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ecdccb]'
              }`}
            >
              {cat === 'all' ? 'Todos os Modelos' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos de Convite */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-[#fcf8f3] border-dashed border-[#D4AF37]/50 py-12 text-center rounded-2xl">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] mx-auto flex items-center justify-center">
              <Heart className="w-6 h-6 text-[#D4AF37]" />
            </div>
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum modelo encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70 max-w-sm mx-auto">
              Não encontramos nenhum modelo com esses critérios de busca.
            </p>
            {isAdminAuthenticated && (
              <Button
                size="sm"
                onClick={onOpenNewTemplate}
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs"
              >
                Cadastrar Novo Modelo
              </Button>
            )}
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((tpl) => (
            <Card
              key={tpl.id}
              className="group overflow-hidden rounded-3xl bg-[#fcf8f3] border-[#D4AF37]/30 hover:border-[#D4AF37] transition-all duration-300 shadow-sm hover:shadow-md flex flex-col"
            >
              {/* Imagem do Convite */}
              <div className="relative aspect-[4/3] overflow-hidden bg-[#ecdccb]/40">
                <img
                  src={tpl.imageUrl}
                  alt={tpl.title}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  loading="lazy"
                />
                <div className="absolute top-3 left-3">
                  <Badge className="bg-[#4B2E20]/90 text-[#F7EBDD] border-[#D4AF37]/40 backdrop-blur-sm text-[11px] font-medium shadow-sm">
                    {tpl.category}
                  </Badge>
                </div>

                <div className="absolute top-3 right-3 flex items-center gap-1.5">
                  <button
                    onClick={() => setPreviewTemplate(tpl)}
                    className="p-2 rounded-xl bg-white/90 text-[#4B2E20] hover:bg-white shadow-sm transition-transform active:scale-95"
                    title="Ver detalhes do convite"
                  >
                    <Eye className="w-4 h-4" />
                  </button>
                </div>

                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-[#4B2E20]/80 via-transparent to-transparent p-3 pt-6 flex items-end justify-between">
                  <span className="text-white text-xs font-semibold drop-shadow-sm">
                    Preço sugerido: <strong className="text-[#D4AF37] font-bold text-sm">R$ {tpl.price.toFixed(2)}</strong>
                  </span>
                </div>
              </div>

              {/* Informações do Convite */}
              <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                <div className="space-y-2">
                  <h3 className="font-serif font-bold text-base text-[#4B2E20] group-hover:text-[#855729] transition-colors leading-snug">
                    {tpl.title}
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                    {tpl.description}
                  </p>

                  {/* Tags */}
                  {tpl.tags && tpl.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      {tpl.tags.map((tag, i) => (
                        <span
                          key={i}
                          className="text-[10px] px-2 py-0.5 rounded-full bg-[#ecdccb] text-[#4B2E20] font-medium border border-[#D4AF37]/20"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                {/* Ações */}
                <div className="pt-2 border-t border-[#D4AF37]/20 flex items-center gap-2">
                  <Button
                    size="sm"
                    onClick={() => handleWhatsAppContact(tpl)}
                    className="flex-1 bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center justify-center gap-1.5"
                  >
                    <MessageCircle className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Pedir Orçamento</span>
                  </Button>

                  {isAdminAuthenticated && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => onSelectTemplateToOrder(tpl)}
                      className="border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ecdccb] text-xs font-semibold rounded-xl px-3"
                      title="Criar pedido com este modelo"
                    >
                      <Plus className="w-3.5 h-3.5 text-[#D4AF37]" />
                    </Button>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Modal de Prévia Ampliada com Especificações */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
          <div className="max-w-xl w-full bg-[#fcf8f3] border border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[90vh] flex flex-col">
            <div className="relative aspect-video w-full bg-[#ecdccb]/50">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => setPreviewTemplate(null)}
                className="absolute top-3 right-3 p-1.5 rounded-full bg-white/90 text-[#4B2E20] hover:bg-white shadow-md transition-colors"
              >
                ✕
              </button>
            </div>

            <div className="p-6 overflow-y-auto space-y-4">
              <div className="flex items-center justify-between">
                <Badge className="bg-[#4B2E20] text-[#F7EBDD] border-[#D4AF37]/40 text-xs font-medium">
                  {previewTemplate.category}
                </Badge>
                <span className="text-sm font-bold text-[#4B2E20]">
                  Preço Base: <span className="text-[#855729]">R$ {previewTemplate.price.toFixed(2)}</span>
                </span>
              </div>

              <div>
                <h3 className="font-serif font-bold text-xl text-[#4B2E20]">
                  {previewTemplate.title}
                </h3>
                <p className="text-xs text-[#4B2E20]/80 mt-2 leading-relaxed whitespace-pre-line">
                  {previewTemplate.description}
                </p>
              </div>

              {previewTemplate.tags && previewTemplate.tags.length > 0 && (
                <div className="space-y-1.5">
                  <span className="text-[11px] font-bold text-[#4B2E20] uppercase tracking-wider">
                    Acabamentos & Destaques:
                  </span>
                  <div className="flex flex-wrap gap-1.5">
                    {previewTemplate.tags.map((tag, idx) => (
                      <span
                        key={idx}
                        className="text-xs px-2.5 py-1 rounded-full bg-[#ecdccb] text-[#4B2E20] font-medium border border-[#D4AF37]/30 flex items-center gap-1"
                      >
                        <CheckCircle className="w-3 h-3 text-[#D4AF37]" />
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              <div className="pt-3 border-t border-[#D4AF37]/30 flex items-center gap-2">
                <Button
                  onClick={() => {
                    handleWhatsAppContact(previewTemplate);
                    setPreviewTemplate(null);
                  }}
                  className="flex-1 bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center justify-center gap-1.5 py-2.5"
                >
                  <MessageCircle className="w-4 h-4 text-[#D4AF37]" />
                  <span>Conversar no WhatsApp sobre este Modelo</span>
                </Button>

                {isAdminAuthenticated && (
                  <Button
                    onClick={() => {
                      onSelectTemplateToOrder(previewTemplate);
                      setPreviewTemplate(null);
                    }}
                    variant="outline"
                    className="border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ecdccb] text-xs font-semibold rounded-xl px-4 py-2.5"
                  >
                    Gerar Pedido
                  </Button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

