import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Search,
  Calendar,
  Phone,
  Clock,
  CheckCircle2,
  AlertCircle,
  FileText,
  DollarSign,
  Plus,
  Sparkles,
} from 'lucide-react';

interface OrdersManagerProps {
  orders: Order[];
  onUpdateStatus: (orderId: string, newStatus: OrderStatus) => void;
  onUpdatePayment: (orderId: string, newPaymentStatus: PaymentStatus, newPaidValue: number) => void;
  onOpenNewOrder: () => void;
}

export function OrdersManager({
  orders,
  onUpdateStatus,
  onUpdatePayment,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | OrderStatus>('all');

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.category?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return (
          <Badge className="bg-[#ecdccb] text-[#4B2E20] border-[#D4AF37]/50 font-medium text-xs">
            Aguardando Início
          </Badge>
        );
      case 'em_criacao':
        return (
          <Badge className="bg-[#4B2E20] text-[#F7EBDD] border-[#D4AF37]/50 font-medium text-xs">
            Em Confecção
          </Badge>
        );
      case 'aprovacao':
        return (
          <Badge className="bg-[#D4AF37]/20 text-[#4B2E20] border-[#D4AF37] font-medium text-xs">
            Em Aprovação
          </Badge>
        );
      case 'concluido':
        return (
          <Badge className="bg-emerald-100 text-emerald-800 border-emerald-300 font-medium text-xs">
            Pronto & Entregue
          </Badge>
        );
      case 'cancelado':
        return (
          <Badge className="bg-rose-100 text-rose-800 border-rose-300 font-medium text-xs">
            Cancelado
          </Badge>
        );
      default:
        return null;
    }
  };

  const getPaymentBadge = (status: PaymentStatus) => {
    switch (status) {
      case 'pago':
        return (
          <span className="text-[11px] font-bold text-emerald-800 bg-emerald-50 border border-emerald-300 px-2.5 py-0.5 rounded-full">
            Pago Integralmente
          </span>
        );
      case 'parcial':
        return (
          <span className="text-[11px] font-bold text-[#4B2E20] bg-[#D4AF37]/20 border border-[#D4AF37] px-2.5 py-0.5 rounded-full">
            Sinal Pago
          </span>
        );
      case 'pendente':
        return (
          <span className="text-[11px] font-bold text-[#855729] bg-[#ecdccb] border border-[#D4AF37]/40 px-2.5 py-0.5 rounded-full">
            Pagamento Pendente
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center justify-between">
        <div>
          <h2 className="text-2xl font-serif font-bold text-[#4B2E20] tracking-tight flex items-center gap-2">
            <span>Gestão de Pedidos</span>
            <span className="text-xs font-sans font-semibold text-[#4B2E20] bg-[#D4AF37]/20 border border-[#D4AF37]/40 px-2.5 py-0.5 rounded-full">
              {orders.length} pedidos
            </span>
          </h2>
          <p className="text-xs text-[#4B2E20]/70 font-medium mt-0.5">
            Organize os prazos de entrega, status de confecção e pagamentos dos convites.
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-1.5 border border-[#D4AF37]/40 shadow-sm"
        >
          <Plus className="w-4 h-4 text-[#D4AF37]" />
          <span>Cadastrar Novo Pedido</span>
        </Button>
      </div>

      {/* Busca e Filtros */}
      <div className="flex flex-col md:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, modelo ou categoria..."
            className="pl-10 bg-[#fcf8f3] border-[#D4AF37]/40 focus-visible:ring-[#D4AF37] text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 rounded-xl"
          />
        </div>

        {/* Abas de Filtros de Status */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          <button
            onClick={() => setStatusFilter('all')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'all'
                ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ebdccb]'
            }`}
          >
            Todos ({orders.length})
          </button>
          <button
            onClick={() => setStatusFilter('em_criacao')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'em_criacao'
                ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ebdccb]'
            }`}
          >
            Em Confecção
          </button>
          <button
            onClick={() => setStatusFilter('aprovacao')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'aprovacao'
                ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ebdccb]'
            }`}
          >
            Em Aprovação
          </button>
          <button
            onClick={() => setStatusFilter('concluido')}
            className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
              statusFilter === 'concluido'
                ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                : 'bg-[#fcf8f3] text-[#4B2E20]/80 border border-[#D4AF37]/30 hover:bg-[#ebdccb]'
            }`}
          >
            Entregues
          </button>
        </div>
      </div>

      {/* Lista de Pedidos */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-[#fcf8f3] border-dashed border-[#D4AF37]/50 py-12 text-center rounded-2xl shadow-sm">
          <CardContent className="space-y-3">
            <div className="w-12 h-12 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] mx-auto flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-[#D4AF37]" />
            </div>
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum pedido encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70 max-w-sm mx-auto">
              Nenhuma encomenda corresponde à pesquisa atual. Cadastre novos pedidos para acompanhar.
            </p>
            <Button
              size="sm"
              onClick={onOpenNewOrder}
              className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl text-xs"
            >
              Criar Pedido Agora
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredOrders.map((order) => {
            const saldoDevedor = Math.max(0, order.totalValue - order.paidValue);

            return (
              <Card
                key={order.id}
                className="bg-[#fcf8f3] border-[#D4AF37]/30 hover:border-[#D4AF37] transition-all shadow-[0_2px_15px_rgba(75,46,32,0.05)] rounded-2xl overflow-hidden flex flex-col justify-between"
              >
                <div className="p-5 space-y-4">
                  {/* Topo do Card */}
                  <div className="flex items-start justify-between gap-2 border-b border-[#D4AF37]/20 pb-3">
                    <div>
                      <span className="text-[10px] font-bold tracking-wider uppercase text-[#D4AF37] bg-[#4B2E20] px-2 py-0.5 rounded-md">
                        {order.category}
                      </span>
                      <h3 className="font-serif font-bold text-base text-[#4B2E20] mt-1.5">
                        {order.clientName}
                      </h3>
                      <p className="text-xs text-[#4B2E20]/80 font-medium">
                        {order.templateTitle} • <strong className="text-[#4B2E20]">{order.quantity} unidades</strong>
                      </p>
                    </div>

                    <div className="flex flex-col items-end gap-1.5">
                      {getStatusBadge(order.status)}
                      {getPaymentBadge(order.paymentStatus)}
                    </div>
                  </div>

                  {/* Informações de datas e contato */}
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div className="flex items-center gap-1.5 text-[#4B2E20]/80">
                      <Clock className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Entrega: <strong className="text-[#4B2E20]">{order.deadlineDate}</strong></span>
                    </div>

                    <div className="flex items-center gap-1.5 text-[#4B2E20]/80">
                      <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Evento: <strong className="text-[#4B2E20]">{order.eventDate}</strong></span>
                    </div>

                    {order.clientWhatsapp && (
                      <div className="flex items-center gap-1.5 text-[#4B2E20]/80 col-span-2">
                        <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                        <span>WhatsApp: <strong className="text-[#4B2E20]">{order.clientWhatsapp}</strong></span>
                      </div>
                    )}
                  </div>

                  {order.notes && (
                    <div className="text-[11px] text-[#4B2E20]/75 bg-[#ecdccb]/50 p-2.5 rounded-xl border border-[#D4AF37]/20 flex items-start gap-1.5">
                      <FileText className="w-3.5 h-3.5 text-[#D4AF37] shrink-0 mt-0.5" />
                      <span>{order.notes}</span>
                    </div>
                  )}

                  {/* Detalhes Financeiros do Pedido */}
                  <div className="p-3 bg-[#ecdccb]/40 rounded-xl border border-[#D4AF37]/25 flex items-center justify-between">
                    <div>
                      <span className="text-[10px] text-[#4B2E20]/70 uppercase font-semibold block">Total Cobrado</span>
                      <span className="text-sm font-black text-[#4B2E20]">
                        R$ {order.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                    </div>

                    <div className="text-right">
                      <span className="text-[10px] text-[#4B2E20]/70 uppercase font-semibold block">Já Pago</span>
                      <span className="text-sm font-black text-[#D4AF37]">
                        R$ {order.paidValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                    </div>

                    {saldoDevedor > 0 && (
                      <div className="text-right pl-2 border-l border-[#D4AF37]/30">
                        <span className="text-[10px] text-rose-700 uppercase font-bold block">Resta Pagar</span>
                        <span className="text-xs font-bold text-rose-800">
                          R$ {saldoDevedor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Controles de Alteração Rápida */}
                <div className="px-5 py-3 bg-[#ecdccb]/30 border-t border-[#D4AF37]/20 flex flex-wrap items-center justify-between gap-2 text-xs">
                  <div className="flex items-center gap-1.5">
                    <span className="text-[11px] font-semibold text-[#4B2E20]/70">Status:</span>
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateStatus(order.id, e.target.value as OrderStatus)}
                      className="h-8 px-2 rounded-lg bg-[#fcf8f3] border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none"
                    >
                      <option value="pendente">Aguardando Início</option>
                      <option value="em_criacao">Em Confecção</option>
                      <option value="aprovacao">Em Aprovação</option>
                      <option value="concluido">Pronto & Entregue</option>
                      <option value="cancelado">Cancelado</option>
                    </select>
                  </div>

                  {order.paymentStatus !== 'pago' && (
                    <Button
                      size="sm"
                      onClick={() => onUpdatePayment(order.id, 'pago', order.totalValue)}
                      className="h-8 px-3 bg-[#D4AF37] hover:bg-[#bfa035] text-[#4B2E20] font-bold text-[11px] rounded-lg shadow-none"
                    >
                      Confirmar Pagamento Total
                    </Button>
                  )}
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

