import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle de Autenticação da Área Administrativa (Senha: 41526378)
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState<boolean>(false);

  // Modais de Criação
  const [isNewOrderOpen, setIsNewOrderOpen] = useState(false);
  const [isNewTemplateOpen, setIsNewTemplateOpen] = useState(false);
  const [preSelectedTemplate, setPreSelectedTemplate] = useState<InvitationTemplate | null>(null);

  // Contagem de pedidos pendentes
  const pendingOrdersCount = orders.filter((o) => o.status !== 'concluido' && o.status !== 'cancelado').length;

  const handleAdminSuccess = () => {
    setIsAdminAuthenticated(true);
    setIsAdminLoginOpen(false);
    setCurrentTab('dashboard');
  };

  const handleLogoutAdmin = () => {
    setIsAdminAuthenticated(false);
    setCurrentTab('templates');
  };

  const handleSelectTemplateToOrder = (template: InvitationTemplate) => {
    setPreSelectedTemplate(template);
    setIsNewOrderOpen(true);
  };

  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status } : order))
    );
  };

  const handleUpdatePaymentStatus = (orderId: string, paymentStatus: PaymentStatus, paidValue: number) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId ? { ...order, paymentStatus, paidValue } : order
      )
    );
  };

  const handleDeleteOrder = (orderId: string) => {
    if (confirm('Tem certeza que deseja excluir esta encomenda?')) {
      setOrders((prev) => prev.filter((order) => order.id !== orderId));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F7EBDD] text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminLoginOpen(true)}
        onLogoutAdmin={handleLogoutAdmin}
        onOpenNewOrder={() => {
          setPreSelectedTemplate(null);
          setIsNewOrderOpen(true);
        }}
        onOpenNewTemplate={() => setIsNewTemplateOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSelectTemplateToOrder={handleSelectTemplateToOrder}
            onOpenNewTemplate={() => setIsNewTemplateOpen(true)}
            isAdminAuthenticated={isAdminAuthenticated}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onUpdatePaymentStatus={handleUpdatePaymentStatus}
            onDeleteOrder={handleDeleteOrder}
            onOpenNewOrder={() => {
              setPreSelectedTemplate(null);
              setIsNewOrderOpen(true);
            }}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            onOpenNewOrder={() => {
              setPreSelectedTemplate(null);
              setIsNewOrderOpen(true);
            }}
          />
        )}
      </main>

      {/* Rodapé Delicado e Romântico */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#F7EBDD]/90 py-6 text-center text-xs text-[#4B2E20]/75">
        <div className="max-w-7xl mx-auto px-4 space-y-1">
          <p className="font-serif font-bold text-sm text-[#4B2E20]">
            Keh Convites • Ateliê & Papelaria Fina
          </p>
          <p className="text-[11px] text-[#4B2E20]/65">
            Convites feitos à mão com dedicação, papéis nobres e afeto para momentos eternos.
          </p>
        </div>
      </footer>

      {/* Modais do Sistema */}
      <AdminLoginModal
        isOpen={isAdminLoginOpen}
        onClose={() => setIsAdminLoginOpen(false)}
        onSuccess={handleAdminSuccess}
      />

      <NewOrderModal
        isOpen={isNewOrderOpen}
        onClose={() => setIsNewOrderOpen(false)}
        templates={templates}
        preSelectedTemplate={preSelectedTemplate}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isNewTemplateOpen}
        onClose={() => setIsNewTemplateOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

