import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Search,
  Sparkles,
  Heart,
  Plus,
  Eye,
  MessageCircle,
  X,
  Check,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplateToOrder: (template: InvitationTemplate) => void;
  onOpenNewTemplate: () => void;
  isAdminAuthenticated?: boolean;
}

export function TemplatesCatalog({
  templates,
  onSelectTemplateToOrder,
  onOpenNewTemplate,
  isAdminAuthenticated = false,
}: TemplatesCatalogProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  const categories: (string | InvitationCategory)[] = [
    'all',
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesSearch =
      tpl.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tpl.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tpl.tags?.some((tag) => tag.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchesCategory =
      selectedCategory === 'all' || tpl.category === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const handleWhatsAppContact = (tpl: InvitationTemplate) => {
    const text = encodeURIComponent(
      `Olá, Keh Convites! Fiquei encantada com o modelo "${tpl.title}" (${tpl.category}). Gostaria de verificar valores e opções de personalização para meu evento!`
    );
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in">

      {/* Banner Principal com Toque Romântico e Artesanal */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-[#fbf5ed] via-[#f7ebdd] to-[#f5e6d3] border border-[#D4AF37]/45 p-6 sm:p-10 shadow-[0_8px_30px_rgba(75,46,32,0.04)]">
        <div className="relative z-10 max-w-3xl space-y-3.5">
          <div className="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-[#D4AF37]/15 border border-[#D4AF37]/35 text-[#4B2E20] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span className="tracking-wide">Ateliê de Convites Personalizados</span>
          </div>

          <h1 className="text-3xl sm:text-4xl lg:text-5xl font-serif font-bold text-[#4B2E20] tracking-tight leading-tight">
            Coleções que encantam desde o primeiro toque
          </h1>

          <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-normal max-w-2xl">
            Cada convite do nosso ateliê é produzido com papéis nobres, acabamentos delicados, monogramas em hot stamping e detalhes pensados para tornar seu momento memorável.
          </p>

          <div className="pt-2 flex flex-wrap items-center gap-3">
            <span className="inline-flex items-center gap-1.5 text-xs text-[#4B2E20] font-semibold bg-white/70 px-3 py-1.5 rounded-xl border border-[#D4AF37]/30">
              <Check className="w-3.5 h-3.5 text-[#D4AF37]" /> Papelaria Nobre
            </span>
            <span className="inline-flex items-center gap-1.5 text-xs text-[#4B2E20] font-semibold bg-white/70 px-3 py-1.5 rounded-xl border border-[#D4AF37]/30">
              <Check className="w-3.5 h-3.5 text-[#D4AF37]" /> Lacre de Cera Artesanal
            </span>
            <span className="inline-flex items-center gap-1.5 text-xs text-[#4B2E20] font-semibold bg-white/70 px-3 py-1.5 rounded-xl border border-[#D4AF37]/30">
              <Check className="w-3.5 h-3.5 text-[#D4AF37]" /> Acabamentos em Foil Dourado
            </span>
          </div>
        </div>

        {/* Botão de Novo Modelo visível SOMENTE para o Admin */}
        {isAdminAuthenticated && (
          <div className="relative z-10 mt-6 pt-4 border-t border-[#D4AF37]/30 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 bg-white/40 p-4 rounded-2xl">
            <div className="flex items-center gap-2 text-xs font-semibold text-[#4B2E20]">
              <span className="w-2.5 h-2.5 rounded-full bg-[#D4AF37] animate-ping" />
              <span>Painel Administrativo: Gerenciamento ativo do catálogo</span>
            </div>
            <Button
              onClick={onOpenNewTemplate}
              size="sm"
              className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-2 border border-[#D4AF37]/40 shadow-sm"
            >
              <Plus className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Cadastrar Novo Modelo</span>
            </Button>
          </div>
        )}

        {/* Efeito decorativo dourado de fundo */}
        <div className="absolute -top-16 -right-16 w-64 h-64 bg-[#D4AF37]/10 rounded-full blur-3xl pointer-events-none" />
      </div>

      {/* Barra de Filtros e Busca Delicada */}
      <div className="flex flex-col sm:flex-row gap-3.5 items-stretch sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por nome, papel, estilo ou acabamento..."
            className="pl-10 bg-[#fdfaf5] border-[#D4AF37]/40 focus-visible:ring-[#D4AF37] text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 rounded-2xl shadow-sm h-11"
          />
        </div>

        {/* Categorias em Pílulas Sofisticadas */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-[#fcf7f0] text-[#4B2E20]/80 border border-[#D4AF37]/35 hover:bg-[#ebdccb] hover:text-[#4B2E20]'
              }`}
            >
              {cat === 'all' ? 'Todos os Modelos' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos de Convite com Design Luxuoso */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-[#fcf8f3] border-dashed border-[#D4AF37]/50 py-16 text-center rounded-3xl">
          <CardContent className="space-y-3">
            <div className="w-14 h-14 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] mx-auto flex items-center justify-center">
              <Heart className="w-6 h-6 text-[#D4AF37]" />
            </div>
            <h3 className="text-lg font-serif font-bold text-[#4B2E20]">Nenhum modelo encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70 max-w-sm mx-auto">
              Tente buscar com outras palavras-chave ou explore outras categorias do ateliê.
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((tpl) => (
            <Card
              key={tpl.id}
              className="group overflow-hidden rounded-3xl bg-[#fdf9f4] border border-[#D4AF37]/35 hover:border-[#D4AF37] transition-all duration-300 shadow-[0_4px_20px_rgba(75,46,32,0.03)] hover:shadow-[0_8px_30px_rgba(212,175,55,0.18)] flex flex-col"
            >
              {/* Imagem do Convite com Moldura Suave */}
              <div className="relative aspect-[4/3] overflow-hidden bg-[#ebdccb]/40">
                <img
                  src={tpl.imageUrl}
                  alt={tpl.title}
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                  loading="lazy"
                />

                {/* Badge da Categoria */}
                <div className="absolute top-3.5 left-3.5">
                  <Badge className="bg-[#4B2E20]/90 text-[#F7EBDD] border border-[#D4AF37]/40 backdrop-blur-sm text-[11px] font-medium shadow-sm px-2.5 py-0.5">
                    {tpl.category}
                  </Badge>
                </div>

                {/* Botão de Ver Detalhes */}
                <div className="absolute top-3.5 right-3.5">
                  <button
                    onClick={() => setPreviewTemplate(tpl)}
                    className="p-2 rounded-xl bg-white/95 text-[#4B2E20] hover:bg-white shadow-sm transition-transform active:scale-95 border border-[#D4AF37]/30"
                    title="Ver detalhes do convite"
                  >
                    <Eye className="w-4 h-4 text-[#4B2E20]" />
                  </button>
                </div>

                {/* Faixa inferior de acabamento */}
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-[#4B2E20]/75 via-transparent to-transparent p-3.5 pt-8 flex items-end justify-between">
                  <span className="text-[11px] font-medium text-[#F7EBDD]/90 flex items-center gap-1">
                    <Sparkles className="w-3 h-3 text-[#D4AF37]" />
                    Design Exclusivo Keh
                  </span>
                </div>
              </div>

              {/* Informações do Convite */}
              <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                <div className="space-y-2">
                  <h3 className="font-serif font-bold text-base text-[#4B2E20] leading-snug group-hover:text-[#855729] transition-colors">
                    {tpl.title}
                  </h3>

                  <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                    {tpl.description || 'Convite especial com papéis selecionados e acabamento artesanal de alto padrão.'}
                  </p>

                  {/* Tags Delicadas */}
                  {tpl.tags && tpl.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      {tpl.tags.slice(0, 3).map((tag, idx) => (
                        <span
                          key={idx}
                          className="text-[10px] px-2 py-0.5 rounded-md bg-[#ecdccb]/60 text-[#4B2E20] font-medium border border-[#D4AF37]/25"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                {/* Ações: Pedir pelo WhatsApp ou Encomendar */}
                <div className="pt-3 border-t border-[#D4AF37]/25 flex items-center justify-between gap-2">
                  <div className="flex flex-col">
                    <span className="text-[10px] text-[#4B2E20]/60 uppercase tracking-wider font-semibold">
                      A partir de
                    </span>
                    <span className="text-sm font-bold text-[#4B2E20]">
                      R$ {tpl.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    {isAdminAuthenticated ? (
                      <Button
                        size="sm"
                        onClick={() => onSelectTemplateToOrder(tpl)}
                        className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40"
                      >
                        Criar Pedido
                      </Button>
                    ) : (
                      <Button
                        size="sm"
                        onClick={() => handleWhatsAppContact(tpl)}
                        className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center gap-1.5"
                      >
                        <MessageCircle className="w-3.5 h-3.5 text-[#D4AF37]" />
                        <span>Solicitar Orçamento</span>
                      </Button>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Modal Delicado de Preview do Modelo */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
          <div className="relative max-w-xl w-full bg-[#fdf9f4] border border-[#D4AF37]/50 rounded-3xl overflow-hidden shadow-2xl">
            <button
              onClick={() => setPreviewTemplate(null)}
              className="absolute top-4 right-4 z-10 p-2 rounded-full bg-white/90 text-[#4B2E20] hover:bg-white shadow-md"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="aspect-[16/10] overflow-hidden bg-[#ecdccb]/50">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-full object-cover"
              />
            </div>

            <div className="p-6 space-y-4">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <Badge className="bg-[#4B2E20] text-[#F7EBDD] text-xs mb-2">
                    {previewTemplate.category}
                  </Badge>
                  <h3 className="text-xl font-serif font-bold text-[#4B2E20]">
                    {previewTemplate.title}
                  </h3>
                </div>
                <div className="text-right">
                  <span className="text-[11px] text-[#4B2E20]/60 block">Sugerido</span>
                  <span className="text-lg font-bold text-[#4B2E20]">
                    R$ {previewTemplate.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </span>
                </div>
              </div>

              <p className="text-xs text-[#4B2E20]/80 leading-relaxed">
                {previewTemplate.description || 'Convite trabalhado nos mínimos detalhes para impressionar seus convidados.'}
              </p>

              {previewTemplate.tags && (
                <div className="flex flex-wrap gap-2">
                  {previewTemplate.tags.map((t, idx) => (
                    <span
                      key={idx}
                      className="text-xs px-2.5 py-1 rounded-lg bg-[#ecdccb]/60 text-[#4B2E20] font-medium border border-[#D4AF37]/30"
                    >
                      {t}
                    </span>
                  ))}
                </div>
              )}

              <div className="pt-3 border-t border-[#D4AF37]/30 flex items-center justify-end gap-2.5">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setPreviewTemplate(null)}
                  className="text-[#4B2E20] text-xs"
                >
                  Fechar
                </Button>
                {isAdminAuthenticated ? (
                  <Button
                    size="sm"
                    onClick={() => {
                      onSelectTemplateToOrder(previewTemplate);
                      setPreviewTemplate(null);
                    }}
                    className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl"
                  >
                    Montar Pedido com Este Modelo
                  </Button>
                ) : (
                  <Button
                    size="sm"
                    onClick={() => handleWhatsAppContact(previewTemplate)}
                    className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl flex items-center gap-2 border border-[#D4AF37]/40"
                  >
                    <MessageCircle className="w-4 h-4 text-[#D4AF37]" />
                    Conversar no WhatsApp
                  </Button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

