import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { X, Check, Sparkles } from 'lucide-react';

interface NewOrderModalProps {
  isOpen: boolean;
  onClose: () => void;
  templates: InvitationTemplate[];
  preSelectedTemplate?: InvitationTemplate | null;
  onSaveOrder: (newOrder: Order) => void;
}

export function NewOrderModal({
  isOpen,
  onClose,
  templates,
  preSelectedTemplate,
  onSaveOrder,
}: NewOrderModalProps) {
  if (!isOpen) return null;

  const [clientName, setClientName] = useState('');
  const [clientWhatsapp, setClientWhatsapp] = useState('');
  const [selectedTemplateId, setSelectedTemplateId] = useState(
    preSelectedTemplate?.id || (templates[0]?.id ?? '')
  );
  const [category, setCategory] = useState<InvitationCategory>(
    preSelectedTemplate?.category || 'Casamento'
  );
  const [quantity, setQuantity] = useState(80);
  const [totalValue, setTotalValue] = useState(preSelectedTemplate ? preSelectedTemplate.price * 2 : 650);
  const [paidValue, setPaidValue] = useState(325);
  const [deadlineDate, setDeadlineDate] = useState('2025-06-20');
  const [eventDate, setEventDate] = useState('2025-07-25');
  const [notes, setNotes] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!clientName.trim()) {
      alert('Por favor, informe o nome do cliente.');
      return;
    }

    const templateObj = templates.find((t) => t.id === selectedTemplateId);
    const paymentStatus =
      paidValue >= totalValue ? 'pago' : paidValue > 0 ? 'parcial' : 'pendente';

    const newOrder: Order = {
      id: `ord-${Date.now()}`,
      clientName,
      clientWhatsapp,
      templateId: selectedTemplateId,
      templateTitle: templateObj?.title || 'Convite Exclusivo sob Medida',
      category: templateObj?.category || category,
      quantity: Number(quantity) || 1,
      totalValue: Number(totalValue) || 0,
      paidValue: Number(paidValue) || 0,
      eventDate,
      deadlineDate,
      status: 'em_criacao',
      paymentStatus,
      notes,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSaveOrder(newOrder);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/60 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-xl w-full bg-[#fcf8f3] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[90vh] flex flex-col">
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-[#ecdccb]/50">
          <div>
            <CardTitle className="text-lg font-serif font-bold text-[#4B2E20] flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-[#D4AF37]" />
              <span>Novo Pedido de Convite</span>
            </CardTitle>
            <p className="text-xs text-[#4B2E20]/70 font-medium mt-0.5">
              Keh Convites • Preencha os dados do cliente e os valores
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        <CardContent className="overflow-y-auto p-6 space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4 text-xs">
            {/* Nome do Cliente e Contato */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Nome do Cliente / Casal *
                </label>
                <Input
                  required
                  placeholder="Ex: Amanda & Leonardo"
                  value={clientName}
                  onChange={(e) => setClientName(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  WhatsApp de Contato
                </label>
                <Input
                  placeholder="(11) 98888-7777"
                  value={clientWhatsapp}
                  onChange={(e) => setClientWhatsapp(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>
            </div>

            {/* Modelo Escolhido */}
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Modelo de Convite Selecionado
              </label>
              <select
                value={selectedTemplateId}
                onChange={(e) => {
                  setSelectedTemplateId(e.target.value);
                  const found = templates.find((t) => t.id === e.target.value);
                  if (found) {
                    setCategory(found.category);
                    setTotalValue(found.price * 2);
                    setPaidValue(found.price);
                  }
                }}
                className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              >
                {templates.map((tpl) => (
                  <option key={tpl.id} value={tpl.id}>
                    {tpl.title} — {tpl.category} (R$ {tpl.price})
                  </option>
                ))}
              </select>
            </div>

            {/* Quantidade e Prazos */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Quantidade (convites)
                </label>
                <Input
                  type="number"
                  min="1"
                  value={quantity}
                  onChange={(e) => setQuantity(Number(e.target.value))}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Data Limite de Entrega
                </label>
                <Input
                  type="date"
                  value={deadlineDate}
                  onChange={(e) => setDeadlineDate(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Data do Evento
                </label>
                <Input
                  type="date"
                  value={eventDate}
                  onChange={(e) => setEventDate(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>
            </div>

            {/* Valores Financeiros */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3.5 rounded-2xl bg-[#ecdccb]/50 border border-[#D4AF37]/30">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Valor Total Cobrado (R$) *
                </label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={totalValue}
                  onChange={(e) => setTotalValue(Number(e.target.value))}
                  className="bg-white border-[#D4AF37]/50 text-[#4B2E20] font-black rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Valor Pago de Entrada (R$)
                </label>
                <Input
                  type="number"
                  step="0.01"
                  value={paidValue}
                  onChange={(e) => setPaidValue(Number(e.target.value))}
                  className="bg-white border-[#D4AF37]/50 text-[#4B2E20] font-black rounded-xl"
                />
              </div>
            </div>

            {/* Observações */}
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Observações de Papelaria, Lacre ou Personalização
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Fita de seda cor champanhe, lacre de cera dourado, nome dos convidados caligrafado..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              />
            </div>

            <div className="pt-2 flex items-center justify-end gap-2">
              <Button type="button" variant="ghost" onClick={onClose} className="text-[#4B2E20] rounded-xl">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold rounded-xl border border-[#D4AF37]/40"
              >
                <Check className="w-4 h-4 mr-1.5 text-[#D4AF37]" />
                Salvar Pedido
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

