                  type="date"
                  value={deadlineDate}
                  onChange={(e) => setDeadlineDate(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Data do Evento
                </label>
