                    placeholder="Ex: (11) 99999-9999"
                    value={rsvpLink}
                    onChange={(e) => setRsvpLink(e.target.value)}
                    className="bg-white border-[#D4AF37]/35 text-[#4B2E20] rounded-xl h-8 text-[11px]"
                  />
                </div>

                <div>
                  <label className="block text-[10px] text-[#4B2E20]/80 mb-0.5">
                    Localização (Espaço / Google Maps)
