                    value={mapsLocation}
                    onChange={(e) => setMapsLocation(e.target.value)}
                    className="bg-white border-[#D4AF37]/35 text-[#4B2E20] rounded-xl h-8 text-[11px]"
                  />
                </div>
              </div>
            </div>

            {/* Valores Financeiros */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3.5 rounded-2xl bg-[#ecdccb]/50 border border-[#D4AF37]/30">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Valor Total do Convite Digital (R$) *
                </label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={totalValue}
                  onChange={(e) => setTotalValue(Number(e.target.value))}
                  className="bg-white border-[#D4AF37]/50 text-[#4B2E20] font-black rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Valor Já Pago (Pix/Sinal) *
                </label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={paidValue}
                  onChange={(e) => setPaidValue(Number(e.target.value))}
                  className="bg-white border-[#D4AF37]/50 text-[#4B2E20] font-black rounded-xl"
                />
              </div>
            </div>

            {/* Observações */}
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Observações de Personalização (Textos, Músicas, Chave Pix)
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Inserir frase bíblica, chave Pix do casal e horário da recepção..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              />
            </div>

            <div className="pt-2 flex items-center justify-end gap-2">
              <Button type="button" variant="ghost" onClick={onClose} className="text-[#4B2E20] rounded-xl">
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#352016] text-[#F7EBDD] font-bold rounded-xl border border-[#D4AF37]/40"
              >
                Cadastrar Pedido
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

