import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Calendar,
  Phone,
  Search,
  PlusCircle,
  Filter,
  Trash2,
  Clock,
  Sparkles,
} from 'lucide-react';

interface OrdersManagerProps {
  orders: Order[];
  onUpdateOrderStatus: (orderId: string, status: OrderStatus) => void;
  onUpdatePaymentStatus: (orderId: string, status: PaymentStatus, paidValue: number) => void;
  onDeleteOrder: (orderId: string) => void;
  onOpenNewOrder: () => void;
}

export function OrdersManager({
  orders,
  onUpdateOrderStatus,
  onUpdatePaymentStatus,
  onDeleteOrder,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.includes(searchTerm);

    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return <Badge className="bg-amber-100 text-amber-900 border-amber-300">Aguardando Início</Badge>;
      case 'em_criacao':
        return <Badge className="bg-sky-100 text-sky-900 border-sky-300">Em Produção</Badge>;
      case 'aprovacao':
        return <Badge className="bg-purple-100 text-purple-900 border-purple-300">Aprovação de Arte</Badge>;
      case 'concluido':
        return <Badge className="bg-emerald-100 text-emerald-900 border-emerald-300">Entregue / Concluído</Badge>;
      case 'cancelado':
        return <Badge className="bg-rose-100 text-rose-900 border-rose-300">Cancelado</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getPaymentBadge = (status: PaymentStatus) => {
    switch (status) {
      case 'pago':
        return <Badge className="bg-emerald-100 text-emerald-900 border-emerald-300">Quitado</Badge>;
      case 'parcial':
        return <Badge className="bg-amber-100 text-amber-900 border-amber-300">Entrada Paga</Badge>;
      case 'pendente':
        return <Badge className="bg-rose-100 text-rose-900 border-rose-300">Pagamento Pendente</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Cabeçalho do Gerenciador de Pedidos */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-[#fdf9f4] p-6 rounded-3xl border border-[#D4AF37]/35 shadow-sm">
        <div>
          <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-[#D4AF37]/15 text-[#4B2E20] text-xs font-semibold mb-1">
            <Sparkles className="w-3 h-3 text-[#D4AF37]" />
            <span>Controle de Encomendas & Prazos</span>
          </div>
          <h2 className="text-2xl font-serif font-bold text-[#4B2E20]">
            Pedidos de Convites
          </h2>
          <p className="text-xs text-[#4B2E20]/70">
            Acompanhe o status de confecção, prazos de entrega e valores a receber de cada cliente.
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-2 border border-[#D4AF37]/40 shadow-sm"
        >
          <PlusCircle className="w-4 h-4 text-[#D4AF37]" />
          <span>Novo Pedido</span>
        </Button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, convite ou telefone..."
            className="pl-10 bg-[#fdf9f4] border-[#D4AF37]/40 text-xs text-[#4B2E20] rounded-xl h-10"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          <Filter className="w-3.5 h-3.5 text-[#D4AF37] shrink-0" />
          {[
            { id: 'all', label: 'Todos' },
            { id: 'em_criacao', label: 'Em Produção' },
            { id: 'aprovacao', label: 'Aprovação' },
            { id: 'concluido', label: 'Concluídos' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setStatusFilter(tab.id)}
              className={`px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                statusFilter === tab.id
                  ? 'bg-[#4B2E20] text-[#F7EBDD]'
                  : 'bg-[#fcf7f0] text-[#4B2E20]/80 border border-[#D4AF37]/35 hover:bg-[#ebdccb]'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Lista de Pedidos */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-[#fdf9f4] border-dashed border-[#D4AF37]/45 py-12 text-center rounded-3xl">
          <CardContent className="space-y-2">
            <Clock className="w-8 h-8 text-[#D4AF37] mx-auto" />
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum pedido encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70">Nenhuma encomenda bate com os filtros atuais.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {filteredOrders.map((order) => (
            <Card
              key={order.id}
              className="bg-[#fdf9f4] border-[#D4AF37]/35 hover:border-[#D4AF37] transition-all rounded-3xl p-5 shadow-sm"
            >
              <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">

                {/* Dados do Cliente e Convite */}
                <div className="space-y-1.5 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-serif font-bold text-base text-[#4B2E20]">
                      {order.clientName}
                    </span>
                    {getStatusBadge(order.status)}
                    {getPaymentBadge(order.paymentStatus)}
                  </div>

                  <p className="text-xs text-[#4B2E20]/80 font-medium">
                    Modelo: <span className="font-semibold text-[#4B2E20]">{order.templateTitle}</span> • {order.quantity} unidades ({order.category})
                  </p>

                  <div className="flex flex-wrap items-center gap-4 text-[11px] text-[#4B2E20]/70 pt-1">
                    {order.clientWhatsapp && (
                      <span className="flex items-center gap-1">
                        <Phone className="w-3 h-3 text-[#D4AF37]" />
                        {order.clientWhatsapp}
                      </span>
                    )}
                    <span className="flex items-center gap-1">
                      <Calendar className="w-3 h-3 text-[#D4AF37]" />
                      Entrega: <strong className="text-[#4B2E20]">{order.deadlineDate}</strong>
                    </span>
                    {order.eventDate && (
                      <span>Evento: {order.eventDate}</span>
                    )}
                  </div>
                </div>

                {/* Valores e Ações Rápidas */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between lg:justify-end gap-4 border-t lg:border-t-0 border-[#D4AF37]/20 pt-3 lg:pt-0">
                  <div className="text-left sm:text-right">
                    <div className="text-xs text-[#4B2E20]/60 font-semibold uppercase">Total</div>
                    <div className="text-base font-bold text-[#4B2E20]">
                      R$ {order.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </div>
                    <div className="text-[11px] text-[#855729]">
                      Pago: R$ {order.paidValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {/* Alterar Status */}
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as OrderStatus)}
                      className="h-9 px-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:ring-1 focus:ring-[#D4AF37]"
                    >
                      <option value="pendente">Pendente</option>
                      <option value="em_criacao">Em Produção</option>
                      <option value="aprovacao">Aprovação</option>
                      <option value="concluido">Concluído</option>
                      <option value="cancelado">Cancelado</option>
                    </select>

                    {/* Excluir Pedido */}
                    <button
                      onClick={() => onDeleteOrder(order.id)}
                      className="p-2 rounded-xl text-rose-700 hover:bg-rose-100/70 transition-colors"
                      title="Excluir pedido"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>

              </div>
            </Card>
          ))}
        </div>
      )}

    </div>
  );
}

