import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Heart, Sparkles, Smartphone, ShieldCheck } from 'lucide-react';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Autenticação Administrativa com senha fixa "41526378"
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState<boolean>(false);

  // Modais de Criação
  const [isNewOrderOpen, setIsNewOrderOpen] = useState(false);
  const [isNewTemplateOpen, setIsNewTemplateOpen] = useState(false);
  const [preSelectedTemplate, setPreSelectedTemplate] = useState<InvitationTemplate | null>(null);

  // Salvar Novo Pedido Digital
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  // Salvar Novo Modelo Digital
  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  // Atualizar Status do Pedido
  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, status } : ord))
    );
  };

  // Atualizar Pagamento
  const handleUpdatePaymentStatus = (
    orderId: string,
    status: PaymentStatus,
    paidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, paymentStatus: status, paidValue } : ord))
    );
  };

  // Excluir Pedido
  const handleDeleteOrder = (orderId: string) => {
    setOrders((prev) => prev.filter((ord) => ord.id !== orderId));
  };

  // Pedidos Pendentes de entrega
  const pendingOrdersCount = orders.filter(
    (o) => o.status !== 'concluido' && o.status !== 'cancelado'
  ).length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminLoginOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => {
          setPreSelectedTemplate(null);
          setIsNewOrderOpen(true);
        }}
        onOpenNewTemplate={() => setIsNewTemplateOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-10">

        {/* Catálogo de Modelos de Convites Digitais */}
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSelectTemplateToOrder={(template) => {
              setPreSelectedTemplate(template);
              setIsNewOrderOpen(true);
            }}
            isAdminAuthenticated={isAdminAuthenticated}
            onOpenNewTemplate={() => setIsNewTemplateOpen(true)}
          />
        )}

        {/* Gerenciador de Pedidos Digitais (Área Administrativa) */}
        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onUpdatePaymentStatus={handleUpdatePaymentStatus}
            onDeleteOrder={handleDeleteOrder}
            onOpenNewOrder={() => {
              setPreSelectedTemplate(null);
              setIsNewOrderOpen(true);
            }}
          />
        )}

        {/* Dashboard de Ganhos Financeiros (Área Administrativa) */}
        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            onOpenNewOrder={() => {
              setPreSelectedTemplate(null);
              setIsNewOrderOpen(true);
            }}
          />
        )}

        {/* Caso o usuário tente acessar pedidos/ganhos sem autenticação */}
        {(currentTab === 'orders' || currentTab === 'dashboard') && !isAdminAuthenticated && (
          <div className="text-center py-20 space-y-4 max-w-md mx-auto">
            <div className="w-16 h-16 mx-auto rounded-3xl bg-[#4B2E20] flex items-center justify-center text-[#D4AF37] shadow-xl">
              <ShieldCheck className="w-8 h-8" />
            </div>
            <h2 className="text-2xl font-serif font-bold text-[#4B2E20]">Acesso Restrito</h2>
            <p className="text-xs text-[#4B2E20]/80">
              Essa área é exclusiva da administração da Keh Convites. Por favor, insira a senha de acesso para gerenciar pedidos e ganhos.
            </p>
            <button
              onClick={() => setIsAdminLoginOpen(true)}
              className="px-6 py-2.5 rounded-xl bg-[#4B2E20] text-[#F7EBDD] font-bold text-xs border border-[#D4AF37]/50 shadow-md hover:bg-[#352016] transition-colors"
            >
              Inserir Senha de Acesso
            </button>
          </div>
        )}
      </main>

      {/* Rodapé Delicado & Profissional */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ebdccb]/70 py-8 px-4 text-center space-y-3">
        <div className="flex items-center justify-center gap-2 text-[#4B2E20] font-serif font-bold text-base">
          <Smartphone className="w-4 h-4 text-[#D4AF37]" />
          <span>Keh Convites • Ateliê de Convites Digitais & Interativos</span>
        </div>
        <p className="text-xs text-[#4B2E20]/80 max-w-lg mx-auto">
          Convites digitais inteligentes com botões clicáveis de confirmação no WhatsApp, localização GPS no Google Maps e lista de presentes. Elegância na tela do celular de cada convidado.
        </p>
        <div className="flex items-center justify-center gap-1.5 text-[11px] text-[#4B2E20]/70 pt-1">
          <span>Feito com</span>
          <Heart className="w-3 h-3 text-[#D4AF37] fill-[#D4AF37]" />
          <span>para momentos inesquecíveis</span>
        </div>
      </footer>

      {/* Modal de Login Administrativo */}
      <AdminLoginModal
        isOpen={isAdminLoginOpen}
        onClose={() => setIsAdminLoginOpen(false)}
        onSuccess={() => {
          setIsAdminAuthenticated(true);
          setIsAdminLoginOpen(false);
          setCurrentTab('orders');
        }}
      />

      {/* Modal de Novo Pedido Digital */}
      <NewOrderModal
        isOpen={isNewOrderOpen}
        onClose={() => {
          setIsNewOrderOpen(false);
          setPreSelectedTemplate(null);
        }}
        templates={templates}
        preSelectedTemplate={preSelectedTemplate}
        onSaveOrder={handleSaveOrder}
      />

      {/* Modal de Novo Modelo Digital */}
      <NewTemplateModal
        isOpen={isNewTemplateOpen}
        onClose={() => setIsNewTemplateOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

