                      : 'text-[#4B2E20]/80 hover:text-[#4B2E20] hover:bg-[#F7EBDD]/60'
                  }`}
                >
                  <Layers className={`w-3.5 h-3.5 ${currentTab === 'orders' ? 'text-[#D4AF37]' : 'text-[#4B2E20]/60'}`} />
                  <span>Gerenciar Pedidos</span>
                  {pendingOrdersCount > 0 && (
                    <span className="text-[10px] px-2 py-0.5 rounded-full font-bold bg-[#D4AF37] text-[#4B2E20]">
                      {pendingOrdersCount}
                    </span>
                  )}
                </button>

                <button
                  onClick={() => setCurrentTab('dashboard')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-semibold tracking-wide transition-all ${
                    currentTab === 'dashboard'
                      ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                      : 'text-[#4B2E20]/80 hover:text-[#4B2E20] hover:bg-[#F7EBDD]/60'
                  }`}
                >
                  <DollarSign className={`w-3.5 h-3.5 ${currentTab === 'dashboard' ? 'text-[#D4AF37]' : 'text-[#4B2E20]/60'}`} />
                  <span>Meus Ganhos</span>
                </button>
              </nav>
            ) : (
              <div className="flex items-center gap-2">
                <span className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-[#D4AF37]/15 border border-[#D4AF37]/35 text-xs font-medium text-[#4B2E20]">
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Cards WhatsApp • Interativos em PDF • Vídeos Animados • Save The Date</span>
                </span>
              </div>
            )}
          </div>

          {/* Ações da Direita */}
          <div className="flex items-center gap-2">
            {isAdminAuthenticated ? (
              <>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={onOpenNewTemplate}
                  className="hidden sm:inline-flex border-[#D4AF37]/50 bg-[#fbf5ed] text-[#4B2E20] hover:bg-[#ebdccb] hover:border-[#D4AF37] text-xs font-semibold rounded-xl"
                >
                  <Sparkles className="w-3.5 h-3.5 mr-1.5 text-[#D4AF37]" />
                  Novo Modelo Digital
                </Button>

                <Button
                  size="sm"
                  onClick={onOpenNewOrder}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center gap-1.5"
                >
                  <Plus className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Novo Pedido</span>
                </Button>

                <button
                  onClick={onLogoutAdmin}
                  title="Sair da Área Administrativa"
                  className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium text-[#4B2E20] hover:bg-[#ebdccb] border border-[#D4AF37]/30 transition-colors"
                >
                  <LogOut className="w-3.5 h-3.5 text-[#855729]" />
                  <span className="hidden sm:inline text-[11px] font-semibold">Sair</span>
                </button>
              </>
            ) : (
              <Button
                size="sm"
                onClick={onOpenAdminAuth}
                className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center gap-1.5 hover:scale-[1.02] transition-transform"
              >
                <Lock className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Área Restrita</span>
              </Button>
            )}
          </div>

        </div>
      </div>

      {/* Menu Inferior Mobile para Área Administrativa */}
      {isAdminAuthenticated && (
        <div className="flex md:hidden border-t border-[#D4AF37]/25 bg-[#F7EBDD] px-4 py-2 justify-around items-center">
          <button
            onClick={() => setCurrentTab('templates')}
            className={`flex flex-col items-center text-[10px] gap-1 ${
              currentTab === 'templates' ? 'text-[#4B2E20] font-bold' : 'text-[#4B2E20]/60'
            }`}
          >
            <FolderHeart className="w-4 h-4" />
            <span>Modelos</span>
          </button>
          <button
            onClick={() => setCurrentTab('orders')}
            className={`flex flex-col items-center text-[10px] gap-1 ${
              currentTab === 'orders' ? 'text-[#4B2E20] font-bold' : 'text-[#4B2E20]/60'
            }`}
          >
            <Layers className="w-4 h-4" />
            <span>Pedidos</span>
          </button>
          <button
            onClick={() => setCurrentTab('dashboard')}
            className={`flex flex-col items-center text-[10px] gap-1 ${
              currentTab === 'dashboard' ? 'text-[#4B2E20] font-bold' : 'text-[#4B2E20]/60'
            }`}
          >
            <DollarSign className="w-4 h-4" />
            <span>Ganhos</span>
          </button>
        </div>
      )}
    </header>
  );
}

