import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Sparkles,
  Smartphone,
  MousePointerClick,
  MapPin,
  CheckCircle2,
  Gift,
  Share2,
  CalendarCheck,
  MessageCircle,
  Eye,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplateToOrder: (template: InvitationTemplate) => void;
  isAdminAuthenticated: boolean;
  onOpenNewTemplate?: () => void;
}

const categories: ('Todas' | InvitationCategory)[] = [
  'Todas',
  'Casamento',
  '15 Anos',
  'Infantil',
  'Batizado',
  'Corporativo',
  'Bodas',
];

export function TemplatesCatalog({
  templates,
  onSelectTemplateToOrder,
  isAdminAuthenticated,
  onOpenNewTemplate,
