  const [selectedCategory, setSelectedCategory] = useState<'Todas' | InvitationCategory>('Todas');
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  const filteredTemplates = (templates || []).filter((tpl) => {
    return selectedCategory === 'Todas' ? true : tpl?.category === selectedCategory;
  });

  const handleOpenWhatsappOrder = (template: InvitationTemplate) => {
    const text = encodeURIComponent(
      `Olá Keh Convites! Amei o convite digital "${template.title}" (R$ ${template.price.toFixed(2)}) e gostaria de encomendar para o meu evento.`
    );
    window.open(`https://wa.me/5511999999999?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in">

      {/* Banner Principal com Foco em Convites Digitais */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#4B2E20] via-[#352016] to-[#20120b] text-[#F7EBDD] p-6 sm:p-10 shadow-2xl border border-[#D4AF37]/50">
        <div className="relative z-10 max-w-3xl space-y-4">

          <div className="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/45 text-[#D4AF37] text-xs font-semibold tracking-wide">
            <Smartphone className="w-3.5 h-3.5" />
            <span>100% Digital, Interativo & Ecológico</span>
          </div>

          <h1 className="text-2xl sm:text-4xl lg:text-5xl font-serif font-bold tracking-tight text-[#F7EBDD] leading-tight">
            Convites Digitais Interativos <br className="hidden sm:inline" />
            <span className="text-[#D4AF37] italic font-normal">feitos com sofisticação</span>
          </h1>

          <p className="text-xs sm:text-base text-[#F7EBDD]/85 leading-relaxed font-normal max-w-2xl">
            Seus convidados confirmam presença no WhatsApp, abrem o Google Maps para chegar ao local e acessam a lista de presentes em apenas <strong>1 clique na tela do celular</strong>.
          </p>

          {/* Destaques Rápidos da Tecnologia Digital */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5 pt-2">
            <div className="bg-[#fcf8f3]/10 backdrop-blur-sm border border-[#D4AF37]/30 rounded-2xl p-2.5 text-center">
              <MousePointerClick className="w-4 h-4 text-[#D4AF37] mx-auto mb-1" />
              <div className="text-[11px] font-bold text-[#F7EBDD]">Botões Clicáveis</div>
              <div className="text-[9px] text-[#F7EBDD]/70">RSVP & Presentes</div>
            </div>

            <div className="bg-[#fcf8f3]/10 backdrop-blur-sm border border-[#D4AF37]/30 rounded-2xl p-2.5 text-center">
              <MapPin className="w-4 h-4 text-[#D4AF37] mx-auto mb-1" />
              <div className="text-[11px] font-bold text-[#F7EBDD]">GPS Integrado</div>
              <div className="text-[9px] text-[#F7EBDD]/70">Google Maps / Waze</div>
            </div>

            <div className="bg-[#fcf8f3]/10 backdrop-blur-sm border border-[#D4AF37]/30 rounded-2xl p-2.5 text-center">
              <Share2 className="w-4 h-4 text-[#D4AF37] mx-auto mb-1" />
              <div className="text-[11px] font-bold text-[#F7EBDD]">Envio Instantâneo</div>
              <div className="text-[9px] text-[#F7EBDD]/70">Pelo WhatsApp</div>
            </div>

            <div className="bg-[#fcf8f3]/10 backdrop-blur-sm border border-[#D4AF37]/30 rounded-2xl p-2.5 text-center">
              <Gift className="w-4 h-4 text-[#D4AF37] mx-auto mb-1" />
              <div className="text-[11px] font-bold text-[#F7EBDD]">Chave Pix & Lista</div>
              <div className="text-[9px] text-[#F7EBDD]/70">Sem burocracia</div>
            </div>
          </div>
        </div>

        {/* Efeito Glow Dourado de Fundo */}
        <div className="absolute -right-14 -bottom-14 w-80 h-80 bg-[#D4AF37]/15 rounded-full blur-3xl pointer-events-none" />
      </div>

      {/* Categorias dos Convites Digitais */}
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 max-w-full">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-4 py-2 rounded-2xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-[#fdf9f4] text-[#4B2E20]/80 border border-[#D4AF37]/35 hover:bg-[#ecdccb]'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {isAdminAuthenticated && onOpenNewTemplate && (
          <Button
            size="sm"
            onClick={onOpenNewTemplate}
            className="bg-[#4B2E20] hover:bg-[#352016] text-[#F7EBDD] font-semibold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm"
          >
            <Sparkles className="w-3.5 h-3.5 mr-1.5 text-[#D4AF37]" />
            Cadastrar Novo Modelo
          </Button>
        )}
      </div>

      {/* Grid de Modelos Digitais */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredTemplates.map((template) => (
          <Card
            key={template.id}
            className="group overflow-hidden rounded-3xl bg-[#fdf9f4] border-[#D4AF37]/40 hover:border-[#D4AF37] hover:shadow-xl transition-all duration-300 flex flex-col justify-between"
          >
            <div>
              {/* Foto do Convite com moldura mobile */}
              <div className="relative aspect-[4/3] overflow-hidden bg-[#ecdccb]/50">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  loading="lazy"
                />

                {/* Tag de Categoria e Badge de Digital Interativo */}
                <div className="absolute top-3 left-3 flex flex-col gap-1 items-start">
                  <Badge className="bg-[#4B2E20]/90 text-[#F7EBDD] text-[10px] font-bold border border-[#D4AF37]/40 backdrop-blur-sm">
                    {template.category}
                  </Badge>
                  <span className="inline-flex items-center gap-1 bg-[#F7EBDD]/95 text-[#4B2E20] text-[9px] font-bold px-2 py-0.5 rounded-full border border-[#D4AF37]/50 shadow-sm">
                    <Smartphone className="w-2.5 h-2.5 text-[#D4AF37]" />
                    Interativo Celular
                  </span>
                </div>

                {/* Preço em Destaque */}
                <div className="absolute bottom-3 right-3 bg-[#4B2E20]/95 backdrop-blur-md px-3 py-1.5 rounded-xl border border-[#D4AF37]/50 shadow-md">
                  <span className="text-[10px] text-[#F7EBDD]/70 block font-medium">Apenas</span>
                  <span className="text-sm font-black text-[#D4AF37]">
                    R$ {template.price.toFixed(2)}
                  </span>
                </div>
              </div>

              {/* Informações e Recursos Digitais */}
              <CardContent className="p-5 space-y-3">
                <h3 className="font-serif font-bold text-base text-[#4B2E20] group-hover:text-[#855729] transition-colors">
                  {template.title}
                </h3>

                <p className="text-xs text-[#4B2E20]/80 line-clamp-2 leading-relaxed">
                  {template.description}
                </p>

                {/* Recursos inclusos no convite */}
                <div className="space-y-1.5 pt-1 border-t border-[#D4AF37]/25">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#4B2E20]/70 flex items-center gap-1">
                    <MousePointerClick className="w-3 h-3 text-[#D4AF37]" />
                    Botões Inclusos no Convite:
                  </span>
                  <div className="grid grid-cols-2 gap-1 text-[11px] text-[#4B2E20]/90">
                    <span className="flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3 text-[#D4AF37] shrink-0" />
                      Confirmação RSVP
                    </span>
                    <span className="flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3 text-[#D4AF37] shrink-0" />
                      Google Maps GPS
                    </span>
                    <span className="flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3 text-[#D4AF37] shrink-0" />
                      Lista de Presentes
                    </span>
                    <span className="flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3 text-[#D4AF37] shrink-0" />
                      PDF Alta Resolução
                    </span>
                  </div>
                </div>

                {/* Tags */}
                <div className="flex flex-wrap gap-1.5 pt-1">
                  {template.tags?.map((tag, i) => (
                    <span
                      key={i}
                      className="text-[10px] px-2 py-0.5 rounded-lg bg-[#ecdccb]/50 border border-[#D4AF37]/30 text-[#4B2E20]/80 font-medium"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </CardContent>
            </div>

            {/* Ações */}
            <div className="p-5 pt-0 grid grid-cols-2 gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPreviewTemplate(template)}
                className="border-[#D4AF37]/45 text-[#4B2E20] hover:bg-[#ecdccb] rounded-xl text-xs font-semibold flex items-center justify-center gap-1"
              >
                <Eye className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Ver Demonstração</span>
              </Button>

              {isAdminAuthenticated ? (
                <Button
                  size="sm"
                  onClick={() => onSelectTemplateToOrder(template)}
                  className="bg-[#4B2E20] hover:bg-[#352016] text-[#F7EBDD] rounded-xl text-xs font-semibold flex items-center justify-center gap-1 border border-[#D4AF37]/40"
                >
                  <CalendarCheck className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Criar Pedido</span>
                </Button>
              ) : (
                <Button
                  size="sm"
                  onClick={() => handleOpenWhatsappOrder(template)}
                  className="bg-[#4B2E20] hover:bg-[#352016] text-[#F7EBDD] rounded-xl text-xs font-semibold flex items-center justify-center gap-1 border border-[#D4AF37]/40 shadow-sm"
                >
                  <MessageCircle className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Pedir no Whats</span>
                </Button>
              )}
            </div>
          </Card>
        ))}
      </div>

      {/* Modal Interativo de Demonstração Mobile */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <div className="max-w-sm w-full bg-[#fdf9f4] rounded-3xl border-2 border-[#D4AF37] p-6 shadow-2xl relative">
            <div className="text-center space-y-2 mb-4">
              <div className="inline-flex items-center gap-1 px-3 py-0.5 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] text-[11px] font-bold">
                <Smartphone className="w-3 h-3 text-[#D4AF37]" />
                Simulador do Convite no Celular
              </div>
              <h3 className="font-serif font-bold text-lg text-[#4B2E20]">
                {previewTemplate.title}
              </h3>
              <p className="text-xs text-[#4B2E20]/70">
                Assim é como os convidados visualizam no WhatsApp e clicam nos botões:
              </p>
            </div>

            {/* Mockup da tela do celular */}
            <div className="rounded-2xl overflow-hidden border border-[#D4AF37]/40 shadow-inner bg-white mb-4">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-44 object-cover"
              />
              <div className="p-3 space-y-2 bg-[#fcf8f3]">
                <div className="text-center">
                  <div className="font-serif font-bold text-xs text-[#4B2E20]">
                    Celebre Conosco esse Momento Especial!
                  </div>
                  <div className="text-[10px] text-[#4B2E20]/70">
                    Toque nos botões interativos abaixo:
                  </div>
                </div>

                <div className="space-y-1.5 pt-1">
                  <button
                    onClick={() => alert('Simulação: Esse botão abre o WhatsApp direto para confirmação de presença do convidado (RSVP)!')}
                    className="w-full py-2 px-3 rounded-xl bg-[#4B2E20] text-[#F7EBDD] font-bold text-[11px] flex items-center justify-center gap-1.5 border border-[#D4AF37]/40 hover:bg-[#352016] transition-colors"
                  >
                    <CheckCircle2 className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Confirmar Presença (WhatsApp)</span>
                  </button>

                  <button
                    onClick={() => alert('Simulação: Esse botão abre as rotas no Google Maps ou Waze para o convidado chegar ao local do evento!')}
                    className="w-full py-2 px-3 rounded-xl bg-[#F7EBDD] text-[#4B2E20] font-bold text-[11px] flex items-center justify-center gap-1.5 border border-[#D4AF37]/60 hover:bg-[#ecdccb] transition-colors"
                  >
                    <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Como Chegar (Google Maps)</span>
                  </button>

                  <button
                    onClick={() => alert('Simulação: Esse botão direciona para a Chave Pix ou lista de presentes online do casal!')}
                    className="w-full py-2 px-3 rounded-xl bg-[#F7EBDD] text-[#4B2E20] font-bold text-[11px] flex items-center justify-center gap-1.5 border border-[#D4AF37]/60 hover:bg-[#ecdccb] transition-colors"
                  >
                    <Gift className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Lista de Presentes & Chave Pix</span>
                  </button>
                </div>
              </div>
            </div>

            <div className="flex gap-2">
              <Button
                variant="outline"
                className="w-1/2 rounded-xl text-xs text-[#4B2E20] border-[#D4AF37]/40"
                onClick={() => setPreviewTemplate(null)}
              >
                Fechar
              </Button>

              <Button
                className="w-1/2 rounded-xl text-xs bg-[#4B2E20] text-[#F7EBDD] hover:bg-[#352016] border border-[#D4AF37]/40 font-bold"
                onClick={() => {
                  const tpl = previewTemplate;
                  setPreviewTemplate(null);
                  handleOpenWhatsappOrder(tpl);
                }}
              >
                Pedir Este
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

