  save_the_date: {
    label: 'Save The Date Digital',
    icon: <CalendarDays className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
  },
  kit_digital: {
    label: 'Kit Digital Completo',
    icon: <Package className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
  },
  site_rsvp: {
    label: 'Página Web do Evento',
    icon: <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
  },
};

export function TemplatesCatalog({
  templates,
  onSelectTemplateToOrder,
  isAdminAuthenticated = false,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedFormat, setSelectedFormat] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPreview, setSelectedPreview] = useState<InvitationTemplate | null>(null);

  const categories: InvitationCategory[] = [
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesCategory = selectedCategory === 'all' || tpl.category === selectedCategory;
    const matchesFormat = selectedFormat === 'all' || tpl.format === selectedFormat;
    const matchesSearch =
      tpl.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.tags.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase()));

    return matchesCategory && matchesFormat && matchesSearch;
  });

  const handleEncomendarWhatsApp = (template: InvitationTemplate) => {
    const formatName = formatLabels[template.format]?.label || 'Digital';
    const message = encodeURIComponent(
      `Olá Keh Convites! Adorei o modelo de convite digital "${template.title}" (${formatName} - R$ ${template.price.toFixed(2)}). Gostaria de fazer uma encomenda personalizada para o meu evento!`
    );
    window.open(`https://wa.me/5511999999999?text=${message}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in">

      {/* Banner de Apresentação de Todos os Modelos */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#4B2E20] via-[#3a2217] to-[#25150d] text-[#F7EBDD] p-6 sm:p-10 shadow-xl border border-[#D4AF37]/45">
        <div className="relative z-10 max-w-2xl space-y-3.5">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/40 text-[#D4AF37] text-xs font-semibold tracking-wide">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Ateliê Keh Convites • Modelos para Todos os Gostos</span>
          </div>

          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-serif font-bold tracking-tight text-[#F7EBDD]">
            Convites Digitais em Diversos Modelos & Formatos
          </h1>

          <p className="text-xs sm:text-sm text-[#F7EBDD]/80 leading-relaxed font-normal">
            Escolha o formato ideal para o seu evento: <strong className="text-[#F7EBDD]">Cards em imagem para WhatsApp</strong>, <strong className="text-[#F7EBDD]">Convites Interativos em PDF com botões clicáveis</strong> (RSVP e Mapa), <strong className="text-[#F7EBDD]">Vídeos Animados com música</strong> ou <strong className="text-[#F7EBDD]">Save The Date</strong>. Personalizamos textos, cores, fotos e links.
          </p>

          <div className="flex flex-wrap items-center gap-3 pt-2 text-xs text-[#D4AF37]">
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Entrega Direto no WhatsApp
            </span>
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Sem Custo de Frete
            </span>
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Envio Ilimitado aos Convidados
            </span>
          </div>
        </div>

        {/* Efeito Glow Dourado */}
        <div className="absolute -right-10 -bottom-10 w-64 h-64 bg-[#D4AF37]/15 rounded-full blur-3xl pointer-events-none" />
      </div>

      {/* Barra de Busca e Filtros de Formato e Categoria */}
      <div className="space-y-4">

        {/* Barra de Pesquisa */}
        <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
          <div className="relative flex-1 max-w-md">
            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Buscar por tema, modelo, formato ou detalhes..."
              className="pl-10 bg-[#fdf9f4] border-[#D4AF37]/40 text-xs text-[#4B2E20] rounded-xl h-10 shadow-sm"
            />
          </div>

          <div className="text-xs text-[#4B2E20]/80 font-medium self-center">
            Mostrando <strong>{filteredTemplates.length}</strong> de {templates.length} modelos
          </div>
        </div>

        {/* Filtros por Formato Digital */}
        <div className="space-y-1.5">
          <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20]/70 block">
            Filtrar por Formato do Convite Digital:
          </span>
          <div className="flex items-center gap-2 overflow-x-auto pb-1">
            {[
              { id: 'all', label: 'Todos os Formatos', icon: <Sparkles className="w-3.5 h-3.5" /> },
              { id: 'imagem_card', label: 'Cards em Imagem (WhatsApp)', icon: <ImageIcon className="w-3.5 h-3.5" /> },
              { id: 'interativo_pdf', label: 'Interativos em PDF (Botões)', icon: <Smartphone className="w-3.5 h-3.5" /> },
              { id: 'animado_video', label: 'Vídeos Animados', icon: <Video className="w-3.5 h-3.5" /> },
              { id: 'save_the_date', label: 'Save The Date', icon: <CalendarDays className="w-3.5 h-3.5" /> },
              { id: 'kit_digital', label: 'Kits Digitais Completos', icon: <Package className="w-3.5 h-3.5" /> },
            ].map((fmt) => (
              <button
                key={fmt.id}
                onClick={() => setSelectedFormat(fmt.id)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all border ${
                  selectedFormat === fmt.id
                    ? 'bg-[#4B2E20] text-[#F7EBDD] border-[#4B2E20] shadow-sm'
                    : 'bg-[#fdf9f4] text-[#4B2E20]/80 border-[#D4AF37]/30 hover:bg-[#ebdccb]'
                }`}
              >
                {fmt.icon}
                <span>{fmt.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Filtros por Categoria do Evento */}
        <div className="space-y-1.5">
          <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20]/70 block">
            Filtrar por Ocasião:
          </span>
          <div className="flex items-center gap-1.5 overflow-x-auto pb-1">
            <button
              onClick={() => setSelectedCategory('all')}
              className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${
                selectedCategory === 'all'
                  ? 'bg-[#D4AF37] text-[#4B2E20] font-bold'
                  : 'bg-[#fdf9f4] text-[#4B2E20]/70 hover:bg-[#ebdccb]'
              }`}
            >
              Todas as Ocasiões
            </button>
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${
                  selectedCategory === cat
                    ? 'bg-[#D4AF37] text-[#4B2E20] font-bold'
                    : 'bg-[#fdf9f4] text-[#4B2E20]/70 hover:bg-[#ebdccb]'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

      </div>

      {/* Grid de Modelos de Convites */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-[#fdf9f4] border-dashed border-[#D4AF37]/45 py-12 text-center rounded-3xl">
          <CardContent className="space-y-2">
            <Sparkles className="w-8 h-8 text-[#D4AF37] mx-auto" />
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum modelo encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70">Tente ajustar a busca ou os filtros de formato e ocasião.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => {
            const formatInfo = formatLabels[template.format] || formatLabels.interativo_pdf;

            return (
              <Card
                key={template.id}
                className="group overflow-hidden bg-[#fdf9f4] border-[#D4AF37]/35 hover:border-[#D4AF37] transition-all duration-300 shadow-md hover:shadow-xl rounded-3xl flex flex-col justify-between"
              >
                <div>
                  {/* Foto de Capa com Badges */}
                  <div className="relative aspect-[4/3] w-full overflow-hidden bg-[#ecdccb]/50">
                    <img
                      src={template.imageUrl}
                      alt={template.title}
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                      loading="lazy"
                    />

                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/20" />

                    {/* Badge de Formato Digital */}
                    <div className="absolute top-3 left-3 flex flex-col gap-1.5 items-start">
                      <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold bg-[#4B2E20]/90 text-[#F7EBDD] backdrop-blur-sm border border-[#D4AF37]/50 shadow-sm">
                        {formatInfo.icon}
                        <span>{formatInfo.label}</span>
                      </span>
                    </div>

                    {/* Categoria */}
                    <div className="absolute top-3 right-3">
                      <Badge className="bg-[#D4AF37] text-[#4B2E20] font-bold text-[10px] shadow-sm">
                        {template.category}
                      </Badge>
                    </div>

                    {/* Preço de Aquisição */}
                    <div className="absolute bottom-3 left-3 text-white">
                      <div className="text-[10px] uppercase font-semibold text-[#F7EBDD]/80">A partir de</div>
                      <div className="text-xl font-bold font-serif text-[#F7EBDD] drop-shadow-sm">
                        R$ {template.price.toFixed(2)}
                      </div>
                    </div>

                    {/* Botão de Ver Prévia */}
                    <button
                      onClick={() => setSelectedPreview(template)}
                      className="absolute bottom-3 right-3 p-2 rounded-xl bg-white/90 hover:bg-white text-[#4B2E20] shadow-md transition-all hover:scale-105"
                      title="Ver Detalhes do Modelo"
                    >
                      <Eye className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Conteúdo do Card */}
                  <div className="p-5 space-y-3">
                    <h3 className="font-serif font-bold text-base text-[#4B2E20] line-clamp-1 group-hover:text-[#855729] transition-colors">
                      {template.title}
                    </h3>

                    <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                      {template.description}
                    </p>

                    {/* Tags do Modelo */}
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      {(template.tags || []).slice(0, 3).map((tag, i) => (
                        <span
                          key={i}
                          className="text-[10px] px-2 py-0.5 rounded-md bg-[#ecdccb]/60 text-[#4B2E20] font-medium border border-[#D4AF37]/25"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Ações do Card */}
                <div className="p-5 pt-0 space-y-2">
                  <div className="flex gap-2">
                    <Button
                      onClick={() => handleEncomendarWhatsApp(template)}
                      className="flex-1 bg-[#25D366] hover:bg-[#20ba5a] text-white font-bold text-xs rounded-xl shadow-sm flex items-center justify-center gap-1.5"
                    >
                      <MessageCircle className="w-3.5 h-3.5" />
                      <span>Pedir no WhatsApp</span>
                    </Button>

                    {isAdminAuthenticated && onSelectTemplateToOrder && (
                      <Button
                        onClick={() => onSelectTemplateToOrder(template)}
                        variant="outline"
                        className="border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ebdccb] text-xs font-semibold rounded-xl"
                        title="Criar Pedido com Este Modelo"
                      >
                        Pedido
                      </Button>
                    )}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Prévia / Detalhes do Modelo */}
      {selectedPreview && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-lg w-full bg-[#fdf9f4] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[90vh] flex flex-col">
            <div className="relative aspect-[16/10] w-full bg-black/10">
              <img
                src={selectedPreview.imageUrl}
                alt={selectedPreview.title}
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => setSelectedPreview(null)}
                className="absolute top-3 right-3 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center hover:bg-black/80 transition-colors"
              >
                ✕
              </button>
            </div>

            <div className="p-6 space-y-4 overflow-y-auto">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-[#D4AF37] uppercase tracking-wider">
                  {formatLabels[selectedPreview.format]?.label} • {selectedPreview.category}
                </span>
                <span className="text-xl font-bold font-serif text-[#4B2E20]">
                  R$ {selectedPreview.price.toFixed(2)}
                </span>
              </div>

              <h2 className="text-xl font-serif font-bold text-[#4B2E20]">
                {selectedPreview.title}
              </h2>

              <p className="text-xs text-[#4B2E20]/80 leading-relaxed">
                {selectedPreview.description}
              </p>

              {selectedPreview.features && selectedPreview.features.length > 0 && (
                <div className="space-y-1.5 pt-2">
                  <span className="text-xs font-bold text-[#4B2E20]">Recursos Inclusos:</span>
                  <ul className="space-y-1">
                    {selectedPreview.features.map((feat, i) => (
                      <li key={i} className="text-xs text-[#4B2E20]/85 flex items-center gap-1.5">
                        <CheckCircle2 className="w-3.5 h-3.5 text-[#D4AF37] shrink-0" />
                        <span>{feat}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="pt-4 flex gap-2">
                <Button
                  onClick={() => {
                    handleEncomendarWhatsApp(selectedPreview);
                    setSelectedPreview(null);
                  }}
                  className="flex-1 bg-[#25D366] hover:bg-[#20ba5a] text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5"
                >
                  <MessageCircle className="w-4 h-4" />
                  <span>Personalizar este Modelo pelo WhatsApp</span>
                </Button>
              </div>
            </div>
          </Card>
        </div>
      )}

    </div>
  );
}

