import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus, DigitalFormat } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Calendar,
  Phone,
  Search,
  PlusCircle,
  Filter,
  Trash2,
  Clock,
  Smartphone,
  Video,
  Image as ImageIcon,
  CalendarDays,
  Package,
  Send,
} from 'lucide-react';

interface OrdersManagerProps {
  orders: Order[];
  onUpdateOrderStatus: (orderId: string, status: OrderStatus) => void;
  onUpdatePaymentStatus: (orderId: string, status: PaymentStatus, paidValue: number) => void;
  onDeleteOrder: (orderId: string) => void;
  onOpenNewOrder: () => void;
}

const formatBadge = (format: DigitalFormat) => {
  switch (format) {
    case 'imagem_card':
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px] bg-[#ecdccb]/40">
          <ImageIcon className="w-2.5 h-2.5 mr-1 text-[#D4AF37]" /> Card em Imagem
        </Badge>
      );
    case 'interativo_pdf':
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px] bg-[#ecdccb]/40">
          <Smartphone className="w-2.5 h-2.5 mr-1 text-[#D4AF37]" /> PDF Interativo
        </Badge>
      );
    case 'animado_video':
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px] bg-[#ecdccb]/40">
          <Video className="w-2.5 h-2.5 mr-1 text-[#D4AF37]" /> Vídeo Animado
        </Badge>
      );
    case 'save_the_date':
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px] bg-[#ecdccb]/40">
          <CalendarDays className="w-2.5 h-2.5 mr-1 text-[#D4AF37]" /> Save The Date
        </Badge>
      );
    case 'kit_digital':
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px] bg-[#ecdccb]/40">
          <Package className="w-2.5 h-2.5 mr-1 text-[#D4AF37]" /> Kit Digital
        </Badge>
      );
    default:
      return (
        <Badge variant="outline" className="border-[#D4AF37]/50 text-[#4B2E20] text-[10px]">
          Digital
        </Badge>
      );
  }
};

export function OrdersManager({
  orders,
  onUpdateOrderStatus,
  onUpdatePaymentStatus,
  onDeleteOrder,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.includes(searchTerm);

    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return <Badge className="bg-amber-100 text-amber-900 border-amber-300">Aguardando Início</Badge>;
      case 'em_criacao':
        return <Badge className="bg-sky-100 text-sky-900 border-sky-300">Em Criação da Arte</Badge>;
      case 'aprovacao':
        return <Badge className="bg-purple-100 text-purple-900 border-purple-300">Aprovação do Cliente</Badge>;
      case 'concluido':
        return <Badge className="bg-emerald-100 text-emerald-900 border-emerald-300">Arte Final Entregue</Badge>;
      case 'cancelado':
        return <Badge className="bg-rose-100 text-rose-900 border-rose-300">Cancelado</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getPaymentBadge = (status: PaymentStatus) => {
    switch (status) {
      case 'pago':
        return <Badge className="bg-emerald-100 text-emerald-900 border-emerald-300">Quitado</Badge>;
      case 'parcial':
        return <Badge className="bg-amber-100 text-amber-900 border-amber-300">Sinal Pago</Badge>;
      case 'pendente':
        return <Badge className="bg-rose-100 text-rose-900 border-rose-300">Pagamento Pendente</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const handleSendWhatsAppNotification = (order: Order) => {
    const text = encodeURIComponent(
      `Olá ${order.clientName}! Aqui é a Keh Convites. Seu convite digital "${order.templateTitle}" já está pronto para visualização e aprovação!`
    );
    const phone = order.clientWhatsapp.replace(/\D/g, '');
    window.open(`https://wa.me/55${phone}?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Cabeçalho */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-[#fdf9f4] p-6 rounded-3xl border border-[#D4AF37]/35 shadow-sm">
        <div>
          <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-[#D4AF37]/15 text-[#4B2E20] text-xs font-semibold mb-1">
            <Smartphone className="w-3 h-3 text-[#D4AF37]" />
            <span>Fila de Produção • Todos os Modelos Digitais</span>
          </div>
          <h2 className="text-2xl font-serif font-bold text-[#4B2E20]">
            Pedidos de Convites Digitais
          </h2>
          <p className="text-xs text-[#4B2E20]/70">
            Acompanhe o status de criação dos Cards, Interativos, Vídeos e Save The Date.
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold rounded-xl text-xs flex items-center gap-2 border border-[#D4AF37]/40 shadow-sm"
        >
          <PlusCircle className="w-4 h-4 text-[#D4AF37]" />
          <span>Novo Pedido Digital</span>
        </Button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, modelo ou WhatsApp..."
            className="pl-10 bg-[#fdf9f4] border-[#D4AF37]/40 text-xs text-[#4B2E20] rounded-xl h-10"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          <Filter className="w-3.5 h-3.5 text-[#D4AF37] shrink-0" />
          {[
            { id: 'all', label: 'Todos' },
            { id: 'em_criacao', label: 'Em Criação' },
            { id: 'aprovacao', label: 'Aprovação' },
            { id: 'concluido', label: 'Entregues' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setStatusFilter(tab.id)}
              className={`px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                statusFilter === tab.id
                  ? 'bg-[#4B2E20] text-[#F7EBDD]'
                  : 'bg-[#fcf7f0] text-[#4B2E20]/80 border border-[#D4AF37]/35 hover:bg-[#ebdccb]'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Lista de Pedidos Digitais */}
      {filteredOrders.length === 0 ? (
        <Card className="bg-[#fdf9f4] border-dashed border-[#D4AF37]/45 py-12 text-center rounded-3xl">
          <CardContent className="space-y-2">
            <Clock className="w-8 h-8 text-[#D4AF37] mx-auto" />
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum pedido encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70">Nenhuma encomenda bate com os filtros atuais.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {filteredOrders.map((order) => (
            <Card
              key={order.id}
              className="bg-[#fdf9f4] border-[#D4AF37]/35 hover:border-[#D4AF37] transition-all rounded-3xl p-5 shadow-sm"
            >
              <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">

                {/* Dados do Cliente e Convite */}
                <div className="space-y-1.5 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-serif font-bold text-base text-[#4B2E20]">
                      {order.clientName}
                    </span>
                    {getStatusBadge(order.status)}
                    {getPaymentBadge(order.paymentStatus)}
                    {formatBadge(order.digitalFormat)}
                  </div>

                  <p className="text-xs text-[#4B2E20]/85 font-medium">
                    Modelo: <span className="font-semibold text-[#4B2E20]">{order.templateTitle}</span> ({order.category})
                  </p>

                  <div className="flex flex-wrap items-center gap-4 text-[11px] text-[#4B2E20]/70 pt-1">
                    {order.clientWhatsapp && (
                      <span className="flex items-center gap-1">
                        <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                        {order.clientWhatsapp}
                      </span>
                    )}

                    {order.deadlineDate && (
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                        Prazo da prévia: {order.deadlineDate}
                      </span>
                    )}

                    {order.eventDate && (
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                        Data do evento: {order.eventDate}
                      </span>
                    )}
                  </div>

                  {order.notes && (
                    <p className="text-[11px] text-[#4B2E20]/70 bg-[#ecdccb]/40 p-2 rounded-xl border border-[#D4AF37]/20 mt-1">
                      <strong>Obs:</strong> {order.notes}
                    </p>
                  )}
                </div>

                {/* Status, Valores e Ações */}
                <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 lg:border-l lg:border-[#D4AF37]/25 lg:pl-6">

                  {/* Valores */}
                  <div className="text-left sm:text-right">
                    <div className="text-xs text-[#4B2E20]/70">Valor do Convite</div>
                    <div className="text-base font-bold text-[#4B2E20]">
                      R$ {order.totalValue.toFixed(2)}
                    </div>
                    <div className="text-[10px] text-[#855729]">
                      Pago: R$ {order.paidValue.toFixed(2)}
                      {order.totalValue - order.paidValue > 0 && (
                        <span className="text-amber-800 font-semibold block">
                          Falta: R$ {(order.totalValue - order.paidValue).toFixed(2)}
                        </span>
                      )}
                    </div>
                  </div>

                  {/* Seleção de Status da Arte */}
                  <div className="flex flex-col gap-1.5">
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as OrderStatus)}
                      className="h-8 px-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium"
                    >
                      <option value="pendente">Aguardando Início</option>
                      <option value="em_criacao">Em Criação da Arte</option>
                      <option value="aprovacao">Em Aprovação</option>
                      <option value="concluido">Arte Final Entregue</option>
                      <option value="cancelado">Cancelado</option>
                    </select>

                    <div className="flex items-center gap-1.5">
                      {order.clientWhatsapp && (
                        <button
                          onClick={() => handleSendWhatsAppNotification(order)}
                          className="flex-1 px-2.5 py-1.5 rounded-xl bg-[#25D366] hover:bg-[#20ba5a] text-white text-[10px] font-bold flex items-center justify-center gap-1 shadow-sm"
                          title="Avisar cliente pelo WhatsApp"
                        >
                          <Send className="w-3 h-3" />
                          <span>Avisar no Whats</span>
                        </button>
                      )}

                      <button
                        onClick={() => {
                          if (confirm(`Excluir o pedido de ${order.clientName}?`)) {
                            onDeleteOrder(order.id);
                          }
                        }}
                        className="p-1.5 rounded-xl bg-[#ecdccb]/50 hover:bg-rose-100 text-[#4B2E20] hover:text-rose-700 transition-colors"
                        title="Excluir Pedido"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>

                </div>

              </div>
            </Card>
          ))}
        </div>
      )}

    </div>
  );
}

