  Phone,
  Calendar,
  FileCheck,
} from 'lucide-react';

export interface OrdersManagerProps {
  orders: Order[];
  setOrders?: React.Dispatch<React.SetStateAction<Order[]>>;
  onOpenNewOrder: () => void;
}

const statusConfig: Record<OrderStatus, { label: string; color: string; icon: React.ReactNode }> = {
  pendente: {
    label: 'Na Fila',
    color: 'bg-amber-100 text-amber-900 border-amber-300',
    icon: <Clock className="w-3 h-3 text-amber-700" />,
  },
  em_criacao: {
    label: 'Em Criação da Arte',
    color: 'bg-blue-100 text-blue-900 border-blue-300',
    icon: <Sparkles className="w-3 h-3 text-blue-700" />,
  },
  aprovacao: {
    label: 'Aguardando Aprovação',
    color: 'bg-purple-100 text-purple-900 border-purple-300',
    icon: <Eye className="w-3 h-3 text-purple-700" />,
  },
  concluido: {
    label: 'Entregue no WhatsApp',
    color: 'bg-emerald-100 text-emerald-900 border-emerald-300',
    icon: <CheckCircle2 className="w-3 h-3 text-emerald-700" />,
  },
  cancelado: {
    label: 'Cancelado',
    color: 'bg-rose-100 text-rose-900 border-rose-300',
    icon: <Trash2 className="w-3 h-3 text-rose-700" />,
  },
};

export function OrdersManager({ orders, setOrders, onOpenNewOrder }: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('todos');

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    if (setOrders) {
      setOrders((prev) =>
        prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
      );
    }
  };

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'todos' || order.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Top Banner & Ações */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-gradient-to-r from-[#ecdccb]/80 via-[#fcf8f3] to-[#ecdccb]/80 p-5 rounded-2xl border border-[#D4AF37]/30 shadow-sm">
        <div>
          <h2 className="text-xl font-serif font-bold text-[#4B2E20] flex items-center gap-2">
            <FileCheck className="w-5 h-5 text-[#D4AF37]" />
            <span>Gerenciamento de Pedidos de Convites</span>
          </h2>
          <p className="text-xs text-[#4B2E20]/75 mt-0.5">
            Acompanhe o status de criação, aprovação e entrega dos convites digitais
          </p>
        </div>

        <Button
          onClick={onOpenNewOrder}
          className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl shadow border border-[#D4AF37]/40 flex items-center gap-2"
        >
          <Plus className="w-4 h-4 text-[#D4AF37]" />
          <span>Cadastrar Novo Pedido</span>
        </Button>
      </div>

      {/* Busca e Filtros */}
      <div className="flex flex-col md:flex-row gap-3 items-center justify-between">
        <div className="relative w-full md:w-80">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
          <Input
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar por cliente, convite ou WhatsApp..."
            className="pl-9 bg-white border-[#D4AF37]/30 text-xs text-[#4B2E20] rounded-xl"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto w-full md:w-auto pb-1">
          <Filter className="w-3.5 h-3.5 text-[#D4AF37] shrink-0" />
          {['todos', 'pendente', 'em_criacao', 'aprovacao', 'concluido'].map((st) => (
            <button
              key={st}
              onClick={() => setStatusFilter(st)}
              className={`px-3 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all border ${
                statusFilter === st
                  ? 'bg-[#4B2E20] text-[#F7EBDD] border-[#4B2E20] shadow-sm'
                  : 'bg-white text-[#4B2E20]/80 border-[#D4AF37]/25 hover:bg-[#ecdccb]/50'
              }`}
            >
              {st === 'todos' ? 'Todos os Pedidos' : statusConfig[st as OrderStatus]?.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Pedidos */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredOrders.length === 0 ? (
          <div className="col-span-full text-center py-12 bg-white/70 rounded-2xl border border-dashed border-[#D4AF37]/40">
            <p className="text-sm text-[#4B2E20]/70 font-serif">Nenhum pedido encontrado neste filtro.</p>
          </div>
        ) : (
          filteredOrders.map((order) => {
            const st = statusConfig[order.status] || statusConfig.pendente;
            return (
              <Card
                key={order.id}
                className="bg-white/95 border-[#D4AF37]/35 rounded-2xl shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col justify-between"
              >
                <div>
                  <div className="p-4 border-b border-[#D4AF37]/20 bg-[#fdfaf6] flex items-center justify-between">
                    <div>
                      <h3 className="font-bold text-sm text-[#4B2E20]">{order.clientName}</h3>
                      <span className="text-[11px] text-[#4B2E20]/70 flex items-center gap-1">
                        <Phone className="w-3 h-3 text-[#D4AF37]" />
                        {order.clientWhatsapp || 'Sem WhatsApp informado'}
                      </span>
                    </div>

                    <Badge className={`text-[10px] border ${st.color} flex items-center gap-1`}>
                      {st.icon}
                      <span>{st.label}</span>
                    </Badge>
                  </div>

                  <div className="p-4 space-y-2.5 text-xs text-[#4B2E20]">
                    <div>
                      <span className="text-[10px] uppercase font-bold text-[#4B2E20]/60 block">Modelo Escolhido:</span>
                      <p className="font-semibold text-xs text-[#4B2E20]">{order.templateTitle}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-2 text-[11px] pt-1">
                      <div className="bg-[#fcf8f3] p-2 rounded-xl border border-[#D4AF37]/20">
                        <span className="text-[#4B2E20]/60 block text-[10px]">Data do Evento:</span>
                        <span className="font-medium flex items-center gap-1 mt-0.5">
                          <Calendar className="w-3 h-3 text-[#D4AF37]" />
                          {order.eventDate || 'Não informada'}
                        </span>
                      </div>

                      <div className="bg-[#fcf8f3] p-2 rounded-xl border border-[#D4AF37]/20">
                        <span className="text-[#4B2E20]/60 block text-[10px]">Valor Total:</span>
                        <span className="font-bold text-[#4B2E20] mt-0.5 block">
                          R$ {Number(order.totalValue || 0).toFixed(2)}
                        </span>
                      </div>
                    </div>

                    {order.notes && (
                      <div className="bg-amber-50/70 p-2 rounded-xl border border-amber-200/60 text-[11px] text-[#4B2E20]/80">
                        <strong className="block text-[#4B2E20]">Detalhes / Notas:</strong>
                        <p className="line-clamp-2">{order.notes}</p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Ações de Status */}
                <div className="p-3 bg-[#faf5ee] border-t border-[#D4AF37]/20 flex items-center justify-between gap-2">
                  <select
                    value={order.status}
                    onChange={(e) => handleUpdateStatus(order.id, e.target.value as OrderStatus)}
                    className="text-xs bg-white border border-[#D4AF37]/35 rounded-xl px-2 py-1 text-[#4B2E20] focus:outline-none"
                  >
                    <option value="pendente">Na Fila</option>
                    <option value="em_criacao">Em Criação</option>
                    <option value="aprovacao">Aguardando Aprovação</option>
                    <option value="concluido">Entregue / Concluído</option>
                    <option value="cancelado">Cancelado</option>
                  </select>

                  {order.clientWhatsapp && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => {
                        const cleanPhone = order.clientWhatsapp.replace(/\D/g, '');
                        window.open(
                          `https://wa.me/55${cleanPhone}?text=Ol%C3%A1%20${encodeURIComponent(
                            order.clientName
                          )}!%20Aqui%20%C3%A9%20a%20Keh%20Convites.%20Estou%20entrando%20em%20contato%20sobre%20o%20seu%20convite%20digital!`,
                          '_blank'
                        );
                      }}
                      className="border-[#D4AF37]/40 text-[#4B2E20] text-[11px] h-7 px-2 rounded-lg hover:bg-white"
                    >
                      <Send className="w-3 h-3 mr-1 text-[#D4AF37]" />
                      Chamar
                    </Button>
                  )}
                </div>
              </Card>
            );
          })
        )}
      </div>
    </div>
  );
}

