import React, { useState } from 'react';
import { InvitationTemplate } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Smartphone,
  Gift,
  Upload,
  CheckCircle2,
  MessageCircle,
  HelpCircle,
  Image as ImageIcon
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
}

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const isInteractiveByDefault =
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp' ||
    template.format === 'kit_digital';

  const [celebrantName, setCelebrantName] = useState('');
  const [eventDate, setEventDate] = useState('');
  const [eventTime, setEventTime] = useState('');
  const [eventLocation, setEventLocation] = useState('');
  const [specialQuote, setSpecialQuote] = useState('');
  const [clientWhatsapp, setClientWhatsapp] = useState('');

  // Opção de interação
  const [hasInteraction, setHasInteraction] = useState(isInteractiveByDefault);
  const [rsvpWhatsapp, setRsvpWhatsapp] = useState('');
  const [giftList, setGiftList] = useState('');

  // Foto anexada
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const [photoName, setPhotoName] = useState<string>('');

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setPhotoName(file.name);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendOrder = (e: React.FormEvent) => {
    e.preventDefault();

    if (!celebrantName.trim() || !clientWhatsapp.trim() || !eventDate || !eventLocation.trim()) {
      alert('Por favor, preencha os dados principais do evento e seu WhatsApp para contato.');
      return;
    }

    const messageLines = [
      `✨ *NOVO PEDIDO PERSONALIZADO - KEH CONVITES* ✨`,
      `═════════════════════════════`,
      `💌 *Modelo Escolhido:* ${template.title}`,
      `💰 *Valor:* R$ ${template.price.toFixed(2)}`,
      ``,
      `🎂 *Nome do Aniversariante / Anfitrião:* ${celebrantName}`,
      `📅 *Data do Evento:* ${eventDate}`,
      `⏰ *Horário:* ${eventTime || 'A definir'}`,
      `📍 *Local / Endereço:* ${eventLocation}`,
      specialQuote ? `📜 *Frase Especial:* "${specialQuote}"` : '',
      `📱 *WhatsApp para Contato:* ${clientWhatsapp}`,
      ``,
    ];

    if (hasInteraction) {
      messageLines.push(
        `🔘 *DADOS DE INTERAÇÃO / BOTÕES:*`,
        rsvpWhatsapp ? `• Confirmação de Presença (RSVP): ${rsvpWhatsapp}` : '• Confirmação de Presença: Não informado',
        giftList ? `• Lista de Presentes / Tamanhos: ${giftList}` : '',
        ``
      );
    }

    if (photoPreview) {
      messageLines.push(`📸 *Foto Selecionada:* Sim (anexada: ${photoName || 'Foto do aniversariante'})`);
    } else {
      messageLines.push(`📸 *Foto:* Sem foto ou enviarei pelo chat`);
    }

    messageLines.push(
      ``,
      `Aguardando retorno para confirmar a arte e receber a prévia! 💕`
    );

    const fullMessage = messageLines.filter((l) => l !== '').join('\n');
    const waUrl = `https://wa.me/5511999999999?text=${encodeURIComponent(fullMessage)}`;

    window.open(waUrl, '_blank');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdf9f4] border border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-5 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <img
              src={template.imageUrl}
              alt={template.title}
              className="w-12 h-12 rounded-xl object-cover border border-[#D4AF37]/40 shadow-sm"
            />
            <div>
              <div className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-[#D4AF37]/20 text-[#4B2E20] text-[10px] font-bold">
                <Sparkles className="w-3 h-3 text-[#D4AF37]" />
                Personalização do Convite
              </div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20] line-clamp-1">
                {template.title}
              </CardTitle>
              <p className="text-[11px] text-[#4B2E20]/80">
                Preencha os dados do seu evento abaixo para criarmos sua arte
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Formulário com Scroll */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-5 text-xs text-[#4B2E20]">
          <form onSubmit={handleSendOrder} className="space-y-4">

            {/* Bloco 1: Dados do Anfitrião e Contato */}
            <div className="bg-[#f7ebdd]/60 p-4 rounded-2xl border border-[#D4AF37]/30 space-y-3">
              <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20] flex items-center gap-1.5">
                <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                1. Quem é o aniversariante / homenageado?
              </span>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block mb-1 font-semibold text-[#4B2E20]">
                    Nome do Aniversariante / Casal *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Lorena (Faz 5 anos) ou Ana & Pedro"
                    value={celebrantName}
                    onChange={(e) => setCelebrantName(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                  />
                </div>

                <div>
                  <label className="block mb-1 font-semibold text-[#4B2E20]">
                    Seu WhatsApp para Contato e Prévia *
                  </label>
                  <Input
                    required
                    placeholder="(11) 99999-9999"
                    value={clientWhatsapp}
                    onChange={(e) => setClientWhatsapp(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                  />
                </div>
              </div>
            </div>

            {/* Bloco 2: Informações do Evento */}
            <div className="bg-[#f7ebdd]/60 p-4 rounded-2xl border border-[#D4AF37]/30 space-y-3">
              <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20] flex items-center gap-1.5">
                <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                2. Data, Horário e Local
              </span>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block mb-1 font-semibold text-[#4B2E20]">
                    Data e Dia da Semana *
                  </label>
                  <Input
                    required
                    placeholder="Ex: 25 de Outubro (Sábado)"
                    value={eventDate}
                    onChange={(e) => setEventDate(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                  />
                </div>

                <div>
                  <label className="block mb-1 font-semibold text-[#4B2E20]">
                    Horário do Evento
                  </label>
                  <div className="relative">
                    <Clock className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                    <Input
                      placeholder="Ex: Às 19h00 ou Das 14h às 18h"
                      value={eventTime}
                      onChange={(e) => setEventTime(e.target.value)}
                      className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block mb-1 font-semibold text-[#4B2E20]">
                  Local do Evento e Endereço Completo *
                </label>
                <div className="relative">
                  <MapPin className="w-3.5 h-3.5 absolute left-3 top-3 text-[#D4AF37]" />
                  <Input
                    required
                    placeholder="Ex: Buffet Algodão Doce - Av. das Flores, 120, Bairro Jardim"
                    value={eventLocation}
                    onChange={(e) => setEventLocation(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                  />
                </div>
              </div>

              <div>
                <label className="block mb-1 font-semibold text-[#4B2E20]">
                  Frase Especial ou Versículo (Opcional)
                </label>
                <textarea
                  rows={2}
                  placeholder="Ex: 'Um dia inesquecível para comemorar nossa alegria!' ou versículo bíblico..."
                  value={specialQuote}
                  onChange={(e) => setSpecialQuote(e.target.value)}
                  className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                />
              </div>
            </div>

            {/* Bloco 3: Informações de Interação (Confirmação e Lista de Presentes) */}
            <div className="bg-[#f7ebdd]/60 p-4 rounded-2xl border border-[#D4AF37]/30 space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20] flex items-center gap-1.5">
                  <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
                  3. Recursos Interativos & Confirmação de Presença
                </span>
                <label className="flex items-center gap-2 cursor-pointer text-xs font-semibold select-none">
                  <input
                    type="checkbox"
                    checked={hasInteraction}
                    onChange={(e) => setHasInteraction(e.target.checked)}
                    className="w-4 h-4 rounded text-[#4B2E20] accent-[#4B2E20]"
                  />
                  <span>Incluir Botões Interativos</span>
                </label>
              </div>

              {hasInteraction ? (
                <div className="space-y-3 pt-1 border-t border-[#D4AF37]/20 animate-fade-in">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div>
                      <label className="block mb-1 font-semibold text-[#4B2E20]">
                        Número de WhatsApp para Confirmação de Presença (RSVP)
                      </label>
                      <Input
                        placeholder="Ex: (11) 98888-7777"
                        value={rsvpWhatsapp}
                        onChange={(e) => setRsvpWhatsapp(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl h-9 text-xs"
                      />
                      <span className="text-[10px] text-[#4B2E20]/70 mt-0.5 block">
                        Seus convidados clicam no botão e confirmam diretamente no seu WhatsApp.
                      </span>
                    </div>

                    <div>
                      <label className="block mb-1 font-semibold text-[#4B2E20]">
                        Sugestão de Presentes / Tamanhos / Brinquedos
                      </label>
                      <textarea
                        rows={2}
                        placeholder="Ex: Roupa: Tam 4 • Sapato: Nº 26 • Brinquedos lúdicos / Pix ou Link"
                        value={giftList}
                        onChange={(e) => setGiftList(e.target.value)}
                        className="w-full p-2 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                      />
                    </div>
                  </div>
                </div>
              ) : (
                <p className="text-[11px] text-[#4B2E20]/70">
                  Marque a caixa acima caso seu modelo tenha botões clicáveis de RSVP e sugestão de presente.
                </p>
              )}
            </div>

            {/* Bloco 4: Anexo de Foto */}
            <div className="bg-[#f7ebdd]/60 p-4 rounded-2xl border border-[#D4AF37]/30 space-y-3">
              <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20] flex items-center gap-1.5">
                <ImageIcon className="w-3.5 h-3.5 text-[#D4AF37]" />
                4. Foto do Aniversariante / Casal (Se o modelo tiver foto)
              </span>

              <div className="flex flex-col sm:flex-row items-center gap-4">
                <label className="w-full sm:w-auto flex-1 flex flex-col items-center justify-center p-3.5 border-2 border-dashed border-[#D4AF37]/60 rounded-2xl cursor-pointer hover:bg-white/80 transition-all text-center">
                  <Upload className="w-5 h-5 text-[#4B2E20] mb-1" />
                  <span className="text-xs font-semibold text-[#4B2E20]">
                    Clique aqui para selecionar uma foto
                  </span>
                  <span className="text-[10px] text-[#4B2E20]/70">
                    JPG, PNG ou WEBP em boa qualidade
                  </span>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    className="hidden"
                  />
                </label>

                {photoPreview && (
                  <div className="flex items-center gap-2 bg-white p-2 rounded-2xl border border-[#D4AF37]/40 shrink-0">
                    <img
                      src={photoPreview}
                      alt="Prévia"
                      className="w-16 h-16 rounded-xl object-cover"
                    />
                    <div className="text-[11px] pr-2">
                      <p className="font-bold text-[#4B2E20] line-clamp-1 max-w-[120px]">
                        {photoName || 'Foto anexada'}
                      </p>
                      <button
                        type="button"
                        onClick={() => {
                          setPhotoPreview(null);
                          setPhotoName('');
                        }}
                        className="text-red-600 hover:underline text-[10px]"
                      >
                        Remover
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Resumo e Botão de Ação */}
            <div className="pt-2 flex flex-col sm:flex-row items-center justify-between gap-3">
              <div className="text-[11px] text-[#4B2E20]/80">
                Total do Modelo: <strong className="text-base text-[#4B2E20] font-bold">R$ {template.price.toFixed(2)}</strong>
              </div>

              <div className="flex items-center gap-2 w-full sm:w-auto">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onClose}
                  className="text-[#4B2E20] rounded-xl text-xs flex-1 sm:flex-none"
                >
                  Cancelar
                </Button>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold rounded-xl text-xs border border-[#D4AF37]/40 shadow-md flex items-center justify-center gap-2 px-6 h-11 flex-1 sm:flex-none"
                >
                  <MessageCircle className="w-4 h-4 text-[#D4AF37]" />
                  <span>Enviar Pedido pelo WhatsApp</span>
                </Button>
              </div>
            </div>

          </form>
        </CardContent>
      </Card>
    </div>
  );
}

