import React, { useState, useRef } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat, Order } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Sparkles,
  Smartphone,
  Video,
  Image as ImageIcon,
  CalendarDays,
  Package,
  Search,
  MessageCircle,
  Eye,
  CheckCircle2,
  X,
  Upload,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Phone,
  UserCheck,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplateToOrder?: (template: InvitationTemplate) => void;
  isAdminAuthenticated?: boolean;
  onClientSubmitOrder?: (newOrder: Order) => void;
}

const formatLabels: Record<DigitalFormat, { label: string; icon: React.ReactNode; color: string }> = {
  interativo_pdf: {
    label: 'Interativo (PDF Clicável)',
    icon: <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
  },
  imagem_card: {
    label: 'Card Digital (WhatsApp/Foto)',
    icon: <ImageIcon className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
  },
  animado_video: {
    label: 'Vídeo Animado com Música',
    icon: <Video className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
  },
  save_the_date: {
    label: 'Save The Date Digital',
    icon: <CalendarDays className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
  },
  kit_digital: {
    label: 'Kit Digital Completo',
    icon: <Package className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
  },
  site_rsvp: {
    label: 'Página Web do Evento',
    icon: <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
  },
};

export function TemplatesCatalog({
  templates,
  onSelectTemplateToOrder,
  isAdminAuthenticated = false,
  onClientSubmitOrder,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedFormat, setSelectedFormat] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Estado para Modal de Encomenda do Cliente
  const [modalTemplate, setModalTemplate] = useState<InvitationTemplate | null>(null);
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  // Campos do formulário do cliente
  const [aniversariante, setAniversariante] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos interativos (condicionais)
  const [temInteracao, setTemInteracao] = useState(false);
  const [rsvpTelefone, setRsvpTelefone] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Anexo de Foto
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreviewUrl, setFotoPreviewUrl] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories: InvitationCategory[] = [
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesCategory = selectedCategory === 'all' || tpl.category === selectedCategory;
    const matchesFormat = selectedFormat === 'all' || tpl.format === selectedFormat;
    const matchesSearch =
      tpl.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.tags?.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase()));

    return matchesCategory && matchesFormat && matchesSearch;
  });

  const handleOpenClientOrderModal = (template: InvitationTemplate) => {
    setModalTemplate(template);
    // Se o formato for interativo ou kit digital ou site rsvp, já liga por padrão a interação
    const isInteractiveType =
      template.format === 'interativo_pdf' ||
      template.format === 'site_rsvp' ||
      template.format === 'kit_digital';
    setTemInteracao(isInteractiveType);
    setAniversariante('');
    setDataEvento('');
    setHorarioEvento('');
    setLocalEvento('');
    setFraseEspecial('');
    setWhatsappCliente('');
    setRsvpTelefone('');
    setListaPresentes('');
    setFotoFile(null);
    setFotoPreviewUrl(null);
  };

  const handleCloseClientOrderModal = () => {
    setModalTemplate(null);
    setFotoPreviewUrl(null);
    setFotoFile(null);
  };

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      const url = URL.createObjectURL(file);
      setFotoPreviewUrl(url);
    }
  };

  const handleSubmitClientOrder = (e: React.FormEvent) => {
    e.preventDefault();
    if (!modalTemplate) return;

    if (!aniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante ou homenageado(a)!');
      return;
    }
    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o seu número de WhatsApp para contato!');
      return;
    }

    // Montar mensagem para o WhatsApp do Ateliê
    let mensagemWhatsApp = `Olá Keh Convites! Gostaria de encomendar este modelo de convite digital:\n\n`;
    mensagemWhatsApp += `💌 *Modelo:* ${modalTemplate.title}\n`;
    mensagemWhatsApp += `🏷️ *Formato:* ${formatLabels[modalTemplate.format]?.label || 'Digital'}\n`;
    mensagemWhatsApp += `💰 *Valor:* R$ ${modalTemplate.price.toFixed(2)}\n\n`;
    mensagemWhatsApp += `📋 *DADOS DO EVENTO:*\n`;
    mensagemWhatsApp += `✨ *Nome do Aniversariante/Homenageado:* ${aniversariante}\n`;
    mensagemWhatsApp += `📅 *Data do Evento:* ${dataEvento || 'A definir'}\n`;
    mensagemWhatsApp += `⏰ *Horário:* ${horarioEvento || 'A definir'}\n`;
    mensagemWhatsApp += `📍 *Local / Endereço:* ${localEvento || 'A definir'}\n`;

    if (fraseEspecial.trim()) {
      mensagemWhatsApp += `💬 *Frase Especial:* "${fraseEspecial.trim()}"\n`;
    }
    mensagemWhatsApp += `📱 *Meu WhatsApp:* ${whatsappCliente}\n`;

    if (temInteracao || modalTemplate.format === 'interativo_pdf') {
      mensagemWhatsApp += `\n🔗 *INFORMAÇÕES INTERATIVAS:*\n`;
      if (rsvpTelefone.trim()) {
        mensagemWhatsApp += `✔️ *Confirmação de Presença (RSVP):* ${rsvpTelefone.trim()}\n`;
      }
      if (listaPresentes.trim()) {
        mensagemWhatsApp += `🎁 *Lista de Presentes (Sapato/Roupas/Brinquedos/Pix):* ${listaPresentes.trim()}\n`;
      }
    }

    if (fotoFile) {
      mensagemWhatsApp += `\n📸 *Foto para o convite:* Sim, já selecionei uma foto e estou enviando aqui no chat!`;
    }

    // Salvar pedido no sistema também para aparecer no painel
    if (onClientSubmitOrder) {
      const newOrder: Order = {
        id: `ord-${Date.now()}`,
        clientName: aniversariante,
        clientWhatsapp: whatsappCliente,
        templateId: modalTemplate.id,
        templateTitle: modalTemplate.title,
        category: modalTemplate.category,
        digitalFormat: modalTemplate.format,
        rsvpLink: rsvpTelefone ? `WhatsApp RSVP: ${rsvpTelefone}` : undefined,
        mapsLocation: localEvento,
        totalValue: modalTemplate.price,
        paidValue: 0,
        eventDate: dataEvento,
        deadlineDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        status: 'pendente',
        paymentStatus: 'pendente',
        notes: `Horário: ${horarioEvento} | Frase: ${fraseEspecial} | Lista: ${listaPresentes} | Tem foto: ${fotoFile ? 'Sim' : 'Não'}`,
        createdAt: new Date().toISOString().split('T')[0],
      };
      onClientSubmitOrder(newOrder);
    }

    // Abrir WhatsApp do Ateliê com todos os dados
    const encoded = encodeURIComponent(mensagemWhatsApp);
    window.open(`https://wa.me/5511999999999?text=${encoded}`, '_blank');

    handleCloseClientOrderModal();
  };

  return (
    <div className="space-y-8 animate-fade-in">

      {/* Banner de Apresentação */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#4B2E20] via-[#3a2217] to-[#25150d] text-[#F7EBDD] p-6 sm:p-10 shadow-xl border border-[#D4AF37]/45">
        <div className="relative z-10 max-w-2xl space-y-3.5">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/40 text-[#D4AF37] text-xs font-semibold tracking-wide">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Ateliê Keh Convites • Modelos Exclusivos & Personalizados</span>
          </div>

          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-serif font-bold tracking-tight text-[#F7EBDD]">
            Convites Digitais em Diversos Modelos & Formatos
          </h1>

          <p className="text-xs sm:text-sm text-[#F7EBDD]/80 leading-relaxed font-normal">
            Escolha o modelo dos seus sonhos, aperte em <strong className="text-[#F7EBDD]">Quero este modelo</strong> e preencha os detalhes do seu evento (nome do aniversariante, data, local, frase especial, lista de presentes e fotos).
          </p>

          <div className="flex flex-wrap items-center gap-3 pt-2 text-xs text-[#D4AF37]">
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Entrega Direto no WhatsApp
            </span>
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Botões Clicáveis e Interação
            </span>
            <span className="flex items-center gap-1 bg-[#D4AF37]/15 px-2.5 py-1 rounded-lg border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5" /> Anexe Fotos e Detalhes
            </span>
          </div>
        </div>

        <div className="absolute -right-10 -bottom-10 w-64 h-64 bg-[#D4AF37]/15 rounded-full blur-3xl pointer-events-none" />
      </div>

      {/* Barra de Pesquisa e Filtros */}
      <div className="space-y-4">
        <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
          <div className="relative flex-1 max-w-md">
            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Buscar por tema, modelo, formato ou detalhes..."
              className="pl-10 bg-[#fdf9f4] border-[#D4AF37]/40 text-xs text-[#4B2E20] rounded-xl h-10 shadow-sm"
            />
          </div>

          <div className="text-xs text-[#4B2E20]/80 font-medium self-center">
            Mostrando <strong>{filteredTemplates.length}</strong> de {templates.length} modelos
          </div>
        </div>

        {/* Filtros por Formato */}
        <div className="space-y-1.5">
          <span className="text-[11px] font-bold uppercase tracking-wider text-[#4B2E20]/70 block">
            Filtrar por Formato do Convite Digital:
          </span>
          <div className="flex items-center gap-2 overflow-x-auto pb-1">
            {[
              { id: 'all', label: 'Todos os Formatos', icon: <Sparkles className="w-3.5 h-3.5" /> },
              { id: 'imagem_card', label: 'Cards em Imagem (WhatsApp)', icon: <ImageIcon className="w-3.5 h-3.5" /> },
              { id: 'interativo_pdf', label: 'Interativos em PDF (Botões)', icon: <Smartphone className="w-3.5 h-3.5" /> },
              { id: 'animado_video', label: 'Vídeos Animados', icon: <Video className="w-3.5 h-3.5" /> },
              { id: 'save_the_date', label: 'Save The Date', icon: <CalendarDays className="w-3.5 h-3.5" /> },
              { id: 'kit_digital', label: 'Kits Digitais Completos', icon: <Package className="w-3.5 h-3.5" /> },
            ].map((fmt) => (
              <button
                key={fmt.id}
                onClick={() => setSelectedFormat(fmt.id)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all border ${
                  selectedFormat === fmt.id
                    ? 'bg-[#4B2E20] text-[#F7EBDD] border-[#4B2E20] shadow-sm'
                    : 'bg-[#fcf8f3] text-[#4B2E20]/80 border-[#D4AF37]/30 hover:bg-[#ecdccb]'
                }`}
              >
                {fmt.icon}
                <span>{fmt.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Filtros por Categoria */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${
              selectedCategory === 'all'
                ? 'bg-[#D4AF37] text-[#4B2E20] font-bold'
                : 'bg-white text-[#4B2E20]/70 hover:bg-[#ecdccb]/50'
            }`}
          >
            Todas as Ocasiões
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3 py-1 rounded-lg text-xs font-medium whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#D4AF37] text-[#4B2E20] font-bold'
                  : 'bg-white text-[#4B2E20]/70 hover:bg-[#ecdccb]/50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredTemplates.map((template) => {
          const fmt = formatLabels[template.format] || formatLabels.imagem_card;
          return (
            <Card
              key={template.id}
              className="group bg-[#fcf8f3] border-[#D4AF37]/35 rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col justify-between"
            >
              <div>
                <div className="relative aspect-[4/3] overflow-hidden bg-[#e0d0bf]">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                  <div className="absolute top-3 left-3 flex flex-wrap gap-1.5">
                    <Badge className={`text-[10px] font-semibold border-0 ${fmt.color} flex items-center gap-1 shadow-sm`}>
                      {fmt.icon}
                      <span>{fmt.label}</span>
                    </Badge>
                  </div>
                  <div className="absolute top-3 right-3">
                    <span className="bg-[#4B2E20]/90 text-[#D4AF37] text-xs font-bold px-2.5 py-1 rounded-xl shadow-md border border-[#D4AF37]/40">
                      R$ {template.price.toFixed(2)}
                    </span>
                  </div>
                </div>

                <CardContent className="p-5 space-y-3">
                  <div>
                    <span className="text-[10px] font-bold uppercase tracking-wider text-[#D4AF37]">
                      {template.category}
                    </span>
                    <h3 className="font-serif font-bold text-base text-[#4B2E20] leading-snug line-clamp-1 mt-0.5">
                      {template.title}
                    </h3>
                  </div>

                  <p className="text-xs text-[#4B2E20]/80 line-clamp-2 leading-relaxed">
                    {template.description}
                  </p>

                  <div className="flex flex-wrap gap-1 pt-1">
                    {template.tags?.slice(0, 3).map((tag, idx) => (
                      <span
                        key={idx}
                        className="text-[10px] px-2 py-0.5 rounded-md bg-[#ecdccb]/60 text-[#4B2E20] border border-[#D4AF37]/20 font-medium"
                      >
                        #{tag}
                      </span>
                    ))}
                  </div>
                </CardContent>
              </div>

              {/* Botões do Card */}
              <div className="p-5 pt-0 grid grid-cols-2 gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPreviewTemplate(template)}
                  className="w-full border-[#D4AF37]/40 bg-white text-[#4B2E20] hover:bg-[#ecdccb]/50 text-xs rounded-xl"
                >
                  <Eye className="w-3.5 h-3.5 mr-1 text-[#D4AF37]" />
                  Ver Detalhes
                </Button>

                {/* BOTÃO "QUERO ESSE MODELO" -> Abre o Formulário Completo com as questões exigidas */}
                <Button
                  size="sm"
                  onClick={() => handleOpenClientOrderModal(template)}
                  className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center justify-center gap-1.5"
                >
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Quero este modelo</span>
                </Button>
              </div>
            </Card>
          );
        })}
      </div>

      {/* MODAL DE PERSONALIZAÇÃO & FORMULÁRIO DO CLIENTE */}
      {modalTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-2xl w-full bg-[#fdf9f5] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">

            {/* Cabeçalho do Modal */}
            <div className="p-4 sm:p-5 border-b border-[#D4AF37]/25 bg-[#ecdccb]/60 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] flex items-center justify-center text-[#D4AF37] shadow">
                  <Sparkles className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-serif font-bold text-base sm:text-lg text-[#4B2E20]">
                    Personalize o seu Convite
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75">
                    Modelo selecionado: <strong className="text-[#4B2E20]">{modalTemplate.title}</strong> (R$ {modalTemplate.price.toFixed(2)})
                  </p>
                </div>
              </div>
              <button
                onClick={handleCloseClientOrderModal}
                className="p-1.5 rounded-xl hover:bg-[#ebdccb] text-[#4B2E20] transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Conteúdo do Formulário */}
            <div className="overflow-y-auto p-5 sm:p-6 space-y-5">
              <form onSubmit={handleSubmitClientOrder} className="space-y-4 text-xs">

                {/* 1. Nome do Aniversariante */}
                <div>
                  <label className="block text-[#4B2E20] font-bold mb-1.5 flex items-center gap-1.5">
                    <UserCheck className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Nome do Aniversariante / Homenageado(a) *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Theo (1 aninho) ou Amanda & Lucas"
                    value={aniversariante}
                    onChange={(e) => setAniversariante(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-sm rounded-xl h-10"
                  />
                </div>

                {/* 2. Data, Dia e Horário */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                      <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                      Data e Dia do Evento *
                    </label>
                    <Input
                      required
                      placeholder="Ex: 15/10/2025 (Sábado)"
                      value={dataEvento}
                      onChange={(e) => setDataEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                      <Clock className="w-3.5 h-3.5 text-[#D4AF37]" />
                      Horário do Evento *
                    </label>
                    <Input
                      required
                      placeholder="Ex: A partir das 16:30"
                      value={horarioEvento}
                      onChange={(e) => setHorarioEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>
                </div>

                {/* 3. Local do Evento */}
                <div>
                  <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                    <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Local do Evento e Endereço Completo *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Buffet Estrela Mágica - Rua das Flores, 120, Bairro Jardim"
                    value={localEvento}
                    onChange={(e) => setLocalEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                {/* 4. Frase Especial (Opcional) */}
                <div>
                  <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                    <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Frase Especial no Convite (Opcional)
                  </label>
                  <Input
                    placeholder="Ex: 'Um ano de pura alegria e bênçãos! Venha comemorar comigo.'"
                    value={fraseEspecial}
                    onChange={(e) => setFraseEspecial(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                {/* 5. Número do WhatsApp para Contato */}
                <div>
                  <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                    <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Seu Número do WhatsApp para Contato & Envio da Arte *
                  </label>
                  <Input
                    required
                    placeholder="(DDD) 99999-9999"
                    value={whatsappCliente}
                    onChange={(e) => setWhatsappCliente(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                {/* 6. Se o modelo tiver interação ou botões interativos */}
                <div className="p-4 rounded-2xl bg-[#ecdccb]/50 border border-[#D4AF37]/35 space-y-3">
                  <div className="flex items-center justify-between">
                    <label className="flex items-center gap-2 cursor-pointer select-none">
                      <input
                        type="checkbox"
                        checked={temInteracao}
                        onChange={(e) => setTemInteracao(e.target.checked)}
                        className="w-4 h-4 rounded text-[#4B2E20] focus:ring-[#D4AF37] accent-[#4B2E20]"
                      />
                      <span className="font-bold text-[#4B2E20] text-xs">
                        Este convite terá botões interativos / confirmação de presença?
                      </span>
                    </label>
                    <span className="text-[10px] text-[#4B2E20]/70 font-semibold uppercase">
                      Interatividade
                    </span>
                  </div>

                  {temInteracao && (
                    <div className="space-y-3 pt-2 border-t border-[#D4AF37]/25 animate-fade-in">
                      <div>
                        <label className="block text-[#4B2E20] font-bold mb-1">
                          Número da Confirmação de Presença (RSVP WhatsApp):
                        </label>
                        <Input
                          placeholder="Ex: (11) 98888-7777 (número que receberá os 'Sim, confirmo')"
                          value={rsvpTelefone}
                          onChange={(e) => setRsvpTelefone(e.target.value)}
                          className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                        />
                      </div>

                      <div>
                        <label className="block text-[#4B2E20] font-bold mb-1 flex items-center gap-1.5">
                          <Gift className="w-3.5 h-3.5 text-[#D4AF37]" />
                          Lista de Presentes / Sugestões (Sapato, Tamanho de Roupas, Brinquedos ou Pix):
                        </label>
                        <textarea
                          rows={2}
                          placeholder="Ex: Roupa tamanho 2, Sapato nº 21, Brinquedos educativos ou Chave Pix para presentes..."
                          value={listaPresentes}
                          onChange={(e) => setListaPresentes(e.target.value)}
                          className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                        />
                      </div>
                    </div>
                  )}
                </div>

                {/* 7. Anexo de Foto da Pessoa / Aniversariante */}
                <div className="p-4 rounded-2xl bg-white border border-[#D4AF37]/35 space-y-2.5">
                  <label className="block text-[#4B2E20] font-bold text-xs flex items-center gap-1.5">
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Deseja Adicionar Foto no Convite? (Anexar arquivo)
                  </label>

                  <input
                    type="file"
                    accept="image/*"
                    ref={fileInputRef}
                    onChange={handleFotoUpload}
                    className="hidden"
                  />

                  <div className="flex flex-col sm:flex-row items-center gap-3">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => fileInputRef.current?.click()}
                      className="border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ecdccb]/50 text-xs rounded-xl"
                    >
                      <Upload className="w-3.5 h-3.5 mr-1.5 text-[#D4AF37]" />
                      {fotoFile ? 'Trocar Foto Anexada' : 'Selecionar Foto do Aniversariante'}
                    </Button>

                    {fotoFile && (
                      <span className="text-xs text-emerald-800 font-semibold truncate max-w-xs">
                        ✓ {fotoFile.name}
                      </span>
                    )}
                  </div>

                  {/* Prévia da Foto */}
                  {fotoPreviewUrl && (
                    <div className="mt-2 flex items-center gap-3 p-2 bg-[#fdf9f4] rounded-xl border border-[#D4AF37]/25">
                      <img
                        src={fotoPreviewUrl}
                        alt="Prévia Foto"
                        className="w-16 h-16 object-cover rounded-xl border border-[#D4AF37]/40"
                      />
                      <div className="text-[11px] text-[#4B2E20]">
                        <p className="font-bold">Foto Carregada com Sucesso!</p>
                        <p className="text-[#4B2E20]/70">Essa foto será adaptada no layout do convite.</p>
                      </div>
                    </div>
                  )}
                </div>

                {/* Botões do Rodapé */}
                <div className="pt-3 flex items-center justify-end gap-2.5 border-t border-[#D4AF37]/25">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={handleCloseClientOrderModal}
                    className="text-[#4B2E20] rounded-xl text-xs"
                  >
                    Voltar
                  </Button>
                  <Button
                    type="submit"
                    className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold rounded-xl text-xs px-6 py-2.5 border border-[#D4AF37]/40 shadow flex items-center gap-2"
                  >
                    <MessageCircle className="w-4 h-4 text-[#D4AF37]" />
                    <span>Enviar Pedido pelo WhatsApp</span>
                  </Button>
                </div>
              </form>
            </div>
          </Card>
        </div>
      )}

      {/* Modal de Detalhes / Preview */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-lg w-full bg-[#fdf9f4] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden">
            <div className="relative aspect-video">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => setPreviewTemplate(null)}
                className="absolute top-3 right-3 p-1 rounded-full bg-black/60 text-white hover:bg-black/80"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-5 space-y-3 text-xs text-[#4B2E20]">
              <div className="flex items-center justify-between">
                <Badge className="bg-[#4B2E20] text-[#D4AF37]">
                  {previewTemplate.category}
                </Badge>
                <span className="font-bold text-base text-[#4B2E20]">
                  R$ {previewTemplate.price.toFixed(2)}
                </span>
              </div>
              <h3 className="text-base font-serif font-bold text-[#4B2E20]">
                {previewTemplate.title}
              </h3>
              <p className="leading-relaxed text-[#4B2E20]/80">
                {previewTemplate.description}
              </p>

              <div className="pt-3 flex gap-2">
                <Button
                  onClick={() => {
                    const t = previewTemplate;
                    setPreviewTemplate(null);
                    handleOpenClientOrderModal(t);
                  }}
                  className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold rounded-xl text-xs flex items-center justify-center gap-2"
                >
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Quero este modelo (Preencher Detalhes)</span>
                </Button>
              </div>
            </div>
          </Card>
        </div>
      )}

    </div>
  );
}

