import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat, Order } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ClientOrderModal } from '@/components/ClientOrderModal';
import {
  Sparkles,
  Smartphone,
  Video,
  Image as ImageIcon,
  CalendarDays,
  Package,
  Search,
  MessageCircle,
  Eye,
  CheckCircle2,
  X,
  Layers,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplateToOrder?: (template: InvitationTemplate) => void;
  isAdminAuthenticated?: boolean;
  onClientSubmitOrder?: (newOrder: Order) => void;
}

const formatLabels: Record<DigitalFormat, { label: string; icon: React.ReactNode; color: string; isInteractive: boolean }> = {
  imagem_card: {
    label: 'Card Digital Simples (WhatsApp)',
    icon: <ImageIcon className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
    isInteractive: false,
  },
  interativo_pdf: {
    label: 'Interativo (Botões Clicáveis)',
    icon: <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
    isInteractive: true,
  },
  animado_video: {
    label: 'Vídeo Animado com Música',
    icon: <Video className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
    isInteractive: false,
  },
  save_the_date: {
    label: 'Save The Date Digital',
    icon: <CalendarDays className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
    isInteractive: false,
  },
  kit_digital: {
    label: 'Kit Digital Completo',
    icon: <Package className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#4B2E20] text-[#F7EBDD]',
    isInteractive: true,
  },
  site_rsvp: {
    label: 'Página Web do Evento',
    icon: <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />,
    color: 'bg-[#ebdccb] text-[#4B2E20]',
    isInteractive: true,
  },
};

export function TemplatesCatalog({
  templates,
  isAdminAuthenticated = false,
  onClientSubmitOrder,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedFormat, setSelectedFormat] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Controle do Modal de Encomenda do Cliente
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  const categories: InvitationCategory[] = [
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesCategory = selectedCategory === 'all' || tpl.category === selectedCategory;
    const matchesFormat = selectedFormat === 'all' || tpl.format === selectedFormat;
    const matchesSearch =
      tpl.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.tags?.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase()));

    return matchesCategory && matchesFormat && matchesSearch;
  });

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Banner de Boas-Vindas */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-[#4B2E20] via-[#5c3725] to-[#784932] text-[#F7EBDD] p-6 sm:p-10 border border-[#D4AF37]/40 shadow-xl">
        <div className="relative z-10 max-w-2xl space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/50 text-[#D4AF37] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5" />
            <span>Catálogo Exclusivo • Keh Convites Digitais</span>
          </div>
          <h1 className="text-3xl sm:text-4xl font-serif font-bold text-[#F7EBDD] tracking-tight">
            Escolha seu Modelo dos Sonhos
          </h1>
          <p className="text-xs sm:text-sm text-[#F7EBDD]/80 leading-relaxed">
            Personalizamos qualquer tema para sua comemoração! Temos <strong>Cards Digitais Simples</strong> (sem botões, para envio direto de imagem no WhatsApp) e <strong>Convites Interativos</strong> (com botões clicáveis de confirmação de presença e presentes).
          </p>
        </div>
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="space-y-4">
        <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between">
          <div className="relative flex-1 max-w-md">
            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#4B2E20]/60" />
            <Input
              placeholder="Buscar por tema (ex: Safari, Patrulha Canina, Casamento, Ursinho)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 bg-white/90 border-[#D4AF37]/40 text-[#4B2E20] placeholder:text-[#4B2E20]/50 rounded-2xl text-xs h-11"
            />
          </div>

          {/* Filtro por Formato (Simples vs Interativo) */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
            <button
              onClick={() => setSelectedFormat('all')}
              className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedFormat === 'all'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-white/70 text-[#4B2E20]/80 hover:bg-white border border-[#D4AF37]/30'
              }`}
            >
              Todos os Formatos
            </button>
            <button
              onClick={() => setSelectedFormat('imagem_card')}
              className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedFormat === 'imagem_card'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-white/70 text-[#4B2E20]/80 hover:bg-white border border-[#D4AF37]/30'
              }`}
            >
              Cards Simples (WhatsApp)
            </button>
            <button
              onClick={() => setSelectedFormat('interativo_pdf')}
              className={`px-3 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                selectedFormat === 'interativo_pdf'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-white/70 text-[#4B2E20]/80 hover:bg-white border border-[#D4AF37]/30'
              }`}
            >
              Interativos (Botões Clicáveis)
            </button>
          </div>
        </div>

        {/* Categorias / Ocasiões */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 text-xs">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-3.5 py-1.5 rounded-full font-semibold transition-all ${
              selectedCategory === 'all'
                ? 'bg-[#D4AF37] text-[#4B2E20] shadow-sm'
                : 'bg-white/80 text-[#4B2E20]/80 hover:bg-[#ebdccb] border border-[#D4AF37]/30'
            }`}
          >
            Todas Ocasiões
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3.5 py-1.5 rounded-full font-semibold whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-[#D4AF37] text-[#4B2E20] shadow-sm'
                  : 'bg-white/80 text-[#4B2E20]/80 hover:bg-[#ebdccb] border border-[#D4AF37]/30'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos */}
      {filteredTemplates.length === 0 ? (
        <div className="text-center py-16 bg-white/60 rounded-3xl border border-[#D4AF37]/30 p-8 space-y-3">
          <Layers className="w-10 h-10 text-[#D4AF37] mx-auto opacity-70" />
          <h3 className="font-serif font-bold text-lg text-[#4B2E20]">Nenhum modelo encontrado</h3>
          <p className="text-xs text-[#4B2E20]/70 max-w-md mx-auto">
            Tente outro termo na busca ou limpe os filtros para ver todas as opções disponíveis no Ateliê Keh Convites.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => {
            const formatMeta = formatLabels[template.format] || formatLabels.imagem_card;
            const isInteractive = formatMeta.isInteractive;

            return (
              <Card
                key={template.id}
                className="group flex flex-col bg-white/90 border-[#D4AF37]/35 rounded-3xl overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 hover:-translate-y-1"
              >
                {/* Imagem do Modelo */}
                <div className="relative aspect-[4/3] overflow-hidden bg-[#ebdccb]/30">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-[#4B2E20]/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-4">
                    <button
                      onClick={() => setPreviewTemplate(template)}
                      className="w-full py-2 px-3 rounded-xl bg-white/95 text-[#4B2E20] text-xs font-semibold flex items-center justify-center gap-1.5 shadow-md hover:bg-white"
                    >
                      <Eye className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Ver Foto em Tamanho Maior</span>
                    </button>
                  </div>

                  {/* Badge de Formato no Topo da Foto */}
                  <div className="absolute top-3 left-3 flex flex-col gap-1.5">
                    <Badge className="bg-[#4B2E20]/90 text-[#F7EBDD] backdrop-blur-md text-[10px] font-semibold border-none flex items-center gap-1 py-1 px-2.5">
                      {formatMeta.icon}
                      <span>{formatMeta.label}</span>
                    </Badge>
                  </div>

                  {/* Indicador se é Simples ou Interativo */}
                  <div className="absolute top-3 right-3">
                    <span
                      className={`text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm ${
                        isInteractive
                          ? 'bg-emerald-100 text-emerald-800 border border-emerald-300'
                          : 'bg-[#F7EBDD] text-[#4B2E20] border border-[#D4AF37]/40'
                      }`}
                    >
                      {isInteractive ? 'Com Botões' : 'Sem Botões'}
                    </span>
                  </div>
                </div>

                {/* Conteúdo do Card */}
                <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                  <div className="space-y-2">
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-[11px] font-semibold text-[#855729] uppercase tracking-wider">
                        {template.category}
                      </span>
                      <span className="text-lg font-serif font-black text-[#4B2E20]">
                        R$ {template.price.toFixed(2)}
                      </span>
                    </div>

                    <h3 className="font-serif font-bold text-[#4B2E20] text-base group-hover:text-[#855729] transition-colors line-clamp-1">
                      {template.title}
                    </h3>

                    <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                      {template.description}
                    </p>

                    {/* Tags */}
                    {template.tags && template.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1 pt-1">
                        {template.tags.slice(0, 3).map((tag, i) => (
                          <span
                            key={i}
                            className="text-[10px] bg-[#F7EBDD]/60 text-[#4B2E20] px-2 py-0.5 rounded-md border border-[#D4AF37]/25"
                          >
                            {tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Botão de Ação: Quero este Modelo */}
                  <div className="pt-2 border-t border-[#D4AF37]/20">
                    <Button
                      onClick={() => setSelectedTemplateForOrder(template)}
                      className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-md border border-[#D4AF37]/40 flex items-center justify-center gap-2 group-hover:scale-[1.01] transition-all"
                    >
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Quero este Modelo</span>
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Prévia de Imagem */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-fade-in">
          <div className="relative max-w-lg w-full bg-white rounded-3xl overflow-hidden p-2 shadow-2xl">
            <button
              onClick={() => setPreviewTemplate(null)}
              className="absolute top-4 right-4 z-10 p-2 rounded-full bg-[#4B2E20] text-[#F7EBDD] hover:bg-black transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
            <img
              src={previewTemplate.imageUrl}
              alt={previewTemplate.title}
              className="w-full max-h-[80vh] object-contain rounded-2xl"
            />
            <div className="p-4 text-center">
              <h3 className="font-serif font-bold text-base text-[#4B2E20]">
                {previewTemplate.title}
              </h3>
              <p className="text-xs text-[#4B2E20]/75">{previewTemplate.category}</p>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Pedido do Cliente (Formulário com Tema e Opções de Interação) */}
      <ClientOrderModal
        isOpen={Boolean(selectedTemplateForOrder)}
        onClose={() => setSelectedTemplateForOrder(null)}
        template={selectedTemplateForOrder}
        onSubmitOrder={onClientSubmitOrder}
      />
    </div>
  );
}

files.oldContent:
import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Heart, Sparkles, Phone, ShieldCheck } from 'lucide-react';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle da Área Administrativa protegida por senha
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
