      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            isAdminAuthenticated={isAdminAuthenticated}
            onSelectTemplateToOrder={(tpl) => {
              setSelectedTemplateForOrder(tpl);
              setIsNewOrderModalOpen(true);
            }}
            onClientSubmitOrder={(newOrder) => {
              setOrders((prev) => [newOrder, ...prev]);
            }}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            setOrders={setOrders}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsNewOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsNewOrderModalOpen(true);
            }}
          />
        )}
      </main>

      {/* Rodapé Elegante */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ecdccb]/50 py-8 px-4 text-center text-xs text-[#4B2E20]/80 space-y-2">
        <div className="flex items-center justify-center gap-2">
          <span className="font-serif font-bold text-sm text-[#4B2E20]">Keh Convites</span>
          <span className="text-[#D4AF37]">•</span>
          <span>Ateliê Especializado em Convites Digitais</span>
        </div>
        <p className="flex items-center justify-center gap-1 text-[11px] text-[#4B2E20]/70">
          Feito com <Heart className="w-3.5 h-3.5 text-rose-500 fill-rose-500" /> para momentos inesquecíveis.
        </p>
      </footer>

      {/* Modais */}
      <AdminLoginModal
        isOpen={isAdminLoginOpen}
        onClose={() => setIsAdminLoginOpen(false)}
        onSuccess={handleAdminAuthSuccess}
      />

      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => {
          setIsNewOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        templates={templates}
        preSelectedTemplate={selectedTemplateForOrder}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => setIsNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

