import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle de Autenticação Administrativa
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState<boolean>(false);

  // Modais de Criação Administrativa
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  // Handlers de Pedidos
  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, status } : ord))
    );
  };

  const handleUpdatePayment = (orderId: string, paidValue: number) => {
    setOrders((prev) =>
      prev.map((ord) => {
        if (ord.id !== orderId) return ord;
        const paymentStatus =
          paidValue >= ord.totalValue
            ? 'pago'
            : paidValue > 0
            ? 'parcial'
            : 'pendente';
        return { ...ord, paidValue, paymentStatus };
      })
    );
  };

  const handleSaveNewOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleSaveNewTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  // Contagem de Pedidos Pendentes
  const pendingOrdersCount = orders.filter(
    (o) => o.status === 'pendente' || o.status === 'em_criacao'
  ).length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminModalOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => {
          setSelectedTemplateForOrder(null);
          setIsNewOrderModalOpen(true);
        }}
        onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            isAdminAuthenticated={isAdminAuthenticated}
            onSelectTemplateToOrder={(template) => {
              setSelectedTemplateForOrder(template);
              setIsNewOrderModalOpen(true);
            }}
            onClientSubmitOrder={(newOrder) => {
              setOrders((prev) => [newOrder, ...prev]);
            }}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdatePayment}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsNewOrderModalOpen(true);
            }}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => {
              setSelectedTemplateForOrder(null);
              setIsNewOrderModalOpen(true);
            }}
          />
        )}
      </main>

      {/* Rodapé Elegante */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ebdccb]/40 py-6 text-center text-xs text-[#4B2E20]/75">
        <div className="max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3">
          <p className="font-serif font-bold text-[#4B2E20]">
            Keh Convites • Ateliê de Convites Digitais
          </p>
          <p className="text-[11px] text-[#4B2E20]/60">
            Cards WhatsApp • Interativos em PDF • Vídeos Animados • Save The Date
          </p>
        </div>
      </footer>

      {/* Modal de Acesso com Senha Administrativa (41526378) */}
      <AdminLoginModal
        isOpen={isAdminModalOpen}
        onClose={() => setIsAdminModalOpen(false)}
        onSuccess={() => {
          setIsAdminAuthenticated(true);
          setIsAdminModalOpen(false);
          setCurrentTab('orders');
        }}
      />

      {/* Modal de Novo Pedido Manual (Admin) */}
      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => setIsNewOrderModalOpen(false)}
        templates={templates}
        preSelectedTemplate={selectedTemplateForOrder}
        onSaveOrder={handleSaveNewOrder}
      />

      {/* Modal de Novo Modelo de Convite (Admin) */}
      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => setIsNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveNewTemplate}
      />
    </div>
  );
}

