                        </span>
                      </div>
                    </div>

                    {order.notes && (
                      <div className="bg-amber-50/70 p-2 rounded-xl border border-amber-200/60 text-[11px] text-[#4B2E20]/80">
                        <strong className="block text-[#4B2E20]">Detalhes / Notas:</strong>
                        <p className="line-clamp-2">{order.notes}</p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Ações de Status */}
                <div className="p-3 bg-[#faf5ee] border-t border-[#D4AF37]/20 flex items-center justify-between gap-2">
                  <select
                    value={order.status}
                    onChange={(e) => handleUpdateStatus(order.id, e.target.value as OrderStatus)}
