      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <div className="sm:col-span-2 relative">
          <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
          <Input
            placeholder="Buscar por cliente, aniversariante, tema ou WhatsApp..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-10 bg-white/95 border-[#D4AF37]/35 rounded-2xl text-xs text-[#4B2E20]"
          />
        </div>

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="h-10 px-3 rounded-2xl bg-white border border-[#D4AF37]/35 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
        >
          <option value="all">Todos os Status ({safeOrders.length})</option>
          <option value="pendente">Aguardando Início</option>
          <option value="em_criacao">Em Criação / Arte</option>
          <option value="aprovacao">Enviado para Aprovação</option>
          <option value="concluido">Finalizado & Entregue</option>
        </select>
      </div>

      {/* Lista de Pedidos */}
      <div className="grid grid-cols-1 gap-4">
        {filteredOrders.length === 0 ? (
          <Card className="bg-white/90 border-[#D4AF37]/30 rounded-3xl p-12 text-center">
            <Layers className="w-10 h-10 mx-auto text-[#D4AF37]/60 mb-2" />
            <p className="text-base font-serif font-bold text-[#4B2E20]">Nenhum pedido encontrado</p>
            <p className="text-xs text-[#4B2E20]/70 mt-1">
              Os pedidos realizados pelos clientes ou cadastrados aparecerão aqui.
            </p>
          </Card>
        ) : (
          filteredOrders.map((order) => {
            const statusConfig = statusLabels[order.status] || statusLabels.pendente;

            return (
              <Card
                key={order.id}
                className="bg-white/95 border-[#D4AF37]/35 rounded-2xl shadow-sm hover:shadow-md transition-all p-5"
              >
                <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
                  <div className="space-y-1.5 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-serif font-bold text-base text-[#4B2E20]">
                        {order.clientName}
                      </span>
                      <span
                        className={`text-[10px] font-bold px-2.5 py-0.5 rounded-full border ${statusConfig.color} ${statusConfig.border}`}
                      >
                        {statusConfig.label}
                      </span>
                      <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-[#ebdccb] text-[#4B2E20]">
                        {order.category}
                      </span>
                    </div>

                    <p className="text-xs text-[#4B2E20]/80">
                      <strong>Modelo:</strong> {order.templateTitle}
                    </p>

                    {order.notes && (
                      <p className="text-xs text-[#4B2E20]/70 bg-[#faf5ee] p-2 rounded-xl border border-[#D4AF37]/20">
                        {order.notes}
                      </p>
                    )}

                    <div className="flex flex-wrap items-center gap-4 text-[11px] text-[#4B2E20]/70 pt-1">
                      {order.eventDate && (
                        <span className="flex items-center gap-1">
                          <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                          Data: {order.eventDate}
                        </span>
                      )}
                      {order.mapsLocation && (
                        <span className="flex items-center gap-1">
                          <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" />
                          Local: {order.mapsLocation}
                        </span>
                      )}
                      {order.clientWhatsapp && (
                        <span className="flex items-center gap-1 font-medium text-[#4B2E20]">
                          <MessageCircle className="w-3.5 h-3.5 text-emerald-600" />
                          WhatsApp: {order.clientWhatsapp}
                        </span>
                      )}
                    </div>
                  </div>

                  {/* Valores e Ações */}
                  <div className="flex flex-col sm:flex-row lg:flex-col items-start lg:items-end justify-between w-full lg:w-auto gap-3 pt-3 lg:pt-0 border-t lg:border-t-0 border-[#D4AF37]/20">
                    <div className="text-left lg:text-right">
                      <span className="text-xs text-[#4B2E20]/70 block">Valor do Convite</span>
                      <span className="text-lg font-serif font-bold text-[#4B2E20]">
                        R$ {Number(order.totalValue || 0).toFixed(2)}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      {/* Alteração Rápida de Status */}
                      <select
                        value={order.status}
                        onChange={(e) => handleStatusChange(order.id, e.target.value as OrderStatus)}
                        className="h-8 px-2.5 rounded-xl bg-[#faf5ee] border border-[#D4AF37]/40 text-xs font-semibold text-[#4B2E20] focus:outline-none"
                      >
                        <option value="pendente">Aguardando Início</option>
                        <option value="em_criacao">Em Criação</option>
                        <option value="aprovacao">Aprovação</option>
                        <option value="concluido">Finalizado</option>
                        <option value="cancelado">Cancelado</option>
                      </select>

                      {order.clientWhatsapp && (
                        <a
                          href={`https://wa.me/55${order.clientWhatsapp.replace(/\D/g, '')}?text=${encodeURIComponent(
                            `Olá ${order.clientName}! Aqui é do Keh Convites sobre a arte do seu convite "${order.templateTitle}".`
                          )}`}
                          target="_blank"
                          rel="noreferrer"
                          className="p-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white shadow-sm transition-colors"
                          title="Falar no WhatsApp"
                        >
                          <Send className="w-4 h-4" />
                        </a>
                      )}
                    </div>
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>
    </div>
  );
}

