import React, { useState, useRef } from 'react';
import { InvitationTemplate, DigitalFormat, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Smartphone,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  MessageCircle,
  HelpCircle,
  CheckCircle2,
  Image as ImageIcon,
  MousePointerClick,
  Sparkle,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  // Verifica o tipo de convite
  const isInteractivePdf = template.format === 'interativo_pdf';
  const isSiteWeb = template.format === 'site_rsvp';
  const isVideo = template.format === 'animado_video';
  const isCardSimples = template.format === 'imagem_card' || template.format === 'save_the_date';

  // O convite pode ter botões por padrão ou por upgrade opcional
  const modeloJaPossuiBotoes = isInteractivePdf || isSiteWeb;

  // Estados dos Campos
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [idade, setIdade] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Interação & Botões Clicáveis
  const [querBotoesInterativos, setQuerBotoesInterativos] = useState<boolean>(modeloJaPossuiBotoes);
  const [rsvpContato, setRsvpContato] = useState('');
  const [localizacaoMaps, setLocalizacaoMaps] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Foto Anexa
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      const url = URL.createObjectURL(file);
      setFotoPreview(url);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, digite o nome do aniversariante ou homenageado(a)!');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o seu número de WhatsApp com DDD para entrarmos em contato!');
      return;
    }

    // Prepara as notas do pedido
    const detalhesExtras = [
      temaFesta ? `Tema: ${temaFesta}` : '',
      idade ? `Idade: ${idade}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      querBotoesInterativos
        ? `Botões Ativos: RSVP (${rsvpContato || 'Sim'}), Local (${localizacaoMaps || 'Sim'}), Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples (Sem botões interativos)',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto',
    ]
      .filter(Boolean)
      .join(' | ');

    // Cria o objeto do pedido para o sistema
    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      rsvpLink: querBotoesInterativos && rsvpContato ? rsvpContato : undefined,
      mapsLocation: localEvento || localizacaoMaps,
      totalValue: template.price,
      paidValue: 0,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      notes: detalhesExtras,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Monta a mensagem personalizada para enviar via WhatsApp diretamente ao Ateliê Keh Convites
    let msg = `Olá Keh Convites! Gostaria de encomendar este convite digital:\n\n`;
    msg += `💌 *Modelo:* ${template.title}\n`;
    msg += `🏷️ *Categoria:* ${template.category}\n`;
    msg += `💰 *Valor:* R$ ${template.price.toFixed(2)}\n\n`;
    msg += `📋 *DADOS PARA PERSONALIZAR:*\n`;
    msg += `✨ *Nome do Aniversariante/Homenageado:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎈 *Tema da Festa:* ${temaFesta}\n`;
    if (idade.trim()) msg += `🎂 *Idade / Anos:* ${idade}\n`;
    msg += `📅 *Data:* ${dataEvento || 'A definir'}\n`;
    msg += `⏰ *Horário:* ${horarioEvento || 'A definir'}\n`;
    msg += `📍 *Local:* ${localEvento || 'A definir'}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase Especial:* "${fraseEspecial}"\n`;
    msg += `📱 *Meu WhatsApp:* ${whatsappCliente}\n\n`;

    if (querBotoesInterativos) {
      msg += `🔘 *INTERAÇÃO & BOTÕES CLICÁVEIS:*\n`;
      if (rsvpContato.trim()) msg += `✔️ *Confirmação de Presença:* ${rsvpContato}\n`;
      if (localizacaoMaps.trim()) msg += `🗺️ *Link/Endereço Localização:* ${localizacaoMaps}\n`;
      if (listaPresentes.trim()) msg += `🎁 *Lista de Presentes (Sapato, Roupas, Brinquedos):* ${listaPresentes}\n\n`;
    } else {
      msg += `🖼️ *Formato:* Convite em Imagem Simples (Sem botões de interação)\n\n`;
    }

    if (fotoFile) {
      msg += `📸 *Foto anexada:* Sim, já preparei a foto e vou enviar aqui na conversa!`;
    }

    const encodedMsg = encodeURIComponent(msg);
    // Redireciona para o WhatsApp do Ateliê Keh Convites (abre em nova aba)
    const numeroWhats = '5511999999999'; // número padrão do ateliê
    window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');

    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfaf6] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-6 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shadow-sm">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Personalizar Meu Convite
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                Modelo: <span className="font-bold text-[#4B2E20]">{template.title}</span> • R$ {template.price.toFixed(2)}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Formulário com Rolagem Suave */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-5 text-xs text-[#4B2E20]">
          <form onSubmit={handleSubmit} className="space-y-4">

            {/* Aviso sobre o Tipo do Convite */}
            <div className={`p-3.5 rounded-2xl border flex items-start gap-3 ${
              modeloJaPossuiBotoes
                ? 'bg-amber-50/90 border-[#D4AF37]/40 text-[#4B2E20]'
                : 'bg-[#faf5ee] border-[#D4AF37]/30 text-[#4B2E20]'
            }`}>
              <div className="w-7 h-7 rounded-xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shrink-0 mt-0.5">
                {modeloJaPossuiBotoes ? <MousePointerClick className="w-4 h-4" /> : <ImageIcon className="w-4 h-4" />}
              </div>
              <div className="text-xs">
                <p className="font-bold">
                  {modeloJaPossuiBotoes
                    ? '✨ Modelo Interativo com Botões Clicáveis'
                    : '🖼️ Modelo em Imagem Simples para WhatsApp'}
                </p>
                <p className="text-[#4B2E20]/80 mt-0.5 text-[11px] leading-relaxed">
                  {modeloJaPossuiBotoes
                    ? 'Este modelo possui botões interativos onde seus convidados podem clicar direto para confirmar presença, abrir a localização e ver a lista de presentes.'
                    : 'Este modelo é entregue em imagem de alta resolução para enviar direto no WhatsApp. Se você quiser botões clicáveis, pode ativar a opção abaixo!'}
                </p>
              </div>
            </div>

            {/* SEÇÃO 1: DADOS PRINCIPAIS DO ANIVERSARIANTE / EVENTO */}
            <div className="space-y-3">
              <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-1.5 border-b border-[#D4AF37]/20 pb-1.5">
                <Heart className="w-4 h-4 text-[#D4AF37]" />
                <span>Dados do Evento</span>
              </h4>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20]">
                    Nome do Aniversariante ou Homenageado(a) *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Sophia ou Maria Clara"
                    value={nomeAniversariante}
                    onChange={(e) => setNomeAniversariante(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Sparkle className="w-3 h-3 text-[#D4AF37]" />
                    <span>Tema da Festa / Decoração *</span>
                  </label>
                  <Input
                    placeholder="Ex: Safári, Princesas, Floral Boho, Realeza, Neon..."
                    value={temaFesta}
                    onChange={(e) => setTemaFesta(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20]">
                    Idade que vai fazer (opcional)
                  </label>
                  <Input
                    placeholder="Ex: 1 Aninho ou 15 Anos"
                    value={idade}
                    onChange={(e) => setIdade(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Calendar className="w-3 h-3 text-[#D4AF37]" />
                    <span>Data do Evento</span>
                  </label>
                  <Input
                    type="date"
                    value={dataEvento}
                    onChange={(e) => setDataEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Clock className="w-3 h-3 text-[#D4AF37]" />
                    <span>Horário</span>
                  </label>
                  <Input
                    placeholder="Ex: 16:00h às 21:00h"
                    value={horarioEvento}
                    onChange={(e) => setHorarioEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                  />
                </div>
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <MapPin className="w-3 h-3 text-[#D4AF37]" />
                  <span>Local / Endereço da Festa</span>
                </label>
                <Input
                  placeholder="Ex: Buffet Estrela Encantada - Rua das Flores, 120 - Centro"
                  value={localEvento}
                  onChange={(e) => setLocalEvento(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                />
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20]">
                  Frase Especial (se você quiser colocar no convite)
                </label>
                <Input
                  placeholder="Ex: Venha comemorar comigo esse dia mágico! Sua presença é o meu maior presente."
                  value={fraseEspecial}
                  onChange={(e) => setFraseEspecial(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                />
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20]">
                  Seu WhatsApp para Contato & Envio da Arte *
                </label>
                <Input
                  required
                  placeholder="Ex: (11) 99999-8888"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                />
              </div>
            </div>

            {/* SEÇÃO 2: FOTO DO ANIVERSARIANTE (OPCIONAL) */}
            <div className="space-y-2 pt-2 border-t border-[#D4AF37]/20">
              <label className="block font-semibold text-[#4B2E20] flex items-center gap-1.5">
                <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Foto do Aniversariante / Homenageado(a) (Opcional)</span>
              </label>
              <div className="flex flex-col sm:flex-row items-center gap-3 p-3 bg-white border border-[#D4AF37]/30 rounded-2xl">
                <input
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
                  onChange={handleFotoChange}
                  className="hidden"
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => fileInputRef.current?.click()}
                  className="border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ebdccb] text-xs rounded-xl"
                >
                  <Upload className="w-3.5 h-3.5 mr-1.5 text-[#D4AF37]" />
                  {fotoFile ? 'Trocar Foto' : 'Escolher Foto do Dispositivo'}
                </Button>

                {fotoPreview && (
                  <div className="flex items-center gap-2">
                    <img
                      src={fotoPreview}
                      alt="Prévia"
                      className="w-10 h-10 rounded-xl object-cover border border-[#D4AF37]"
                    />
                    <span className="text-[11px] text-[#4B2E20]/80 truncate max-w-[180px]">
                      {fotoFile?.name}
                    </span>
                    <button
                      type="button"
                      onClick={() => {
                        setFotoFile(null);
                        setFotoPreview(null);
                      }}
                      className="text-red-500 hover:text-red-700 text-xs ml-1"
                    >
                      Remover
                    </button>
                  </div>
                )}
                {!fotoPreview && (
                  <span className="text-[11px] text-[#4B2E20]/60">
                    Se você quiser adicionar foto no modelo, selecione acima.
                  </span>
                )}
              </div>
            </div>

            {/* SEÇÃO 3: SOBRE BOTÕES E INTERAÇÃO (DEPENDE DO MODELO) */}
            <div className="pt-2 border-t border-[#D4AF37]/20 space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-1.5">
                    <MousePointerClick className="w-4 h-4 text-[#D4AF37]" />
                    <span>Interação & Botões Clicáveis</span>
                  </h4>
                  <p className="text-[11px] text-[#4B2E20]/70">
                    {isCardSimples
                      ? 'Modelos simples não têm botões clicáveis. Deseja adicionar interações (RSVP/Presentes)?'
                      : 'Preencha abaixo os links e botões que vão no seu convite interativo.'}
                  </p>
                </div>

                {isCardSimples && (
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={querBotoesInterativos}
                      onChange={(e) => setQuerBotoesInterativos(e.target.checked)}
                      className="w-4 h-4 accent-[#4B2E20] rounded"
                    />
                    <span className="text-xs font-semibold text-[#4B2E20]">Quero com Botões</span>
                  </label>
                )}
              </div>

              {querBotoesInterativos ? (
                <div className="p-4 rounded-2xl bg-[#faf5ee] border border-[#D4AF37]/40 space-y-3 animate-fade-in">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Número para Confirmação de Presença (RSVP / WhatsApp)
                    </label>
                    <Input
                      placeholder="Ex: (11) 98888-7777 - Titia Amanda"
                      value={rsvpContato}
                      onChange={(e) => setRsvpContato(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Link ou Endereço do Google Maps para o Botão "Como Chegar"
                    </label>
                    <Input
                      placeholder="Ex: https://maps.app.goo.gl/... ou Rua do Evento"
                      value={localizacaoMaps}
                      onChange={(e) => setLocalizacaoMaps(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                      <Gift className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Lista de Presentes / Sugestões para o Botão</span>
                    </label>
                    <Input
                      placeholder="Ex: Sapato nº 23, Roupa Tam 4, Brinquedos educativos, ou Chave Pix"
                      value={listaPresentes}
                      onChange={(e) => setListaPresentes(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl text-xs text-[#4B2E20]"
                    />
                    <span className="text-[10px] text-[#4B2E20]/60 mt-0.5 block">
                      Exemplo: Tamanho de roupas, calçados, tipos de brinquedos preferidos ou link de site.
                    </span>
                  </div>
                </div>
              ) : (
                <div className="p-3 bg-white/70 rounded-2xl border border-[#D4AF37]/20 text-[11px] text-[#4B2E20]/75">
                  Convite em formato de <strong>card simples (imagem)</strong> sem botões na tela. Todos os dados (endereço, data e frase) serão desenhados com alta elegância para visualização rápida no celular.
                </div>
              )}
            </div>

            {/* Ações Finais */}
            <div className="pt-4 flex flex-col sm:flex-row items-center justify-between gap-3 border-t border-[#D4AF37]/25">
              <div className="text-left w-full sm:w-auto">
                <span className="text-[11px] text-[#4B2E20]/70 block">Valor do Modelo:</span>
                <span className="text-xl font-serif font-bold text-[#4B2E20]">
                  R$ {template.price.toFixed(2)}
                </span>
              </div>

              <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onClose}
                  className="text-[#4B2E20] rounded-xl text-xs"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-md border border-[#D4AF37]/40 flex items-center gap-2 px-5 py-2.5"
                >
                  <MessageCircle className="w-4 h-4 text-emerald-400" />
                  <span>Enviar Pedido pelo WhatsApp</span>
                </Button>
              </div>
            </div>

          </form>
        </CardContent>
      </Card>
    </div>
  );
}

