import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Smartphone,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  Send,
  Sparkle,
  MousePointerClick,
  FileImage,
  PartyPopper,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  // Verifica se o modelo escolhido é interativo (tem botões) ou se é simples (sem botões)
  const temInteracao = Boolean(template.hasInteraction);

  // Estados dos Campos Solicitados
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappContato, setWhatsappContato] = useState('');

  // Campos específicos de Interação (APENAS se o modelo for interativo com botões)
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Anexo de Foto (opcional)
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      const url = URL.createObjectURL(file);
      setFotoPreview(url);
    }
  };

  const handleRemoveFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o Nome do Aniversariante ou Homenageado(a)!');
      return;
    }

    if (!whatsappContato.trim()) {
      alert('Por favor, informe seu WhatsApp para que possamos enviar a prévia da arte!');
      return;
    }

    // Cria o objeto do pedido para o sistema da Keh Convites
    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappContato,
      theme: temaFesta,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      giftList: temInteracao ? listaPresentes : undefined,
      mapsLocation: localEvento,
      totalValue: template.price,
      paidValue: 0,
      eventDate: dataEvento,
      eventTime: horarioEvento,
      specialPhrase: fraseEspecial,
      photoUrl: fotoPreview || undefined,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      notes: [
        temaFesta ? `Tema: ${temaFesta}` : '',
        diaSemana ? `Dia: ${diaSemana}` : '',
        fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
        temInteracao
          ? `Interativo com Botões | RSVP: ${confirmacaoPresenca || 'Não informado'} | Presentes: ${listaPresentes || 'Não informado'}`
          : 'Convite Simples (sem botões de interação)',
        fotoFile ? `Com Foto (${fotoFile.name})` : 'Sem foto',
      ]
        .filter(Boolean)
        .join(' | '),
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Monta a mensagem para envio no WhatsApp do Ateliê Keh Convites
    let msg = `Olá Keh Convites! Acabei de escolher um modelo no site:\n\n`;
    msg += `💌 *Modelo Escolhido:* ${template.title}\n`;
    msg += `🏷️ *Tipo:* ${temInteracao ? 'Convite Interativo (com botões)' : 'Convite Simples (sem botões)'}\n`;
    msg += `💰 *Valor:* R$ ${template.price.toFixed(2)}\n\n`;
    msg += `📝 *DADOS PARA O CONVITE:*\n`;
    msg += `✨ *Nome do Aniversariante:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎈 *Tema da Festa:* ${temaFesta}\n`;
    msg += `📅 *Data:* ${dataEvento || 'A definir'} ${diaSemana ? `(${diaSemana})` : ''}\n`;
    msg += `⏰ *Horário:* ${horarioEvento || 'A definir'}\n`;
    msg += `📍 *Local do Evento:* ${localEvento || 'A definir'}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase Especial:* "${fraseEspecial}"\n`;
    msg += `📱 *WhatsApp para Contato:* ${whatsappContato}\n\n`;

    // Informações de botões SOMENTE se o modelo tiver interação
    if (temInteracao) {
      msg += `🔘 *INFORMAÇÕES DOS BOTÕES INTERATIVOS:*\n`;
      msg += `✔️ *Confirmação de Presença:* ${confirmacaoPresenca || 'O mesmo número de contato'}\n`;
      if (listaPresentes.trim()) {
        msg += `🎁 *Lista de Presentes (roupas, sapato, brinquedos):* ${listaPresentes}\n`;
      }
      msg += `\n`;
    }

    if (fotoFile) {
      msg += `📸 *Foto anexada:* Sim, já separei a foto e vou enviar aqui na conversa!\n`;
    }

    const encodedMsg = encodeURIComponent(msg);
    window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');

    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Cabeçalho */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-5 bg-[#ecdccb]/50 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shadow-sm shrink-0">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Preencher Dados do Convite
              </CardTitle>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-xs text-[#4B2E20] font-bold">
                  {template.title}
                </span>
                <span className="text-[11px] text-[#4B2E20]/60">•</span>
                <span className="text-xs font-semibold text-[#855729]">
                  R$ {template.price.toFixed(2)}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${
                  temInteracao
                    ? 'bg-amber-100 text-amber-900 border border-amber-300'
                    : 'bg-[#faf5ee] text-[#4B2E20] border border-[#D4AF37]/30'
                }`}>
                  {temInteracao ? 'Modelo Interativo (com botões)' : 'Convite Simples (sem botões)'}
                </span>
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Formulário com rolagem */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-5 text-xs text-[#4B2E20]">
          <form onSubmit={handleSubmit} className="space-y-4">

            {/* Aviso explicativo */}
            <div className="p-3 rounded-2xl bg-[#f5ebe1] border border-[#D4AF37]/30 flex items-center gap-2.5">
              <PartyPopper className="w-4 h-4 text-[#D4AF37] shrink-0" />
              <p className="text-[11px] text-[#4B2E20] leading-snug">
                Preencha as informações da sua festa abaixo. {temInteracao ? 'Como este modelo possui interação, você também pode preencher os dados dos botões clicáveis!' : 'Este é um convite simples (sem botões clicáveis), ideal para envio rápido no WhatsApp.'}
              </p>
            </div>

            {/* SEÇÃO 1: Dados do Evento */}
            <div className="space-y-3">
              <div className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-1.5 border-b border-[#D4AF37]/20 pb-1.5">
                <Sparkle className="w-4 h-4 text-[#D4AF37]" />
                <span>Dados Principais do Evento</span>
              </div>

              {/* Nome do Aniversariante e Tema da Festa */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20]">
                    Nome do Aniversariante / Homenageado *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Maria Alice, Enzo Gabriel..."
                    value={nomeAniversariante}
                    onChange={(e) => setNomeAniversariante(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <PartyPopper className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Tema da Festa / Evento *</span>
                  </label>
                  <Input
                    placeholder="Ex: Safari, Jardim Encantado, Circo, Rústico..."
                    value={temaFesta}
                    onChange={(e) => setTemaFesta(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                  />
                </div>
              </div>

              {/* Data, Dia da Semana e Horário */}
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Data do Evento</span>
                  </label>
                  <Input
                    type="date"
                    value={dataEvento}
                    onChange={(e) => setDataEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20]">
                    Dia da Semana
                  </label>
                  <Input
                    placeholder="Ex: Sábado, Domingo..."
                    value={diaSemana}
                    onChange={(e) => setDiaSemana(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Horário</span>
                  </label>
                  <Input
                    type="time"
                    value={horarioEvento}
                    onChange={(e) => setHorarioEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                  />
                </div>
              </div>

              {/* Local do Evento */}
              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Local do Evento (Salão, Buffet ou Endereço)</span>
                </label>
                <Input
                  placeholder="Ex: Buffet Magia Kids - Rua das Palmeiras, 150"
                  value={localEvento}
                  onChange={(e) => setLocalEvento(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                />
              </div>

              {/* Frase Especial (opcional) */}
              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Frase Especial (opcional)</span>
                </label>
                <Input
                  placeholder='Ex: "Venha comemorar meu 1º aninho!" ou frase bíblica/afetuosa'
                  value={fraseEspecial}
                  onChange={(e) => setFraseEspecial(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                />
              </div>

              {/* WhatsApp para Contato */}
              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Número do WhatsApp para Contato *</span>
                </label>
                <Input
                  required
                  placeholder="Ex: (11) 99999-9999"
                  value={whatsappContato}
                  onChange={(e) => setWhatsappContato(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                />
              </div>
            </div>

            {/* SEÇÃO 2: CAMPOS DE INTERAÇÃO (APENAS SE O MODELO FOR INTERATIVO COM BOTÕES) */}
            {temInteracao && (
              <div className="space-y-3 pt-2">
                <div className="p-3 rounded-2xl bg-amber-50/80 border border-amber-300 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <MousePointerClick className="w-4 h-4 text-amber-700" />
                    <div>
                      <p className="font-bold text-amber-950 text-xs">
                        Configurações dos Botões Clicáveis
                      </p>
                      <p className="text-[11px] text-amber-800">
                        Este modelo interativo possui botões que seus convidados clicam direto no celular.
                      </p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Número para Confirmação de Presença
                    </label>
                    <Input
                      placeholder="Ex: (11) 98888-7777 (ou deixe vazio para usar o mesmo contato)"
                      value={confirmacaoPresenca}
                      onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                      <Gift className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Lista de Presentes / Tamanhos</span>
                    </label>
                    <Input
                      placeholder="Ex: Calçado nº 20, Roupa tam 2, Brinquedos educativos..."
                      value={listaPresentes}
                      onChange={(e) => setListaPresentes(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs h-9 focus-visible:ring-[#D4AF37]"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* SEÇÃO 3: FOTO (OPCIONAL) */}
            <div className="space-y-2 pt-2 border-t border-[#D4AF37]/20">
              <label className="block font-semibold text-[#4B2E20] flex items-center gap-1">
                <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Adicionar Foto da Criança / Homenageado(a) (opcional)</span>
              </label>

              <div className="flex items-center gap-3">
                <input
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
                  onChange={handleFotoChange}
                  className="hidden"
                />

                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => fileInputRef.current?.click()}
                  className="border-[#D4AF37]/40 text-[#4B2E20] hover:bg-[#ecdccb] rounded-xl text-xs flex items-center gap-1.5"
                >
                  <FileImage className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>{fotoFile ? 'Trocar Foto' : 'Escolher Foto do Aparelho'}</span>
                </Button>

                {fotoFile && (
                  <div className="flex items-center gap-2">
                    {fotoPreview && (
                      <img
                        src={fotoPreview}
                        alt="Prévia"
                        className="w-8 h-8 rounded-lg object-cover border border-[#D4AF37]"
                      />
                    )}
                    <span className="text-[11px] text-[#4B2E20]/80 font-medium truncate max-w-[150px]">
                      {fotoFile.name}
                    </span>
                    <button
                      type="button"
                      onClick={handleRemoveFoto}
                      className="text-red-600 hover:text-red-800 text-[11px] font-bold"
                    >
                      Remover
                    </button>
                  </div>
                )}
              </div>
              <p className="text-[10px] text-[#4B2E20]/70">
                Se o modelo tiver espaço para foto, você pode anexar aqui ou enviar diretamente pelo WhatsApp depois.
              </p>
            </div>

            {/* Rodapé com Botões de Ação */}
            <div className="pt-3 border-t border-[#D4AF37]/25 flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] rounded-xl text-xs"
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow border border-[#D4AF37]/40 flex items-center gap-2 px-5"
              >
                <Send className="w-4 h-4 text-[#D4AF37]" />
                <span>Enviar Dados & Encomendar no WhatsApp</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

