import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Sparkles,
  Heart,
  MousePointerClick,
  Smartphone,
  Eye,
  CheckCircle2,
} from 'lucide-react';
import { ClientOrderModal } from '@/components/ClientOrderModal';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOpenNewOrderModal?: (template: InvitationTemplate) => void;
  isAdmin?: boolean;
}

export function TemplatesCatalog({
  templates,
  onOpenNewOrderModal,
  isAdmin = false,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('todos');
  const [selectedFormatFilter, setSelectedFormatFilter] = useState<string>('todos');

  // Modal de Personalização para o Cliente
  const [orderModalOpen, setOrderModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  const categories: InvitationCategory[] = [
    'Infantil',
    'Casamento',
    '15 Anos',
    'Batizado',
    'Corporativo',
    'Bodas',
  ];

  const filteredTemplates = templates.filter((tpl) => {
    const matchesCategory =
      selectedCategory === 'todos' || tpl.category.toLowerCase() === selectedCategory.toLowerCase();

    const matchesFormat =
      selectedFormatFilter === 'todos' ||
      (selectedFormatFilter === 'interativo' && tpl.hasInteraction) ||
      (selectedFormatFilter === 'simples' && !tpl.hasInteraction);

    return matchesCategory && matchesFormat;
  });

  const handleSelectTemplate = (tpl: InvitationTemplate) => {
    setSelectedTemplateForOrder(tpl);
    setOrderModalOpen(true);
  };

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Banner de Apresentação */}
      <section className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#4B2E20] via-[#5c3724] to-[#73442a] text-[#F7EBDD] p-6 sm:p-10 shadow-xl border border-[#D4AF37]/35">
        <div className="relative z-10 max-w-2xl space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/40 text-[#D4AF37] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5" />
            <span>Ateliê Keh Convites • Modelos Digitais Exclusivos</span>
          </div>

          <h1 className="text-2xl sm:text-4xl font-serif font-bold text-[#F7EBDD] tracking-tight leading-tight">
            Escolha o modelo perfeito para o seu momento especial
          </h1>

          <p className="text-xs sm:text-sm text-[#F7EBDD]/80 leading-relaxed font-sans">
            Temos <strong>Convites Simples</strong> em imagem de alta resolução e <strong>Convites Interativos</strong> com botões clicáveis de confirmação de presença e presentes. Escolha seu modelo favorito e preencha os dados da festa!
          </p>
        </div>

        {/* Efeito decorativo dourado de fundo */}
        <div className="absolute right-[-10%] top-[-20%] w-72 h-72 rounded-full bg-[#D4AF37]/10 blur-3xl pointer-events-none" />
      </section>

      {/* Barra de Filtros */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-[#ecdccb]/50 p-3 sm:p-4 rounded-2xl border border-[#D4AF37]/30">
        {/* Filtro por Categoria */}
        <div className="flex flex-wrap items-center gap-1.5">
          <button
            onClick={() => setSelectedCategory('todos')}
            className={`px-3 py-1.5 rounded-xl text-xs font-medium transition-all ${
              selectedCategory === 'todos'
                ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm font-semibold'
                : 'bg-white/80 text-[#4B2E20] hover:bg-white'
            }`}
          >
            Todas Ocasiões
          </button>
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3 py-1.5 rounded-xl text-xs font-medium transition-all ${
                selectedCategory === cat
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm font-semibold'
                  : 'bg-white/80 text-[#4B2E20] hover:bg-white'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Filtro Simples vs Interativo */}
        <div className="flex items-center gap-1.5 bg-white/70 p-1 rounded-xl border border-[#D4AF37]/30 text-xs">
          <button
            onClick={() => setSelectedFormatFilter('todos')}
            className={`px-2.5 py-1 rounded-lg transition-colors font-medium ${
              selectedFormatFilter === 'todos' ? 'bg-[#4B2E20] text-[#F7EBDD]' : 'text-[#4B2E20]'
            }`}
          >
            Todos
          </button>
          <button
            onClick={() => setSelectedFormatFilter('simples')}
            className={`px-2.5 py-1 rounded-lg transition-colors font-medium ${
              selectedFormatFilter === 'simples' ? 'bg-[#4B2E20] text-[#F7EBDD]' : 'text-[#4B2E20]'
            }`}
          >
            Convite Simples
          </button>
          <button
            onClick={() => setSelectedFormatFilter('interativo')}
            className={`px-2.5 py-1 rounded-lg transition-colors font-medium flex items-center gap-1 ${
              selectedFormatFilter === 'interativo' ? 'bg-[#4B2E20] text-[#F7EBDD]' : 'text-[#4B2E20]'
            }`}
          >
            <MousePointerClick className="w-3 h-3" />
            Interativo (Botões)
          </button>
        </div>
      </div>

      {/* Grade de Modelos */}
      {filteredTemplates.length === 0 ? (
        <div className="text-center py-16 bg-white/60 rounded-3xl border border-dashed border-[#D4AF37]/40">
          <p className="text-sm font-serif text-[#4B2E20]">Nenhum modelo encontrado nesta categoria.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => (
            <Card
              key={template.id}
              className="group bg-white/95 border-[#D4AF37]/35 rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col"
            >
              {/* Imagem do Modelo */}
              <div className="relative aspect-[4/5] overflow-hidden bg-[#faf5ee]">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                />

                {/* Badge do Tipo de Convite (Simples ou Interativo) */}
                <div className="absolute top-3 left-3 flex flex-col gap-1.5">
                  <span
                    className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-bold shadow-md ${
                      template.hasInteraction
                        ? 'bg-[#4B2E20] text-[#D4AF37] border border-[#D4AF37]/50'
                        : 'bg-[#faf5ee]/95 text-[#4B2E20] border border-[#D4AF37]/40'
                    }`}
                  >
                    {template.hasInteraction ? (
                      <>
                        <MousePointerClick className="w-3 h-3 text-[#D4AF37]" />
                        Interativo (com Botões)
                      </>
                    ) : (
                      <>
                        <Smartphone className="w-3 h-3 text-[#4B2E20]" />
                        Convite Simples
                      </>
                    )}
                  </span>

                  <span className="inline-block px-2 py-0.5 rounded-full text-[10px] font-semibold bg-white/90 text-[#4B2E20] shadow-sm backdrop-blur-sm self-start">
                    {template.category}
                  </span>
                </div>

                {/* Preço */}
                <div className="absolute bottom-3 right-3 bg-[#4B2E20]/90 backdrop-blur-md text-[#F7EBDD] px-3 py-1 rounded-full text-xs font-bold border border-[#D4AF37]/40 shadow-sm">
                  R$ {template.price.toFixed(2)}
                </div>
              </div>

              {/* Informações do Modelo */}
              <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                <div>
                  <h3 className="text-base font-serif font-bold text-[#4B2E20] group-hover:text-[#855729] transition-colors">
                    {template.title}
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75 mt-1 line-clamp-2 leading-relaxed">
                    {template.description}
                  </p>
                </div>

                {/* Botão de Escolha do Modelo */}
                <Button
                  onClick={() => handleSelectTemplate(template)}
                  className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center justify-center gap-2 py-2.5 active:scale-[0.98] transition-transform"
                >
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Quero este Modelo</span>
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Modal de Personalização do Cliente */}
      <ClientOrderModal
        isOpen={orderModalOpen}
        template={selectedTemplateForOrder}
        onClose={() => {
          setOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        onSubmitOrder={(newOrder) => {
          if (onOpenNewOrderModal) {
            onOpenNewOrderModal(selectedTemplateForOrder!);
          }
        }}
      />
    </div>
  );
}

