} from 'lucide-react';

export interface OrdersManagerProps {
  orders: Order[];
  onOpenNewOrder: () => void;
  onUpdateOrderStatus: (orderId: string, status: OrderStatus) => void;
  onUpdatePaymentStatus: (orderId: string, status: PaymentStatus) => void;
}

export function OrdersManager({
  orders,
  onOpenNewOrder,
  onUpdateOrderStatus,
  onUpdatePaymentStatus,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('todos');

  const safeOrders = orders || [];

  const filteredOrders = safeOrders.filter((ord) => {
    const matchesSearch =
      (ord.clientName || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (ord.templateTitle || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (ord.theme || '').toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'todos' || ord.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'concluido':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">Concluído</span>;
      case 'em_criacao':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 text-blue-800">Em Criação</span>;
      case 'aprovacao':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">Aprovação</span>;
      case 'pendente':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-orange-100 text-orange-800">Pendente</span>;
      default:
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-gray-100 text-gray-800">{status}</span>;
