        >
          <Plus className="w-4 h-4 text-[#D4AF37]" />
          <span>Cadastrar Pedido</span>
        </Button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
        <div className="relative w-full sm:w-72">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
          <Input
            placeholder="Buscar por cliente, modelo ou tema..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 bg-white border-[#D4AF37]/35 text-[#4B2E20] text-xs rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Filter className="w-4 h-4 text-[#4B2E20]/60 shrink-0" />
          <select
