          >
            <option value="todos">Todos os Status</option>
            <option value="pendente">Pendente</option>
            <option value="em_criacao">Em Criação</option>
            <option value="aprovacao">Aprovação</option>
            <option value="concluido">Concluído</option>
          </select>
        </div>
      </div>

      {/* Lista de Pedidos */}
      <div className="space-y-3">
        {filteredOrders.length === 0 ? (
          <div className="text-center py-12 bg-white/70 rounded-2xl border border-dashed border-[#D4AF37]/40">
            <p className="text-xs text-[#4B2E20]/70 font-medium">Nenhum pedido encontrado.</p>
