                  </div>

                  <div className="text-xs text-[#4B2E20]/80 flex flex-wrap items-center gap-x-4 gap-y-1">
                    <span><strong>Modelo:</strong> {ord.templateTitle}</span>
                    {ord.theme && <span><strong>Tema:</strong> {ord.theme}</span>}
                    {ord.clientWhatsapp && (
                      <span className="flex items-center gap-1 text-[#855729]">
                        <Smartphone className="w-3 h-3" />
