                  {ord.notes && (
                    <p className="text-[11px] text-[#4B2E20]/70 bg-[#faf5ee] p-2 rounded-xl mt-1 border border-[#D4AF37]/20">
                      <strong>Detalhes:</strong> {ord.notes}
