                </div>

                {/* Valores & Status */}
                <div className="flex flex-row lg:flex-col items-center lg:items-end justify-between gap-2 shrink-0 border-t lg:border-t-0 pt-3 lg:pt-0 border-[#D4AF37]/20">
                  <div className="text-left lg:text-right">
                    <span className="text-sm font-bold text-[#4B2E20]">
                      R$ {Number(ord.totalValue || 0).toFixed(2)}
                    </span>
                    <span className="block text-[10px] text-emerald-700 font-semibold uppercase">
                      Pgto: {ord.paymentStatus}
