                  </div>

                  <div className="flex items-center gap-1.5">
                    <select
                      value={ord.status}
                      onChange={(e) => onUpdateOrderStatus(ord.id, e.target.value as OrderStatus)}
                      className="h-8 px-2 rounded-lg bg-[#faf5ee] border border-[#D4AF37]/40 text-[11px] text-[#4B2E20] font-semibold focus:outline-none"
                    >
                      <option value="pendente">Pendente</option>
                      <option value="em_criacao">Em Criação</option>
                      <option value="aprovacao">Aprovação</option>
                      <option value="concluido">Concluído</option>
                    </select>

                    <select
                      value={ord.paymentStatus}
                      onChange={(e) => onUpdatePaymentStatus(ord.id, e.target.value as PaymentStatus)}
                      className="h-8 px-2 rounded-lg bg-[#faf5ee] border border-[#D4AF37]/40 text-[11px] text-[#4B2E20] font-semibold focus:outline-none"
                    >
                      <option value="pago">Pago</option>
                      <option value="parcial">Parcial</option>
                      <option value="pendente">Pendente</option>
                    </select>
                  </div>
                </div>
              </div>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

