import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { OrdersManager } from '@/components/OrdersManager';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'templates' | 'orders' | 'dashboard'>('templates');
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle de Acesso Administrativo (Senha: 41526378)
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [adminModalOpen, setAdminModalOpen] = useState<boolean>(false);

  // Modais de Criação (Acesso Administrativo)
  const [newOrderModalOpen, setNewOrderModalOpen] = useState(false);
  const [newTemplateModalOpen, setNewTemplateModalOpen] = useState(false);

  // Handlers de Pedidos
  const handleSaveNewOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, status } : ord))
    );
  };

  const handleUpdatePaymentStatus = (orderId: string, status: PaymentStatus) => {
    setOrders((prev) =>
      prev.map((ord) => {
        if (ord.id === orderId) {
          const paidValue = status === 'pago' ? ord.totalValue : status === 'parcial' ? ord.totalValue / 2 : 0;
          return { ...ord, paymentStatus: status, paidValue };
        }
        return ord;
      })
    );
  };

  const handleSaveNewTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente' || o.status === 'em_criacao').length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={(tab) => {
          if ((tab === 'orders' || tab === 'dashboard') && !isAdminAuthenticated) {
            setAdminModalOpen(true);
            return;
          }
          setCurrentTab(tab);
        }}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setAdminModalOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => setNewOrderModalOpen(true)}
        onOpenNewTemplate={() => setNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenNewOrderModal={(template) => {
              if (isAdminAuthenticated) {
                setNewOrderModalOpen(true);
              }
            }}
            isAdmin={isAdminAuthenticated}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onOpenNewOrder={() => setNewOrderModalOpen(true)}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onUpdatePaymentStatus={handleUpdatePaymentStatus}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Simples e Delicado */}
      <footer className="border-t border-[#D4AF37]/25 bg-[#ecdccb]/40 py-6 text-center text-xs text-[#4B2E20]/75">
        <div className="max-w-7xl mx-auto px-4">
          <p className="font-serif font-bold text-sm text-[#4B2E20]">Keh Convites • Ateliê de Convites Digitais</p>
          <p className="mt-1 text-[11px]">Personalização com carinho para festas e momentos especiais</p>
        </div>
      </footer>

      {/* Modal de Login da Área Administrativa (Senha: 41526378) */}
      <AdminLoginModal
        isOpen={adminModalOpen}
        onClose={() => setAdminModalOpen(false)}
        onSuccess={() => {
          setIsAdminAuthenticated(true);
          setAdminModalOpen(false);
          setCurrentTab('orders');
        }}
      />

      {/* Modal de Criação de Pedido Manual (Admin) */}
      <NewOrderModal
        isOpen={newOrderModalOpen}
        onClose={() => setNewOrderModalOpen(false)}
        templates={templates}
        onSaveOrder={handleSaveNewOrder}
      />

      {/* Modal de Novo Modelo Digital (Admin) */}
      <NewTemplateModal
        isOpen={newTemplateModalOpen}
        onClose={() => setNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveNewTemplate}
      />
    </div>
  );
}

