import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  MessageCircle,
  Phone,
  HelpCircle,
  Image as ImageIcon,
  Send,
  PartyPopper,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  // Define com precisão se o modelo tem botões/interação
  // Se for convite simples em imagem ou hasInteraction for false, NÃO tem botões
  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  // Campos principais
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos exclusivos para modelos QUE TÊM interação
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Foto opcional
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, preencha o nome do aniversariante / homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o WhatsApp para contato.');
      return;
    }

    const notasFormatadas = [
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Modelo Simples (sem botões interativos)',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto',
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      rsvpLink: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      totalValue: template.price,
      paidValue: 0,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Mensagem objetiva e direta para o WhatsApp
    let msg = `Olá Keh Convites! Gostaria de encomendar este convite:\n\n`;
    msg += `💌 *Modelo:* ${template.title}\n`;
    msg += `🏷️ *Tipo:* ${temInteracao ? 'Convite Interativo (com botões)' : 'Convite Simples (sem botões)'}\n`;
    msg += `💰 *Valor:* R$ ${template.price.toFixed(2)}\n\n`;
    msg += `📝 *DADOS DO CONVITE:*\n`;
    msg += `👤 *Nome do aniversariante:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎨 *Tema:* ${temaFesta}\n`;
    if (dataEvento.trim()) msg += `📅 *Data:* ${dataEvento}\n`;
    if (diaSemana.trim()) msg += `🗓️ *Dia da semana:* ${diaSemana}\n`;
    if (horarioEvento.trim()) msg += `⏰ *Horário:* ${horarioEvento}\n`;
    if (localEvento.trim()) msg += `📍 *Local:* ${localEvento}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase especial:* "${fraseEspecial}"\n`;
    msg += `📱 *WhatsApp para contato:* ${whatsappCliente}\n`;

    if (temInteracao) {
      msg += `\n✨ *INFORMAÇÕES DOS BOTÕES INTERATIVOS:*\n`;
      if (confirmacaoPresenca.trim()) msg += `📲 *Confirmação de presença:* ${confirmacaoPresenca}\n`;
      if (linkLocalizacao.trim()) msg += `🗺️ *Localização (Maps/Endereço):* ${linkLocalizacao}\n`;
      if (listaPresentes.trim()) msg += `🎁 *Lista de presentes (tamanho de roupas, calçados, brinquedos):* ${listaPresentes}\n`;
    }

    if (fotoFile) {
      msg += `\n📸 *Foto:* Vou anexar a foto aqui no WhatsApp!`;
    }

    const encodedMsg = encodeURIComponent(msg);
    window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfaf6] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-5 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shadow-sm">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Preencher Dados do Convite
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                Modelo: <span className="font-bold text-[#4B2E20]">{template.title}</span> • R$ {template.price.toFixed(2)}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Informações e Formulário */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-4 text-xs text-[#4B2E20]">

          {/* Identificação clara do modelo (Simples ou Interativo) */}
          <div className="p-3 rounded-xl bg-[#F7EBDD] border border-[#D4AF37]/35 flex items-center justify-between">
            <span className="font-semibold text-[#4B2E20]">
              Tipo do Modelo:
            </span>
            <span className={`px-2.5 py-1 rounded-lg text-[11px] font-bold ${
              temInteracao
                ? 'bg-[#4B2E20] text-[#D4AF37]'
                : 'bg-white border border-[#D4AF37]/40 text-[#4B2E20]'
            }`}>
              {temInteracao ? 'Convite Interativo (com botões)' : 'Convite Simples (sem botões)'}
            </span>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">

            {/* Bloco 1: Dados do Aniversariante e Tema */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[#4B2E20] font-semibold mb-1">
                  Nome do Aniversariante / Homenageado *
                </label>
                <Input
                  required
                  placeholder="Ex: Lucca ou Maria Clara"
                  value={nomeAniversariante}
                  onChange={(e) => setNomeAniversariante(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] font-semibold mb-1">
                  Tema da Festa / Evento
                </label>
                <div className="relative">
                  <PartyPopper className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                  <Input
                    placeholder="Ex: Safari, Ursinho Príncipe, Floral..."
                    value={temaFesta}
                    onChange={(e) => setTemaFesta(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>
            </div>

            {/* Bloco 2: Data, Dia e Horário */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div>
                <label className="block text-[#4B2E20] font-semibold mb-1">
                  Data do Evento
                </label>
                <div className="relative">
                  <Calendar className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                  <Input
                    type="date"
                    value={dataEvento}
                    onChange={(e) => setDataEvento(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>

              <div>
                <label className="block text-[#4B2E20] font-semibold mb-1">
                  Dia da Semana
                </label>
                <Input
                  placeholder="Ex: Sábado, Domingo..."
                  value={diaSemana}
                  onChange={(e) => setDiaSemana(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="block text-[#4B2E20] font-semibold mb-1">
                  Horário
                </label>
                <div className="relative">
                  <Clock className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                  <Input
                    type="time"
                    value={horarioEvento}
                    onChange={(e) => setHorarioEvento(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>
            </div>

            {/* Bloco 3: Local do Evento */}
            <div>
              <label className="block text-[#4B2E20] font-semibold mb-1">
                Local do Evento
              </label>
              <div className="relative">
                <MapPin className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                <Input
                  placeholder="Ex: Buffet Estrela Dourada - Rua das Flores, 123"
                  value={localEvento}
                  onChange={(e) => setLocalEvento(e.target.value)}
                  className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                />
              </div>
            </div>

            {/* Bloco 4: Frase Especial (se a cliente quiser) */}
            <div>
              <label className="block text-[#4B2E20] font-semibold mb-1 flex items-center justify-between">
                <span>Frase Especial (opcional)</span>
                <span className="text-[10px] text-[#4B2E20]/60 font-normal">se a cliente quiser</span>
              </label>
              <div className="relative">
                <Heart className="w-3.5 h-3.5 absolute left-3 top-3 text-[#D4AF37]" />
                <textarea
                  rows={2}
                  placeholder='Ex: "Venha comemorar comigo o meu 1º aninho!"'
                  value={fraseEspecial}
                  onChange={(e) => setFraseEspecial(e.target.value)}
                  className="w-full pl-8 pr-3 py-2 rounded-xl bg-white border border-[#D4AF37]/40 text-[#4B2E20] text-xs focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                />
              </div>
            </div>

            {/* Bloco 5: WhatsApp para Contato */}
            <div>
              <label className="block text-[#4B2E20] font-semibold mb-1">
                Número do WhatsApp para Contato *
              </label>
              <div className="relative">
                <Phone className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                <Input
                  required
                  placeholder="Ex: (11) 99999-9999"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                />
              </div>
            </div>

            {/* Bloco 6: SE O MODELO TIVER INTERAÇÃO (BOTÕES CLICÁVEIS) */}
            {temInteracao && (
              <div className="p-3.5 rounded-2xl bg-[#ecdccb]/45 border border-[#D4AF37]/40 space-y-3">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-[#D4AF37]" />
                  <h4 className="font-serif font-bold text-xs text-[#4B2E20]">
                    Informações dos Botões Interativos deste Modelo
                  </h4>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[#4B2E20] font-semibold mb-1">
                      Número para Confirmação de Presença
                    </label>
                    <Input
                      placeholder="Ex: WhatsApp para confirmar presença"
                      value={confirmacaoPresenca}
                      onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>

                  <div>
                    <label className="block text-[#4B2E20] font-semibold mb-1">
                      Link ou Endereço da Localização (Maps)
                    </label>
                    <Input
                      placeholder="Link do Google Maps ou endereço exato"
                      value={linkLocalizacao}
                      onChange={(e) => setLinkLocalizacao(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[#4B2E20] font-semibold mb-1">
                    Lista de Presentes (ex: número de sapato, tamanho de roupas, brinquedos)
                  </label>
                  <div className="relative">
                    <Gift className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                    <Input
                      placeholder="Ex: Roupa tamanho 2, sapato 21, brinquedos educativos ou link"
                      value={listaPresentes}
                      onChange={(e) => setListaPresentes(e.target.value)}
                      className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Bloco 7: Anexar Foto (se a pessoa quiser) */}
            <div className="p-3 rounded-2xl bg-white border border-[#D4AF37]/30">
              <div className="flex items-center justify-between mb-2">
                <span className="font-semibold text-[#4B2E20] flex items-center gap-1.5">
                  <ImageIcon className="w-4 h-4 text-[#D4AF37]" />
                  Adicionar Foto (Opcional)
                </span>
                <span className="text-[10px] text-[#4B2E20]/60">se quiser colocar foto no convite</span>
              </div>

              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleFotoChange}
                className="hidden"
                id="foto-upload"
              />

              {!fotoPreview ? (
                <label
                  htmlFor="foto-upload"
                  className="flex items-center justify-center gap-2 p-3 border border-dashed border-[#D4AF37]/60 rounded-xl cursor-pointer hover:bg-[#F7EBDD]/40 transition-colors text-center"
                >
                  <Upload className="w-4 h-4 text-[#4B2E20]/70" />
                  <span className="text-[11px] font-medium text-[#4B2E20]">
                    Clique aqui para anexar a foto do aniversariante
                  </span>
                </label>
              ) : (
                <div className="flex items-center justify-between p-2 rounded-xl bg-[#F7EBDD]/50 border border-[#D4AF37]/30">
                  <div className="flex items-center gap-2.5">
                    <img
                      src={fotoPreview}
                      alt="Prévia"
                      className="w-10 h-10 object-cover rounded-lg border border-[#D4AF37]/40"
                    />
                    <div>
                      <p className="font-semibold text-[#4B2E20] text-[11px] truncate max-w-[180px]">
                        {fotoFile?.name}
                      </p>
                      <span className="text-[10px] text-emerald-700 font-medium">Foto selecionada</span>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={handleRemoverFoto}
                    className="p-1 rounded-lg text-red-700 hover:bg-red-50 text-xs font-semibold"
                  >
                    Remover
                  </button>
                </div>
              )}
            </div>

            {/* Botão de Envio */}
            <div className="pt-2 flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] text-xs rounded-xl"
              >
                Voltar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center gap-2 px-5 py-2.5"
              >
                <Send className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Enviar Pedido pelo WhatsApp</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

