import React from 'react';
import { Layers, DollarSign, FolderHeart, Plus, Sparkles, Lock, LogOut, Smartphone } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface NavbarProps {
  currentTab: 'dashboard' | 'orders' | 'templates';
  setCurrentTab: (tab: 'dashboard' | 'orders' | 'templates') => void;
  isAdminAuthenticated: boolean;
  onOpenAdminAuth: () => void;
  onLogoutAdmin: () => void;
  onOpenNewOrder: () => void;
  onOpenNewTemplate: () => void;
  pendingOrdersCount: number;
}

export function Navbar({
  currentTab,
  setCurrentTab,
  isAdminAuthenticated,
  onOpenAdminAuth,
  onLogoutAdmin,
  onOpenNewOrder,
  onOpenNewTemplate,
  pendingOrdersCount,
}: NavbarProps) {
  return (
    <header className="sticky top-0 z-30 w-full border-b border-[#D4AF37]/35 bg-[#F7EBDD]/92 backdrop-blur-md shadow-[0_4px_24px_rgba(75,46,32,0.05)] transition-all">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="h-20 flex items-center justify-between gap-4">

          {/* Logo e Identidade Visual */}
          <div
            className="flex items-center gap-3.5 cursor-pointer select-none group"
            onClick={() => setCurrentTab('templates')}
          >
            <div className="relative w-12 h-12 rounded-2xl bg-gradient-to-tr from-[#4B2E20] via-[#855729] to-[#D4AF37] p-[1.5px] shadow-sm transition-transform duration-300 group-hover:scale-105">
              <div className="w-full h-full bg-[#fdf9f4] rounded-[14px] flex items-center justify-center relative overflow-hidden">
                <span className="font-serif italic font-black text-2xl text-[#4B2E20] group-hover:text-[#D4AF37] transition-colors">
