  onSelectTemplate: (template: InvitationTemplate) => void;
  isAdmin: boolean;
  onOpenNewTemplate: () => void;
  onSubmitClientOrder?: (newOrder: any) => void;
}

export function TemplatesCatalog({
  templates,
  onSelectTemplate,
  isAdmin,
  onOpenNewTemplate,
  onSubmitClientOrder,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('todos');
  const [searchQuery, setSearchQuery] = useState('');
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);
  const [orderingTemplate, setOrderingTemplate] = useState<InvitationTemplate | null>(null);

  const categories: { label: string; value: string }[] = [
    { label: 'Todos os Modelos', value: 'todos' },
    { label: 'Infantil', value: 'Infantil' },
    { label: 'Casamento', value: 'Casamento' },
    { label: '15 Anos', value: '15 Anos' },
    { label: 'Batizado', value: 'Batizado' },
    { label: 'Bodas', value: 'Bodas' },
    { label: 'Corporativo', value: 'Corporativo' },
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchesCategory =
      selectedCategory === 'todos' || tpl.category === selectedCategory;
    const matchesSearch =
      tpl.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (tpl.tags && tpl.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase())));
    return matchesCategory && matchesSearch;
  });

  const handleOrder = (template: InvitationTemplate) => {
    setOrderingTemplate(template);
  };

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      {/* Banner de Apresentação Delicado & Artesanal */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#fcf7f0] via-[#f7ebdd] to-[#f3dfca] border border-[#D4AF37]/30 shadow-md p-6 sm:p-10 text-center">
        {/* Detalhes decorativos suaves de fundo */}
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-56 h-56 rounded-full bg-[#D4AF37]/10 blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 left-0 -ml-16 -mb-16 w-56 h-56 rounded-full bg-[#4B2E20]/5 blur-3xl pointer-events-none" />

        <div className="relative z-10 max-w-2xl mx-auto space-y-3">
          <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-white/80 border border-[#D4AF37]/40 shadow-xs text-xs font-medium text-[#4B2E20]">
            <Heart className="w-3.5 h-3.5 text-[#D4AF37] fill-[#D4AF37]/30" />
            <span>Feito à mão, com carinho para o seu grande dia</span>
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
          </div>

          <h1 className="text-2xl sm:text-4xl font-serif font-bold text-[#4B2E20] tracking-tight">
            Convites Digitais Exclusivos & Personalizados
          </h1>

          <p className="text-xs sm:text-sm text-[#4B2E20]/80 font-normal leading-relaxed max-w-xl mx-auto">
            Escolha o modelo que mais combina com seu evento. Personalizamos cada detalhe com as suas cores, fotos e informações para encantar os seus convidados no WhatsApp.
          </p>

          <div className="pt-2 flex flex-wrap items-center justify-center gap-3 text-[11px] text-[#4B2E20]/75">
            <span className="flex items-center gap-1 bg-white/60 px-3 py-1 rounded-full border border-[#D4AF37]/25">
              <CheckCircle2 className="w-3 h-3 text-[#D4AF37]" /> Envio rápido no WhatsApp
            </span>
            <span className="flex items-center gap-1 bg-white/60 px-3 py-1 rounded-full border border-[#D4AF37]/25">
              <CheckCircle2 className="w-3 h-3 text-[#D4AF37]" /> Alta resolução para celular
            </span>
            <span className="flex items-center gap-1 bg-white/60 px-3 py-1 rounded-full border border-[#D4AF37]/25">
              <CheckCircle2 className="w-3 h-3 text-[#D4AF37]" /> Modelos Simples e Interativos
            </span>
          </div>
        </div>
      </div>

      {/* Barra de Filtros Delicada */}
      <div className="space-y-4">
        {/* Campo de Busca & Seleção */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white/70 backdrop-blur-sm p-2 sm:p-3 rounded-2xl border border-[#D4AF37]/25 shadow-xs">
          <div className="relative flex-1">
            <Search className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-[#4B2E20]/40" />
            <input
              type="text"
              placeholder="Buscar por tema, estilo (ex: safari, floral, minimalista)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-transparent text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/45 focus:outline-none"
            />
          </div>

          <div className="text-[11px] font-medium text-[#4B2E20]/70 px-3 hidden sm:block">
            {filteredTemplates.length} {filteredTemplates.length === 1 ? 'modelo encontrado' : 'modelos encontrados'}
          </div>
        </div>

        {/* Categorias em Pílulas Delicadas */}
        <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-none">
          {categories.map((cat) => (
            <button
              key={cat.value}
              onClick={() => setSelectedCategory(cat.value)}
              className={`px-4 py-2 rounded-xl text-xs font-medium whitespace-nowrap transition-all duration-200 ${
                selectedCategory === cat.value
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm font-semibold'
                  : 'bg-white/80 hover:bg-[#F7EBDD]/60 text-[#4B2E20]/80 border border-[#D4AF37]/20 hover:border-[#D4AF37]/40'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos Personalizados */}
      {filteredTemplates.length === 0 ? (
        <div className="text-center py-16 bg-white/50 rounded-3xl border border-dashed border-[#D4AF37]/40 p-8 space-y-3">
          <Heart className="w-10 h-10 text-[#D4AF37]/50 mx-auto" />
          <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum modelo encontrado</h3>
          <p className="text-xs text-[#4B2E20]/70 max-w-sm mx-auto">
            Tente pesquisar com outra palavra ou selecione a categoria "Todos os Modelos".
          </p>
          <Button
            onClick={() => {
              setSelectedCategory('todos');
              setSearchQuery('');
            }}
            variant="outline"
            className="border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
          >
            Limpar Filtros
          </Button>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-7">
          {filteredTemplates.map((template) => {
            const isInterativo = Boolean(
              template.hasInteraction ||
              template.format === 'interativo_pdf' ||
              template.format === 'site_rsvp'
            );

            return (
              <Card
                key={template.id}
                className="group bg-white/90 rounded-3xl border border-[#D4AF37]/30 shadow-xs hover:shadow-xl hover:border-[#D4AF37]/60 transition-all duration-300 overflow-hidden flex flex-col hover:-translate-y-1"
              >
                {/* Imagem do Convite */}
                <div className="relative aspect-[4/5] bg-[#F7EBDD]/40 overflow-hidden">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />

                  {/* Gradiente sutil */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                  {/* Badge de Categoria Delicada */}
                  <div className="absolute top-3 left-3 flex flex-col gap-1.5 items-start">
                    <span className="px-3 py-1 rounded-full text-[10px] font-bold bg-[#4B2E20]/90 text-[#F7EBDD] backdrop-blur-md shadow-sm border border-[#D4AF37]/30">
                      {template.category}
                    </span>
                    <span className={`px-2.5 py-0.5 rounded-full text-[9px] font-bold shadow-xs ${
                      isInterativo
                        ? 'bg-[#D4AF37] text-[#4B2E20]'
                        : 'bg-white/95 text-[#4B2E20] border border-[#D4AF37]/30'
                    }`}>
                      {isInterativo ? 'Com Botões Interativos' : 'Convite Simples'}
                    </span>
                  </div>

                  {/* Botão de Espiar/Prévia rápida */}
                  <button
                    onClick={() => setPreviewTemplate(template)}
                    className="absolute bottom-3 right-3 p-2 rounded-full bg-white/90 hover:bg-white text-[#4B2E20] shadow-md transition-transform hover:scale-110"
                    title="Ver detalhes da foto"
                  >
                    <Eye className="w-4 h-4" />
                  </button>
                </div>

                {/* Conteúdo do Card */}
                <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                  <div className="space-y-1.5">
                    <div className="flex items-start justify-between gap-2">
                      <h3 className="font-serif font-bold text-base text-[#4B2E20] group-hover:text-[#83522a] transition-colors leading-snug">
                        {template.title}
                      </h3>
                      <span className="text-sm font-serif font-extrabold text-[#4B2E20] shrink-0">
                        R$ {template.price.toFixed(2)}
                      </span>
                    </div>

                    <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed font-light">
                      {template.description}
                    </p>
                  </div>

                  {/* Características delicadas */}
                  <div className="pt-2 border-t border-[#D4AF37]/15 space-y-3">
                    <div className="flex items-center gap-1.5 text-[11px] text-[#4B2E20]/70">
                      <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Ideal para enviar pelo WhatsApp</span>
                    </div>

                    {/* Botão Principal Quero este Modelo */}
                    <Button
                      onClick={() => handleOrder(template)}
                      className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs py-2.5 rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center justify-center gap-2 hover:scale-[1.01] transition-transform"
                    >
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Quero este Modelo</span>
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Zoom/Prévia da Foto do Modelo */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <div className="relative max-w-lg w-full bg-white rounded-3xl overflow-hidden shadow-2xl border border-[#D4AF37]/40">
            <button
              onClick={() => setPreviewTemplate(null)}
              className="absolute top-3 right-3 z-10 p-2 rounded-full bg-white/90 text-[#4B2E20] shadow hover:bg-white"
            >
              ✕
            </button>
            <div className="aspect-[4/5] bg-[#F7EBDD]/40">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-full object-contain bg-neutral-900"
              />
            </div>
            <div className="p-4 sm:p-5 bg-[#fcf8f3] text-center space-y-2">
              <h4 className="font-serif font-bold text-[#4B2E20] text-base">
                {previewTemplate.title}
              </h4>
              <p className="text-xs text-[#4B2E20]/70">{previewTemplate.description}</p>
              <div className="pt-2">
                <Button
                  onClick={() => {
                    const tpl = previewTemplate;
                    setPreviewTemplate(null);
                    handleOrder(tpl);
                  }}
                  className="bg-[#4B2E20] text-[#F7EBDD] text-xs font-semibold rounded-xl px-6"
                >
                  Quero este Modelo (R$ {previewTemplate.price.toFixed(2)})
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Preenchimento de Pedido */}
      {orderingTemplate && (
        <ClientOrderModal
          isOpen={Boolean(orderingTemplate)}
          template={orderingTemplate}
          onClose={() => setOrderingTemplate(null)}
          onSubmitOrder={(newOrder) => {
            if (onSubmitClientOrder) {
              onSubmitClientOrder(newOrder);
            }
            setOrderingTemplate(null);
          }}
        />
      )}
    </div>
  );
}

