import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ClientOrderModal } from '@/components/ClientOrderModal';
import {
  Sparkles,
  Smartphone,
  MousePointerClick,
  Video,
  CalendarCheck,
  Send,
  Heart,
  Share2,
  CheckCircle2,
  Zap,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  isAdmin: boolean;
  onOpenNewTemplate?: () => void;
  onSelectTemplateToOrder?: (template: InvitationTemplate) => void;
}

export function TemplatesCatalog({
  templates,
  isAdmin,
  onOpenNewTemplate,
  onSelectTemplateToOrder,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('todos');
  const [selectedFormat, setSelectedFormat] = useState<string>('todos');
  const [selectedTemplateForModal, setSelectedTemplateForModal] = useState<InvitationTemplate | null>(null);

  const categories: { label: string; value: string }[] = [
    { label: 'Todos os Temas', value: 'todos' },
    { label: 'Infantil', value: 'Infantil' },
    { label: '15 Anos', value: '15 Anos' },
    { label: 'Casamento', value: 'Casamento' },
    { label: 'Batizado', value: 'Batizado' },
    { label: 'Bodas', value: 'Bodas' },
    { label: 'Corporativo', value: 'Corporativo' },
  ];

  const formats: { label: string; value: string; icon: any }[] = [
    { label: 'Todos os Formatos Digitais', value: 'todos', icon: Smartphone },
    { label: 'Card Digital (WhatsApp)', value: 'imagem_card', icon: Smartphone },
    { label: 'Interativo (com Botões)', value: 'interativo_pdf', icon: MousePointerClick },
    { label: 'Vídeo Animado', value: 'animado_video', icon: Video },
    { label: 'Save The Date Digital', value: 'save_the_date', icon: CalendarCheck },
  ];

  const filteredTemplates = (templates || []).filter((tpl) => {
    const matchCategory = selectedCategory === 'todos' || tpl.category === selectedCategory;
    const matchFormat = selectedFormat === 'todos' || tpl.format === selectedFormat;
    return matchCategory && matchFormat;
  });

  const handleChooseTemplate = (template: InvitationTemplate) => {
    if (onSelectTemplateToOrder) {
      onSelectTemplateToOrder(template);
    } else {
      setSelectedTemplateForModal(template);
    }
  };

  const getFormatBadge = (tpl: InvitationTemplate) => {
    if (tpl.hasInteraction || tpl.format === 'interativo_pdf') {
      return {
        label: 'Digital Interativo • Com Botões',
        className: 'bg-[#4B2E20] text-[#D4AF37] border border-[#D4AF37]/50',
      };
    }
    if (tpl.format === 'animado_video') {
      return {
        label: 'Vídeo Digital com Música',
        className: 'bg-[#693f2c] text-[#F7EBDD] border border-[#D4AF37]/40',
      };
    }
    if (tpl.format === 'save_the_date') {
      return {
        label: 'Save The Date Digital',
        className: 'bg-[#e5cfb8] text-[#4B2E20] border border-[#D4AF37]/40',
      };
    }
    return {
      label: 'Card Digital WhatsApp • Sem Botões',
      className: 'bg-white/90 text-[#4B2E20] border border-[#D4AF37]/40',
    };
  };

  return (
    <div className="space-y-10 animate-fade-in pb-12">
      {/* Banner Principal com destaque para Convites Digitais */}
      <section className="relative overflow-hidden rounded-[2.5rem] bg-gradient-to-b from-[#F7EBDD] via-[#fdf9f5] to-[#f4e6d6] border border-[#D4AF37]/30 p-6 sm:p-10 shadow-sm text-center">
        <div className="max-w-2xl mx-auto space-y-4">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/80 border border-[#D4AF37]/30 text-[#4B2E20] shadow-xs text-xs font-medium">
            <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span className="font-serif italic">100% Digitais • Prontos para Enviar pelo WhatsApp</span>
          </div>

          <h1 className="text-3xl sm:text-4xl lg:text-5xl font-serif font-bold text-[#4B2E20] leading-tight tracking-tight">
            Convites Digitais Personalizados
          </h1>

          <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-normal">
            Escolha seu modelo favorito, nós personalizamos com todos os dados da sua festa e você recebe o arquivo digital prontinho no WhatsApp para enviar aos seus convidados quantas vezes quiser!
          </p>

          {/* Vantagens dos Convites Digitais */}
          <div className="pt-2 grid grid-cols-2 sm:grid-cols-4 gap-2.5 max-w-xl mx-auto text-left">
            <div className="bg-white/75 backdrop-blur-xs p-2.5 rounded-2xl border border-[#D4AF37]/25 flex items-center gap-2 shadow-xs">
              <Zap className="w-4 h-4 text-[#D4AF37] shrink-0" />
              <div>
                <p className="text-[11px] font-bold text-[#4B2E20] leading-tight">Entrega Rápida</p>
                <p className="text-[9px] text-[#4B2E20]/70">Direto no WhatsApp</p>
              </div>
            </div>

            <div className="bg-white/75 backdrop-blur-xs p-2.5 rounded-2xl border border-[#D4AF37]/25 flex items-center gap-2 shadow-xs">
              <Share2 className="w-4 h-4 text-[#D4AF37] shrink-0" />
              <div>
                <p className="text-[11px] font-bold text-[#4B2E20] leading-tight">Envio Ilimitado</p>
                <p className="text-[9px] text-[#4B2E20]/70">Para toda a lista</p>
              </div>
            </div>

            <div className="bg-white/75 backdrop-blur-xs p-2.5 rounded-2xl border border-[#D4AF37]/25 flex items-center gap-2 shadow-xs">
              <MousePointerClick className="w-4 h-4 text-[#D4AF37]" />
              <div>
                <p className="text-[11px] font-bold text-[#4B2E20] leading-tight">Com ou Sem Botão</p>
                <p className="text-[9px] text-[#4B2E20]/70">Opção que desejar</p>
              </div>
            </div>

            <div className="bg-white/75 backdrop-blur-xs p-2.5 rounded-2xl border border-[#D4AF37]/25 flex items-center gap-2 shadow-xs">
              <Heart className="w-4 h-4 text-[#D4AF37] shrink-0" />
              <div>
                <p className="text-[11px] font-bold text-[#4B2E20] leading-tight">Sem Frete</p>
                <p className="text-[9px] text-[#4B2E20]/70">Arquivo digital HD</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Filtros Delicados */}
      <div className="space-y-3">
        {/* Filtro por Formato do Convite Digital */}
        <div className="flex flex-wrap items-center gap-2 justify-center">
          {formats.map((fmt) => {
            const Icon = fmt.icon;
            const isSelected = selectedFormat === fmt.value;
            return (
              <button
                key={fmt.value}
                onClick={() => setSelectedFormat(fmt.value)}
                className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-medium transition-all ${
                  isSelected
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                    : 'bg-white/80 hover:bg-[#F7EBDD]/60 text-[#4B2E20] border border-[#D4AF37]/25'
                }`}
              >
                <Icon className={`w-3.5 h-3.5 ${isSelected ? 'text-[#D4AF37]' : 'text-[#4B2E20]/60'}`} />
                <span>{fmt.label}</span>
              </button>
            );
          })}
        </div>

        {/* Filtro por Ocasião / Tema */}
        <div className="flex flex-wrap items-center gap-1.5 justify-center">
          {categories.map((cat) => {
            const isSelected = selectedCategory === cat.value;
            return (
              <button
                key={cat.value}
                onClick={() => setSelectedCategory(cat.value)}
                className={`px-3 py-1 rounded-full text-[11px] font-semibold transition-all ${
                  isSelected
                    ? 'bg-[#D4AF37] text-[#4B2E20] shadow-xs'
                    : 'bg-[#F7EBDD]/50 hover:bg-[#F7EBDD] text-[#4B2E20]/80 border border-[#D4AF37]/20'
                }`}
              >
                {cat.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Grid de Modelos Digitais */}
      {filteredTemplates.length === 0 ? (
        <div className="text-center py-16 px-4 bg-white/60 rounded-3xl border border-[#D4AF37]/20 max-w-md mx-auto">
          <Smartphone className="w-10 h-10 mx-auto text-[#D4AF37] mb-3 opacity-80" />
          <h3 className="font-serif font-bold text-base text-[#4B2E20]">Nenhum modelo encontrado</h3>
          <p className="text-xs text-[#4B2E20]/70 mt-1">
            Experimente mudar os filtros acima para ver outros modelos de convites digitais.
          </p>
          <Button
            size="sm"
            onClick={() => {
              setSelectedCategory('todos');
              setSelectedFormat('todos');
            }}
            className="mt-4 bg-[#4B2E20] text-[#F7EBDD] text-xs rounded-xl"
          >
            Ver todos os modelos
          </Button>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredTemplates.map((template) => {
            const badge = getFormatBadge(template);
            return (
              <Card
                key={template.id}
                className="group bg-white/95 border-[#D4AF37]/25 hover:border-[#D4AF37]/60 rounded-3xl overflow-hidden shadow-xs hover:shadow-md transition-all duration-300 flex flex-col"
              >
                {/* Imagem do Convite Digital com proporção de tela de celular */}
                <div className="relative aspect-[4/5] overflow-hidden bg-[#F7EBDD]/40">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-full h-full object-cover group-hover:scale-103 transition-transform duration-500"
                    loading="lazy"
                  />

                  {/* Badge de Tipo de Convite Digital */}
                  <div className="absolute top-3 left-3 right-3 flex items-start justify-between gap-1 pointer-events-none">
                    <span
                      className={`text-[10px] font-semibold px-2.5 py-1 rounded-full backdrop-blur-md shadow-xs ${badge.className}`}
                    >
                      {badge.label}
                    </span>
                  </div>

                  {/* Categoria no rodapé da imagem */}
                  <div className="absolute bottom-3 left-3 pointer-events-none">
                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-lg bg-[#4B2E20]/80 text-[#F7EBDD] backdrop-blur-xs">
                      {template.category}
                    </span>
                  </div>
                </div>

                {/* Conteúdo do Card */}
                <CardContent className="p-4 flex-1 flex flex-col justify-between space-y-3">
                  <div>
                    <h3 className="font-serif font-bold text-sm text-[#4B2E20] group-hover:text-[#693f2c] transition-colors line-clamp-1">
                      {template.title}
                    </h3>
                    <p className="text-[11px] text-[#4B2E20]/75 line-clamp-2 mt-1 leading-relaxed">
                      {template.description}
                    </p>
                  </div>

                  {/* Informações de entrega e valor */}
                  <div className="pt-2 border-t border-[#D4AF37]/15">
                    <div className="flex items-center justify-between mb-3">
                      <div>
                        <span className="text-[10px] text-[#4B2E20]/65 block font-medium">Arquivo Digital</span>
                        <span className="text-base font-serif font-bold text-[#4B2E20]">
                          R$ {template.price.toFixed(2)}
                        </span>
                      </div>
                      <span className="text-[10px] font-semibold text-emerald-800 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-200/60 flex items-center gap-1">
                        <CheckCircle2 className="w-3 h-3 text-emerald-700" />
                        Envio WhatsApp
                      </span>
                    </div>

                    {/* Botão de Pedido */}
                    <Button
                      onClick={() => handleChooseTemplate(template)}
                      className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs py-2 rounded-xl border border-[#D4AF37]/35 shadow-xs flex items-center justify-center gap-1.5 transition-all group-hover:scale-[1.01]"
                    >
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Quero este Modelo Digital</span>
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal para preenchimento dos dados do convite digital */}
      {selectedTemplateForModal && (
        <ClientOrderModal
          isOpen={Boolean(selectedTemplateForModal)}
          template={selectedTemplateForModal}
          onClose={() => setSelectedTemplateForModal(null)}
          onSubmitOrder={() => setSelectedTemplateForModal(null)}
        />
      )}
    </div>
  );
}

