                    <label className="block text-[#4B2E20] font-semibold mb-1">
                      Link ou Endereço da Localização (Maps)
                    </label>
                    <Input
                      placeholder="Link do Google Maps ou endereço exato"
                      value={linkLocalizacao}
                      onChange={(e) => setLinkLocalizacao(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>

