                    <Input
                      placeholder="Ex: Roupa tamanho 2, sapato 21, brinquedos educativos ou link"
                      value={listaPresentes}
                      onChange={(e) => setListaPresentes(e.target.value)}
                      className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Bloco 7: Anexar Foto (se a pessoa quiser) */}
            <div className="p-3 rounded-2xl bg-white border border-[#D4AF37]/30">
              <div className="flex items-center justify-between mb-2">
                <span className="font-semibold text-[#4B2E20] flex items-center gap-1.5">
                  <ImageIcon className="w-4 h-4 text-[#D4AF37]" />
                  Adicionar Foto (Opcional)
                </span>
                <span className="text-[10px] text-[#4B2E20]/60">se quiser colocar foto no convite</span>
              </div>

              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleFotoChange}
                className="hidden"
                id="foto-upload"
              />

              {!fotoPreview ? (
                <label
                  htmlFor="foto-upload"
                  className="flex items-center justify-center gap-2 p-3 border border-dashed border-[#D4AF37]/60 rounded-xl cursor-pointer hover:bg-[#F7EBDD]/40 transition-colors text-center"
                >
                  <Upload className="w-4 h-4 text-[#4B2E20]/70" />
                  <span className="text-[11px] font-medium text-[#4B2E20]">
                    Clique aqui para anexar a foto do aniversariante
                  </span>
                </label>
              ) : (
                <div className="flex items-center justify-between p-2 rounded-xl bg-[#F7EBDD]/50 border border-[#D4AF37]/30">
                  <div className="flex items-center gap-2.5">
                    <img
                      src={fotoPreview}
                      alt="Prévia"
                      className="w-10 h-10 object-cover rounded-lg border border-[#D4AF37]/40"
                    />
                    <div>
                      <p className="font-semibold text-[#4B2E20] text-[11px] truncate max-w-[180px]">
                        {fotoFile?.name}
                      </p>
                      <span className="text-[10px] text-emerald-700 font-medium">Foto selecionada</span>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={handleRemoverFoto}
                    className="p-1 rounded-lg text-red-700 hover:bg-red-50 text-xs font-semibold"
                  >
                    Remover
                  </button>
                </div>
              )}
            </div>

            {/* Botão de Envio */}
            <div className="pt-2 flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] text-xs rounded-xl"
              >
                Voltar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center gap-2 px-5 py-2.5"
              >
                <Send className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Enviar Pedido pelo WhatsApp</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

