      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Modelo Simples (sem botões)',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto',
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: template.price,
      paidValue: 0,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Mensagem pronta para o WhatsApp
    let msg = `Olá Keh Convites! Gostaria de encomendar este convite digital:\n\n`;
    msg += `💌 *Modelo Digital:* ${template.title}\n`;
    msg += `🏷️ *Formato:* ${temInteracao ? 'Convite Digital Interativo (com botões)' : 'Convite Digital Simples (sem botões)'}\n`;
    msg += `💰 *Valor:* R$ ${template.price.toFixed(2)}\n\n`;
    msg += `📝 *DADOS PARA PERSONALIZAÇÃO:*\n`;
    msg += `👤 *Nome do aniversariante:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎨 *Tema:* ${temaFesta}\n`;
    if (dataEvento.trim()) msg += `📅 *Data do evento:* ${dataEvento}\n`;
    if (diaSemana.trim()) msg += `🗓️ *Dia da semana:* ${diaSemana}\n`;
    if (horarioEvento.trim()) msg += `⏰ *Horário:* ${horarioEvento}\n`;
    if (localEvento.trim()) msg += `📍 *Local:* ${localEvento}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase especial:* "${fraseEspecial}"\n`;
    msg += `📱 *Meu WhatsApp para envio da prévia:* ${whatsappCliente}\n`;

    if (temInteracao) {
      msg += `\n✨ *INFORMAÇÕES DOS BOTÕES INTERATIVOS:*\n`;
      if (confirmacaoPresenca.trim()) msg += `📲 *Confirmação de presença:* ${confirmacaoPresenca}\n`;
      if (linkLocalizacao.trim()) msg += `🗺️ *Localização (link ou endereço):* ${linkLocalizacao}\n`;
      if (listaPresentes.trim()) msg += `🎁 *Lista de presentes / sugestões:* ${listaPresentes}\n`;
    }

    if (fotoFile) {
      msg += `\n📸 *Foto:* Vou anexar a foto aqui na conversa!`;
    }

    const encodedMsg = encodeURIComponent(msg);
    window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfaf6] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-5 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shadow-xs">
              <Smartphone className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Personalizar Convite Digital
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                Modelo: <span className="font-bold text-[#4B2E20]">{template.title}</span> • R$ {template.price.toFixed(2)}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Informações e Formulário */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-4 text-xs text-[#4B2E20]">

          {/* Identificação clara do formato digital */}
          <div className="p-3 rounded-xl bg-[#F7EBDD] border border-[#D4AF37]/35 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
            <div>
              <span className="font-bold text-[#4B2E20] block">Formato Digital:</span>
              <p className="text-[11px] text-[#4B2E20]/70">
                Você receberá o arquivo pronto em alta resolução para enviar no WhatsApp
              </p>
            </div>
            <span className={`px-2.5 py-1 rounded-lg text-[11px] font-bold self-start sm:self-auto ${
              temInteracao
                ? 'bg-[#4B2E20] text-[#D4AF37]'
                : 'bg-white border border-[#D4AF37]/40 text-[#4B2E20]'
            }`}>
              {temInteracao ? 'Convite Interativo (com botões)' : 'Convite Simples (sem botões)'}
            </span>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Nome do Aniversariante e Tema */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20]">
                  Nome do Aniversariante / Homenageado *
                </label>
                <Input
                  required
                  placeholder="Ex: Alice (faz 5 anos) ou Maria Clara"
                  value={nomeAniversariante}
                  onChange={(e) => setNomeAniversariante(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                />
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20]">
                  Tema da Festa / Evento
                </label>
                <Input
                  placeholder="Ex: Jardim Encantado, Princesas, Safari..."
                  value={temaFesta}
                  onChange={(e) => setTemaFesta(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                />
              </div>
            </div>

            {/* Data, Dia da Semana e Horário */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Data do Evento</span>
                </label>
                <Input
                  type="date"
                  value={dataEvento}
                  onChange={(e) => setDataEvento(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                />
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20]">
                  Dia da Semana
                </label>
                <Input
                  placeholder="Ex: Sábado ou Domingo"
                  value={diaSemana}
                  onChange={(e) => setDiaSemana(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                />
              </div>

              <div>
                <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                  <Clock className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Horário</span>
                </label>
                <Input
                  placeholder="Ex: Às 18:00h"
                  value={horarioEvento}
                  onChange={(e) => setHorarioEvento(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                />
              </div>
            </div>

            {/* Local do Evento */}
            <div>
              <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Local do Evento</span>
              </label>
              <Input
                placeholder="Ex: Buffet Estrela Dourada - Rua das Flores, 123"
                value={localEvento}
                onChange={(e) => setLocalEvento(e.target.value)}
                className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
              />
            </div>

            {/* Frase Especial Opcional */}
            <div>
              <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Frase Especial (se desejar)</span>
              </label>
              <Input
                placeholder='Ex: "Venha comemorar comigo esse dia tão mágico!"'
                value={fraseEspecial}
                onChange={(e) => setFraseEspecial(e.target.value)}
                className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
              />
            </div>

            {/* WhatsApp para Contato e Envio do Convite Digital */}
            <div>
              <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Seu WhatsApp para Receber a Prévia do Convite *</span>
              </label>
              <Input
                required
                placeholder="(DDD) 99999-9999"
                value={whatsappCliente}
                onChange={(e) => setWhatsappCliente(e.target.value)}
                className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
              />
            </div>

            {/* Seção Exclusiva para Modelos com Interação / Botões */}
            {temInteracao && (
              <div className="p-4 rounded-2xl bg-[#ecdccb]/40 border border-[#D4AF37]/30 space-y-3">
                <div className="flex items-center gap-1.5">
                  <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                  <h4 className="font-serif font-bold text-xs text-[#4B2E20]">
                    Informações dos Botões Clicáveis
                  </h4>
                </div>
                <p className="text-[11px] text-[#4B2E20]/70">
                  Como este é um convite digital interativo, seus convidados poderão clicar diretamente na tela:
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Número para Confirmação de Presença
                    </label>
                    <Input
                      placeholder="Ex: WhatsApp (DDD) 99999-9999"
                      value={confirmacaoPresenca}
                      onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Localização no Maps (Link ou Endereço)
                    </label>
                    <Input
                      placeholder="Ex: Link do Google Maps ou CEP"
                      value={linkLocalizacao}
                      onChange={(e) => setLinkLocalizacao(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                    />
                  </div>
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20] flex items-center gap-1">
                    <Gift className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Lista de Presentes / Sugestões (roupa, calçado, brinquedo)</span>
                  </label>
                  <Input
                    placeholder="Ex: Roupa tam 4, Calçado 26, brinquedos educativos ou link de lista"
                    value={listaPresentes}
                    onChange={(e) => setListaPresentes(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl text-xs h-10"
                  />
                </div>
              </div>
            )}

            {/* Campo Opcional de Anexo de Foto */}
            <div className="p-3.5 rounded-2xl bg-white/70 border border-[#D4AF37]/30 space-y-2">
              <label className="block font-semibold text-[#4B2E20] flex items-center gap-1.5">
                <ImageIcon className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Deseja adicionar foto da criança / aniversariante no convite? (Opcional)</span>
              </label>

              <div className="flex items-center gap-3">
                <input
                  type="file"
                  accept="image/*"
                  ref={fileInputRef}
                  onChange={handleFotoChange}
                  className="hidden"
                  id="foto-convite-input"
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => fileInputRef.current?.click()}
                  className="border-[#D4AF37]/40 bg-white text-[#4B2E20] text-xs rounded-xl flex items-center gap-1.5"
                >
                  <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>{fotoFile ? 'Trocar Foto' : 'Anexar Foto'}</span>
                </Button>

                {fotoFile && (
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] text-[#4B2E20] font-medium truncate max-w-[150px]">
                      {fotoFile.name}
                    </span>
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="text-red-600 hover:text-red-800 text-[11px] font-bold"
                    >
                      Remover
                    </button>
                  </div>
                )}
              </div>

              {fotoPreview && (
                <div className="mt-2 w-16 h-16 rounded-xl overflow-hidden border border-[#D4AF37]/40 shadow-xs">
                  <img src={fotoPreview} alt="Prévia" className="w-full h-full object-cover" />
                </div>
              )}
            </div>

            {/* Botão de Envio */}
            <div className="pt-2 flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] text-xs rounded-xl"
              >
                Voltar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs py-2 px-5 rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center gap-1.5"
              >
                <Send className="w-3.5 h-3.5 text-[#D4AF37]" />
                <span>Enviar Dados no WhatsApp</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

