import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  MessageCircle,
  Phone,
  Camera,
  CheckCircle2,
  Send,
  Smartphone,
  Eye,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

// Exemplos realistas de Ensaios Digitais para inspiração do cliente
const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Fundo Safári & Floresta Encantada',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
    tag: 'Mais Pedido',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala & Cenário Real',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
    tag: 'Luxo Delicado',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Cenário Pôr do Sol & Flores',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
    tag: 'Romântico',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio Smash the Cake Digital',
    subtitulo: 'Com bolo temático e balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
    tag: '1º Aninho',
  },
];

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  // Campos do formulário
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos exclusivos de modelos com botões
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Trabalho adicional: Ensaio Digital
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);
  const [previewFotoEnsaio, setPreviewFotoEnsaio] = useState<string | null>(null);

  // Foto enviada pelo cliente (se preferir foto própria)
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
      // Se enviou foto própria, pode desmarcar ensaio ou manter como referência
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante / homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o número de WhatsApp para receber a prévia do seu convite.');
      return;
    }

    const notasFormatadas = [
      'Convite 100% Digital',
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Modelo Simples (sem botões)',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto do Cliente Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      rsvpLink: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: 0,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      wantsDigitalPhotoshoot: querEnsaioDigital,
      digitalPhotoshootTheme: querEnsaioDigital ? ensaioEscolhido : undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Mensagem pronta e organizada para o WhatsApp da Keh
    let msg = `Olá Keh Convites! Gostaria de encomendar este convite digital:\n\n`;
    msg += `💌 *Modelo Digital:* ${template.title}\n`;
    msg += `🏷️ *Formato:* ${temInteracao ? 'Convite Digital Interativo (com botões)' : 'Convite Digital Simples (sem botões)'}\n`;
    msg += `💰 *Valor do Convite:* R$ ${template.price.toFixed(2)}\n`;

    if (querEnsaioDigital) {
      msg += `✨ *Adicional Ensaio Digital:* SIM (+ R$ 25,00)\n`;
      msg += `🎨 *Estilo do Ensaio:* ${ensaioEscolhido}\n`;
      msg += `💵 *Valor Total com Ensaio:* R$ ${valorTotalFinal.toFixed(2)}\n`;
    }

    msg += `\n📝 *DADOS PARA PERSONALIZAÇÃO:*\n`;
    msg += `👤 *Nome do aniversariante:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎨 *Tema:* ${temaFesta}\n`;
    if (dataEvento.trim()) msg += `📅 *Data do evento:* ${dataEvento}\n`;
    if (diaSemana.trim()) msg += `🗓️ *Dia da semana:* ${diaSemana}\n`;
    if (horarioEvento.trim()) msg += `⏰ *Horário:* ${horarioEvento}\n`;
    if (localEvento.trim()) msg += `📍 *Local:* ${localEvento}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase especial:* "${fraseEspecial}"\n`;
    msg += `📱 *Meu WhatsApp para envio da prévia:* ${whatsappCliente}\n`;

    if (temInteracao) {
      msg += `\n✨ *INFORMAÇÕES DOS BOTÕES INTERATIVOS:*\n`;
      if (confirmacaoPresenca.trim()) msg += `📲 *Confirmação de presença:* ${confirmacaoPresenca}\n`;
      if (linkLocalizacao.trim()) msg += `🗺️ *Localização (link ou endereço):* ${linkLocalizacao}\n`;
      if (listaPresentes.trim()) msg += `🎁 *Lista de presentes / sugestões:* ${listaPresentes}\n`;
    }

    if (querEnsaioDigital) {
      msg += `\n📸 *Ensaio Digital:* Quero que você crie o ensaio temático digital para colocar no meu convite! Vou te enviar uma foto simples do rosto para você transformar.`;
    } else if (fotoFile) {
      msg += `\n📸 *Foto:* Vou anexar minha própria foto pronta aqui na conversa!`;
    }

    const encodedMsg = encodeURIComponent(msg);
    window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfaf6] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between p-4 sm:p-5 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center shadow-xs">
              <Smartphone className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Personalizar Convite Digital
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                Modelo: <span className="font-bold text-[#4B2E20]">{template.title}</span> • R$ {template.price.toFixed(2)}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Formulário com Scroll */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-5 text-xs text-[#4B2E20]">

          {/* Identificação clara do formato digital */}
          <div className="p-3.5 rounded-2xl bg-[#F7EBDD] border border-[#D4AF37]/35 flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
            <div>
              <span className="font-bold text-[#4B2E20] text-xs block">Formato Digital:</span>
              <p className="text-[11px] text-[#4B2E20]/70">
                Você receberá o arquivo pronto em alta resolução para enviar aos convidados no WhatsApp.
              </p>
            </div>
            <span
              className={`px-3 py-1 rounded-xl text-[11px] font-bold self-start sm:self-auto ${
                temInteracao
                  ? 'bg-[#4B2E20] text-[#D4AF37] border border-[#D4AF37]/40'
                  : 'bg-stone-200 text-stone-700'
              }`}
            >
              {temInteracao ? 'Convite Interativo (com botões)' : 'Convite Simples (sem botões)'}
            </span>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">

            {/* Bloco 1: Dados do Aniversariante e Tema */}
            <div className="space-y-3">
              <h4 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider flex items-center gap-1.5 border-b border-[#D4AF37]/25 pb-1">
                <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                1. Informações Principais
              </h4>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1">
                    Nome do Aniversariante / Homenageado *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Cecília faz 1 aninho"
                    value={nomeAniversariante}
                    onChange={(e) => setNomeAniversariante(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>

                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1">
                    Tema da Festa / Evento
                  </label>
                  <Input
                    placeholder="Ex: Safári Baby, Princesa, Jardim Encantado"
                    value={temaFesta}
                    onChange={(e) => setTemaFesta(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1">
                    Data do Evento
                  </label>
                  <div className="relative">
                    <Calendar className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                    <Input
                      type="date"
                      value={dataEvento}
                      onChange={(e) => setDataEvento(e.target.value)}
                      className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>

                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1">
                    Dia da Semana
                  </label>
                  <Input
                    placeholder="Ex: Sábado, Domingo"
                    value={diaSemana}
                    onChange={(e) => setDiaSemana(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>

                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1">
                    Horário do Evento
                  </label>
                  <div className="relative">
                    <Clock className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                    <Input
                      placeholder="Ex: Às 16h30"
                      value={horarioEvento}
                      onChange={(e) => setHorarioEvento(e.target.value)}
                      className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block font-semibold text-[#4B2E20] mb-1">
                  Local / Endereço Completo
                </label>
                <div className="relative">
                  <MapPin className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                  <Input
                    placeholder="Ex: Buffet Sonho Dourado - Rua das Palmeiras, 120"
                    value={localEvento}
                    onChange={(e) => setLocalEvento(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>

              <div>
                <label className="block font-semibold text-[#4B2E20] mb-1">
                  Frase Especial / Texto do Convite (Opcional)
                </label>
                <Input
                  placeholder='Ex: "Venha comemorar meu primeiro aninho repleto de magia!"'
                  value={fraseEspecial}
                  onChange={(e) => setFraseEspecial(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="block font-semibold text-[#4B2E20] mb-1">
                  Seu WhatsApp (para receber a prévia) *
                </label>
                <div className="relative">
                  <Phone className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                  <Input
                    required
                    placeholder="(00) 90000-0000"
                    value={whatsappCliente}
                    onChange={(e) => setWhatsappCliente(e.target.value)}
                    className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                  />
                </div>
              </div>
            </div>

            {/* Bloco 2: Se o modelo for Interativo com botões */}
            {temInteracao && (
              <div className="space-y-3 pt-2">
                <h4 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider flex items-center gap-1.5 border-b border-[#D4AF37]/25 pb-1">
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  2. Dados para os Botões Interativos Clicáveis
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1">
                      WhatsApp para Confirmação de Presença
                    </label>
                    <Input
                      placeholder="Ex: (11) 98888-7777 da mamãe"
                      value={confirmacaoPresenca}
                      onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1">
                      Link da Localização (Google Maps ou Waze)
                    </label>
                    <Input
                      placeholder="Cole o link ou deixe em branco para usarmos o endereço"
                      value={linkLocalizacao}
                      onChange={(e) => setLinkLocalizacao(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                    />
                  </div>
                </div>

                <div>
                  <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                    <Gift className="w-3 h-3 text-[#D4AF37]" />
                    <span>Lista de Presentes / Tamanhos (Roupa, Calçado ou Brinquedos)</span>
                  </label>
                  <textarea
                    rows={2}
                    placeholder="Ex: Roupas tamanho 2, Calçado nº 20, ou link da lista virtual em loja..."
                    value={listaPresentes}
                    onChange={(e) => setListaPresentes(e.target.value)}
                    className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                  />
                </div>
              </div>
            )}

            {/* Bloco 3: NOVO - Oferta Especial de Ensaio Digital & Exemplos */}
            <div className="pt-2 space-y-3">
              <div className="flex items-center justify-between border-b border-[#D4AF37]/25 pb-1">
                <h4 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider flex items-center gap-1.5">
                  <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
                  {temInteracao ? '3' : '2'}. Foto do Convite ou Ensaio Digital Artístico
                </h4>
                <span className="text-[10px] font-bold text-[#D4AF37] bg-[#4B2E20] px-2 py-0.5 rounded-full">
                  Exclusivo Keh Convites
                </span>
              </div>

              {/* Box de Apresentação do Ensaio Digital */}
              <div className="p-4 rounded-2xl bg-gradient-to-br from-[#F7EBDD] via-white to-[#F7EBDD] border border-[#D4AF37]/45 shadow-sm space-y-3">
                <div className="flex items-start justify-between gap-3">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-serif font-bold text-[#4B2E20]">
                        Não tem fotos profissionais do seu pequeno ou do casal?
                      </span>
                    </div>
                    <p className="text-[11px] text-[#4B2E20]/80 leading-relaxed">
                      Transformamos uma foto simples do seu celular em um lindo <strong>Ensaio Fotográfico Digital Temático</strong> com figurino e cenário profissional para brilhar no seu convite!
                    </p>
                  </div>
                </div>

                {/* Vitrine de Exemplos de Ensaios Digitais */}
                <div>
                  <span className="text-[10px] uppercase font-bold text-[#4B2E20]/75 block mb-2">
                    Veja alguns exemplos reais de Ensaios Digitais criados por nós:
                  </span>

                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
                    {EXEMPLOS_ENSAIOS_DIGITAIS.map((ex) => {
                      const isSelected = querEnsaioDigital && ensaioEscolhido === ex.titulo;
                      return (
                        <div
                          key={ex.id}
                          onClick={() => {
                            setQuerEnsaioDigital(true);
                            setEnsaioEscolhido(ex.titulo);
                          }}
                          className={`relative rounded-xl overflow-hidden border cursor-pointer transition-all duration-200 group text-left ${
                            isSelected
                              ? 'border-[#4B2E20] ring-2 ring-[#D4AF37] scale-[1.02] shadow-md'
                              : 'border-[#D4AF37]/35 hover:border-[#D4AF37] hover:shadow-xs'
                          }`}
                        >
                          <div className="h-24 w-full overflow-hidden bg-stone-100 relative">
                            <img
                              src={ex.foto}
                              alt={ex.titulo}
                              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                            />
                            <span className="absolute top-1 left-1 text-[9px] bg-[#4B2E20]/85 backdrop-blur-xs text-[#F7EBDD] px-1.5 py-0.5 rounded-md font-semibold">
                              {ex.tag}
                            </span>
                            {isSelected && (
                              <div className="absolute inset-0 bg-[#4B2E20]/30 flex items-center justify-center">
                                <CheckCircle2 className="w-6 h-6 text-[#D4AF37] drop-shadow-md" />
                              </div>
                            )}
                          </div>
                          <div className="p-2 bg-white/90">
                            <p className="font-bold text-[11px] text-[#4B2E20] leading-tight truncate">
                              {ex.titulo}
                            </p>
                            <span className="text-[9px] text-[#4B2E20]/70 block truncate">
                              {ex.subtitulo}
                            </span>
                            <span className="text-[10px] font-bold text-[#D4AF37] block mt-1">
                              + R$ {ex.preco.toFixed(2)}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Opção de Seleção do Ensaio Digital */}
                <div className="pt-2 border-t border-[#D4AF37]/25 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                  <label className="flex items-center gap-2 cursor-pointer select-none">
                    <input
                      type="checkbox"
                      checked={querEnsaioDigital}
                      onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                      className="w-4 h-4 text-[#D4AF37] accent-[#4B2E20] rounded"
                    />
                    <div>
                      <span className="font-bold text-xs text-[#4B2E20]">
                        Sim, quero incluir Ensaio Digital Personalizado (+ R$ 25,00)
                      </span>
                      <p className="text-[10px] text-[#4B2E20]/70">
                        {querEnsaioDigital
                          ? `Estilo Selecionado: "${ensaioEscolhido}". Envie qualquer fotinho do rosto pelo WhatsApp!`
                          : 'Clique para adicionar um ensaio fotográfico temático ao convite'}
                      </p>
                    </div>
                  </label>

                  {querEnsaioDigital && (
                    <span className="text-xs font-bold px-2.5 py-1 rounded-lg bg-[#4B2E20] text-[#D4AF37] self-start sm:self-auto shrink-0 shadow-xs">
                      + R$ 25,00 no convite
                    </span>
                  )}
                </div>
              </div>

              {/* Anexo de Foto Própria (se o cliente já tiver a foto dele) */}
              <div className="p-3 rounded-xl bg-white border border-[#D4AF37]/30 space-y-2">
                <span className="text-[11px] font-semibold text-[#4B2E20] block">
                  Já tem a foto que deseja usar no convite? Anexe abaixo (ou envie depois no WhatsApp):
                </span>

                <div className="flex items-center gap-3">
                  <input
                    type="file"
                    accept="image/*"
                    ref={fileInputRef}
                    onChange={handleFotoChange}
                    className="hidden"
                    id="fotoUploadInput"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => fileInputRef.current?.click()}
                    className="border-[#D4AF37]/50 text-[#4B2E20] bg-[#faf5ee] hover:bg-[#ecdccb] text-xs rounded-xl flex items-center gap-1.5"
                  >
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>{fotoFile ? 'Trocar Foto' : 'Selecionar Foto do Aparelho'}</span>
                  </Button>

                  {fotoPreview && (
                    <div className="flex items-center gap-2">
                      <img
                        src={fotoPreview}
                        alt="Preview"
                        className="w-9 h-9 rounded-lg object-cover border border-[#D4AF37]/50 shadow-xs"
                      />
                      <button
                        type="button"
                        onClick={handleRemoverFoto}
                        className="text-[11px] text-red-600 hover:underline font-medium"
                      >
                        Remover
                      </button>
                    </div>
                  )}

                  {!fotoPreview && (
                    <span className="text-[10px] text-[#4B2E20]/60 italic">
                      Opcional. Se preferir, pode enviar direto pelo WhatsApp.
                    </span>
                  )}
                </div>
              </div>
            </div>

            {/* Resumo de Valores */}
            <div className="p-3.5 rounded-2xl bg-[#ecdccb]/60 border border-[#D4AF37]/40 flex items-center justify-between">
              <div>
                <span className="text-xs text-[#4B2E20]/80 block">Valor do Pedido:</span>
                <span className="text-[11px] text-[#4B2E20]/70">
                  Convite Digital ({template.title}): R$ {template.price.toFixed(2)}
                  {querEnsaioDigital && ` + Ensaio Digital: R$ 25,00`}
                </span>
              </div>
              <div className="text-right">
                <span className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                  R$ {valorTotalFinal.toFixed(2)}
                </span>
              </div>
            </div>

            {/* Botões de Ação */}
            <div className="pt-2 flex flex-col sm:flex-row items-center justify-end gap-2.5">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="w-full sm:w-auto text-[#4B2E20] text-xs rounded-xl"
              >
                Voltar aos Modelos
              </Button>

              <Button
                type="submit"
                className="w-full sm:w-auto bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs px-5 py-2.5 rounded-xl border border-[#D4AF37]/50 shadow-md flex items-center justify-center gap-2 group transition-all"
              >
                <Send className="w-3.5 h-3.5 text-[#D4AF37] group-hover:translate-x-0.5 transition-transform" />
                <span>Confirmar & Abrir WhatsApp da Keh</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

