import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { Heart, Sparkles, MessageCircle } from 'lucide-react';

export default function App() {
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);
  const [currentTab, setCurrentTab] = useState<'templates' | 'orders' | 'dashboard'>('templates');

  // Controle de Autenticação da Área Restrita
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState<boolean>(false);

  // Modais de Cadastro (somente admin)
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);

  const handleOpenAdminAuth = () => {
    setIsLoginModalOpen(true);
  };

  const handleLoginSuccess = () => {
    setIsAdminAuthenticated(true);
    setIsLoginModalOpen(false);
    setCurrentTab('orders');
  };

  const handleLogoutAdmin = () => {
    setIsAdminAuthenticated(false);
    setCurrentTab('templates');
  };

  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: Order['status']) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, status } : ord))
    );
  };

  const handleUpdateOrderPayment = (
    orderId: string,
    paymentStatus: Order['paymentStatus'],
    paidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((ord) =>
        ord.id === orderId ? { ...ord, paymentStatus, paidValue } : ord
      )
    );
  };

  const pendingOrdersCount = orders.filter(
    (o) => o.status === 'pendente' || o.status === 'em_criacao'
  ).length;

  return (
    <div className="min-h-screen flex flex-col bg-[#F7EBDD] text-[#4B2E20] selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={handleOpenAdminAuth}
        onLogoutAdmin={handleLogoutAdmin}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Central */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSelectTemplate={() => {}}
            isAdmin={isAdminAuthenticated}
            onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
            onSubmitClientOrder={handleSaveOrder}
          />
        )}

        {isAdminAuthenticated && currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdateOrderPayment}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}

        {isAdminAuthenticated && currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Delicado & Artesanal */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ecdccb]/50 py-8 px-4 text-center mt-auto">
        <div className="max-w-md mx-auto space-y-2 text-xs text-[#4B2E20]/80">
          <div className="flex items-center justify-center gap-1.5 text-sm font-serif font-bold text-[#4B2E20]">
            <Heart className="w-4 h-4 text-[#D4AF37] fill-[#D4AF37]" />
            <span>Keh Convites • Ateliê de Convites Digitais</span>
          </div>
          <p className="text-[11px] text-[#4B2E20]/70 font-light">
            Feito especialmente para você e para o seu momento mais inesquecível.
          </p>
          <div className="pt-2 text-[10px] text-[#4B2E20]/50">
            © {new Date().getFullYear()} Keh Convites. Todos os direitos reservados.
          </div>
        </div>
      </footer>

      {/* Modal de Autenticação com Senha da Área Restrita */}
      <AdminLoginModal
        isOpen={isLoginModalOpen}
        onClose={() => setIsLoginModalOpen(false)}
        onSuccess={handleLoginSuccess}
      />

      {/* Modal de Novo Pedido (Área Administrativa) */}
      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => setIsNewOrderModalOpen(false)}
        templates={templates}
        onSaveOrder={handleSaveOrder}
      />

      {/* Modal de Novo Modelo (Área Administrativa) */}
      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => setIsNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

