import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Heart, Sparkles, Smartphone, ShieldCheck, Camera } from 'lucide-react';

export default function App() {
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminAuthModalOpen, setIsAdminAuthModalOpen] = useState<boolean>(false);

  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente' || o.status === 'em_criacao').length;

  const handleOpenAdminAuth = () => {
    setIsAdminAuthModalOpen(true);
  };

  const handleAdminAuthSuccess = () => {
    setIsAdminAuthenticated(true);
    setIsAdminAuthModalOpen(false);
    setCurrentTab('orders');
  };

  const handleLogoutAdmin = () => {
    setIsAdminAuthenticated(false);
    setCurrentTab('templates');
  };

  const handleOpenOrderModal = (template: InvitationTemplate) => {
    setSelectedTemplateForOrder(template);
    setIsNewOrderModalOpen(true);
  };

  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleClientSubmitOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((ord) => (ord.id === orderId ? { ...ord, status } : ord))
    );
  };

  const handleUpdateOrderPayment = (
    orderId: string,
    paymentStatus: PaymentStatus,
    paidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((ord) =>
        ord.id === orderId ? { ...ord, paymentStatus, paidValue } : ord
      )
    );
  };

  return (
    <div className="min-h-screen bg-[#FDFBF7] text-[#4B2E20] font-sans flex flex-col selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={handleOpenAdminAuth}
        onLogoutAdmin={handleLogoutAdmin}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 pt-6 pb-12">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOpenOrderModal={handleOpenOrderModal}
            onClientSubmitOrder={handleClientSubmitOrder}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdateOrderPayment}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Delicado & Profissional */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#F7EBDD]/70 py-8 text-center text-xs text-[#4B2E20]/80">
        <div className="max-w-7xl mx-auto px-4 space-y-2">
          <div className="flex items-center justify-center gap-2">
            <span className="font-serif font-bold text-sm text-[#4B2E20]">Keh Convites</span>
            <span>•</span>
            <span className="font-medium text-[#4B2E20]/70">Convites Digitais & Ensaios Virtuais</span>
          </div>
          <p className="text-[11px] text-[#4B2E20]/65 max-w-md mx-auto">
            Design afetivo, personalizado e de alta resolução pronto para encantar seus convidados via WhatsApp.
          </p>
          <div className="pt-2 flex items-center justify-center gap-1 text-[11px] text-[#855729]">
            <Heart className="w-3.5 h-3.5 fill-[#D4AF37] text-[#D4AF37]" />
            <span>Feito com dedicação para tornar seu evento inesquecível</span>
          </div>
        </div>
      </footer>

      {/* Modais */}
      <AdminLoginModal
        isOpen={isAdminAuthModalOpen}
        onClose={() => setIsAdminAuthModalOpen(false)}
        onSuccess={handleAdminAuthSuccess}
      />

      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => {
          setIsNewOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        templates={templates}
        preSelectedTemplate={selectedTemplateForOrder}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => setIsNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

