    { id: 'interativo_pdf', label: 'Com Botões Clicáveis' },
    { id: 'imagem_card', label: 'Simples para WhatsApp' },
    { id: 'animado_video', label: 'Vídeos Animados' },
    { id: 'save_the_date', label: 'Save The Date' },
  ];

  const filteredTemplates = templates.filter((tpl) => {
    const matchesCategory =
      selectedCategory === 'todos' || tpl.category === selectedCategory;

    const matchesFormat =
      selectedFormat === 'todos' ||
      (selectedFormat === 'interativo_pdf'
        ? tpl.hasInteraction || tpl.format === 'interativo_pdf'
        : selectedFormat === 'imagem_card'
        ? !tpl.hasInteraction && tpl.format === 'imagem_card'
        : tpl.format === selectedFormat);

    const matchesSearch =
      tpl.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tpl.tags.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase())) ||
      tpl.description.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesCategory && matchesFormat && matchesSearch;
  });

  const handleQueroEsteModelo = (tpl: InvitationTemplate) => {
    setTemplateParaPersonalizar(tpl);
    setModalClientOpen(true);
  };

  const handleEncomendarEnsaioDireto = (temaExemplo: string) => {
    // Escolhe um modelo para personalizar ou abre com o primeiro da lista
    const modeloBase = templates[0] || null;
    if (modeloBase) {
      setTemplateParaPersonalizar({
        ...modeloBase,
        title: `Convite Digital + Ensaio (${temaExemplo})`,
      });
      setModalClientOpen(true);
    }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-16">
      {/* Banner de Apresentação Delicado */}
      <section className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#FFFDF9] via-[#FAF3EB] to-[#F7EBDD] border border-[#D4AF37]/35 shadow-md p-6 sm:p-10 text-center">
        <div className="max-w-2xl mx-auto space-y-3">
          <div className="inline-flex items-center gap-2 px-3.5 py-1 rounded-full bg-[#ecdccb]/80 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold">
            <Heart className="w-3.5 h-3.5 text-[#D4AF37] fill-[#D4AF37]" />
            <span>Feito com amor e delicadeza para o seu momento</span>
          </div>

          <h1 className="text-2xl sm:text-4xl font-serif font-black text-[#4B2E20] tracking-tight">
            Convites Digitais Exclusivos
          </h1>

          <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-normal">
            Escolha seu modelo preferido, personalize com seus dados e receba seu arquivo digital
            em alta resolução direto no WhatsApp pronto para compartilhar com seus convidados.
          </p>

          <div className="flex flex-wrap items-center justify-center gap-2 sm:gap-4 pt-2 text-[11px] font-medium text-[#4B2E20]">
            <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/70 border border-[#D4AF37]/30">
              <CheckCircle2 className="w-3.5 h-3.5 text-[#D4AF37]" />
              Modelos com e sem botões
            </span>
            <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/70 border border-[#D4AF37]/30">
              <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
              Opção com Ensaio Digital
            </span>
            <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/70 border border-[#D4AF37]/30">
              <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
              Envio Rápido pelo WhatsApp
            </span>
          </div>
        </div>
      </section>

      {/* SEÇÃO ESPECIAL: ENSAIOS DIGITAIS PARA O CONVITE */}
      <section className="space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-3 border-b border-[#D4AF37]/25 pb-3">
          <div>
            <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-[#4B2E20] text-[#D4AF37] text-[11px] font-bold mb-1">
              <Camera className="w-3 h-3" />
              <span>Serviço Especial Keh Convites</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
              Ensaios Digitais Temáticos
            </h2>
            <p className="text-xs text-[#4B2E20]/75">
              Não tem uma foto profissional no tema da festa? Nós criamos um ensaio digital temático exclusivo para a capa do seu convite!
            </p>
          </div>
          <span className="text-[11px] font-semibold text-[#855729] bg-[#F7EBDD] px-3 py-1 rounded-xl border border-[#D4AF37]/30 self-start sm:self-auto">
            Você pode adicionar em qualquer convite ✨
          </span>
        </div>

        {/* Grid de Exemplos de Ensaios Digitais */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {ensaiosDigitaisExemplos.map((ensaio) => (
            <Card
              key={ensaio.id}
              className="bg-white/95 border-[#D4AF37]/35 rounded-2xl overflow-hidden hover:shadow-lg transition-all duration-300 flex flex-col group"
            >
              <div className="relative aspect-[4/5] overflow-hidden bg-[#faf4ec]">
                <img
                  src={ensaio.imagem}
                  alt={ensaio.titulo}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                />
                <div className="absolute top-2.5 left-2.5">
                  <span className="px-2.5 py-1 rounded-lg text-[10px] font-bold bg-[#4B2E20]/85 text-[#F7EBDD] backdrop-blur-xs border border-[#D4AF37]/40">
                    {ensaio.tag}
                  </span>
                </div>
                <div className="absolute inset-0 bg-gradient-to-t from-[#4B2E20]/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-3">
                  <p className="text-[11px] text-[#F7EBDD] font-medium leading-tight">
                    {ensaio.subtitulo}
                  </p>
                </div>
              </div>

              <CardContent className="p-3.5 flex-1 flex flex-col justify-between space-y-2">
                <div>
                  <span className="text-[10px] uppercase font-bold text-[#855729] tracking-wider block">
                    {ensaio.tema}
                  </span>
                  <h3 className="text-sm font-serif font-bold text-[#4B2E20] leading-snug">
                    {ensaio.titulo}
                  </h3>
                </div>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleEncomendarEnsaioDireto(ensaio.tema)}
                  className="w-full text-xs font-semibold border-[#D4AF37]/50 bg-[#fdfaf6] hover:bg-[#4B2E20] hover:text-[#F7EBDD] text-[#4B2E20] rounded-xl flex items-center justify-center gap-1.5 transition-colors"
                >
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Quero Convite com este Ensaio</span>
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </section>

      {/* CATÁLOGO DE MODELOS DE CONVITES DIGITAIS */}
      <section className="space-y-6 pt-4">
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
                Modelos de Convites Digitais
              </h2>
              <p className="text-xs text-[#4B2E20]/75">
                Escolha o estilo do seu evento e preencha com as suas informações
              </p>
            </div>

            {/* Barra de Busca rápida */}
            <div className="w-full sm:w-72">
              <input
                type="text"
                placeholder="Buscar modelo ou tema..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full h-9 px-3.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              />
            </div>
          </div>

          {/* Filtros de Categoria */}
          <div className="flex flex-wrap items-center gap-1.5">
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.id)}
                className={`px-3 py-1.5 rounded-xl text-xs font-semibold transition-all ${
                  selectedCategory === cat.id
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-xs'
                    : 'bg-white/80 hover:bg-[#ecdccb]/60 text-[#4B2E20] border border-[#D4AF37]/25'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>

          {/* Filtros de Formato (Com Botão x Simples) */}
          <div className="flex flex-wrap items-center gap-1.5 pt-1">
            <span className="text-[11px] font-bold text-[#4B2E20]/80 mr-1">Filtrar por:</span>
            {formatFilters.map((fmt) => (
              <button
                key={fmt.id}
                onClick={() => setSelectedFormat(fmt.id)}
                className={`px-2.5 py-1 rounded-lg text-[11px] font-medium transition-all ${
                  selectedFormat === fmt.id
                    ? 'bg-[#D4AF37] text-[#4B2E20] font-bold shadow-xs'
                    : 'bg-white/60 hover:bg-white text-[#4B2E20]/80 border border-[#D4AF37]/20'
                }`}
              >
                {fmt.label}
              </button>
            ))}
          </div>
        </div>

        {/* Grid de Modelos */}
        {filteredTemplates.length === 0 ? (
          <div className="p-12 text-center bg-white/70 rounded-3xl border border-[#D4AF37]/30">
            <Sparkles className="w-8 h-8 text-[#D4AF37] mx-auto mb-2 opacity-60" />
            <p className="text-sm font-serif text-[#4B2E20] font-semibold">
              Nenhum modelo encontrado com esse filtro.
            </p>
            <button
              onClick={() => {
                setSelectedCategory('todos');
                setSelectedFormat('todos');
                setSearchQuery('');
              }}
              className="mt-2 text-xs font-bold text-[#855729] underline hover:text-[#4B2E20]"
            >
              Limpar filtros e ver todos
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
            {filteredTemplates.map((template) => {
              const temInteracao = Boolean(
                template.hasInteraction ||
                template.format === 'interativo_pdf' ||
                template.format === 'site_rsvp'
              );

              return (
                <Card
                  key={template.id}
                  className="bg-white/95 border-[#D4AF37]/35 rounded-2xl overflow-hidden hover:shadow-xl transition-all duration-300 flex flex-col group"
                >
                  {/* Foto do Modelo com Badge de Formato */}
                  <div className="relative aspect-[3/4] overflow-hidden bg-[#faf5ee]">
                    <img
                      src={template.imageUrl}
                      alt={template.title}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    />

                    {/* Badge de Categoria */}
                    <div className="absolute top-2.5 left-2.5">
                      <span className="px-2.5 py-0.5 rounded-lg text-[10px] font-bold bg-[#4B2E20]/85 text-[#F7EBDD] backdrop-blur-xs border border-[#D4AF37]/40">
                        {template.category}
                      </span>
                    </div>

                    {/* Badge de Interação / Formato */}
                    <div className="absolute top-2.5 right-2.5">
                      <span
                        className={`px-2 py-0.5 rounded-lg text-[9px] font-bold backdrop-blur-xs shadow-xs border ${
                          temInteracao
                            ? 'bg-[#D4AF37] text-[#4B2E20] border-[#4B2E20]/20'
                            : 'bg-white/90 text-[#4B2E20] border-[#D4AF37]/30'
                        }`}
                      >
                        {temInteracao ? '✨ Com Botões' : '💌 Simples WhatsApp'}
                      </span>
                    </div>

                    {/* Botão Ver Foto Grande */}
                    <button
                      onClick={() => setPreviewTemplate(template)}
                      className="absolute bottom-2.5 right-2.5 p-2 rounded-xl bg-white/90 hover:bg-white text-[#4B2E20] shadow-sm transition-transform active:scale-95"
                      title="Visualizar Detalhes"
                    >
                      <Eye className="w-3.5 h-3.5 text-[#4B2E20]" />
                    </button>
                  </div>

                  {/* Informações e Botão Principal */}
                  <CardContent className="p-4 flex-1 flex flex-col justify-between space-y-3">
                    <div>
                      <h3 className="font-serif font-bold text-sm text-[#4B2E20] group-hover:text-[#855729] transition-colors line-clamp-1">
                        {template.title}
                      </h3>
                      <p className="text-[11px] text-[#4B2E20]/75 line-clamp-2 mt-1 leading-snug">
                        {template.description}
                      </p>
                    </div>

                    <div className="pt-2 border-t border-[#D4AF37]/20 flex items-center justify-between">
                      <div>
                        <span className="text-[10px] text-[#4B2E20]/65 block font-medium">A partir de</span>
                        <span className="text-base font-serif font-black text-[#4B2E20]">
                          R$ {template.price.toFixed(2)}
                        </span>
                      </div>

                      {/* Botão Principal: Quero este Modelo */}
                      <Button
                        size="sm"
                        onClick={() => handleQueroEsteModelo(template)}
                        className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-xs border border-[#D4AF37]/40 flex items-center gap-1.5"
                      >
                        <Heart className="w-3.5 h-3.5 text-[#D4AF37] fill-[#D4AF37]" />
                        <span>Quero este</span>
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </section>

      {/* Modal de Prévia Ampliada */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#fcf8f3] rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl border border-[#D4AF37]/50">
            <div className="relative aspect-[3/4] bg-[#faf5ee]">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => setPreviewTemplate(null)}
                className="absolute top-3 right-3 p-2 rounded-full bg-[#4B2E20]/80 text-[#F7EBDD] hover:bg-[#4B2E20]"
              >
                ✕
              </button>
            </div>
            <div className="p-5 space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-serif font-bold text-lg text-[#4B2E20]">
                    {previewTemplate.title}
                  </h3>
                  <span className="text-xs text-[#4B2E20]/75">
                    {previewTemplate.category} • {previewTemplate.hasInteraction ? 'Com botões interativos' : 'Modelo simples para WhatsApp'}
                  </span>
                </div>
                <span className="text-lg font-serif font-bold text-[#4B2E20]">
                  R$ {previewTemplate.price.toFixed(2)}
                </span>
              </div>
              <p className="text-xs text-[#4B2E20]/80">{previewTemplate.description}</p>
              <div className="flex items-center gap-2 pt-2">
                <Button
                  variant="outline"
                  onClick={() => setPreviewTemplate(null)}
                  className="flex-1 text-xs rounded-xl border-[#D4AF37]/40"
                >
                  Voltar
                </Button>
                <Button
                  onClick={() => {
                    const t = previewTemplate;
                    setPreviewTemplate(null);
                    handleQueroEsteModelo(t);
                  }}
                  className="flex-1 bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl"
                >
                  Personalizar este Modelo
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Personalização do Pedido do Cliente */}
      <ClientOrderModal
        isOpen={modalClientOpen}
        template={templateParaPersonalizar}
        onClose={() => {
          setModalClientOpen(false);
          setTemplateParaPersonalizar(null);
        }}
        onSubmitOrder={(newOrder) => {
          if (onClientSubmitOrder) {
            onClientSubmitOrder(newOrder);
          }
        }}
      />
    </div>
  );
}

