import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  MessageCircle,
  Phone,
  Camera,
  CheckCircle2,
  Send,
  Smartphone,
  Check,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

// Exemplos de Ensaios Digitais para inspiração no final do formulário
const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala e Castelo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol e Cenário Floral',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake e Balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
  },
];

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  // 1. Campos essenciais do Convite Digital (Foco total no convite)
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // 2. Campos exclusivos se o modelo tiver botões/interação
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // 3. Foto do cliente
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 4. No final do formulário: Ensaio Digital Opcional
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante / homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o número do WhatsApp para contato e envio da prévia.');
      return;
    }

    const notasFormatadas = [
      'Convite Digital Keh Convites',
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples (sem botões)',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      rsvpLink: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: 0,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pendente',
      wantsDigitalPhotoshoot: querEnsaioDigital,
      digitalPhotoshootTheme: querEnsaioDigital ? ensaioEscolhido : undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);

    // Mensagem formatada para o WhatsApp
    let msg = `Olá Keh Convites! Gostaria de encomendar este convite digital:\n\n`;
    msg += `💌 *Modelo Digital:* ${template.title}\n`;
    msg += `🏷️ *Tipo:* ${temInteracao ? 'Convite Digital Interativo (com botões)' : 'Convite Digital Simples'}\n`;
    msg += `💰 *Valor do Convite:* R$ ${template.price.toFixed(2)}\n`;

    if (querEnsaioDigital) {
      msg += `📸 *Adicional Ensaio Digital:* SIM (+ R$ 25,00 - ${ensaioEscolhido})\n`;
      msg += `💵 *Total Geral:* R$ ${valorTotalFinal.toFixed(2)}\n`;
    }

    msg += `\n📝 *DADOS DA CELEBRAÇÃO:*\n`;
    msg += `👤 *Nome do Aniversariante:* ${nomeAniversariante}\n`;
    if (temaFesta.trim()) msg += `🎨 *Tema:* ${temaFesta}\n`;
    if (dataEvento.trim()) msg += `📅 *Data:* ${dataEvento}\n`;
    if (diaSemana.trim()) msg += `🗓️ *Dia da Semana:* ${diaSemana}\n`;
    if (horarioEvento.trim()) msg += `⏰ *Horário:* ${horarioEvento}\n`;
    if (localEvento.trim()) msg += `📍 *Local:* ${localEvento}\n`;
    if (fraseEspecial.trim()) msg += `💬 *Frase:* "${fraseEspecial}"\n`;
    msg += `📱 *WhatsApp para contato:* ${whatsappCliente}\n`;

    if (temInteracao) {
      msg += `\n✨ *BOTÕES INTERATIVOS:*\n`;
      if (confirmacaoPresenca.trim()) msg += `📲 *Confirmação de Presença:* ${confirmacaoPresenca}\n`;
      if (linkLocalizacao.trim()) msg += `🗺️ *Localização:* ${linkLocalizacao}\n`;
      if (listaPresentes.trim()) msg += `🎁 *Lista de Presentes:* ${listaPresentes}\n`;
    }

    if (querEnsaioDigital) {
      msg += `\n📸 *Ensaio Digital:* Gostaria de incluir o ensaio digital temático para a arte do meu convite!\n`;
    }

    if (fotoFile) {
      msg += `\n📎 *Foto:* Vou anexar aqui a foto para a produção.\n`;
    }

    const telKehLimpo = '5511999999999';
    const linkZap = `https://wa.me/${telKehLimpo}?text=${encodeURIComponent(msg)}`;
    window.open(linkZap, '_blank');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fcf8f3] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-[#ecdccb]/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] flex items-center justify-center text-[#D4AF37] shadow-sm">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                Personalizar Meu Convite Digital
              </CardTitle>
              <p className="text-[11px] text-[#4B2E20]/75 font-medium">
                Modelo: <strong className="text-[#4B2E20]">{template.title}</strong> • {temInteracao ? 'Convite Interativo' : 'Convite Simples'}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Formulário - Foco Total nos Convites com Ensaio no Final */}
        <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-6">
          <form onSubmit={handleSubmit} className="space-y-6">

            {/* MINI RESUMO DO MODELO ESCOLHIDO */}
            <div className="flex items-center gap-3.5 p-3.5 rounded-2xl bg-white border border-[#D4AF37]/30 shadow-xs">
              <img
                src={template.imageUrl}
                alt={template.title}
                className="w-14 h-16 rounded-xl object-cover border border-[#D4AF37]/20 shrink-0"
              />
              <div className="flex-1 min-w-0">
                <span className="text-[10px] px-2 py-0.5 rounded-md font-semibold bg-[#ebdccb] text-[#4B2E20] inline-block mb-1">
                  {temInteracao ? 'Convite com Botões Interativos' : 'Convite Digital Simples'}
                </span>
                <h4 className="text-xs font-serif font-bold text-[#4B2E20] truncate">
                  {template.title}
                </h4>
                <p className="text-[11px] text-[#4B2E20]/75">
                  Valor do convite: <strong className="text-[#4B2E20]">R$ {template.price.toFixed(2)}</strong>
                </p>
              </div>
            </div>

            {/* SEÇÃO 1: DADOS PRINCIPAIS DO CONVITE */}
            <div className="space-y-3.5">
              <div className="border-b border-[#D4AF37]/25 pb-1.5 flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                <h3 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider">
                  1. Informações do Aniversariante e Evento
                </h3>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Nome do aniversariante / homenageado *
                  </label>
                  <Input
                    required
                    placeholder="Ex: Sophia ou Lorenzo"
                    value={nomeAniversariante}
                    onChange={(e) => setNomeAniversariante(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Tema da festa / evento
                  </label>
                  <Input
                    placeholder="Ex: Jardim Encantado, Realeza, Safári..."
                    value={temaFesta}
                    onChange={(e) => setTemaFesta(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Data do evento
                  </label>
                  <Input
                    type="date"
                    value={dataEvento}
                    onChange={(e) => setDataEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Dia da semana
                  </label>
                  <Input
                    placeholder="Ex: Sábado ou Domingo"
                    value={diaSemana}
                    onChange={(e) => setDiaSemana(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Horário da festa
                  </label>
                  <Input
                    placeholder="Ex: às 16:30h"
                    value={horarioEvento}
                    onChange={(e) => setHorarioEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                  Local do evento
                </label>
                <Input
                  placeholder="Ex: Buffet Estrela Kids - Rua das Flores, 120"
                  value={localEvento}
                  onChange={(e) => setLocalEvento(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                  Frase especial ou mensagem (opcional)
                </label>
                <Input
                  placeholder="Ex: 'Venha comemorar comigo o meu 1º aninho!'"
                  value={fraseEspecial}
                  onChange={(e) => setFraseEspecial(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                />
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                  Seu WhatsApp para contato e envio da prévia *
                </label>
                <Input
                  required
                  placeholder="Ex: (11) 98765-4321"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                />
              </div>
            </div>

            {/* SEÇÃO 2: DADOS DE INTERAÇÃO (APENAS SE O CONVITE TIVER BOTÕES) */}
            {temInteracao && (
              <div className="space-y-3.5 p-4 rounded-2xl bg-[#fdfaf6] border border-[#D4AF37]/35">
                <div className="border-b border-[#D4AF37]/25 pb-1.5 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Smartphone className="w-4 h-4 text-[#D4AF37]" />
                    <h3 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider">
                      2. Dados dos Botões Clicáveis do Convite
                    </h3>
                  </div>
                  <span className="text-[10px] px-2 py-0.5 rounded-full bg-[#ebdccb] text-[#4B2E20] font-semibold">
                    Modelo Interativo
                  </span>
                </div>

                <p className="text-[11px] text-[#4B2E20]/75">
                  Este modelo possui botões para os seus convidados clicarem direto no WhatsApp. Preencha as informações que deseja incluir:
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                      WhatsApp para Confirmação de Presença
                    </label>
                    <Input
                      placeholder="Ex: (11) 98888-9999 com a mamãe"
                      value={confirmacaoPresenca}
                      onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                      Link ou Endereço de Localização (GPS / Maps)
                    </label>
                    <Input
                      placeholder="Ex: Link do Google Maps ou Waze"
                      value={linkLocalizacao}
                      onChange={(e) => setLinkLocalizacao(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Sugestão de Lista de Presentes
                  </label>
                  <Input
                    placeholder="Ex: Roupas tam 2, Calçados tam 22, Fralda G ou link de site"
                    value={listaPresentes}
                    onChange={(e) => setListaPresentes(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>
              </div>
            )}

            {/* SEÇÃO 3: FOTO DO ANIVERSARIANTE (OPCIONAL) */}
            <div className="space-y-3 p-4 rounded-2xl bg-white border border-[#D4AF37]/30">
              <div className="border-b border-[#D4AF37]/25 pb-1.5 flex items-center gap-2">
                <Upload className="w-4 h-4 text-[#D4AF37]" />
                <h3 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider">
                  Foto para o Convite (Opcional)
                </h3>
              </div>

              <div className="flex flex-col sm:flex-row items-center gap-4">
                {fotoPreview ? (
                  <div className="relative w-20 h-20 rounded-xl overflow-hidden border-2 border-[#D4AF37] shrink-0">
                    <img src={fotoPreview} alt="Prévia" className="w-full h-full object-cover" />
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="absolute top-1 right-1 p-0.5 rounded-full bg-red-600 text-white"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ) : (
                  <div
                    onClick={() => fileInputRef.current?.click()}
                    className="w-full sm:w-auto flex-1 border-2 border-dashed border-[#D4AF37]/50 rounded-xl p-4 text-center cursor-pointer hover:bg-[#faf5ee] transition-colors"
                  >
                    <Upload className="w-5 h-5 text-[#D4AF37] mx-auto mb-1" />
                    <span className="text-xs font-semibold text-[#4B2E20] block">
                      Clique para anexar foto do aniversariante
                    </span>
                    <span className="text-[10px] text-[#4B2E20]/65">
                      (Ou envie direto pelo WhatsApp depois)
                    </span>
                  </div>
                )}

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleFotoChange}
                  className="hidden"
                />
              </div>
            </div>

            {/* SEÇÃO 4 (NO FINAL): ENSAIOS DIGITAIS COMO TRABALHO ADICIONAL */}
            <div className="space-y-3.5 p-4 rounded-2xl bg-gradient-to-br from-[#faf4ec] to-[#f7ebdd]/60 border border-[#D4AF37]/45">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Camera className="w-4 h-4 text-[#D4AF37]" />
                  <h3 className="text-xs font-serif font-bold text-[#4B2E20] uppercase tracking-wider">
                    Deseja incluir um Ensaio Digital no convite?
                  </h3>
                </div>
                <span className="text-[10px] px-2 py-0.5 rounded-full bg-[#ebdccb] text-[#4B2E20] font-bold">
                  + R$ 25,00
                </span>
              </div>

              <p className="text-[11px] text-[#4B2E20]/80 leading-relaxed">
                Transformamos uma foto simples de celular do anfitrião em um <strong>ensaio fotográfico temático</strong> de estúdio para colocar no seu convite.
              </p>

              {/* Botão de Ativação do Ensaio */}
              <label className="flex items-center gap-2.5 p-3 rounded-xl bg-white border border-[#D4AF37]/40 cursor-pointer hover:bg-[#fffdf9] transition-all">
                <input
                  type="checkbox"
                  checked={querEnsaioDigital}
                  onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                  className="w-4 h-4 text-[#4B2E20] rounded accent-[#4B2E20]"
                />
                <span className="text-xs font-bold text-[#4B2E20]">
                  Sim! Quero que você crie o ensaio temático para o meu convite (+ R$ 25,00)
                </span>
              </label>

              {/* Exemplos em miniaturas caso a cliente queira conferir */}
              {querEnsaioDigital && (
                <div className="space-y-2 pt-2 animate-fade-in">
                  <span className="text-[11px] font-semibold text-[#4B2E20] block">
                    Escolha ou inspire-se em um dos estilos de ensaio:
                  </span>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                    {EXEMPLOS_ENSAIOS_DIGITAIS.map((ex) => (
                      <div
                        key={ex.id}
                        onClick={() => setEnsaioEscolhido(ex.titulo)}
                        className={`p-2 rounded-xl border text-center cursor-pointer transition-all bg-white ${
                          ensaioEscolhido === ex.titulo
                            ? 'border-[#4B2E20] ring-2 ring-[#D4AF37] shadow-xs'
                            : 'border-[#D4AF37]/30 hover:border-[#D4AF37]'
                        }`}
                      >
                        <div className="aspect-square rounded-lg overflow-hidden mb-1.5 bg-[#ebdccb]">
                          <img src={ex.foto} alt={ex.titulo} className="w-full h-full object-cover" />
                        </div>
                        <p className="text-[10px] font-bold text-[#4B2E20] truncate">{ex.titulo}</p>
                        <span className="text-[9px] text-[#4B2E20]/70 truncate block">{ex.subtitulo}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* RESUMO DE VALOR E BOTÃO FINAL */}
            <div className="pt-2 border-t border-[#D4AF37]/25 space-y-3">
              <div className="flex items-center justify-between text-xs text-[#4B2E20] px-1">
                <span>Convite Digital:</span>
                <span className="font-semibold">R$ {template.price.toFixed(2)}</span>
              </div>

              {querEnsaioDigital && (
                <div className="flex items-center justify-between text-xs text-[#4B2E20] px-1">
                  <span>Ensaio Digital Temático:</span>
                  <span className="font-semibold text-emerald-800">+ R$ {valorEnsaio.toFixed(2)}</span>
                </div>
              )}

              <div className="flex items-center justify-between p-3 rounded-2xl bg-[#ebdccb]/60 border border-[#D4AF37]/40 text-[#4B2E20]">
                <span className="text-xs font-serif font-bold">Valor Total:</span>
                <span className="text-base font-serif font-bold">
                  R$ {valorTotalFinal.toFixed(2)}
                </span>
              </div>

              <div className="flex items-center justify-end gap-2.5 pt-2">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onClose}
                  className="text-[#4B2E20] rounded-xl text-xs"
                >
                  Voltar aos Modelos
                </Button>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs py-3 px-6 rounded-2xl border border-[#D4AF37]/40 shadow-sm flex items-center gap-2 hover:scale-[1.01] transition-transform"
                >
                  <Send className="w-4 h-4 text-[#D4AF37]" />
                  <span>Enviar Pedido pelo WhatsApp</span>
                </Button>
              </div>
            </div>

          </form>
        </CardContent>
      </Card>
    </div>
  );
}

