          {/* ======================= TELA 3: CONFIRMAÇÃO DE SUCESSO ======================= */}
          {etapa === 'concluido' && (
            <div className="py-6 text-center space-y-4 animate-fade-in">
              <div className="w-16 h-16 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto shadow-md border-2 border-emerald-300">
                <CheckCircle2 className="w-9 h-9" />
              </div>

              <div className="space-y-1">
                <h3 className="font-serif font-bold text-xl text-[#4B2E20]">
                  Pedido Registrado com Sucesso!
                </h3>
                <p className="text-xs text-[#4B2E20]/80 max-w-md mx-auto">
                  Recebemos todos os dados do convite de <strong>{nomeAniversariante}</strong>.
                </p>
              </div>

              <div className="p-4 bg-[#ecdccb]/40 rounded-2xl border border-[#D4AF37]/40 max-w-md mx-auto text-left text-xs space-y-2">
                <p className="font-bold text-[#4B2E20] flex items-center gap-1.5">
                  <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                  <span>Próximos Passos:</span>
                </p>
                <p className="text-[#4B2E20]/80">
                  • Vamos iniciar a produção personalizada do seu convite.
                </p>
                <p className="text-[#4B2E20]/80">
                  • A prévia será enviada diretamente no seu WhatsApp: <strong>{whatsappCliente}</strong>.
                </p>
                <p className="text-[#4B2E20]/80">
                  • Chave PIX utilizada: <strong>{CHAVE_PIX_KEH}</strong>.
                </p>
              </div>

              <div className="pt-2">
                <Button
                  type="button"
                  onClick={handleFecharModal}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl px-8 py-2.5 shadow-md"
                >
                  Fechar Janela
                </Button>
              </div>
            </div>
          )}

        </CardContent>
      </Card>
    </div>
  );
}

