import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  MessageCircle,
  Phone,
  Camera,
  CheckCircle2,
  Send,
  Smartphone,
  Check,
  QrCode,
  Copy,
  ArrowRight,
  ArrowLeft,
  ShieldCheck,
  CheckCheck,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

// Exemplos de Ensaios Digitais para inspiração no final do formulário
const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala e Castelo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol e Cenário Floral',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake e Balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
  },
];

const CHAVE_PIX_KEH = '32998040080';

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  // Etapa do fluxo: 'formulario' ou 'pagamento_pix' ou 'concluido'
  const [etapa, setEtapa] = useState<'formulario' | 'pagamento_pix' | 'concluido'>('formulario');

  // 1. Campos essenciais do Convite Digital
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // 2. Campos exclusivos se o modelo tiver botões/interação
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // 3. Foto do cliente
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 4. No final do formulário: Ensaio Digital Opcional
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);

  // Estado de cópia do PIX
  const [pixCopiado, setPixCopiado] = useState(false);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCopiarPix = () => {
    navigator.clipboard.writeText(CHAVE_PIX_KEH);
    setPixCopiado(true);
    setTimeout(() => setPixCopiado(false), 3000);
  };

  const handleAvancarParaPix = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante ou homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o número de WhatsApp para podermos entregar o convite.');
      return;
    }

    setEtapa('pagamento_pix');
  };

  const handleFinalizarPedido = () => {
    const notasFormatadas = [
      'Convite Digital Keh Convites',
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples (sem botões)',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
      `Pagamento PIX: R$ ${valorTotalFinal.toFixed(2)} (Chave: ${CHAVE_PIX_KEH})`,
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      rsvpLink: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: valorTotalFinal,
      eventDate: dataEvento,
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pago',
      wantsDigitalPhotoshoot: querEnsaioDigital,
      digitalPhotoshootTheme: querEnsaioDigital ? ensaioEscolhido : undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);
    setEtapa('concluido');
  };

  const handleFecharModal = () => {
    setEtapa('formulario');
    setPixCopiado(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">

        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/80 to-[#f7ebdd]/80 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] border border-[#D4AF37]/50 flex items-center justify-center text-[#D4AF37] shadow-sm">
              {etapa === 'pagamento_pix' ? (
                <QrCode className="w-5 h-5" />
              ) : etapa === 'concluido' ? (
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
              ) : (
                <Sparkles className="w-5 h-5" />
              )}
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                {etapa === 'pagamento_pix'
                  ? 'Pagamento do Convite via PIX'
                  : etapa === 'concluido'
                  ? 'Pedido Concluído com Sucesso!'
                  : 'Personalize Seu Convite Digital'}
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                {template.title} • {temInteracao ? 'Modelo Interativo com Botões' : 'Modelo Simples'}
              </p>
            </div>
          </div>
          <button
            onClick={handleFecharModal}
            className="p-1.5 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Corpo do Modal com Scroll Suave */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-6 text-xs text-[#4B2E20]">

          {/* ======================= TELA 1: FORMULÁRIO DO CONVITE ======================= */}
          {etapa === 'formulario' && (
            <form onSubmit={handleAvancarParaPix} className="space-y-6">

              {/* Banner Informativo do Modelo */}
              <div className="p-3.5 bg-gradient-to-r from-[#fbf5ed] to-[#f5ebdc] rounded-2xl border border-[#D4AF37]/30 flex items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-14 h-14 object-cover rounded-xl border border-[#D4AF37]/40 shadow-sm"
                  />
                  <div>
                    <span className="text-[11px] font-semibold text-[#855729] uppercase tracking-wider block">
                      {template.category}
                    </span>
                    <h4 className="font-serif font-bold text-[#4B2E20] text-sm">
                      {template.title}
                    </h4>
                    <span className="text-[11px] text-[#4B2E20]/70">
                      {temInteracao ? '✨ Botões Clicáveis inclusos' : '💌 Card Digital sem botões'}
                    </span>
                  </div>
                </div>

                <div className="text-right shrink-0">
                  <span className="text-[11px] text-[#4B2E20]/70 block font-medium">Valor</span>
                  <span className="text-base font-serif font-bold text-[#4B2E20]">
                    R$ {template.price.toFixed(2)}
                  </span>
                </div>
              </div>

              {/* SEÇÃO 1: DADOS PRINCIPAIS DO CONVITE */}
              <div className="space-y-4">
                <div className="flex items-center gap-2 border-b border-[#D4AF37]/25 pb-1.5">
                  <Heart className="w-4 h-4 text-[#D4AF37]" />
                  <h3 className="font-serif font-bold text-sm text-[#4B2E20]">
                    1. Informações da Comemoração
                  </h3>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Nome do Aniversariante / Homenageado *
                    </label>
                    <Input
                      required
                      placeholder="Ex: Cecília faz 1 aninho / Lucas & Sofia"
                      value={nomeAniversariante}
                      onChange={(e) => setNomeAniversariante(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Tema da Festa ou Evento
                    </label>
                    <Input
                      placeholder="Ex: Safári Baby, Bosque Encantado, Princesas, Rústico..."
                      value={temaFesta}
                      onChange={(e) => setTemaFesta(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Data do Evento
                    </label>
                    <div className="relative">
                      <Calendar className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                      <Input
                        type="date"
                        value={dataEvento}
                        onChange={(e) => setDataEvento(e.target.value)}
                        className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Dia da Semana
                    </label>
                    <Input
                      placeholder="Ex: Sábado, Domingo"
                      value={diaSemana}
                      onChange={(e) => setDiaSemana(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Horário
                    </label>
                    <div className="relative">
                      <Clock className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                      <Input
                        type="time"
                        value={horarioEvento}
                        onChange={(e) => setHorarioEvento(e.target.value)}
                        className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Local do Evento / Endereço
                    </label>
                    <div className="relative">
                      <MapPin className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                      <Input
                        placeholder="Ex: Buffet Villa Encantada - Rua das Flores, 120"
                        value={localEvento}
                        onChange={(e) => setLocalEvento(e.target.value)}
                        className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 text-[#4B2E20]">
                      Seu WhatsApp para Contato *
                    </label>
                    <div className="relative">
                      <Phone className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
                      <Input
                        required
                        placeholder="(DDD) 99999-9999"
                        value={whatsappCliente}
                        onChange={(e) => setWhatsappCliente(e.target.value)}
                        className="pl-8 bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block font-semibold mb-1 text-[#4B2E20]">
                    Frase Especial ou Versículo (Opcional)
                  </label>
                  <Input
                    placeholder='Ex: "Venha comemorar comigo esse momento tão especial!"'
                    value={fraseEspecial}
                    onChange={(e) => setFraseEspecial(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                  />
                </div>
              </div>

              {/* SEÇÃO 2: BOTÕES CLICÁVEIS (SOMENTE SE O MODELO TIVER INTERAÇÃO) */}
              {temInteracao ? (
                <div className="space-y-4 p-4 rounded-2xl bg-[#ecdccb]/35 border border-[#D4AF37]/35">
                  <div className="flex items-center gap-2 border-b border-[#D4AF37]/25 pb-1.5">
                    <Smartphone className="w-4 h-4 text-[#D4AF37]" />
                    <h3 className="font-serif font-bold text-sm text-[#4B2E20]">
                      2. Botões Interativos (Clicáveis)
                    </h3>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div>
                      <label className="block font-semibold mb-1 text-[#4B2E20]">
                        Confirmação de Presença
                      </label>
                      <Input
                        placeholder="WhatsApp ou link RSVP"
                        value={confirmacaoPresenca}
                        onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>

                    <div>
                      <label className="block font-semibold mb-1 text-[#4B2E20]">
                        Link do Google Maps
                      </label>
                      <Input
                        placeholder="Link da localização"
                        value={linkLocalizacao}
                        onChange={(e) => setLinkLocalizacao(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>

                    <div>
                      <label className="block font-semibold mb-1 text-[#4B2E20]">
                        Lista de Presentes / Pix
                      </label>
                      <Input
                        placeholder="Site ou sugestão de presente"
                        value={listaPresentes}
                        onChange={(e) => setListaPresentes(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>
                </div>
              ) : (
                <div className="p-3 bg-[#ecdccb]/20 rounded-xl border border-[#D4AF37]/20 flex items-center gap-2.5">
                  <Sparkles className="w-4 h-4 text-[#D4AF37] shrink-0" />
                  <p className="text-[11px] text-[#4B2E20]/80">
                    <strong>Modelo Simples:</strong> Este convite é criado em imagem de alta resolução (Card Digital) para fácil envio no WhatsApp, sem botões de clique.
                  </p>
                </div>
              )}

              {/* SEÇÃO 3: ANEXAR FOTO DO ANIVERSARIANTE (OPCIONAL) */}
              <div className="space-y-2">
                <label className="block font-semibold text-[#4B2E20]">
                  Foto para o Convite (Opcional)
                </label>
                <div className="flex items-center gap-3">
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFotoChange}
                    accept="image/*"
                    className="hidden"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => fileInputRef.current?.click()}
                    className="border-[#D4AF37]/50 bg-white text-[#4B2E20] hover:bg-[#ecdccb]/40 rounded-xl text-xs flex items-center gap-1.5"
                  >
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>{fotoFile ? 'Trocar Foto' : 'Escolher Foto do Arquivo'}</span>
                  </Button>

                  {fotoPreview && (
                    <div className="flex items-center gap-2">
                      <img
                        src={fotoPreview}
                        alt="Preview"
                        className="w-9 h-9 object-cover rounded-lg border border-[#D4AF37]/40 shadow-sm"
                      />
                      <button
                        type="button"
                        onClick={handleRemoverFoto}
                        className="text-red-600 hover:text-red-700 font-semibold text-[11px] underline"
                      >
                        Remover
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* SEÇÃO 4: ENSAIOS DIGITAIS NO FINAL DO FORMULÁRIO (FOCO PRIMÁRIO NOS CONVITES) */}
              <div className="p-4 rounded-2xl bg-gradient-to-br from-[#faf4ec] to-[#f4e6d7] border border-[#D4AF37]/40 shadow-sm space-y-3">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <Camera className="w-4 h-4 text-[#D4AF37]" />
                    <h3 className="font-serif font-bold text-sm text-[#4B2E20]">
                      Deseja adicionar um Ensaio Digital? (Opcional)
                    </h3>
                  </div>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={querEnsaioDigital}
                      onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                      className="sr-only peer"
                    />
                    <div className="w-9 h-5 bg-stone-300 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-stone-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-[#4B2E20]"></div>
                  </label>
                </div>

                <p className="text-[11px] text-[#4B2E20]/80 leading-relaxed">
                  Criamos uma foto digital personalizada temática incrível para colocar na arte do seu convite! Transformamos a foto comum em um cenário profissional dos sonhos.
                </p>

                {/* Se marcar a opção, mostra os exemplos de ensaio */}
                {querEnsaioDigital && (
                  <div className="pt-2 space-y-2.5 animate-fade-in">
                    <span className="text-[11px] font-bold text-[#4B2E20] block">
                      Escolha o Estilo do Ensaio Digital (+ R$ 25,00):
                    </span>

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                      {EXEMPLOS_ENSAIOS_DIGITAIS.map((ex) => (
                        <div
                          key={ex.id}
                          onClick={() => setEnsaioEscolhido(ex.titulo)}
                          className={`cursor-pointer rounded-xl border p-1.5 transition-all flex flex-col justify-between ${
                            ensaioEscolhido === ex.titulo
                              ? 'border-[#4B2E20] bg-white shadow-md ring-2 ring-[#D4AF37]'
                              : 'border-[#D4AF37]/30 bg-white/70 hover:border-[#D4AF37]'
                          }`}
                        >
                          <img
                            src={ex.foto}
                            alt={ex.titulo}
                            className="w-full h-16 object-cover rounded-lg mb-1.5"
                          />
                          <p className="font-serif font-bold text-[10px] text-[#4B2E20] truncate">
                            {ex.titulo}
                          </p>
                          <span className="text-[9px] text-[#855729] truncate block">
                            {ex.subtitulo}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* RESUMO DE VALOR E BOTÃO DE AVANÇAR */}
              <div className="pt-3 border-t border-[#D4AF37]/25 flex flex-col sm:flex-row items-center justify-between gap-3">
                <div>
                  <span className="text-[11px] text-[#4B2E20]/70 block">Total a Pagar</span>
                  <div className="flex items-baseline gap-2">
                    <span className="text-xl font-serif font-bold text-[#4B2E20]">
                      R$ {valorTotalFinal.toFixed(2)}
                    </span>
                    {querEnsaioDigital && (
                      <span className="text-[10px] text-[#855729] font-medium">
                        (Convite R$ {template.price.toFixed(2)} + Ensaio R$ 25,00)
                      </span>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-2 w-full sm:w-auto">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={handleFecharModal}
                    className="text-[#4B2E20] text-xs rounded-xl"
                  >
                    Cancelar
                  </Button>
                  <Button
                    type="submit"
                    className="flex-1 sm:flex-none bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-md flex items-center justify-center gap-2 px-5 py-2.5"
                  >
                    <span>Ir para o Pagamento via PIX</span>
                    <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                  </Button>
                </div>
              </div>

            </form>
          )}

          {/* ======================= TELA 2: PAGAMENTO VIA PIX ======================= */}
          {etapa === 'pagamento_pix' && (
            <div className="space-y-6 animate-fade-in">

              {/* Resumo do Pedido */}
              <div className="p-4 bg-white rounded-2xl border border-[#D4AF37]/35 shadow-sm space-y-3">
                <div className="flex items-center justify-between border-b border-[#D4AF37]/20 pb-2">
                  <span className="font-serif font-bold text-sm text-[#4B2E20]">
                    Resumo do Pedido
                  </span>
                  <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-[#ecdccb] text-[#4B2E20]">
                    Keh Convites
                  </span>
                </div>

                <div className="grid grid-cols-2 gap-2 text-xs">
                  <div>
                    <span className="text-[#4B2E20]/60 block text-[11px]">Homenageado(a)</span>
                    <span className="font-bold text-[#4B2E20]">{nomeAniversariante}</span>
                  </div>
                  <div>
                    <span className="text-[#4B2E20]/60 block text-[11px]">Tema</span>
                    <span className="font-bold text-[#4B2E20]">{temaFesta || 'A definir'}</span>
                  </div>
                  <div>
                    <span className="text-[#4B2E20]/60 block text-[11px]">Modelo</span>
                    <span className="font-medium text-[#4B2E20]">{template.title}</span>
                  </div>
                  <div>
                    <span className="text-[#4B2E20]/60 block text-[11px]">Formato</span>
                    <span className="font-medium text-[#4B2E20]">
                      {temInteracao ? 'Interativo com Botões' : 'Simples (Card)'}
                    </span>
                  </div>
                  {querEnsaioDigital && (
                    <div className="col-span-2 text-[11px] bg-amber-50 p-2 rounded-lg border border-[#D4AF37]/30 text-[#4B2E20]">
                      ✨ <strong>Ensaio Digital Incluso:</strong> {ensaioEscolhido} (+ R$ 25,00)
                    </div>
                  )}
                </div>

                <div className="pt-2 border-t border-[#D4AF37]/20 flex items-center justify-between">
                  <span className="text-xs font-semibold text-[#4B2E20]">Valor Total do Pedido:</span>
                  <span className="text-xl font-serif font-bold text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>
              </div>

              {/* Caixa Principal de Pagamento PIX */}
              <div className="p-5 bg-gradient-to-br from-[#faf3eb] to-[#f4e7d7] rounded-3xl border-2 border-[#D4AF37]/60 shadow-md text-center space-y-4">
                <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#4B2E20] text-[#D4AF37] text-xs font-bold shadow-sm">
                  <ShieldCheck className="w-3.5 h-3.5" />
                  <span>Pagamento Seguro via PIX</span>
                </div>

                <div>
                  <h3 className="font-serif font-bold text-lg text-[#4B2E20]">
                    Pague agora via Chave PIX
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75 mt-0.5">
                    Copie a chave PIX abaixo no aplicativo do seu banco:
                  </p>
                </div>

                {/* Chave PIX com Botão de Copiar */}
                <div className="bg-white p-3 rounded-2xl border border-[#D4AF37]/50 shadow-sm flex items-center justify-between gap-2 max-w-md mx-auto">
                  <div className="text-left pl-2">
                    <span className="text-[10px] text-[#4B2E20]/60 block uppercase font-bold tracking-wider">
                      Chave PIX (Telefone)
                    </span>
                    <span className="font-mono text-base font-bold text-[#4B2E20] select-all">
                      {CHAVE_PIX_KEH}
                    </span>
                  </div>

                  <Button
                    type="button"
                    onClick={handleCopiarPix}
                    className={`rounded-xl text-xs font-bold shadow-sm transition-all flex items-center gap-1.5 px-4 py-2 ${
                      pixCopiado
                        ? 'bg-emerald-600 hover:bg-emerald-700 text-white'
                        : 'bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD]'
                    }`}
                  >
                    {pixCopiado ? (
                      <>
                        <CheckCheck className="w-4 h-4 text-emerald-200" />
                        <span>Chave Copiada!</span>
                      </>
                    ) : (
                      <>
                        <Copy className="w-4 h-4 text-[#D4AF37]" />
                        <span>Copiar Chave</span>
                      </>
                    )}
                  </Button>
                </div>

                {/* Passo a passo rápido */}
                <div className="text-left bg-white/70 p-3.5 rounded-xl border border-[#D4AF37]/30 space-y-1.5 text-[11px] text-[#4B2E20]/85">
                  <p className="font-bold text-[#4B2E20] mb-1">Como pagar:</p>
                  <p>1. Abra o app do seu banco e escolha <strong>PIX</strong>.</p>
                  <p>2. Selecione <strong>Transferir / Pagar com Chave Celular</strong>.</p>
                  <p>3. Cole a chave <strong>{CHAVE_PIX_KEH}</strong> e digite o valor <strong>R$ {valorTotalFinal.toFixed(2)}</strong>.</p>
                  <p>4. Após pagar, clique no botão <strong>"Confirmar Pedido Realizado"</strong> abaixo.</p>
                </div>
              </div>

              {/* Botões de Ação */}
              <div className="pt-2 flex flex-col sm:flex-row items-center justify-between gap-3">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setEtapa('formulario')}
                  className="text-[#4B2E20] text-xs rounded-xl flex items-center gap-1.5"
                >
                  <ArrowLeft className="w-3.5 h-3.5" />
                  <span>Voltar e Editar Dados</span>
                </Button>

                <Button
                  type="button"
                  onClick={handleFinalizarPedido}
                  className="w-full sm:w-auto bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs rounded-xl shadow-lg flex items-center justify-center gap-2 px-6 py-3"
                >
                  <CheckCircle2 className="w-4 h-4 text-emerald-200" />
                  <span>Confirmar Pedido Realizado</span>
                </Button>
              </div>

            </div>
          )}

          {/* ======================= TELA 3: CONFIRMAÇÃO DE SUCESSO ======================= */}
          {etapa === 'concluido' && (
            <div className="py-6 text-center space-y-4 animate-fade-in">
              <div className="w-16 h-16 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto shadow-md border-2 border-emerald-300">
                <CheckCircle2 className="w-9 h-9" />
              </div>

              <div className="space-y-1">
                <h3 className="font-serif font-bold text-xl text-[#4B2E20]">
                  Pedido Registrado com Sucesso!
                </h3>
                <p className="text-xs text-[#4B2E20]/80 max-w-md mx-auto">
                  Recebemos todos os dados do convite de <strong>{nomeAniversariante}</strong>.
                </p>
              </div>

              <div className="p-4 bg-[#ecdccb]/40 rounded-2xl border border-[#D4AF37]/40 max-w-md mx-auto text-left text-xs space-y-2">
                <p className="font-bold text-[#4B2E20] flex items-center gap-1.5">
                  <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                  <span>Próximos Passos:</span>
                </p>
                <p className="text-[#4B2E20]/80">
                  • Vamos iniciar a produção personalizada do seu convite.
                </p>
                <p className="text-[#4B2E20]/80">
                  • A prévia será enviada diretamente no seu WhatsApp: <strong>{whatsappCliente}</strong>.
                </p>
                <p className="text-[#4B2E20]/80">
                  • Chave PIX utilizada: <strong>{CHAVE_PIX_KEH}</strong>.
                </p>
              </div>

              <div className="pt-2">
                <Button
                  type="button"
                  onClick={handleFecharModal}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl px-8 py-2.5 shadow-md"
                >
                  Fechar Janela
                </Button>
              </div>
            </div>
          )}

        </CardContent>
      </Card>
    </div>
  );
}

