import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  Phone,
  Camera,
  CheckCircle2,
  QrCode,
  Copy,
  ArrowRight,
  ArrowLeft,
  ShieldCheck,
  CheckCheck,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala e Castelo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol e Cenário Floral',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake e Balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
  },
];

const CHAVE_PIX_KEH = '32998040080';

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  const [etapa, setEtapa] = useState<'formulario' | 'pagamento_pix' | 'concluido'>('formulario');

  // Campos do formulário
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos para modelo com botões
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Foto
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Ensaio Digital Opcional
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);

  // Estado de cópia do PIX
  const [pixCopiado, setPixCopiado] = useState(false);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCopiarPix = () => {
    navigator.clipboard.writeText(CHAVE_PIX_KEH);
    setPixCopiado(true);
    setTimeout(() => setPixCopiado(false), 3000);
  };

  // Ao clicar em Ir para Pagamento
  const handleAvancarParaPix = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante ou homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o número de WhatsApp para contato.');
      return;
    }

    // Registra imediatamente o pedido na base administrativa como pendente de conferência PIX
    const notasFormatadas = [
      'Pedido feito pelo Catálogo Online',
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples (sem botões)',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
      `PIX Keh Convites: R$ ${valorTotalFinal.toFixed(2)} (Chave: ${CHAVE_PIX_KEH})`,
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: valorTotalFinal,
      eventDate: dataEvento || new Date().toISOString().split('T')[0],
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pago',
      includeDigitalPhotoshoot: querEnsaioDigital,
      photoshootDetails: querEnsaioDigital ? ensaioEscolhido : undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);
    setEtapa('pagamento_pix');
  };

  const handleConcluirEFechar = () => {
    setEtapa('formulario');
    setPixCopiado(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">

        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/80 to-[#f7ebdd]/80 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] border border-[#D4AF37]/50 flex items-center justify-center text-[#D4AF37] shadow-sm">
              {etapa === 'pagamento_pix' ? (
                <QrCode className="w-5 h-5" />
              ) : etapa === 'concluido' ? (
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
              ) : (
                <Sparkles className="w-5 h-5" />
              )}
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                {etapa === 'pagamento_pix'
                  ? 'Pagamento via PIX'
                  : etapa === 'concluido'
                  ? 'Pedido Confirmado com Sucesso!'
                  : 'Personalize seu Convite Digital'}
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                {etapa === 'pagamento_pix'
                  ? 'Efetue a transferência para iniciarmos a produção'
                  : etapa === 'concluido'
                  ? 'Recebido na Área Administrativa com sucesso'
                  : `Modelo: ${template.title}`}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Conteúdo Dinâmico */}
        <CardContent className="overflow-y-auto p-4 sm:p-6 space-y-6 flex-1 text-xs text-[#4B2E20]">

          {/* TELA 1: FORMULÁRIO DE DADOS */}
          {etapa === 'formulario' && (
            <form id="form-convite" onSubmit={handleAvancarParaPix} className="space-y-6">

              {/* Resumo do Convite Selecionado */}
              <div className="flex items-center gap-4 p-3.5 bg-[#ecdccb]/50 border border-[#D4AF37]/40 rounded-2xl">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-14 h-14 rounded-xl object-cover border border-[#D4AF37]/50 shadow-sm"
                />
                <div className="flex-1">
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20]">{template.title}</h4>
                  <p className="text-[11px] text-[#4B2E20]/75">
                    {temInteracao ? 'Convite Digital com Botões Interativos' : 'Convite Digital Card'}
                  </p>
                </div>
                <div className="text-right">
                  <span className="text-[10px] text-[#4B2E20]/70 font-semibold block">Valor do Convite</span>
                  <span className="text-base font-serif font-bold text-[#4B2E20]">
                    R$ {template.price.toFixed(2)}
                  </span>
                </div>
              </div>

              {/* Informações Principais da Festa */}
              <div className="space-y-3 bg-white/70 p-4 rounded-2xl border border-[#D4AF37]/30">
                <h5 className="font-serif font-bold text-xs uppercase tracking-wider text-[#4B2E20] border-b border-[#D4AF37]/20 pb-1.5">
                  1. Dados Principais do Convite
                </h5>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold mb-1">Nome do Aniversariante / Homenageado *</label>
                    <Input
                      required
                      placeholder="Ex: Sophia (Faz 5 Anos)"
                      value={nomeAniversariante}
                      onChange={(e) => setNomeAniversariante(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1">Tema da Festa / Decoração</label>
                    <Input
                      placeholder="Ex: Bosque Encantado, Circo, Safari..."
                      value={temaFesta}
                      onChange={(e) => setTemaFesta(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <label className="block font-semibold mb-1 flex items-center gap-1">
                      <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" /> Data do Evento
                    </label>
                    <Input
                      type="date"
                      value={dataEvento}
                      onChange={(e) => setDataEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1">Dia da Semana</label>
                    <Input
                      placeholder="Ex: Sábado, Domingo"
                      value={diaSemana}
                      onChange={(e) => setDiaSemana(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 flex items-center gap-1">
                      <Clock className="w-3.5 h-3.5 text-[#D4AF37]" /> Horário
                    </label>
                    <Input
                      placeholder="Ex: Às 18:00h"
                      value={horarioEvento}
                      onChange={(e) => setHorarioEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold mb-1 flex items-center gap-1">
                      <MapPin className="w-3.5 h-3.5 text-[#D4AF37]" /> Local / Endereço da Festa
                    </label>
                    <Input
                      placeholder="Ex: Buffet Algodão Doce - Rua das Flores, 120"
                      value={localEvento}
                      onChange={(e) => setLocalEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold mb-1 flex items-center gap-1">
                      <Phone className="w-3.5 h-3.5 text-[#D4AF37]" /> Seu WhatsApp para Receber a Prévia *
                    </label>
                    <Input
                      required
                      placeholder="Ex: (32) 99999-8888"
                      value={whatsappCliente}
                      onChange={(e) => setWhatsappCliente(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 rounded-xl"
                    />
                  </div>
                </div>

                <div>
                  <label className="block font-semibold mb-1 flex items-center gap-1">
                    <Heart className="w-3.5 h-3.5 text-[#D4AF37]" /> Frase Especial / Bíblica (Opcional)
                  </label>
                  <Input
                    placeholder='Ex: "Venha comemorar comigo esse dia tão especial!"'
                    value={fraseEspecial}
                    onChange={(e) => setFraseEspecial(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 rounded-xl"
                  />
                </div>
              </div>

              {/* Botões Clicáveis (Apenas se for Interativo) */}
              {temInteracao && (
                <div className="space-y-3 bg-[#fdf8f0] p-4 rounded-2xl border border-[#D4AF37]/40">
                  <div className="flex items-center justify-between border-b border-[#D4AF37]/20 pb-1.5">
                    <h5 className="font-serif font-bold text-xs uppercase tracking-wider text-[#4B2E20] flex items-center gap-1.5">
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      2. Botões Clicáveis do Convite
                    </h5>
                    <span className="text-[10px] bg-[#D4AF37]/25 text-[#4B2E20] px-2 py-0.5 rounded-full font-semibold">
                      Interativo
                    </span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div>
                      <label className="block font-semibold mb-1">WhatsApp para Confirmar Presença</label>
                      <Input
                        placeholder="Ex: (32) 99999-0000"
                        value={confirmacaoPresenca}
                        onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 rounded-xl"
                      />
                    </div>

                    <div>
                      <label className="block font-semibold mb-1">Link do Google Maps (Local)</label>
                      <Input
                        placeholder="Link ou nome do buffet"
                        value={linkLocalizacao}
                        onChange={(e) => setLinkLocalizacao(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 rounded-xl"
                      />
                    </div>

                    <div>
                      <label className="block font-semibold mb-1 flex items-center gap-1">
                        <Gift className="w-3 h-3 text-[#D4AF37]" /> Link da Lista de Presentes
                      </label>
                      <Input
                        placeholder="Site ou sugestão de presente"
                        value={listaPresentes}
                        onChange={(e) => setListaPresentes(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 rounded-xl"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* Foto do Aniversariante */}
              <div className="space-y-2 bg-white/70 p-4 rounded-2xl border border-[#D4AF37]/30">
                <h5 className="font-serif font-bold text-xs uppercase tracking-wider text-[#4B2E20] border-b border-[#D4AF37]/20 pb-1.5 flex items-center gap-1.5">
                  <Upload className="w-3.5 h-3.5 text-[#D4AF37]" /> Foto para o Convite (Opcional)
                </h5>

                <div className="flex flex-col sm:flex-row items-center gap-4">
                  {fotoPreview ? (
                    <div className="relative group shrink-0">
                      <img
                        src={fotoPreview}
                        alt="Foto escolhida"
                        className="w-20 h-20 object-cover rounded-2xl border-2 border-[#D4AF37]"
                      />
                      <button
                        type="button"
                        onClick={handleRemoverFoto}
                        className="absolute -top-2 -right-2 bg-red-600 text-white rounded-full p-1 shadow hover:bg-red-700"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  ) : null}

                  <div className="flex-1 w-full">
                    <input
                      type="file"
                      ref={fileInputRef}
                      accept="image/*"
                      onChange={handleFotoChange}
                      className="hidden"
                      id="upload-foto-convite"
                    />
                    <label
                      htmlFor="upload-foto-convite"
                      className="flex items-center justify-center gap-2 w-full p-3 border-2 border-dashed border-[#D4AF37]/50 rounded-2xl cursor-pointer hover:bg-[#ecdccb]/30 transition-all text-[#4B2E20] font-medium"
                    >
                      <Upload className="w-4 h-4 text-[#D4AF37]" />
                      <span>{fotoFile ? 'Trocar foto selecionada' : 'Clique para enviar a foto da criança/casal'}</span>
                    </label>
                  </div>
                </div>
              </div>

              {/* Seção no final: Adicionar Ensaio Digital Opcional */}
              <div className="space-y-3 bg-gradient-to-br from-[#ecdccb]/50 to-[#fdf8f0] p-4 rounded-2xl border border-[#D4AF37]/45">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center">
                      <Camera className="w-4 h-4" />
                    </div>
                    <div>
                      <h5 className="font-serif font-bold text-sm text-[#4B2E20]">
                        Deseja incluir um Ensaio Digital?
                      </h5>
                      <p className="text-[11px] text-[#4B2E20]/75">
                        Transformamos a foto comum em um cenário profissional com IA (+ R$ 25,00)
                      </p>
                    </div>
                  </div>

                  <input
                    type="checkbox"
                    id="checkEnsaio"
                    checked={querEnsaioDigital}
                    onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                    className="w-5 h-5 rounded accent-[#4B2E20] cursor-pointer mt-1"
                  />
                </div>

                {querEnsaioDigital && (
                  <div className="pt-2 border-t border-[#D4AF37]/20 space-y-2.5">
                    <p className="text-[11px] font-semibold text-[#4B2E20]">
                      Selecione o estilo do ensaio digital desejado:
                    </p>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                      {EXEMPLOS_ENSAIOS_DIGITAIS.map((ensaio) => (
                        <div
                          key={ensaio.id}
                          onClick={() => setEnsaioEscolhido(ensaio.titulo)}
                          className={`p-2 rounded-xl border text-center cursor-pointer transition-all ${
                            ensaioEscolhido === ensaio.titulo
                              ? 'border-[#4B2E20] bg-white shadow-md ring-2 ring-[#D4AF37]'
                              : 'border-[#D4AF37]/30 bg-white/60 hover:bg-white'
                          }`}
                        >
                          <img
                            src={ensaio.foto}
                            alt={ensaio.titulo}
                            className="w-full h-16 object-cover rounded-lg mb-1"
                          />
                          <p className="text-[10px] font-bold text-[#4B2E20] truncate">{ensaio.titulo}</p>
                          <span className="text-[9px] text-[#4B2E20]/70">+ R$ 25,00</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Totalizador */}
              <div className="flex items-center justify-between p-4 bg-[#4B2E20] text-[#F7EBDD] rounded-2xl shadow-md">
                <div>
                  <span className="text-xs text-[#D4AF37] font-semibold block">Total do Pedido</span>
                  <span className="text-xs text-[#F7EBDD]/80">
                    {template.title} {querEnsaioDigital && '+ Ensaio Digital'}
                  </span>
                </div>
                <div className="text-right">
                  <span className="text-2xl font-serif font-black text-[#D4AF37]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>
              </div>

              <div className="pt-1 flex items-center justify-end gap-3">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onClose}
                  className="text-[#4B2E20] text-xs rounded-xl"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs sm:text-sm px-6 py-2.5 rounded-xl border border-[#D4AF37]/50 shadow-md flex items-center gap-2"
                >
                  <span>Continuar para Pagamento PIX</span>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                </Button>
              </div>

            </form>
          )}

          {/* TELA 2: OPÇÃO DE PAGAMENTO PIX (Chave 32998040080) */}
          {etapa === 'pagamento_pix' && (
            <div className="space-y-6 animate-fade-in text-center">

              <div className="p-4 bg-emerald-50 border border-emerald-300 rounded-2xl text-emerald-900 text-xs">
                <div className="flex items-center justify-center gap-2 font-bold mb-1">
                  <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                  <span>Pedido registrado na Área Administrativa com sucesso!</span>
                </div>
                <p className="text-[11px] text-emerald-800">
                  Agora faça a transferência do valor via PIX para iniciarmos a montagem do convite.
                </p>
              </div>

              {/* Caixa com o valor e a chave PIX */}
              <div className="p-6 bg-white border border-[#D4AF37]/50 rounded-3xl shadow-sm max-w-md mx-auto space-y-4">
                <div className="w-14 h-14 rounded-2xl bg-[#4B2E20] text-[#D4AF37] flex items-center justify-center mx-auto shadow-md">
                  <QrCode className="w-8 h-8" />
                </div>

                <div>
                  <span className="text-xs text-[#4B2E20]/75 uppercase font-semibold">Valor Total a Pagar</span>
                  <div className="text-3xl font-serif font-black text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </div>
                </div>

                <div className="p-3.5 bg-[#fdfbf7] border border-[#D4AF37]/40 rounded-2xl text-left space-y-1">
                  <span className="text-[10px] font-bold uppercase text-[#4B2E20]/70">Chave PIX (Telefone):</span>
                  <div className="flex items-center justify-between gap-2">
                    <span className="font-mono font-bold text-base text-[#4B2E20] tracking-wider select-all">
                      {CHAVE_PIX_KEH}
                    </span>
                    <Button
                      type="button"
                      size="sm"
                      onClick={handleCopiarPix}
                      className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl flex items-center gap-1.5 px-3 py-1.5 shrink-0"
                    >
                      {pixCopiado ? (
                        <>
                          <CheckCheck className="w-3.5 h-3.5 text-emerald-400" />
                          <span>Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy className="w-3.5 h-3.5 text-[#D4AF37]" />
                          <span>Copiar Chave</span>
                        </>
                      )}
                    </Button>
                  </div>
                  <span className="text-[10px] text-[#4B2E20]/70 block pt-1">
                    Titular: Keila Souza / Keh Convites
                  </span>
                </div>

                <div className="p-3 bg-amber-50 rounded-xl border border-amber-200 text-left text-[11px] text-amber-900 space-y-1">
                  <div className="flex items-center gap-1.5 font-bold">
                    <ShieldCheck className="w-4 h-4 text-amber-700 shrink-0" />
                    <span>Como funciona a entrega:</span>
                  </div>
                  <p className="text-[10px] leading-relaxed text-amber-800">
                    Após realizar o PIX, a Keh Convites já tem todos os seus dados e iniciará a personalização. A prévia em alta definição será enviada diretamente no seu WhatsApp: <strong>{whatsappCliente}</strong>.
                  </p>
                </div>
              </div>

              <div className="flex items-center justify-center gap-3 pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setEtapa('formulario')}
                  className="border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl flex items-center gap-1.5"
                >
                  <ArrowLeft className="w-3.5 h-3.5" />
                  <span>Voltar aos Dados</span>
                </Button>
                <Button
                  type="button"
                  onClick={() => setEtapa('concluido')}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl px-5 py-2.5 border border-[#D4AF37]/50 shadow flex items-center gap-2"
                >
                  <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                  <span>Já Efetuei o PIX</span>
                </Button>
              </div>

            </div>
          )}

          {/* TELA 3: TELA FINAL DE CONFIRMAÇÃO */}
          {etapa === 'concluido' && (
            <div className="space-y-6 text-center py-6 animate-fade-in">
              <div className="w-16 h-16 rounded-3xl bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto shadow-md">
                <CheckCircle2 className="w-10 h-10" />
              </div>

              <div className="space-y-2">
                <h3 className="font-serif font-black text-2xl text-[#4B2E20]">
                  Muito Obrigada pela Confiança! ✨
                </h3>
                <p className="text-xs text-[#4B2E20]/80 max-w-md mx-auto leading-relaxed">
                  Seu pedido para o anfitrião <strong>{nomeAniversariante}</strong> foi recebido com sucesso na nossa produção.
                </p>
              </div>

              <div className="p-4 bg-white border border-[#D4AF37]/40 rounded-2xl max-w-md mx-auto text-left text-xs space-y-1.5">
                <p className="font-bold text-[#4B2E20]">📋 Resumo do Pedido:</p>
                <p className="text-[#4B2E20]/80"><strong>Convite:</strong> {template.title}</p>
                {temaFesta && <p className="text-[#4B2E20]/80"><strong>Tema:</strong> {temaFesta}</p>}
                <p className="text-[#4B2E20]/80"><strong>Contato:</strong> {whatsappCliente}</p>
                <p className="text-[#4B2E20]/80"><strong>Valor Total:</strong> R$ {valorTotalFinal.toFixed(2)}</p>
              </div>

              <div className="pt-2">
                <Button
                  type="button"
                  onClick={handleConcluirEFechar}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-sm px-8 py-3 rounded-xl border border-[#D4AF37]/50 shadow-md"
                >
                  Concluir e Voltar aos Modelos
                </Button>
              </div>
            </div>
          )}

        </CardContent>
      </Card>
    </div>
  );
}

