import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Sparkles,
  Heart,
  Smartphone,
  Eye,
  CheckCircle2,
  Calendar,
  Share2,
  SlidersHorizontal,
  Send,
  Camera,
  Layers,
  Star,
} from 'lucide-react';
import { ClientOrderModal } from '@/components/ClientOrderModal';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOpenNewOrderModal?: (template: InvitationTemplate) => void;
  isAdmin?: boolean;
}

const CATEGORIES: { label: string; value: 'all' | InvitationCategory }[] = [
  { label: 'Todos os Convites', value: 'all' },
  { label: 'Infantil', value: 'Infantil' },
  { label: '15 Anos', value: '15 Anos' },
  { label: 'Casamento', value: 'Casamento' },
  { label: 'Batizado', value: 'Batizado' },
  { label: 'Bodas', value: 'Bodas' },
  { label: 'Corporativo', value: 'Corporativo' },
];

const FORMAT_BADGES: Record<DigitalFormat, { label: string; bg: string; text: string }> = {
  imagem_card: { label: 'Convite Simples', bg: 'bg-[#ebdccb]', text: 'text-[#4B2E20]' },
  interativo_pdf: { label: 'Interativo com Botões', bg: 'bg-[#D4AF37]/25', text: 'text-[#4B2E20]' },
  animado_video: { label: 'Vídeo Animado', bg: 'bg-[#4B2E20]/15', text: 'text-[#4B2E20]' },
  save_the_date: { label: 'Save The Date', bg: 'bg-[#edd9c0]', text: 'text-[#4B2E20]' },
  kit_digital: { label: 'Kit Digital Completo', bg: 'bg-[#D4AF37]/35', text: 'text-[#4B2E20]' },
  site_rsvp: { label: 'Site / Página Interativa', bg: 'bg-[#4B2E20]/20', text: 'text-[#4B2E20]' },
};

export const EXEMPLOS_ENSAIOS_CATALOGO = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque Encantado ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
    descricao: 'Transformamos uma foto do seu filho(a) em um ensaio fotográfico no tema da festa.',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Realeza & Princesa',
    subtitulo: 'Vestidos de Gala e Castelo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
    descricao: 'Visual dos sonhos com coroa, brilho e cenário real para convites de 15 Anos e Meninas.',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal & Pré-Wedding',
    subtitulo: 'Pôr do Sol, Flores e Elegância',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
    descricao: 'Fotos artísticas digitais do casal em harmonia perfeita com a paleta do casamento.',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash the Cake e Balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
    descricao: 'Cenários fofos com bolo temático e iluminação de estúdio profissional.',
  },
];

export function TemplatesCatalog({ templates, onOpenNewOrderModal, isAdmin }: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<'all' | InvitationCategory>('all');
  const [formatFilter, setFormatFilter] = useState<'all' | 'simples' | 'interativo'>('all');
  const [orderModalOpen, setOrderModalOpen] = useState(false);
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  // Filtragem dos convites
  const filteredTemplates = templates.filter((tpl) => {
    const matchCategory = selectedCategory === 'all' || tpl.category === selectedCategory;
    let matchFormat = true;
    if (formatFilter === 'simples') {
      matchFormat = !tpl.hasInteraction && tpl.format !== 'interativo_pdf' && tpl.format !== 'site_rsvp';
    } else if (formatFilter === 'interativo') {
      matchFormat = Boolean(tpl.hasInteraction || tpl.format === 'interativo_pdf' || tpl.format === 'site_rsvp');
    }
    return matchCategory && matchFormat;
  });

  const handleChooseTemplate = (template: InvitationTemplate) => {
    setSelectedTemplateForOrder(template);
    setOrderModalOpen(true);
  };

  return (
    <div className="space-y-12 pb-16">

      {/* 1. SEÇÃO DE APRESENTAÇÃO - FOCO TOTAL NOS CONVITES DIGITAIS */}
      <section className="relative overflow-hidden rounded-3xl bg-gradient-to-b from-[#fcf8f3] via-[#f7ebdd]/60 to-[#fcf8f3] border border-[#D4AF37]/35 p-6 sm:p-10 text-center shadow-sm">
        <div className="max-w-2xl mx-auto space-y-4">
          <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-[#ebdccb]/70 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold tracking-wide">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Ateliê de Convites 100% Digitais</span>
          </div>

          <h1 className="text-3xl sm:text-4xl lg:text-5xl font-serif font-bold text-[#4B2E20] leading-tight">
            Convites Digitais Delicados & Personalizados
          </h1>

          <p className="text-sm sm:text-base text-[#4B2E20]/80 font-normal leading-relaxed">
            Envie com carinho pelo WhatsApp. Escolha o seu modelo favorito abaixo, preencha os dados da sua celebração e receba prontinho para compartilhar com seus convidados.
          </p>

          <div className="pt-2 flex flex-wrap items-center justify-center gap-3 sm:gap-6 text-xs text-[#4B2E20]/90 font-medium">
            <div className="flex items-center gap-1.5">
              <CheckCircle2 className="w-4 h-4 text-[#D4AF37]" />
              <span>Envio Imediato via WhatsApp</span>
            </div>
            <div className="flex items-center gap-1.5">
              <CheckCircle2 className="w-4 h-4 text-[#D4AF37]" />
              <span>Modelos Simples ou Interativos</span>
            </div>
            <div className="flex items-center gap-1.5">
              <CheckCircle2 className="w-4 h-4 text-[#D4AF37]" />
              <span>Sem custo de frete</span>
            </div>
          </div>
        </div>
      </section>

      {/* 2. FILTROS RÁPIDOS DE CONVITES */}
      <section className="space-y-4">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          {/* Categorias por Ocasião */}
          <div className="flex items-center gap-1.5 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-none">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.value}
                onClick={() => setSelectedCategory(cat.value)}
                className={`px-4 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all border ${
                  selectedCategory === cat.value
                    ? 'bg-[#4B2E20] text-[#F7EBDD] border-[#4B2E20] shadow-sm'
                    : 'bg-white/80 text-[#4B2E20]/80 border-[#D4AF37]/30 hover:border-[#D4AF37] hover:bg-[#F7EBDD]/40'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>

          {/* Filtro por tipo de convite */}
          <div className="flex items-center gap-1 bg-[#ebdccb]/60 p-1 rounded-xl border border-[#D4AF37]/30 self-stretch md:self-auto justify-center">
            <button
              onClick={() => setFormatFilter('all')}
              className={`px-3 py-1.5 text-[11px] font-semibold rounded-lg transition-all ${
                formatFilter === 'all'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-xs'
                  : 'text-[#4B2E20]/75 hover:text-[#4B2E20]'
              }`}
            >
              Todos ({templates.length})
            </button>
            <button
              onClick={() => setFormatFilter('simples')}
              className={`px-3 py-1.5 text-[11px] font-semibold rounded-lg transition-all ${
                formatFilter === 'simples'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-xs'
                  : 'text-[#4B2E20]/75 hover:text-[#4B2E20]'
              }`}
            >
              Simples (Card Foto)
            </button>
            <button
              onClick={() => setFormatFilter('interativo')}
              className={`px-3 py-1.5 text-[11px] font-semibold rounded-lg transition-all ${
                formatFilter === 'interativo'
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-xs'
                  : 'text-[#4B2E20]/75 hover:text-[#4B2E20]'
              }`}
            >
              Interativos (com Botões)
            </button>
          </div>
        </div>

        {/* 3. VITRINE PRINCIPAL DE CONVITES DIGITAIS */}
        {filteredTemplates.length === 0 ? (
          <div className="text-center py-16 bg-white/60 border border-[#D4AF37]/30 rounded-3xl p-8">
            <Smartphone className="w-10 h-10 text-[#D4AF37] mx-auto mb-3 opacity-60" />
            <h3 className="text-lg font-serif font-bold text-[#4B2E20]">Nenhum convite encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70 mt-1">
              Tente selecionar outra categoria ou tipo de convite acima.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-6 pt-2">
            {filteredTemplates.map((template) => {
              const badgeInfo = FORMAT_BADGES[template.format] || {
                label: template.hasInteraction ? 'Interativo' : 'Convite Simples',
                bg: 'bg-[#ebdccb]',
                text: 'text-[#4B2E20]',
              };

              const temBotoes = Boolean(
                template.hasInteraction ||
                template.format === 'interativo_pdf' ||
                template.format === 'site_rsvp'
              );

              return (
                <Card
                  key={template.id}
                  className="group flex flex-col justify-between overflow-hidden bg-white border border-[#D4AF37]/35 rounded-3xl shadow-sm hover:shadow-md hover:border-[#D4AF37] transition-all duration-300"
                >
                  <div className="p-4 space-y-3.5">
                    {/* Imagem do Convite */}
                    <div className="relative aspect-[4/5] rounded-2xl overflow-hidden bg-[#faf5ee] border border-[#D4AF37]/20">
                      <img
                        src={template.imageUrl}
                        alt={template.title}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                      />

                      {/* Tag Formato */}
                      <div className="absolute top-3 left-3 flex flex-col gap-1.5 items-start">
                        <span
                          className={`px-3 py-1 rounded-full text-[10px] font-bold tracking-wide uppercase backdrop-blur-md shadow-xs ${badgeInfo.bg} ${badgeInfo.text} border border-[#D4AF37]/30`}
                        >
                          {badgeInfo.label}
                        </span>
                        <span className="px-2.5 py-0.5 rounded-full text-[9px] font-semibold bg-[#4B2E20]/80 text-[#F7EBDD] backdrop-blur-md">
                          {template.category}
                        </span>
                      </div>

                      {/* Aviso de Botões / Simples */}
                      <div className="absolute bottom-3 inset-x-3">
                        <div className="px-3 py-1.5 rounded-xl bg-white/95 backdrop-blur-md border border-[#D4AF37]/40 text-[#4B2E20] text-[11px] font-medium flex items-center justify-between shadow-xs">
                          <span className="flex items-center gap-1.5">
                            <Smartphone className="w-3.5 h-3.5 text-[#D4AF37]" />
                            {temBotoes ? 'Com botões clicáveis' : 'Card digital simples (sem botões)'}
                          </span>
                          <span className="font-bold text-[#4B2E20]">
                            R$ {template.price.toFixed(2)}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Descrição e Título */}
                    <div className="space-y-1.5">
                      <h3 className="font-serif font-bold text-base text-[#4B2E20] line-clamp-1">
                        {template.title}
                      </h3>
                      <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                        {template.description || 'Convite digital exclusivo para WhatsApp com design refinado e personalizado.'}
                      </p>
                    </div>

                    {/* Tags */}
                    {template.tags && template.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1 pt-1">
                        {template.tags.slice(0, 3).map((tag, idx) => (
                          <span
                            key={idx}
                            className="text-[10px] px-2 py-0.5 rounded-md bg-[#faf5ee] text-[#4B2E20]/70 border border-[#D4AF37]/20 font-medium"
                          >
                            #{tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Ação: Botão Quero este Modelo */}
                  <div className="p-4 pt-0">
                    <Button
                      onClick={() => handleChooseTemplate(template)}
                      className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs py-2.5 rounded-2xl border border-[#D4AF37]/40 shadow-xs flex items-center justify-center gap-2 group-hover:scale-[1.01] transition-transform"
                    >
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Quero este Modelo</span>
                    </Button>
                  </div>
                </Card>
              );
            })}
          </div>
        )}
      </section>

      {/* 4. SEÇÃO NO FINAL: ENSAIOS DIGITAIS OPCIONAIS (COMO COMPLEMENTO) */}
      <section className="mt-16 pt-10 border-t border-[#D4AF37]/25">
        <div className="rounded-3xl bg-gradient-to-br from-[#faf4ec] via-[#f7ebdd]/40 to-[#faf4ec] border border-[#D4AF37]/35 p-6 sm:p-10">
          <div className="max-w-2xl mx-auto text-center space-y-3 mb-8">
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#ebdccb] border border-[#D4AF37]/40 text-[#4B2E20] text-[11px] font-semibold">
              <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Trabalho Adicional • Ensaios Digitais</span>
            </div>

            <h2 className="text-2xl sm:text-3xl font-serif font-bold text-[#4B2E20]">
              Quer uma foto no tema para o seu convite?
            </h2>

            <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed">
              Além da personalização do convite, também criamos <strong>Ensaios Fotográficos Digitais</strong>. Não precisa ir a estúdio: basta nos mandar uma foto simples de celular do rostinho que transformamos no cenário perfeito da sua festa!
            </p>
          </div>

          {/* Cards de Exemplo de Ensaio Digital */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
              <div
                key={ensaio.id}
                className="bg-white rounded-2xl overflow-hidden border border-[#D4AF37]/30 shadow-xs hover:shadow-md transition-all flex flex-col justify-between p-3"
              >
                <div className="space-y-2.5">
                  <div className="relative aspect-[4/5] rounded-xl overflow-hidden bg-[#ebdccb]">
                    <img
                      src={ensaio.foto}
                      alt={ensaio.titulo}
                      className="w-full h-full object-cover"
                    />
                    <div className="absolute top-2 right-2 px-2 py-0.5 rounded-full text-[9px] font-bold bg-[#4B2E20]/80 text-[#F7EBDD] backdrop-blur-sm">
                      Exemplo
                    </div>
                  </div>

                  <div>
                    <h4 className="text-xs font-serif font-bold text-[#4B2E20]">
                      {ensaio.titulo}
                    </h4>
                    <span className="text-[10px] text-[#4B2E20]/70 font-medium block">
                      {ensaio.subtitulo}
                    </span>
                    <p className="text-[11px] text-[#4B2E20]/80 mt-1 leading-snug">
                      {ensaio.descricao}
                    </p>
                  </div>
                </div>

                <div className="pt-3 border-t border-[#D4AF37]/20 mt-2 flex items-center justify-between">
                  <span className="text-[10px] text-[#4B2E20]/70 font-medium">Adicional</span>
                  <span className="text-xs font-bold text-[#4B2E20]">
                    + R$ {ensaio.preco.toFixed(2)}
                  </span>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 text-center">
            <p className="text-xs text-[#4B2E20]/75">
              💡 Você pode solicitar a inclusão de um ensaio fotográfico digital diretamente ao escolher qualquer modelo de convite acima!
            </p>
          </div>
        </div>
      </section>

      {/* Modal de Pedido Personalizado do Cliente */}
      <ClientOrderModal
        isOpen={orderModalOpen}
        template={selectedTemplateForOrder}
        onClose={() => {
          setOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        onSubmitOrder={(newOrder) => {
          if (onOpenNewOrderModal) {
            onOpenNewOrderModal(selectedTemplateForOrder!);
          }
          setOrderModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
      />
    </div>
  );
}

