              <Button
                onClick={() => {
                  const t = previewTemplate;
                  setPreviewTemplate(null);
                  handleAbrirPedidoCliente(t);
                }}
                className="bg-[#4B2E20] text-[#F7EBDD] font-bold text-xs rounded-xl"
              >
                Personalizar este Modelo
              </Button>
            </div>
          </Card>
        </div>
