import React, { useState } from 'react';
import { Order, OrderStatus, PaymentStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Calendar,
  Clock,
  Phone,
  Search,
  CheckCircle2,
  Clock4,
  AlertCircle,
  ExternalLink,
  MessageCircle,
  Camera,
  Sparkles,
} from 'lucide-react';

export interface OrdersManagerProps {
  orders: Order[];
  onUpdateStatus: (orderId: string, status: OrderStatus) => void;
  onUpdatePayment: (orderId: string, paymentStatus: PaymentStatus, paidValue: number) => void;
  onDeleteOrder?: (orderId: string) => void;
}

export function OrdersManager({
  orders,
  onUpdateStatus,
  onUpdatePayment,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('todos');

  const filteredOrders = (orders || []).filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.includes(searchTerm);

    const matchesStatus =
      statusFilter === 'todos' || order.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
            Gerenciamento de Pedidos
          </h2>
          <p className="text-xs text-[#4B2E20]/75">
            Acompanhe as encomendas dos clientes, status de produção e pagamentos
          </p>
        </div>

        <div className="flex items-center gap-2">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#D4AF37]" />
            <Input
              placeholder="Buscar por cliente ou WhatsApp..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 h-9 text-xs rounded-xl bg-white border-[#D4AF37]/40 text-[#4B2E20] w-64"
            />
          </div>
        </div>
      </div>

      {/* Lista de Pedidos */}
      <div className="space-y-3">
        {filteredOrders.length === 0 ? (
          <Card className="p-8 text-center bg-white/80 border-[#D4AF37]/30 rounded-2xl">
            <p className="text-xs text-[#4B2E20]/70 font-medium">Nenhum pedido encontrado.</p>
          </Card>
        ) : (
          filteredOrders.map((order) => (
            <Card
              key={order.id}
              className="bg-white/95 border-[#D4AF37]/35 rounded-2xl overflow-hidden hover:shadow-md transition-shadow"
            >
              <CardContent className="p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="space-y-1.5 flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-serif font-bold text-sm text-[#4B2E20]">
                      {order.clientName}
                    </span>
                    <span className="text-[10px] px-2 py-0.5 rounded-full font-bold bg-[#ecdccb] text-[#4B2E20] border border-[#D4AF37]/25">
                      {order.category}
                    </span>

                    {order.includeDigitalPhotoshoot && (
                      <span className="text-[10px] px-2 py-0.5 rounded-full font-bold bg-[#4B2E20] text-[#D4AF37] border border-[#D4AF37]/40 flex items-center gap-1">
                        <Camera className="w-3 h-3" />
                        + Ensaio Digital
                      </span>
                    )}
                  </div>

                  <p className="text-xs text-[#4B2E20]/80 font-medium">
                    Modelo: <span className="font-semibold text-[#4B2E20]">{order.templateTitle}</span>
                  </p>

                  {order.notes && (
                    <p className="text-[11px] text-[#4B2E20]/70 bg-[#faf6f0] p-2 rounded-xl border border-[#D4AF37]/20 leading-relaxed">
                      {order.notes}
                    </p>
                  )}

                  <div className="flex flex-wrap items-center gap-3 text-[11px] text-[#4B2E20]/70 pt-1">
                    {order.clientWhatsapp && (
                      <a
                        href={`https://wa.me/${order.clientWhatsapp.replace(/\D/g, '')}`}
                        target="_blank"
                        rel="noreferrer"
                        className="flex items-center gap-1 text-emerald-700 font-semibold hover:underline"
                      >
                        <MessageCircle className="w-3.5 h-3.5" />
                        <span>{order.clientWhatsapp}</span>
                      </a>
                    )}
                    {order.eventDate && (
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3 h-3 text-[#D4AF37]" />
                        Data do evento: {order.eventDate}
                      </span>
                    )}
                  </div>
                </div>

                {/* Status e Ações */}
                <div className="flex sm:flex-col items-center sm:items-end justify-between gap-3 border-t sm:border-t-0 pt-3 sm:pt-0 border-[#D4AF37]/20">
                  <div className="text-left sm:text-right">
                    <span className="text-[10px] text-[#4B2E20]/70 block font-medium">Valor Total</span>
                    <span className="text-sm font-serif font-bold text-[#4B2E20]">
                      R$ {Number(order.totalValue || 0).toFixed(2)}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateStatus(order.id, e.target.value as OrderStatus)}
                      className="h-8 px-2.5 rounded-xl bg-[#fcf8f3] border border-[#D4AF37]/40 text-xs font-semibold text-[#4B2E20] focus:outline-none"
                    >
                      <option value="pendente">Pendente</option>
                      <option value="em_criacao">Em Criação</option>
                      <option value="aprovacao">Aprovação</option>
                      <option value="concluido">Concluído</option>
                      <option value="cancelado">Cancelado</option>
                    </select>

                    <select
                      value={order.paymentStatus}
                      onChange={(e) => {
                        const status = e.target.value as PaymentStatus;
                        const val = status === 'pago' ? order.totalValue : status === 'parcial' ? order.totalValue / 2 : 0;
                        onUpdatePayment(order.id, status, val);
                      }}
                      className="h-8 px-2 rounded-xl bg-[#fcf8f3] border border-[#D4AF37]/40 text-xs font-semibold text-[#4B2E20] focus:outline-none"
                    >
                      <option value="pendente">Pagamento Pendente</option>
                      <option value="parcial">Sinal Pago (50%)</option>
                      <option value="pago">Total Pago</option>
                    </select>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

