  Heart,
  Gift,
  Camera,
  Copy,
  Check,
  X,
  Phone,
  FileText,
  UserCheck,
} from 'lucide-react';

export interface OrdersManagerProps {
  orders: Order[];
  onUpdateOrderStatus: (orderId: string, status: OrderStatus) => void;
  onOpenNewOrder: () => void;
}

export function OrdersManager({
  orders,
  onUpdateOrderStatus,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('todos');
  const [selectedOrderDetails, setSelectedOrderDetails] = useState<Order | null>(null);
  const [copiedText, setCopiedText] = useState(false);

  const safeOrders = orders || [];

  const filteredOrders = safeOrders.filter((order) => {
    const matchesSearch =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.includes(searchTerm) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.theme?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus = statusFilter === 'todos' || order.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-bold bg-amber-100 text-amber-900 border border-amber-300 flex items-center gap-1">
            <Clock className="w-3 h-3" /> Pendente / PIX
          </span>
        );
      case 'em_criacao':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-bold bg-blue-100 text-blue-900 border border-blue-300 flex items-center gap-1">
            <Sparkles className="w-3 h-3" /> Em Criação
          </span>
        );
      case 'aprovacao':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-bold bg-purple-100 text-purple-900 border border-purple-300 flex items-center gap-1">
            <UserCheck className="w-3 h-3" /> Enviado p/ Aprovação
          </span>
        );
      case 'concluido':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-900 border border-emerald-300 flex items-center gap-1">
            <CheckCircle2 className="w-3 h-3" /> Concluído & Entregue
          </span>
        );
      case 'cancelado':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-bold bg-red-100 text-red-900 border border-red-300">
            Cancelado
          </span>
        );
      default:
        return null;
    }
  };

  const handleCopyOrderSummary = (order: Order) => {
    const resumo = `📋 PEDIDO KEH CONVITES
Cliente: ${order.clientName}
WhatsApp: ${order.clientWhatsapp}
Modelo: ${order.templateTitle} (${order.category})
Tema: ${order.theme || 'Não especificado'}
Data do Evento: ${order.eventDate} ${order.eventTime ? `às ${order.eventTime}` : ''}
Local: ${order.mapsLocation || 'A combinar'}
${order.specialPhrase ? `Frase: "${order.specialPhrase}"` : ''}
${order.hasInteraction ? `Interativo: RSVP (${order.rsvpContact || 'Sim'}) | Presentes (${order.giftList || 'Sim'})` : 'Convite Simples'}
${order.includeDigitalPhotoshoot ? `Ensaio Digital: Sim (${order.photoshootDetails || 'Incluso'})` : 'Sem Ensaio Digital'}
Valor Total: R$ ${order.totalValue.toFixed(2)}
Notas: ${order.notes || 'Sem observações'}`;

    navigator.clipboard.writeText(resumo);
    setCopiedText(true);
    setTimeout(() => setCopiedText(false), 2500);
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Topo / Filtros */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white/95 p-4 rounded-2xl border border-[#D4AF37]/35 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
          <Input
            placeholder="Buscar por cliente, whatsapp, tema ou modelo..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 bg-[#fcf8f3] border-[#D4AF37]/30 text-xs text-[#4B2E20] rounded-xl"
          />
        </div>

        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-[#D4AF37]" />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="h-10 px-3 rounded-xl bg-[#fcf8f3] border border-[#D4AF37]/35 text-xs text-[#4B2E20] font-medium focus:outline-none"
          >
            <option value="todos">Todos os Status ({safeOrders.length})</option>
            <option value="pendente">Pendentes</option>
            <option value="em_criacao">Em Criação</option>
            <option value="aprovacao">Aprovação</option>
            <option value="concluido">Concluídos</option>
          </select>
        </div>
      </div>

      {/* Lista de Pedidos */}
      <div className="grid grid-cols-1 gap-4">
        {filteredOrders.length === 0 ? (
          <div className="text-center py-12 bg-white/80 rounded-3xl border border-[#D4AF37]/30 p-8">
            <Sparkles className="w-10 h-10 mx-auto text-[#D4AF37] mb-2 opacity-60" />
            <h3 className="text-base font-serif font-bold text-[#4B2E20]">Nenhum pedido encontrado</h3>
            <p className="text-xs text-[#4B2E20]/70 mt-1 max-w-sm mx-auto">
              Quando clientes realizarem pedidos pelo catálogo ou quando você registrar manualmente, eles aparecerão aqui com todos os detalhes.
            </p>
          </div>
        ) : (
          filteredOrders.map((order) => (
            <Card
              key={order.id}
              className="bg-white/95 border-[#D4AF37]/35 rounded-2xl shadow-sm hover:shadow-md transition-all overflow-hidden"
            >
              <div className="p-4 sm:p-5 flex flex-col md:flex-row md:items-center justify-between gap-4">

                {/* Dados resumidos do cliente */}
                <div className="space-y-1.5 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-serif font-bold text-base text-[#4B2E20]">
                      {order.clientName}
                    </span>
                    {getStatusBadge(order.status)}
                    {order.includeDigitalPhotoshoot && (
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-[#D4AF37]/20 text-[#4B2E20] border border-[#D4AF37]/40 flex items-center gap-1">
                        <Camera className="w-3 h-3 text-[#D4AF37]" /> + Ensaio Digital
                      </span>
                    )}
                  </div>

                  <div className="text-xs text-[#4B2E20]/75 flex flex-wrap items-center gap-x-4 gap-y-1">
                    <span className="font-semibold text-[#4B2E20]">
                      Modelo: {order.templateTitle}
                    </span>
                    {order.theme && (
                      <span className="text-[#855729] font-medium">
                        Tema: {order.theme}
                      </span>
                    )}
                    <span>WhatsApp: {order.clientWhatsapp}</span>
                    <span>Data do Evento: {order.eventDate}</span>
                  </div>

                  {order.notes && (
                    <p className="text-[11px] text-[#4B2E20]/70 italic line-clamp-1 bg-[#faf5ee] p-1.5 rounded-lg border border-[#D4AF37]/20">
                      {order.notes}
                    </p>
                  )}
                </div>

                {/* Preço e Ações */}
                <div className="flex flex-wrap md:flex-col items-center md:items-end justify-between gap-2 shrink-0 border-t md:border-t-0 pt-3 md:pt-0 border-[#D4AF37]/15">
                  <div className="text-left md:text-right">
                    <span className="text-xs text-[#4B2E20]/70 block font-medium">Valor Total</span>
                    <span className="text-base font-serif font-bold text-[#4B2E20]">
                      R$ {Number(order.totalValue || 0).toFixed(2)}
                    </span>
                  </div>

                  <div className="flex items-center gap-2">
                    {/* Botão de Ver Detalhes Completos */}
                    <Button
                      size="sm"
                      onClick={() => setSelectedOrderDetails(order)}
                      className="bg-[#ecdccb] hover:bg-[#dfcbb7] text-[#4B2E20] font-bold text-xs rounded-xl shadow-xs flex items-center gap-1.5"
                    >
                      <Eye className="w-3.5 h-3.5 text-[#4B2E20]" />
                      <span>Ver Tudo o Que a Cliente Quer</span>
                    </Button>

                    {/* Mudar Status */}
                    <select
                      value={order.status}
                      onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as OrderStatus)}
                      className="h-9 px-2.5 rounded-xl bg-[#4B2E20] text-[#F7EBDD] text-xs font-semibold focus:outline-none shadow-xs border border-[#D4AF37]/40 cursor-pointer"
                    >
                      <option value="pendente">Pendente</option>
                      <option value="em_criacao">Em Criação</option>
                      <option value="aprovacao">Aprovação</option>
                      <option value="concluido">Concluído</option>
                      <option value="cancelado">Cancelado</option>
                    </select>
                  </div>
                </div>

              </div>
            </Card>
          ))
        )}
      </div>

      {/* Modal com TODAS as informações que a cliente preencheu */}
      {selectedOrderDetails && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">

            <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/80 to-[#f7ebdd]/80 shrink-0">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] border border-[#D4AF37]/50 flex items-center justify-center text-[#D4AF37] shadow-sm">
                  <FileText className="w-5 h-5" />
                </div>
                <div>
                  <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                    Detalhes do Pedido de {selectedOrderDetails.clientName}
                  </CardTitle>
                  <p className="text-xs text-[#4B2E20]/75 font-medium">
                    Todas as informações enviadas pela cliente para confecção do convite
                  </p>
                </div>
              </div>
              <button
                onClick={() => setSelectedOrderDetails(null)}
                className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </CardHeader>

            <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-4 text-xs text-[#4B2E20]">

              {/* Barra de Status e Ações Rápidas */}
              <div className="flex flex-wrap items-center justify-between gap-3 p-3 bg-[#ecdccb]/40 rounded-2xl border border-[#D4AF37]/30">
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-xs">Status do Pedido:</span>
                  {getStatusBadge(selectedOrderDetails.status)}
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleCopyOrderSummary(selectedOrderDetails)}
                    className="border-[#D4AF37]/50 bg-white text-[#4B2E20] hover:bg-[#faf5ee] text-xs h-8 rounded-xl flex items-center gap-1.5"
                  >
                    {copiedText ? (
                      <>
                        <Check className="w-3.5 h-3.5 text-emerald-600" />
                        <span>Copiado!</span>
                      </>
                    ) : (
                      <>
                        <Copy className="w-3.5 h-3.5 text-[#D4AF37]" />
                        <span>Copiar Resumo</span>
                      </>
                    )}
                  </Button>

                  <a
                    href={`https://wa.me/55${selectedOrderDetails.clientWhatsapp.replace(/\D/g, '')}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-semibold text-xs shadow-xs"
                  >
                    <Phone className="w-3.5 h-3.5" />
                    <span>Chamar Cliente no WhatsApp</span>
                  </a>
                </div>
              </div>

              {/* Bloco 1: Modelo e Tipo Escolhido */}
              <div className="p-4 bg-white rounded-2xl border border-[#D4AF37]/30 shadow-xs space-y-2">
                <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                  <span>Modelo & Formato Escolhido</span>
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                  <div>
                    <span className="text-[#4B2E20]/60 block">Modelo:</span>
                    <span className="font-bold text-[#4B2E20] text-sm">
                      {selectedOrderDetails.templateTitle}
                    </span>
                  </div>
                  <div>
                    <span className="text-[#4B2E20]/60 block">Categoria / Tipo:</span>
                    <span className="font-semibold text-[#4B2E20]">
                      {selectedOrderDetails.category} • {selectedOrderDetails.digitalFormat}
                    </span>
                  </div>
                </div>
              </div>

              {/* Bloco 2: O que deve estar escrito no convite */}
              <div className="p-4 bg-white rounded-2xl border border-[#D4AF37]/30 shadow-xs space-y-3">
                <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-2">
                  <Heart className="w-4 h-4 text-[#D4AF37]" />
                  <span>Dados que a Cliente Quer no Convite</span>
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div className="p-2.5 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                    <span className="text-[#4B2E20]/65 text-[11px] block">Nome do Aniversariante / Homenageado:</span>
                    <span className="font-bold text-[#4B2E20] text-sm">
                      {selectedOrderDetails.clientName}
                    </span>
                  </div>

                  <div className="p-2.5 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                    <span className="text-[#4B2E20]/65 text-[11px] block">Tema da Festa / Decoração:</span>
                    <span className="font-bold text-[#4B2E20] text-sm">
                      {selectedOrderDetails.theme || 'Não informado / Seguir o tema do modelo'}
                    </span>
                  </div>

                  <div className="p-2.5 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                    <span className="text-[#4B2E20]/65 text-[11px] flex items-center gap-1">
                      <Calendar className="w-3 h-3 text-[#D4AF37]" />
                      <span>Data do Evento:</span>
                    </span>
                    <span className="font-bold text-[#4B2E20]">
                      {selectedOrderDetails.eventDate || 'A definir'}
                    </span>
                  </div>

                  <div className="p-2.5 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                    <span className="text-[#4B2E20]/65 text-[11px] flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-[#D4AF37]" />
                      <span>Local ou Endereço:</span>
                    </span>
                    <span className="font-bold text-[#4B2E20]">
                      {selectedOrderDetails.mapsLocation || 'A combinar'}
                    </span>
                  </div>
                </div>

                {selectedOrderDetails.specialPhrase && (
                  <div className="p-3 bg-amber-50/80 rounded-xl border border-amber-200">
                    <span className="text-amber-900/70 text-[11px] font-semibold block">
                      Frase Especial Solicitada:
                    </span>
                    <p className="font-serif italic font-bold text-[#4B2E20] text-sm mt-0.5">
                      &quot;{selectedOrderDetails.specialPhrase}&quot;
                    </p>
                  </div>
                )}
              </div>

              {/* Bloco 3: Funções Interativas (se o modelo tiver botões) */}
              <div className="p-4 bg-white rounded-2xl border border-[#D4AF37]/30 shadow-xs space-y-2">
                <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                  <span>Botões Clicáveis e Interações</span>
                </h4>

                {selectedOrderDetails.hasInteraction ? (
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <div className="p-2 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                      <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">RSVP / Confirmação</span>
                      <p className="font-bold text-xs">{selectedOrderDetails.rsvpContact || 'Sim'}</p>
                    </div>

                    <div className="p-2 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                      <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Localização GPS</span>
                      <p className="font-bold text-xs">{selectedOrderDetails.mapsLocation || 'Sim'}</p>
                    </div>

                    <div className="p-2 bg-[#fcf8f3] rounded-xl border border-[#D4AF37]/20">
                      <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Lista de Presentes</span>
                      <p className="font-bold text-xs">{selectedOrderDetails.giftList || 'Sim'}</p>
                    </div>
                  </div>
                ) : (
                  <p className="text-xs text-[#4B2E20]/70 italic">
                    Convite Simples em imagem/vídeo sem botões interativos clicáveis.
                  </p>
                )}
              </div>

              {/* Bloco 4: Ensaio Digital Opcional */}
              <div className="p-4 bg-white rounded-2xl border border-[#D4AF37]/30 shadow-xs space-y-2">
                <h4 className="font-serif font-bold text-sm text-[#4B2E20] flex items-center gap-2">
                  <Camera className="w-4 h-4 text-[#D4AF37]" />
                  <span>Ensaio Digital Adicional</span>
                </h4>
                {selectedOrderDetails.includeDigitalPhotoshoot ? (
                  <div className="p-3 bg-emerald-50 rounded-xl border border-emerald-300 text-emerald-950 font-medium">
                    <span className="font-bold block text-emerald-900">
                      ✅ A cliente contratou o Ensaio Digital junto ao convite (+ R$ 25,00)
                    </span>
                    <span className="text-xs text-emerald-800">
                      Tema do Ensaio Solicitado: {selectedOrderDetails.photoshootDetails || 'Infantil / Pré-Wedding'}
                    </span>
                  </div>
                ) : (
                  <p className="text-xs text-[#4B2E20]/70 italic">
                    Nenhum ensaio digital contratado neste pedido.
                  </p>
                )}
              </div>

              {/* Bloco 5: Resumo Completo das Notas do Sistema */}
              {selectedOrderDetails.notes && (
                <div className="p-4 bg-[#faf5ee] rounded-2xl border border-[#D4AF37]/25 space-y-1">
                  <span className="font-bold text-xs text-[#4B2E20] block">Notas Completas do Formulário:</span>
                  <p className="text-xs text-[#4B2E20]/80 whitespace-pre-line leading-relaxed">
                    {selectedOrderDetails.notes}
                  </p>
                </div>
              )}

              {/* Bloco 6: Valores & PIX */}
              <div className="p-4 bg-[#ecdccb]/50 rounded-2xl border border-[#D4AF37]/35 flex flex-col sm:flex-row items-center justify-between gap-3">
                <div>
                  <span className="text-xs text-[#4B2E20]/75 font-semibold">Valor Total Cobrado:</span>
                  <p className="text-xl font-serif font-bold text-[#4B2E20]">
                    R$ {Number(selectedOrderDetails.totalValue || 0).toFixed(2)}
                  </p>
                  <span className="text-[11px] text-emerald-700 font-bold">
                    Chave PIX Informada ao Cliente: 32998040080
                  </span>
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    onClick={() => {
                      onUpdateOrderStatus(selectedOrderDetails.id, 'em_criacao');
                      setSelectedOrderDetails({
                        ...selectedOrderDetails,
                        status: 'em_criacao',
                      });
                    }}
                    className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-xs"
                  >
                    Iniciar Criação do Convite
                  </Button>

                  <Button
                    onClick={() => {
                      onUpdateOrderStatus(selectedOrderDetails.id, 'concluido');
                      setSelectedOrderDetails({
                        ...selectedOrderDetails,
                        status: 'concluido',
                      });
                    }}
                    className="bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs rounded-xl shadow-xs"
                  >
                    Marcar como Entregue
                  </Button>
                </div>
              </div>

            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

