import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat, Order } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Sparkles,
  Search,
  Eye,
  SlidersHorizontal,
  Camera,
  Image as ImageIcon,
  Smartphone,
  Video,
  Clock,
  Heart,
  CalendarHeart,
} from 'lucide-react';
import { ClientOrderModal } from './ClientOrderModal';

export const EXEMPLOS_ENSAIOS_CATALOGO = [
  {
    id: 'ens-1',
    title: 'Ensaio Infantil Temático',
    category: 'Infantil',
    imageUrl: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=800&q=80',
