    category: '15 Anos / Infantil',
    imageUrl: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=800&q=80',
    description: 'Composição de vestidos dignos de conto de fadas e cenários de castelo encantador.',
  },
  {
    id: 'ens-3',
    title: 'Ensaio Pré-Wedding / Casal',
    category: 'Casamento',
