    title: 'Ensaio Primeiro Aninho',
    category: 'Infantil / 1º Ano',
    imageUrl: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=800&q=80',
    description: 'Smash The Cake digital e cenários repletos de balões com acabamento suave e delicado.',
  },
];

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOrderTemplate: (template: InvitationTemplate) => void;
  onSubmitClientOrder?: (newOrder: Order) => void;
  isAdmin?: boolean;
}

export function TemplatesCatalog({
  templates,
  onOrderTemplate,
  onSubmitClientOrder,
  isAdmin = false,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('todos');
  const [selectedFormat, setSelectedFormat] = useState<string>('todos');
  const [searchQuery, setSearchQuery] = useState('');
  const [previewTemplate, setPreviewTemplate] = useState<InvitationTemplate | null>(null);

  // Modal de Pedido Personalizado do Cliente
  const [clientOrderModalTemplate, setClientOrderModalTemplate] = useState<InvitationTemplate | null>(null);

  const categories: { label: string; value: string }[] = [
    { label: 'Todos os Modelos', value: 'todos' },
    { label: 'Casamento', value: 'Casamento' },
    { label: '15 Anos', value: '15 Anos' },
    { label: 'Infantil', value: 'Infantil' },
    { label: 'Batizado', value: 'Batizado' },
    { label: 'Corporativo', value: 'Corporativo' },
    { label: 'Bodas', value: 'Bodas' },
  ];

  const formats: { label: string; value: string; icon: React.ElementType }[] = [
    { label: 'Todos os Formatos', value: 'todos', icon: SlidersHorizontal },
    { label: 'Card Simples (WhatsApp)', value: 'imagem_card', icon: ImageIcon },
    { label: 'Interativo (Botões)', value: 'interativo_pdf', icon: Smartphone },
    { label: 'Vídeo Animado', value: 'animado_video', icon: Video },
    { label: 'Save The Date', value: 'save_the_date', icon: Clock },
  ];

  const filteredTemplates = templates.filter((t) => {
    const matchesCategory = selectedCategory === 'todos' || t.category === selectedCategory;
    const matchesFormat = selectedFormat === 'todos' || t.format === selectedFormat;
    const matchesSearch =
      t.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesFormat && matchesSearch;
  });

  const getFormatBadge = (format: DigitalFormat) => {
    switch (format) {
      case 'imagem_card':
        return { label: 'Card Simples', bg: 'bg-[#ecdccb] text-[#4B2E20]' };
      case 'interativo_pdf':
        return { label: 'Com Botões Clicáveis', bg: 'bg-[#D4AF37]/25 text-[#4B2E20] border border-[#D4AF37]/50 font-semibold' };
      case 'animado_video':
        return { label: 'Vídeo Animado', bg: 'bg-purple-100 text-purple-900 border border-purple-200' };
      case 'save_the_date':
        return { label: 'Save The Date', bg: 'bg-rose-100 text-rose-900 border border-rose-200' };
      default:
        return { label: 'Digital', bg: 'bg-gray-100 text-gray-800' };
    }
  };

  const handleAbrirPedidoCliente = (tmpl: InvitationTemplate) => {
    setClientOrderModalTemplate(tmpl);
  };

  const handleSubmeterPedidoDoCliente = (novoPedido: Order) => {
    if (onSubmitClientOrder) {
      onSubmitClientOrder(novoPedido);
    } else {
      onOrderTemplate(clientOrderModalTemplate || templates[0]);
    }
  };

  return (
    <div className="space-y-12 animate-fade-in pb-16">

      {/* Banner Principal - Foco em Convites Digitais */}
      <div className="relative rounded-3xl overflow-hidden bg-gradient-to-r from-[#ecdccb] via-[#F7EBDD] to-[#eddccb] border border-[#D4AF37]/35 shadow-sm p-6 sm:p-10 text-[#4B2E20]">
        <div className="max-w-2xl relative z-10 space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#4B2E20] text-[#D4AF37] text-xs font-semibold shadow-sm">
            <Sparkles className="w-3.5 h-3.5" />
            <span>Convites Digitais Exclusivos & Personalizados</span>
          </div>

          <h1 className="text-3xl sm:text-4xl font-serif font-bold tracking-tight text-[#4B2E20] leading-tight">
            Encante seus convidados desde o primeiro clique
          </h1>

          <p className="text-sm sm:text-base text-[#4B2E20]/80 leading-relaxed font-serif italic">
            Convites digitais práticos para enviar no WhatsApp: escolha o seu modelo favorito, preencha os dados da festa e faça o pagamento via PIX para receber sua arte personalizada!
          </p>
        </div>
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="space-y-4">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">

          {/* Categorias */}
          <div className="flex items-center gap-1.5 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-none">
            {categories.map((cat) => (
              <button
                key={cat.value}
                onClick={() => setSelectedCategory(cat.value)}
                className={`whitespace-nowrap px-4 py-2 rounded-2xl text-xs font-semibold tracking-wide transition-all ${
                  selectedCategory === cat.value
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-md border border-[#D4AF37]/40'
                    : 'bg-white/80 hover:bg-white text-[#4B2E20] border border-[#D4AF37]/30'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>

          {/* Campo de Busca */}
          <div className="relative w-full md:w-72">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
            <input
              type="text"
              placeholder="Buscar por tema, modelo..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 bg-white/90 border border-[#D4AF37]/35 rounded-2xl text-xs text-[#4B2E20] placeholder:text-[#4B2E20]/50 focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 shadow-sm"
            />
          </div>
        </div>

        {/* Filtro por Formato */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 text-xs">
          <span className="text-[#4B2E20]/70 font-semibold flex items-center gap-1 shrink-0">
            <SlidersHorizontal className="w-3.5 h-3.5 text-[#D4AF37]" /> Formato:
          </span>
          {formats.map((fmt) => {
            const Icon = fmt.icon;
            const isSelected = selectedFormat === fmt.value;
            return (
              <button
                key={fmt.value}
                onClick={() => setSelectedFormat(fmt.value)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[11px] font-medium transition-all ${
                  isSelected
                    ? 'bg-[#D4AF37] text-[#4B2E20] font-bold shadow-sm'
                    : 'bg-[#ecdccb]/50 text-[#4B2E20]/80 hover:bg-[#ecdccb]'
                }`}
              >
                <Icon className="w-3 h-3" />
                <span>{fmt.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Grid de Convites Digitais */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-serif font-bold text-[#4B2E20] flex items-center gap-2">
            <CalendarHeart className="w-5 h-5 text-[#D4AF37]" />
            <span>Catálogo de Convites ({filteredTemplates.length})</span>
          </h2>
        </div>

        {filteredTemplates.length === 0 ? (
          <div className="p-12 text-center bg-white/60 border border-[#D4AF37]/30 rounded-3xl">
            <Heart className="w-10 h-10 mx-auto text-[#D4AF37]/50 mb-3" />
            <p className="font-serif text-[#4B2E20] font-bold">Nenhum modelo encontrado com estes filtros.</p>
            <p className="text-xs text-[#4B2E20]/70 mt-1">Tente remover os filtros ou buscar por outro termo.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredTemplates.map((template) => {
              const badge = getFormatBadge(template.format);
              return (
                <Card
                  key={template.id}
                  className="group bg-white border-[#D4AF37]/30 rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1 flex flex-col"
                >
                  {/* Foto de Capa do Convite */}
                  <div className="relative aspect-[3/4] overflow-hidden bg-[#faf5ee]">
                    <img
                      src={template.imageUrl}
                      alt={template.title}
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                    />

                    <div className="absolute top-3 left-3 flex flex-col gap-1.5 items-start">
                      <span className={`text-[10px] px-2.5 py-1 rounded-full font-bold shadow-sm ${badge.bg}`}>
                        {badge.label}
                      </span>
                    </div>

                    <div className="absolute top-3 right-3">
                      <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-white/90 text-[#4B2E20] border border-[#D4AF37]/30 shadow-sm">
                        {template.category}
                      </span>
                    </div>

                    {/* Botão de Ver Prévia */}
                    <button
                      onClick={() => setPreviewTemplate(template)}
                      className="absolute inset-0 bg-[#4B2E20]/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity text-white gap-2 font-serif font-medium text-xs backdrop-blur-[2px]"
                    >
                      <Eye className="w-4 h-4 text-[#D4AF37]" />
                      <span>Ampliar Modelo</span>
                    </button>
                  </div>

                  {/* Informações do Convite */}
                  <CardContent className="p-4 sm:p-5 flex flex-col flex-1 justify-between">
                    <div>
                      <h3 className="font-serif font-bold text-base text-[#4B2E20] line-clamp-1 group-hover:text-[#855729] transition-colors">
                        {template.title}
                      </h3>
                      <p className="text-xs text-[#4B2E20]/75 line-clamp-2 mt-1 leading-relaxed">
                        {template.description}
                      </p>
                    </div>

                    <div className="pt-4 border-t border-[#D4AF37]/20 mt-4 flex items-center justify-between">
                      <div>
                        <span className="text-[10px] text-[#4B2E20]/70 uppercase font-semibold block">Preço</span>
                        <span className="text-lg font-serif font-bold text-[#4B2E20]">
                          R$ {template.price.toFixed(2)}
                        </span>
                      </div>

                      <Button
                        onClick={() => handleAbrirPedidoCliente(template)}
                        className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm flex items-center gap-1.5 px-4"
                      >
                        <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                        <span>Quero Esse</span>
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      {/* SEÇÃO NO FINAL: ENSAIOS DIGITAIS DE EXEMPLO (Inspiração Opcional) */}
      <section className="pt-8 border-t border-[#D4AF37]/30 space-y-6">
        <div className="text-center max-w-xl mx-auto space-y-2">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#ecdccb] text-[#4B2E20] text-xs font-semibold">
            <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Serviço Adicional Exclusivo</span>
          </div>
          <h3 className="text-2xl font-serif font-bold text-[#4B2E20]">
            Ensaios Digitais para seu Convite
          </h3>
          <p className="text-xs text-[#4B2E20]/75 leading-relaxed">
            Não tem uma foto de estúdio? Criamos um cenário digital cinematográfico para a foto do seu pequeno ou do casal, pronto para estampar seu convite!
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
            <Card
              key={ensaio.id}
              className="bg-white/80 border-[#D4AF37]/30 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all group"
            >
              <div className="aspect-[4/3] overflow-hidden bg-gray-100">
                <img
                  src={ensaio.imageUrl}
                  alt={ensaio.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                />
              </div>
              <div className="p-3.5 space-y-1">
                <span className="text-[10px] font-bold text-[#D4AF37] uppercase">{ensaio.category}</span>
                <h4 className="font-serif font-bold text-xs text-[#4B2E20]">{ensaio.title}</h4>
                <p className="text-[11px] text-[#4B2E20]/70 line-clamp-2 leading-tight">
                  {ensaio.description}
                </p>
              </div>
            </Card>
          ))}
        </div>
      </section>

      {/* Modal de Zoom do Convite */}
      {previewTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-lg w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden">
            <div className="relative">
              <img
                src={previewTemplate.imageUrl}
                alt={previewTemplate.title}
                className="w-full max-h-[70vh] object-contain bg-black/5"
              />
              <button
                onClick={() => setPreviewTemplate(null)}
                className="absolute top-3 right-3 p-2 bg-[#4B2E20]/80 hover:bg-[#4B2E20] text-white rounded-full transition-colors"
              >
                ✕
              </button>
            </div>
            <div className="p-5 flex items-center justify-between">
              <div>
                <h4 className="font-serif font-bold text-base text-[#4B2E20]">{previewTemplate.title}</h4>
                <span className="text-xs text-[#4B2E20]/70">R$ {previewTemplate.price.toFixed(2)}</span>
              </div>
              <Button
                onClick={() => {
                  const t = previewTemplate;
                  setPreviewTemplate(null);
                  handleAbrirPedidoCliente(t);
                }}
                className="bg-[#4B2E20] text-[#F7EBDD] font-bold text-xs rounded-xl"
              >
                Personalizar este Modelo
              </Button>
            </div>
          </Card>
        </div>
      )}

      {/* Modal de Pedido e Pagamento PIX */}
      <ClientOrderModal
        isOpen={Boolean(clientOrderModalTemplate)}
        template={clientOrderModalTemplate}
        onClose={() => setClientOrderModalTemplate(null)}
        onSubmitOrder={handleSubmeterPedidoDoCliente}
      />

    </div>
  );
}

