import React, { useState, useRef } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ClientOrderModal } from '@/components/ClientOrderModal';
import {
  Sparkles,
  Search,
  Filter,
  CheckCircle,
  Eye,
  Camera,
  Play,
  Heart,
  Upload,
  Edit,
  Tag,
  Percent,
  X,
  FileVideo,
  ImageIcon,
} from 'lucide-react';

export const EXEMPLOS_ENSAIOS_CATALOGO = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque, Ursinho ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
    descricao: 'Criamos a foto artística no tema da festa para você colocar de capa no convite.',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala, Castelo e Flores',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
    descricao: 'Foto impecável estilo pintura digital de princesa para encantar toda a família.',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol, Praia e Cenário Floral',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
    descricao: 'Para casamentos e noivados: ensaio romântico digital sem precisar de estúdio.',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash The Cake, Balões e Cenário Boho',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
    descricao: 'Recordação delicada e inesquecível do primeiro aniversário.',
  },
];

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOpenOrderModal: (template: InvitationTemplate) => void;
  onUpdateTemplate?: (updatedTemplate: InvitationTemplate) => void;
  isAdminAuthenticated?: boolean;
}

export function TemplatesCatalog({
  templates,
  onOpenOrderModal,
  onUpdateTemplate,
  isAdminAuthenticated = false,
}: TemplatesCatalogProps) {
  const [activeCategory, setActiveCategory] = useState<string>('todos');
  const [activeFormat, setActiveFormat] = useState<string>('todos');
  const [searchTerm, setSearchTerm] = useState('');

  // Modal de Pedido da Cliente
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);

  // Modal de Edição da Administradora (Fotos, Vídeos, Valores e Promoção)
  const [editingTemplate, setEditingTemplate] = useState<InvitationTemplate | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editPrice, setEditPrice] = useState<number>(0);
  const [editOriginalPrice, setEditOriginalPrice] = useState<number>(0);
  const [editIsPromotion, setEditIsPromotion] = useState(false);
  const [editImageUrl, setEditImageUrl] = useState('');
  const [editVideoUrl, setEditVideoUrl] = useState('');
  const [editFormat, setEditFormat] = useState<DigitalFormat>('imagem_card');
  const [editCategory, setEditCategory] = useState<InvitationCategory>('Infantil');
  const [editDescription, setEditDescription] = useState('');
  const editFileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['todos', 'Casamento', '15 Anos', 'Infantil', 'Batizado', 'Corporativo', 'Bodas'];

  const filteredTemplates = templates.filter((template) => {
    const matchesCategory = activeCategory === 'todos' || template.category === activeCategory;
    const matchesFormat = activeFormat === 'todos' || template.format === activeFormat;
    const matchesSearch =
      template.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      template.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      template.tags.some((t) => t.toLowerCase().includes(searchTerm.toLowerCase()));

    return matchesCategory && matchesFormat && matchesSearch;
  });

  const getFormatLabel = (fmt: DigitalFormat) => {
    switch (fmt) {
      case 'imagem_card':
        return 'Card em Imagem';
      case 'interativo_pdf':
        return 'Interativo (Botões)';
      case 'animado_video':
        return 'Vídeo com Música';
      case 'save_the_date':
        return 'Save The Date';
      case 'kit_digital':
        return 'Kit Digital Completo';
      case 'site_rsvp':
        return 'Página Web';
      default:
        return 'Convite Digital';
    }
  };

  const handleOpenEdit = (tpl: InvitationTemplate) => {
    setEditingTemplate(tpl);
    setEditTitle(tpl.title);
    setEditPrice(tpl.price);
    setEditOriginalPrice(tpl.originalPrice || tpl.price + 20);
    setEditIsPromotion(Boolean(tpl.isPromotion));
    setEditImageUrl(tpl.imageUrl);
    setEditVideoUrl(tpl.videoUrl || '');
    setEditFormat(tpl.format);
    setEditCategory(tpl.category);
    setEditDescription(tpl.description);
  };

  const handleUploadImageFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setEditImageUrl(url);
    }
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTemplate || !onUpdateTemplate) return;

    const updated: InvitationTemplate = {
      ...editingTemplate,
      title: editTitle,
      price: Number(editPrice) || 0,
      originalPrice: editIsPromotion ? Number(editOriginalPrice) || undefined : undefined,
      isPromotion: editIsPromotion,
      imageUrl: editImageUrl,
      videoUrl: editVideoUrl || undefined,
      format: editFormat,
      category: editCategory,
      description: editDescription,
    };

    onUpdateTemplate(updated);
    setEditingTemplate(null);
  };

  return (
    <div className="space-y-16 animate-fade-in pb-16">

      {/* 1. SEÇÃO DE CONVITES DIGITAIS (DESTAQUE PRINCIPAL) */}
      <section className="space-y-8">
        <div className="text-center max-w-2xl mx-auto space-y-2">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#ecdccb]/80 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Convites Digitais Exclusivos & Personalizados</span>
          </div>
          <h2 className="text-2xl sm:text-3xl font-serif font-bold text-[#4B2E20] tracking-tight">
            Escolha o Modelo do Seu Convite
          </h2>
          <p className="text-xs sm:text-sm text-[#4B2E20]/75">
            Cards para WhatsApp, Convites Interativos com botões clicáveis de localização e confirmação, ou Vídeos animados com música.
          </p>
        </div>

        {/* Barra de Filtros e Busca */}
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 bg-white/90 p-3 rounded-2xl border border-[#D4AF37]/30 shadow-sm">
          {/* Categorias */}
          <div className="flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-3 py-1.5 rounded-xl text-xs font-semibold tracking-wide whitespace-nowrap transition-all ${
                  activeCategory === cat
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                    : 'text-[#4B2E20]/70 hover:text-[#4B2E20] hover:bg-[#faf4ec]'
                }`}
              >
                {cat === 'todos' ? 'Todos os Temas' : cat}
              </button>
            ))}
          </div>

          {/* Busca */}
          <div className="relative w-full sm:w-64 shrink-0">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
            <Input
              placeholder="Buscar tema ou modelo..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 bg-[#fdfbf7] border-[#D4AF37]/35 text-xs text-[#4B2E20] rounded-xl"
            />
          </div>
        </div>

        {/* Grid de Modelos de Convites */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => (
            <Card
              key={template.id}
              className="group overflow-hidden bg-white/95 border-[#D4AF37]/30 rounded-3xl shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col justify-between"
            >
              <div>
                {/* Imagem do Convite com Badges */}
                <div className="relative h-64 sm:h-72 overflow-hidden bg-[#faf6f0]">
                  <img
                    src={template.imageUrl}
                    alt={template.title}
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/20" />

                  {/* Badge de Promoção */}
                  {template.isPromotion && (
                    <div className="absolute top-3 left-3 bg-rose-600 text-white text-[11px] font-black px-2.5 py-1 rounded-full shadow-md flex items-center gap-1 animate-pulse">
                      <Percent className="w-3 h-3" />
                      <span>PROMOÇÃO</span>
                    </div>
                  )}

                  {/* Badge de Formato */}
                  <div className="absolute top-3 right-3 bg-[#4B2E20]/85 backdrop-blur-md text-[#F7EBDD] text-[10px] font-semibold px-2.5 py-1 rounded-full border border-[#D4AF37]/50">
                    {getFormatLabel(template.format)}
                  </div>

                  {/* Categoria no fundo */}
                  <div className="absolute bottom-3 left-3 right-3 flex items-end justify-between text-white">
                    <span className="text-xs font-semibold bg-white/20 backdrop-blur-md px-2 py-0.5 rounded-lg border border-white/20">
                      {template.category}
                    </span>
                    {template.hasInteraction && (
                      <span className="text-[10px] bg-amber-400/90 text-[#4B2E20] font-bold px-2 py-0.5 rounded-lg">
                        ✨ Com Botões
                      </span>
                    )}
                  </div>
                </div>

                {/* Conteúdo do Card */}
                <div className="p-4 sm:p-5 space-y-2">
                  <h3 className="font-serif font-bold text-base sm:text-lg text-[#4B2E20] line-clamp-1 group-hover:text-[#693f2c] transition-colors">
                    {template.title}
                  </h3>
                  <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                    {template.description}
                  </p>

                  {/* Tags */}
                  <div className="flex flex-wrap gap-1 pt-1">
                    {template.tags.slice(0, 3).map((tag, idx) => (
                      <span
                        key={idx}
                        className="text-[10px] px-2 py-0.5 bg-[#fdfaf5] border border-[#D4AF37]/25 rounded-md text-[#4B2E20]/80 font-medium"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              </div>

              {/* Rodapé com Preço e Ações */}
              <div className="p-4 sm:p-5 pt-0 flex flex-col gap-2.5 border-t border-[#D4AF37]/15">
                <div className="flex items-baseline justify-between pt-3">
                  <div>
                    {template.isPromotion && template.originalPrice && (
                      <span className="text-xs text-rose-500/80 line-through mr-1.5 font-medium">
                        R$ {template.originalPrice.toFixed(2)}
                      </span>
                    )}
                    <span className="text-lg sm:text-xl font-serif font-black text-[#4B2E20]">
                      R$ {template.price.toFixed(2)}
                    </span>
                  </div>
                  <span className="text-[10px] text-[#4B2E20]/70 font-medium">
                    Envio digital ilimitado
                  </span>
                </div>

                {/* Botão de Pedido para Clientes */}
                <Button
                  onClick={() => setSelectedTemplateForOrder(template)}
                  className="w-full bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-sm flex items-center justify-center gap-1.5"
                >
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Personalizar Este Convite</span>
                </Button>

                {/* Botão EXCLUSIVO DA ADMINISTRADORA: Editar fotos, vídeos, valores e promoção */}
                {isAdminAuthenticated && (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleOpenEdit(template)}
                    className="w-full border-[#D4AF37]/60 bg-[#faf5ee] hover:bg-[#ebdccb] text-[#4B2E20] font-bold text-xs rounded-xl flex items-center justify-center gap-1.5"
                  >
                    <Edit className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Editar Modelo (Foto, Vídeo, Preço & Promoção)</span>
                  </Button>
                )}
              </div>
            </Card>
          ))}
        </div>
      </section>

      {/* 2. SEÇÃO DE ENSAIOS DIGITAIS (NO FINAL DA PÁGINA) */}
      <section className="space-y-6 pt-6 border-t border-[#D4AF37]/25">
        <div className="text-center max-w-2xl mx-auto space-y-1.5">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-amber-100/80 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold">
            <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Serviço Adicional Opcional</span>
          </div>
          <h3 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
            Ensaios Fotográficos Digitais
          </h3>
          <p className="text-xs sm:text-sm text-[#4B2E20]/75">
            Você pode adicionar um ensaio temático ao seu pedido para a foto de capa do convite, sem precisar ir a um estúdio!
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
            <Card
              key={ensaio.id}
              className="bg-white/90 border-[#D4AF37]/30 rounded-2xl overflow-hidden shadow-sm flex flex-col justify-between"
            >
              <div>
                <div className="h-44 overflow-hidden relative">
                  <img
                    src={ensaio.foto}
                    alt={ensaio.titulo}
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute top-2 right-2 bg-[#4B2E20]/80 text-[#D4AF37] text-[10px] font-bold px-2 py-0.5 rounded-full">
                    R$ {ensaio.preco.toFixed(2)}
                  </div>
                </div>
                <div className="p-3.5 space-y-1">
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20]">{ensaio.titulo}</h4>
                  <p className="text-[11px] text-[#4B2E20]/70">{ensaio.subtitulo}</p>
                  <p className="text-[10px] text-[#4B2E20]/60 line-clamp-2 mt-1">{ensaio.descricao}</p>
                </div>
              </div>
            </Card>
          ))}
        </div>
      </section>

      {/* MODAL DE PEDIDO DA CLIENTE */}
      <ClientOrderModal
        isOpen={Boolean(selectedTemplateForOrder)}
        template={selectedTemplateForOrder}
        onClose={() => setSelectedTemplateForOrder(null)}
        onSubmitOrder={(order) => {
          onOpenOrderModal(selectedTemplateForOrder!);
          setSelectedTemplateForOrder(null);
        }}
      />

      {/* MODAL DA ADMINISTRADORA: EDITAR MODELO (FOTOS, VÍDEO, VALORES, PROMOÇÃO) */}
      {editingTemplate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
            <div className="border-b border-[#D4AF37]/25 flex items-center justify-between p-4 bg-[#ecdccb]/60">
              <div className="flex items-center gap-2">
                <Edit className="w-5 h-5 text-[#D4AF37]" />
                <h3 className="font-serif font-bold text-base text-[#4B2E20]">
                  Editar Modelo: {editingTemplate.title}
                </h3>
              </div>
              <button
                onClick={() => setEditingTemplate(null)}
                className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20]"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSaveEdit} className="p-5 space-y-4 overflow-y-auto text-xs text-[#4B2E20]">
              <div>
                <label className="block font-semibold mb-1">Título do Modelo</label>
                <Input
                  required
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 rounded-xl"
                />
              </div>

              {/* Upload de Imagem e Link */}
              <div className="p-3.5 bg-white/90 border border-[#D4AF37]/30 rounded-2xl space-y-3">
                <div className="flex items-center justify-between">
                  <span className="font-bold flex items-center gap-1.5">
                    <ImageIcon className="w-4 h-4 text-[#D4AF37]" />
                    Foto / Capa do Convite
                  </span>
                  <input
                    type="file"
                    ref={editFileInputRef}
                    onChange={handleUploadImageFile}
                    accept="image/*"
                    className="hidden"
                  />
                  <Button
                    type="button"
                    size="sm"
                    onClick={() => editFileInputRef.current?.click()}
                    className="bg-[#D4AF37] hover:bg-[#c29c2a] text-[#4B2E20] font-bold text-[11px] rounded-xl flex items-center gap-1"
                  >
                    <Upload className="w-3 h-3" />
                    Enviar Nova Foto do Computador
                  </Button>
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20]/70 mb-1">
                    Ou digite o Link direto da imagem (URL):
                  </label>
                  <Input
                    value={editImageUrl}
                    onChange={(e) => setEditImageUrl(e.target.value)}
                    placeholder="https://..."
                    className="bg-white border-[#D4AF37]/30 rounded-xl text-xs"
                  />
                </div>

                {editImageUrl && (
                  <div className="h-32 w-full rounded-xl overflow-hidden border border-[#D4AF37]/30">
                    <img src={editImageUrl} alt="Preview" className="w-full h-full object-cover" />
                  </div>
                )}
              </div>

              {/* Vídeo do Convite */}
              <div className="p-3.5 bg-white/90 border border-[#D4AF37]/30 rounded-2xl space-y-2">
                <span className="font-bold flex items-center gap-1.5">
                  <FileVideo className="w-4 h-4 text-[#D4AF37]" />
                  Vídeo do Convite (Opcional - link do MP4/Instagram/YouTube)
                </span>
                <Input
                  value={editVideoUrl}
                  onChange={(e) => setEditVideoUrl(e.target.value)}
                  placeholder="https://exemplo.com/convite-animado.mp4"
                  className="bg-white border-[#D4AF37]/30 rounded-xl text-xs"
                />
              </div>

              {/* Valores e Promoção */}
              <div className="p-3.5 bg-[#faf5ee] border border-[#D4AF37]/40 rounded-2xl space-y-3">
                <div className="flex items-center justify-between">
                  <span className="font-bold flex items-center gap-1.5">
                    <Tag className="w-4 h-4 text-[#D4AF37]" />
                    Configuração de Preço & Promoção
                  </span>

                  <label className="flex items-center gap-2 cursor-pointer font-bold text-xs text-rose-700 bg-rose-50 px-2.5 py-1 rounded-xl border border-rose-300">
                    <input
                      type="checkbox"
                      checked={editIsPromotion}
                      onChange={(e) => setEditIsPromotion(e.target.checked)}
                      className="rounded accent-rose-600"
                    />
                    <span>Ativar Promoção</span>
                  </label>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold mb-1">
                      Preço de Venda Atual (R$) *
                    </label>
                    <Input
                      type="number"
                      step="1"
                      required
                      value={editPrice}
                      onChange={(e) => setEditPrice(Number(e.target.value))}
                      className="bg-white border-[#D4AF37]/50 font-bold text-sm text-[#4B2E20] rounded-xl"
                    />
                  </div>

                  {editIsPromotion && (
                    <div>
                      <label className="block font-semibold mb-1 text-rose-800">
                        Preço Original "De: R$" (Riscado)
                      </label>
                      <Input
                        type="number"
                        step="1"
                        value={editOriginalPrice}
                        onChange={(e) => setEditOriginalPrice(Number(e.target.value))}
                        className="bg-white border-rose-300 font-bold text-sm text-rose-800 rounded-xl"
                      />
                    </div>
                  )}
                </div>
              </div>

              {/* Categoria e Formato */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold mb-1">Categoria / Ocasião</label>
                  <select
                    value={editCategory}
                    onChange={(e) => setEditCategory(e.target.value as InvitationCategory)}
                    className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium"
                  >
                    <option value="Infantil">Infantil</option>
                    <option value="Casamento">Casamento</option>
                    <option value="15 Anos">15 Anos</option>
                    <option value="Batizado">Batizado</option>
                    <option value="Corporativo">Corporativo</option>
                    <option value="Bodas">Bodas</option>
                  </select>
                </div>

                <div>
                  <label className="block font-semibold mb-1">Formato</label>
                  <select
                    value={editFormat}
                    onChange={(e) => setEditFormat(e.target.value as DigitalFormat)}
                    className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium"
                  >
                    <option value="imagem_card">Card em Imagem (WhatsApp)</option>
                    <option value="interativo_pdf">Interativo com Botões (PDF)</option>
                    <option value="animado_video">Vídeo Animado com Música</option>
                    <option value="save_the_date">Save The Date</option>
                    <option value="kit_digital">Kit Digital Completo</option>
                    <option value="site_rsvp">Página Web</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block font-semibold mb-1">Descrição</label>
                <textarea
                  rows={2}
                  value={editDescription}
                  onChange={(e) => setEditDescription(e.target.value)}
                  className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] resize-none"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-2 border-t border-[#D4AF37]/20">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setEditingTemplate(null)}
                  className="text-[#4B2E20] rounded-xl text-xs"
                >
                  Cancelar
                </Button>
                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-sm"
                >
                  Salvar Alterações
                </Button>
              </div>
            </form>
          </Card>
        </div>
      )}
    </div>
  );
}

