import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';

export default function App() {
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Navegação
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');

  // Autenticação Administrativa
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState<boolean>(false);

  // Modais de Criação
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [preSelectedTemplate, setPreSelectedTemplate] = useState<InvitationTemplate | null>(null);

  // Contagem de pedidos pendentes para notificação
  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente').length;

  const handleOpenAdminAuth = () => {
    setIsAdminModalOpen(true);
  };

  const handleAdminSuccess = () => {
    setIsAdminAuthenticated(true);
    setIsAdminModalOpen(false);
    setCurrentTab('orders'); // Redireciona diretamente para a visualização dos pedidos
  };

  const handleLogoutAdmin = () => {
    setIsAdminAuthenticated(false);
    setCurrentTab('templates');
  };

  // Quando o cliente faz o pedido pelo formulário do catálogo
  const handleClientOrderSubmission = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  // Pedido manual aberto pelo admin
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleSaveTemplate = (newTemplate: InvitationTemplate) => {
    setTemplates((prev) => [newTemplate, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: Order['status']) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status } : order))
    );
  };

  const handleUpdatePaymentStatus = (orderId: string, paymentStatus: Order['paymentStatus']) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, paymentStatus } : order))
    );
  };

  const handleDeleteOrder = (orderId: string) => {
    setOrders((prev) => prev.filter((order) => order.id !== orderId));
  };

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] font-sans flex flex-col selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={handleOpenAdminAuth}
        onLogoutAdmin={handleLogoutAdmin}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => setIsNewTemplateModalOpen(true)}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onOrderTemplate={(tmpl) => {
              setPreSelectedTemplate(tmpl);
              setIsNewOrderModalOpen(true);
            }}
            onSubmitClientOrder={handleClientOrderSubmission}
            isAdmin={isAdminAuthenticated}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onUpdatePaymentStatus={handleUpdatePaymentStatus}
            onDeleteOrder={handleDeleteOrder}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}

        {currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Delicado */}
      <footer className="border-t border-[#D4AF37]/25 bg-[#ecdccb]/40 py-6 text-center text-xs text-[#4B2E20]/70">
        <p className="font-serif">Keh Convites • Convites Digitais & Arte com Afeto</p>
        <p className="text-[11px] mt-1 text-[#4B2E20]/50">
          Chave PIX Oficial: 32998040080
        </p>
      </footer>

      {/* Modais de Gestão e Segurança */}
      <AdminLoginModal
        isOpen={isAdminModalOpen}
        onClose={() => setIsAdminModalOpen(false)}
        onSuccess={handleAdminSuccess}
      />

      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => {
          setIsNewOrderModalOpen(false);
          setPreSelectedTemplate(null);
        }}
        templates={templates}
        preSelectedTemplate={preSelectedTemplate}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => setIsNewTemplateModalOpen(false)}
        onSaveTemplate={handleSaveTemplate}
      />
    </div>
  );
}

