import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Heart, Sparkles, Instagram, MessageCircle, ShieldCheck } from 'lucide-react';

export default function App() {
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Controle de Abas e Autenticação
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);

  // Modais de Criação e Edição
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [templateToEdit, setTemplateToEdit] = useState<InvitationTemplate | null>(null);

  // Ações de Pedidos
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => {
        if (order.id === orderId) {
          const isFinished = status === 'concluido';
          return {
            ...order,
            status,
            paidValue: isFinished ? order.totalValue : order.paidValue,
            paymentStatus: isFinished ? 'pago' : order.paymentStatus,
          };
        }
        return order;
      })
    );
  };

  // Ações de Templates (Cadastrar ou Editar)
  const handleSaveTemplate = (savedTemplate: InvitationTemplate) => {
    setTemplates((prev) => {
      const exists = prev.some((t) => t.id === savedTemplate.id);
      if (exists) {
        return prev.map((t) => (t.id === savedTemplate.id ? savedTemplate : t));
      }
      return [savedTemplate, ...prev];
    });
    setTemplateToEdit(null);
  };

  const handleOpenEditTemplate = (template: InvitationTemplate) => {
    setTemplateToEdit(template);
    setIsTemplateModalOpen(true);
  };

  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente' || o.status === 'em_criacao').length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminModalOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => {
          setTemplateToEdit(null);
          setIsTemplateModalOpen(true);
        }}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 pt-6">
        {/* Aviso se estiver na área administrativa */}
        {isAdminAuthenticated && (
          <div className="mb-6 p-3 rounded-2xl bg-[#ecdccb]/80 border border-[#D4AF37]/40 flex flex-wrap items-center justify-between gap-3 text-xs">
            <div className="flex items-center gap-2 text-[#4B2E20] font-semibold">
              <ShieldCheck className="w-4 h-4 text-[#D4AF37]" />
              <span>Modo Administradora Ativo: você pode editar modelos, fotos, vídeos, promoções e ver todos os detalhes dos pedidos.</span>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => {
                  setTemplateToEdit(null);
                  setIsTemplateModalOpen(true);
                }}
                className="px-3 py-1 bg-[#4B2E20] text-[#F7EBDD] rounded-xl font-bold hover:bg-[#392115] transition-colors"
              >
                + Cadastrar Modelo
              </button>
            </div>
          </div>
        )}

        {/* Visualização de Abas */}
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSubmitClientOrder={(newOrder) => {
              handleSaveOrder(newOrder);
            }}
            isAdminAuthenticated={isAdminAuthenticated}
            onEditTemplate={handleOpenEditTemplate}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}

        {currentTab === 'dashboard' && (
