  const [originalPrice, setOriginalPrice] = useState<number | undefined>(undefined);
  const [isPromo, setIsPromo] = useState(false);
  const [imageUrl, setImageUrl] = useState(
    'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80'
  );
  const [videoUrl, setVideoUrl] = useState('');
  const [description, setDescription] = useState('');
  const [tagsInput, setTagsInput] = useState('Digital, WhatsApp, Alta Resolução');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (templateToEdit) {
      setTitle(templateToEdit.title);
      setCategory(templateToEdit.category);
      setFormat(templateToEdit.format);
      setHasInteraction(templateToEdit.hasInteraction);
      setPrice(templateToEdit.price);
      setOriginalPrice(templateToEdit.originalPrice);
      setIsPromo(Boolean(templateToEdit.isPromo));
      setImageUrl(templateToEdit.imageUrl);
      setVideoUrl(templateToEdit.videoUrl || '');
      setDescription(templateToEdit.description || '');
      setTagsInput(templateToEdit.tags?.join(', ') || '');
    } else {
      setTitle('');
      setCategory('Casamento');
      setFormat('imagem_card');
      setHasInteraction(false);
      setPrice(49);
      setOriginalPrice(undefined);
      setIsPromo(false);
      setImageUrl('https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80');
      setVideoUrl('');
      setDescription('');
      setTagsInput('Digital, WhatsApp, Alta Resolução');
    }
  }, [templateToEdit, isOpen]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const isVideo = file.type.startsWith('video');
      const url = URL.createObjectURL(file);
      if (isVideo) {
        setVideoUrl(url);
      } else {
        setImageUrl(url);
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      alert('Por favor, informe o título do modelo.');
      return;
    }

    const tags = tagsInput
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);

    const savedTemplate: InvitationTemplate = {
      id: templateToEdit?.id || `tmpl-${Date.now()}`,
      title,
      category,
      format,
      price: Number(price) || 0,
      originalPrice: isPromo && originalPrice ? Number(originalPrice) : undefined,
      isPromo,
      imageUrl: imageUrl.trim() || 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80',
      videoUrl: videoUrl.trim() || undefined,
      description,
      tags,
      features: templateToEdit?.features || [
        'Personalização de texto e data',
        'Entrega direta no WhatsApp',
        'Sem limite de envios',
      ],
      timesUsed: templateToEdit?.timesUsed || 0,
      hasInteraction: hasInteraction || format === 'interativo_pdf' || format === 'site_rsvp',
    };

    onSaveTemplate(savedTemplate);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/65 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-xl w-full bg-[#fcf8f3] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-[#ecdccb]/50">
          <div>
            <CardTitle className="text-lg font-serif font-bold text-[#4B2E20] flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-[#D4AF37]" />
              <span>{templateToEdit ? 'Editar Modelo Cadastrado' : 'Cadastrar Novo Modelo Digital'}</span>
            </CardTitle>
            <p className="text-xs text-[#4B2E20]/70 font-medium mt-0.5">
              Keh Convites • Altere fotos, vídeos demonstrativos, valores e promoções
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        <CardContent className="overflow-y-auto p-6 space-y-4">
          <form onSubmit={handleSubmit} className="space-y-4 text-xs">
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Título do Modelo *
              </label>
              <Input
                required
                placeholder="Ex: Card Digital Floral Marsala ou Vídeo Safári"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Formato / Tipo do Convite Digital
                </label>
                <select
                  value={format}
                  onChange={(e) => {
                    const fmt = e.target.value as DigitalFormat;
                    setFormat(fmt);
                    const isInterativo = fmt === 'interativo_pdf' || fmt === 'site_rsvp';
                    setHasInteraction(isInterativo);
                  }}
                  className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                >
                  <option value="imagem_card">Card Digital (Foto / Imagem WhatsApp)</option>
                  <option value="interativo_pdf">Interativo em PDF (Botões Clicáveis)</option>
                  <option value="animado_video">Vídeo Animado (com Música MP4)</option>
                  <option value="save_the_date">Save The Date Digital</option>
                  <option value="kit_digital">Kit Digital Completo (Combo)</option>
                  <option value="site_rsvp">Página Web do Evento</option>
                </select>
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Ocasião / Categoria
                </label>
                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value as InvitationCategory)}
                  className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                >
                  <option value="Casamento">Casamento</option>
                  <option value="15 Anos">15 Anos</option>
                  <option value="Infantil">Infantil</option>
                  <option value="Batizado">Batizado</option>
                  <option value="Corporativo">Corporativo</option>
                  <option value="Bodas">Bodas</option>
                </select>
              </div>
            </div>

            {/* Configuração de Preço e Promoção */}
            <div className="p-3.5 bg-[#ecdccb]/40 border border-[#D4AF37]/35 rounded-2xl space-y-3">
              <div className="flex items-center justify-between">
                <span className="font-semibold text-[#4B2E20] flex items-center gap-1.5 text-xs">
                  <Tag className="w-4 h-4 text-[#D4AF37]" />
                  Valores & Oferta
                </span>
                <label className="flex items-center gap-2 cursor-pointer text-xs font-bold text-[#4B2E20]">
                  <input
                    type="checkbox"
                    checked={isPromo}
                    onChange={(e) => {
                      setIsPromo(e.target.checked);
                      if (e.target.checked && !originalPrice) {
                        setOriginalPrice(price + 20);
                      }
                    }}
                    className="w-4 h-4 text-[#D4AF37] accent-[#4B2E20] rounded"
                  />
                  <span>Ativar Preço Promocional 🔥</span>
                </label>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-[#4B2E20] mb-1 font-semibold">
                    {isPromo ? 'Preço Promocional Atual (R$) *' : 'Preço de Venda (R$) *'}
                  </label>
                  <Input
                    type="number"
                    step="1"
                    required
                    value={price}
                    onChange={(e) => setPrice(Number(e.target.value))}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] font-bold rounded-xl text-sm"
                  />
                </div>

                {isPromo && (
                  <div>
                    <label className="block text-[#4B2E20] mb-1 font-semibold">
                      Preço Normal / Antigo (De R$)
                    </label>
                    <Input
                      type="number"
                      step="1"
                      placeholder="Ex: 59"
                      value={originalPrice || ''}
                      onChange={(e) => setOriginalPrice(Number(e.target.value))}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-sm"
                    />
                    <p className="text-[10px] text-[#4B2E20]/70 mt-1">
                      Aparecerá riscado no catálogo como &quot;De R$ {originalPrice || 0} Por R$ {price}&quot;.
                    </p>
                  </div>
                )}
              </div>
            </div>

            {/* Foto e Vídeo do Modelo */}
            <div className="p-3.5 bg-white border border-[#D4AF37]/35 rounded-2xl space-y-3">
              <span className="font-semibold text-[#4B2E20] flex items-center gap-1.5 text-xs">
                <ImageIcon className="w-4 h-4 text-[#D4AF37]" />
                Foto e Vídeo do Convite
              </span>

              <div className="space-y-2">
                <div>
                  <label className="block text-[#4B2E20] mb-1 font-semibold">
                    Link da Imagem / Foto de Capa (URL)
                  </label>
                  <Input
                    placeholder="https://exemplo.com/foto-modelo.jpg"
                    value={imageUrl}
                    onChange={(e) => setImageUrl(e.target.value)}
                    className="bg-[#faf5ee] border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-[#4B2E20] mb-1 font-semibold flex items-center gap-1">
                    <Video className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Link do Vídeo / Demonstração (opcional para vídeo animado)</span>
                  </label>
                  <Input
                    placeholder="https://exemplo.com/video-demo.mp4 ou YouTube/Drive"
                    value={videoUrl}
                    onChange={(e) => setVideoUrl(e.target.value)}
                    className="bg-[#faf5ee] border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                <div className="pt-1">
                  <input
                    type="file"
                    ref={fileInputRef}
                    accept="image/*,video/*"
                    onChange={handleFileUpload}
                    className="hidden"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => fileInputRef.current?.click()}
                    className="w-full border-dashed border-[#D4AF37] text-[#4B2E20] hover:bg-[#faf5ee] text-xs h-9 rounded-xl flex items-center justify-center gap-2"
                  >
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Enviar Arquivo do Computador / Celular</span>
                  </Button>
                </div>

                {imageUrl && (
                  <div className="flex items-center gap-3 p-2 bg-[#faf5ee] rounded-xl border border-[#D4AF37]/20">
                    <img
                      src={imageUrl}
                      alt="Prévia"
                      className="w-14 h-14 object-cover rounded-lg border border-[#D4AF37]/30 shadow-xs"
                    />
                    <div className="text-[11px] text-[#4B2E20]">
                      <p className="font-semibold">Prévia da Imagem Selecionada</p>
                      <p className="text-[#4B2E20]/70 line-clamp-1">{imageUrl}</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Interação com botões */}
            <div className="flex items-center gap-2 p-3 bg-amber-50/70 border border-[#D4AF37]/30 rounded-xl">
              <input
                type="checkbox"
                id="checkHasInteraction"
                checked={hasInteraction}
                onChange={(e) => setHasInteraction(e.target.checked)}
                className="w-4 h-4 text-[#D4AF37] rounded accent-[#4B2E20]"
              />
              <label htmlFor="checkHasInteraction" className="text-xs text-[#4B2E20] font-medium cursor-pointer">
                Possui botões clicáveis / interação (RSVP, mapa, lista de presentes)
              </label>
            </div>

            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Descrição do Modelo
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Convite delicado com detalhes dourados e flores aquareladas..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full px-3 py-2 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-normal focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              />
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] text-xs rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl border border-[#D4AF37]/40 shadow-sm"
              >
                {templateToEdit ? 'Salvar Alterações' : 'Cadastrar Modelo'}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

