import React, { useState, useEffect, useRef } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Upload,
  Video,
  Image as ImageIcon,
  Trash2,
  Play,
  Percent,
  CheckCircle,
  Film,
} from 'lucide-react';

interface NewTemplateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSaveTemplate: (template: InvitationTemplate) => void;
  templateToEdit?: InvitationTemplate | null;
}

export function NewTemplateModal({
  isOpen,
  onClose,
  onSaveTemplate,
  templateToEdit,
}: NewTemplateModalProps) {
  if (!isOpen) return null;

  const [title, setTitle] = useState('');
  const [category, setCategory] = useState<InvitationCategory>('Casamento');
  const [format, setFormat] = useState<DigitalFormat>('imagem_card');
  const [hasInteraction, setHasInteraction] = useState(false);
  const [price, setPrice] = useState<number>(49);
  const [originalPrice, setOriginalPrice] = useState<number | ''>('');
  const [isPromo, setIsPromo] = useState(false);
  const [imageUrl, setImageUrl] = useState(
    'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80'
  );
  const [videoUrl, setVideoUrl] = useState('');
  const [description, setDescription] = useState('');
  const [tagsInput, setTagsInput] = useState('Digital, WhatsApp, Alta Resolução');

  // Nomes dos arquivos carregados do computador para feedback visual
  const [imageFileName, setImageFileName] = useState<string>('');
  const [videoFileName, setVideoFileName] = useState<string>('');

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (templateToEdit) {
      setTitle(templateToEdit.title || '');
      setCategory(templateToEdit.category || 'Casamento');
      setFormat(templateToEdit.format || 'imagem_card');
      setHasInteraction(Boolean(templateToEdit.hasInteraction));
      setPrice(templateToEdit.price || 49);
      setOriginalPrice(templateToEdit.originalPrice ?? '');
      setIsPromo(Boolean(templateToEdit.isPromotion));
      setImageUrl(templateToEdit.imageUrl || '');
      setVideoUrl(templateToEdit.videoUrl || '');
      setDescription(templateToEdit.description || '');
      setTagsInput(templateToEdit.tags?.join(', ') || 'Digital, WhatsApp');
      setImageFileName('');
      setVideoFileName('');
    } else {
      setTitle('');
      setCategory('Casamento');
      setFormat('imagem_card');
      setHasInteraction(false);
      setPrice(49);
      setOriginalPrice('');
      setIsPromo(false);
      setImageUrl('https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80');
      setVideoUrl('');
      setDescription('');
      setTagsInput('Digital, WhatsApp, Alta Resolução');
      setImageFileName('');
      setVideoFileName('');
    }
  }, [templateToEdit, isOpen]);

  // Upload de Foto / Capa do Computador
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFileName(file.name);
      const objectUrl = URL.createObjectURL(file);
      setImageUrl(objectUrl);
    }
  };

  // Upload de Vídeo do Computador
  const handleVideoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setVideoFileName(file.name);
      const objectUrl = URL.createObjectURL(file);
      setVideoUrl(objectUrl);
      // Se subiu um vídeo e o formato ainda for simples, sugere animado_video
      if (format === 'imagem_card') {
        setFormat('animado_video');
      }
    }
  };

  const handleRemoveVideo = () => {
    setVideoUrl('');
    setVideoFileName('');
    if (videoInputRef.current) videoInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      alert('Por favor, informe o título do modelo.');
      return;
    }

    const tags = tagsInput
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);

    const savedTemplate: InvitationTemplate = {
      id: templateToEdit?.id || `tmpl-${Date.now()}`,
      title,
      category,
      format,
      price: Number(price) || 0,
      originalPrice: isPromo && originalPrice !== '' ? Number(originalPrice) : undefined,
      isPromotion: isPromo,
      imageUrl: imageUrl.trim() || 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80',
      videoUrl: videoUrl.trim() || undefined,
      description,
      tags: tags.length > 0 ? tags : ['Digital', 'WhatsApp'],
      features: templateToEdit?.features || [
        'Personalização de texto e data',
        'Entrega direta no WhatsApp',
        'Sem limite de envios',
      ],
      timesUsed: templateToEdit?.timesUsed || 0,
      hasInteraction: hasInteraction || format === 'interativo_pdf' || format === 'site_rsvp',
    };

    onSaveTemplate(savedTemplate);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Cabeçalho */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/90 to-[#f7ebdd]/90 shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-[#4B2E20] flex items-center justify-center text-[#D4AF37] shadow-sm">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                {templateToEdit ? 'Editar Modelo de Convite' : 'Cadastrar Novo Modelo'}
              </CardTitle>
              <p className="text-[11px] text-[#4B2E20]/75 font-medium">
                Envie fotos e vídeos do seu computador, edite valores e promoções
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Corpo do Formulário */}
        <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-5 text-xs text-[#4B2E20]">
          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Título do Convite */}
            <div>
              <label className="block text-xs font-bold text-[#4B2E20] mb-1">
                Nome do Modelo *
              </label>
              <Input
                required
                placeholder="Ex: Convite Animado Realeza Dourada, Card Floral Minimalista..."
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-sm rounded-xl focus-visible:ring-[#D4AF37]"
              />
            </div>

            {/* SEÇÃO 1: FOTO & VÍDEO DO COMPUTADOR */}
            <div className="p-4 rounded-2xl bg-[#ecdccb]/35 border border-[#D4AF37]/30 space-y-4">
              <div className="flex items-center justify-between border-b border-[#D4AF37]/20 pb-2">
                <span className="font-bold text-[#4B2E20] flex items-center gap-1.5 text-xs">
                  <Upload className="w-4 h-4 text-[#D4AF37]" />
                  Mídias do Convite (Fotos e Vídeos do Computador)
                </span>
                <span className="text-[10px] text-[#4B2E20]/70 font-medium">
                  Upload local do seu PC
                </span>
              </div>

              {/* Upload de Foto (Capa / Imagem do Convite) */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 items-start">
                <div className="space-y-2">
                  <label className="block font-semibold text-[#4B2E20] text-[11px]">
                    1. Foto ou Capa Principal (Imagem)
                  </label>
                  <input
                    type="file"
                    ref={imageInputRef}
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => imageInputRef.current?.click()}
                    className="w-full bg-white border-[#D4AF37]/50 hover:bg-[#fbf5ed] text-[#4B2E20] rounded-xl text-xs py-2 h-auto flex items-center justify-center gap-2 shadow-sm"
                  >
                    <ImageIcon className="w-4 h-4 text-[#D4AF37]" />
                    <span>{imageFileName ? 'Trocar Imagem do PC' : 'Enviar Foto do Computador'}</span>
                  </Button>
                  {imageFileName && (
                    <p className="text-[10px] text-emerald-800 font-medium flex items-center gap-1">
                      <CheckCircle className="w-3 h-3 text-emerald-600" />
                      Arquivo: <span className="truncate">{imageFileName}</span>
                    </p>
                  )}
                  <p className="text-[10px] text-[#4B2E20]/60">
                    Formatos aceitos: JPG, PNG, WEBP.
                  </p>
                </div>

                {/* Preview da Foto */}
                <div className="flex items-center gap-3 bg-white/80 p-2.5 rounded-xl border border-[#D4AF37]/30">
                  <img
                    src={imageUrl || 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=400&q=80'}
                    alt="Prévia Foto"
                    className="w-16 h-20 object-cover rounded-lg border border-[#D4AF37]/40 shadow-xs shrink-0 bg-[#ecdccb]/50"
                  />
                  <div className="text-[11px] leading-tight">
                    <p className="font-semibold text-[#4B2E20]">Prévia da Capa</p>
                    <p className="text-[10px] text-[#4B2E20]/70 mt-1">
                      Essa foto aparecerá no catálogo para as clientes escolherem.
                    </p>
                  </div>
                </div>
              </div>

              {/* Upload de Vídeo do Computador */}
              <div className="pt-2 border-t border-[#D4AF37]/20 space-y-3">
                <div className="flex items-center justify-between">
                  <label className="block font-semibold text-[#4B2E20] text-[11px] flex items-center gap-1.5">
                    <Film className="w-3.5 h-3.5 text-[#D4AF37]" />
                    2. Vídeo do Convite (Vídeo animado com música do Computador)
                  </label>
                  {videoUrl && (
                    <button
                      type="button"
                      onClick={handleRemoveVideo}
                      className="text-red-700 hover:text-red-900 text-[10px] flex items-center gap-1 font-semibold transition-colors"
                    >
                      <Trash2 className="w-3 h-3" />
                      Remover vídeo
                    </button>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 items-start">
                  <div className="space-y-2">
                    <input
                      type="file"
                      ref={videoInputRef}
                      accept="video/mp4,video/webm,video/quicktime,video/*"
                      onChange={handleVideoUpload}
                      className="hidden"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => videoInputRef.current?.click()}
                      className="w-full bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] border border-[#D4AF37]/40 rounded-xl text-xs py-2.5 h-auto flex items-center justify-center gap-2 shadow-sm font-semibold"
                    >
                      <Video className="w-4 h-4 text-[#D4AF37]" />
                      <span>{videoUrl ? 'Substituir Vídeo do PC' : 'Enviar Vídeo do Computador (MP4)'}</span>
                    </Button>

                    {videoFileName && (
                      <p className="text-[10px] text-emerald-800 font-medium flex items-center gap-1">
                        <CheckCircle className="w-3 h-3 text-emerald-600" />
                        Vídeo carregado: <span className="truncate">{videoFileName}</span>
                      </p>
                    )}

                    <p className="text-[10px] text-[#4B2E20]/60">
                      Você pode enviar arquivos de vídeo gravados ou montados (MP4, MOV, WEBM) diretamente do seu computador!
                    </p>
                  </div>

                  {/* Player de Preview do Vídeo */}
                  <div className="bg-white/80 p-2.5 rounded-xl border border-[#D4AF37]/30 min-h-[90px] flex items-center justify-center">
                    {videoUrl ? (
                      <div className="w-full space-y-1">
                        <video
                          src={videoUrl}
                          controls
                          className="w-full max-h-36 rounded-lg bg-black/90 object-contain shadow-inner"
                        />
                        <span className="block text-[10px] text-center text-emerald-800 font-semibold">
                          ▶ Vídeo pronto para exibição
                        </span>
                      </div>
                    ) : (
                      <div className="text-center py-3 text-[#4B2E20]/60">
                        <Play className="w-6 h-6 mx-auto mb-1 text-[#D4AF37]/50" />
                        <span className="text-[11px] font-medium">Nenhum vídeo anexado ainda</span>
                        <p className="text-[9px] text-[#4B2E20]/50 mt-0.5">Opcional para modelos animados</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* SEÇÃO 2: VALORES E PROMOÇÃO */}
            <div className="p-4 rounded-2xl bg-white border border-[#D4AF37]/35 space-y-3">
              <div className="flex items-center justify-between">
                <span className="font-bold text-[#4B2E20] flex items-center gap-1.5 text-xs">
                  <Percent className="w-4 h-4 text-[#D4AF37]" />
                  Valores & Promoção
                </span>

                <label className="inline-flex items-center gap-2 cursor-pointer select-none">
                  <input
                    type="checkbox"
                    checked={isPromo}
                    onChange={(e) => setIsPromo(e.target.checked)}
                    className="w-4 h-4 rounded text-[#4B2E20] focus:ring-[#D4AF37]"
                  />
                  <span className="text-xs font-bold text-[#4B2E20] bg-amber-100/80 px-2 py-0.5 rounded-md border border-amber-300">
                    Ativar Promoção?
                  </span>
                </label>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                <div>
                  <label className="block text-[11px] font-bold text-[#4B2E20] mb-1">
                    Preço de Venda Final (R$) *
                  </label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs font-bold text-[#4B2E20]/70">
                      R$
                    </span>
                    <Input
                      type="number"
                      step="0.01"
                      required
                      value={price}
                      onChange={(e) => setPrice(Number(e.target.value))}
                      className="pl-9 bg-[#fcf8f3] border-[#D4AF37]/40 text-[#4B2E20] font-bold text-sm rounded-xl"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                    Preço Original / De R$ (Riscado na Promoção)
                  </label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs font-bold text-[#4B2E20]/50">
                      R$
                    </span>
                    <Input
                      type="number"
                      step="0.01"
                      disabled={!isPromo}
                      placeholder={isPromo ? 'Ex: 69.90' : 'Marque "Ativar Promoção"'}
                      value={originalPrice}
                      onChange={(e) => setOriginalPrice(e.target.value === '' ? '' : Number(e.target.value))}
                      className="pl-9 bg-[#fcf8f3] border-[#D4AF37]/40 text-[#4B2E20] text-sm rounded-xl disabled:opacity-50"
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* SEÇÃO 3: FORMATO, CATEGORIA E INTERAÇÃO */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Formato do Convite Digital
                </label>
                <select
                  value={format}
                  onChange={(e) => {
                    const fmt = e.target.value as DigitalFormat;
                    setFormat(fmt);
                    const isInterativo = fmt === 'interativo_pdf' || fmt === 'site_rsvp';
                    setHasInteraction(isInterativo);
                  }}
                  className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                >
                  <option value="imagem_card">Card Digital (Foto / Imagem WhatsApp)</option>
                  <option value="animado_video">Vídeo Animado (com Música / MP4)</option>
                  <option value="interativo_pdf">Interativo em PDF (com Botões Clicáveis)</option>
                  <option value="save_the_date">Save The Date Digital</option>
                  <option value="kit_digital">Kit Digital Completo (Combo)</option>
                  <option value="site_rsvp">Página Web do Evento</option>
                </select>
              </div>

              <div>
                <label className="block text-[#4B2E20] mb-1 font-semibold">
                  Categoria / Ocasião
                </label>
                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value as InvitationCategory)}
                  className="w-full h-10 px-3 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
                >
                  <option value="Casamento">Casamento</option>
                  <option value="15 Anos">15 Anos</option>
                  <option value="Infantil">Infantil</option>
                  <option value="Batizado">Batizado</option>
                  <option value="Corporativo">Corporativo</option>
                  <option value="Bodas">Bodas</option>
                </select>
              </div>
            </div>

            {/* Opção se tem botões interativos */}
            <div className="p-3 bg-white rounded-xl border border-[#D4AF37]/30 flex items-center justify-between">
              <div>
                <p className="font-bold text-[#4B2E20] text-xs">Possui botões clicáveis?</p>
                <p className="text-[10px] text-[#4B2E20]/70">
                  Ex: Botão de confirmar presença, localização no Maps e lista de presentes.
                </p>
              </div>
              <label className="inline-flex items-center gap-1.5 cursor-pointer">
                <input
                  type="checkbox"
                  checked={hasInteraction}
                  onChange={(e) => setHasInteraction(e.target.checked)}
                  className="w-4 h-4 rounded text-[#4B2E20] focus:ring-[#D4AF37]"
                />
                <span className="text-xs font-semibold text-[#4B2E20]">
                  {hasInteraction ? 'Sim (Interativo)' : 'Não (Simples)'}
                </span>
              </label>
            </div>

            {/* Descrição */}
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Descrição ou Detalhes para a Cliente
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Convite digital personalizado de alta definição, pronto para enviar pelo WhatsApp aos seus convidados."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full p-2.5 rounded-xl bg-white border border-[#D4AF37]/40 text-xs text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
              />
            </div>

            {/* Tags */}
            <div>
              <label className="block text-[#4B2E20] mb-1 font-semibold">
                Tags de Busca (separadas por vírgula)
              </label>
              <Input
                placeholder="Digital, WhatsApp, Princesa, Safári, Florais"
                value={tagsInput}
                onChange={(e) => setTagsInput(e.target.value)}
                className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
              />
            </div>

            {/* Botões do Rodapé */}
            <div className="pt-3 border-t border-[#D4AF37]/25 flex items-center justify-end gap-2.5">
              <Button
                type="button"
                variant="ghost"
                onClick={onClose}
                className="text-[#4B2E20] rounded-xl text-xs"
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold rounded-xl text-xs border border-[#D4AF37]/40 shadow-sm px-6 py-2.5 flex items-center gap-2"
              >
                <Sparkles className="w-4 h-4 text-[#D4AF37]" />
                <span>{templateToEdit ? 'Salvar Alterações do Modelo' : 'Cadastrar Modelo'}</span>
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

