                </div>

                <div className="grid grid-cols-1 gap-3">
                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-[#D4AF37]" />
