              <div className="p-3 bg-white rounded-2xl border border-[#D4AF37]/30 space-y-2">
                <div className="flex items-center justify-between">
                  <label className="font-semibold text-[#4B2E20] text-xs flex items-center gap-1.5">
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
