                  </label>
                  {fotoPreview && (
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="text-red-700 hover:text-red-900 text-[11px] font-medium"
                    >
                      Remover foto
                    </button>
                  )}
                </div>

                <input
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
