                )}
              </div>

              {/* WhatsApp do Cliente */}
              <div>
                <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                  <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                  Seu WhatsApp para Receber a Prévia e o Convite Pronto *
                </label>
                <Input
                  required
                  placeholder="Ex: (32) 99804-0080"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                />
              </div>

              {/* Totalizador e Botão de Prosseguir */}
              <div className="pt-3 border-t border-[#D4AF37]/25 flex items-center justify-between">
                <div>
                  <span className="text-[11px] text-[#4B2E20]/75 block">Valor Total:</span>
                  <span className="text-xl font-serif font-bold text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-md border border-[#D4AF37]/50 px-5 py-2.5 flex items-center gap-2"
                >
                  <span>Ir para Pagamento PIX</span>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                </Button>
              </div>
            </form>
          )}

          {/* ETAPA 2: PAGAMENTO VIA PIX */}
          {etapa === 'pagamento_pix' && (
            <div className="space-y-6 text-center animate-fade-in py-2">
              <div className="w-16 h-16 rounded-2xl bg-emerald-100 border border-emerald-300 mx-auto flex items-center justify-center text-emerald-800 shadow-sm">
                <QrCode className="w-8 h-8" />
              </div>

              <div>
                <h3 className="text-xl font-serif font-bold text-[#4B2E20]">
                  Chave PIX da Keh Convites
                </h3>
                <p className="text-xs text-[#4B2E20]/75 mt-1 max-w-md mx-auto">
                  Faça o pagamento no seu aplicativo do banco para iniciarmos a produção do seu convite com carinho!
                </p>
              </div>

              {/* Caixa com o valor e a chave */}
              <div className="bg-white p-5 rounded-2xl border border-[#D4AF37]/40 shadow-sm max-w-md mx-auto space-y-3">
                <div className="flex items-center justify-between border-b border-[#D4AF37]/20 pb-2">
                  <span className="text-xs text-[#4B2E20]/70 font-medium">Valor a Pagar:</span>
                  <span className="text-lg font-serif font-bold text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <div className="text-left space-y-1">
                  <span className="text-[11px] font-semibold text-[#4B2E20]">
                    Chave PIX (Telefone / Celular):
                  </span>
                  <div className="flex items-center justify-between bg-[#fcf8f3] p-2.5 rounded-xl border border-[#D4AF37]/30">
                    <span className="font-mono font-bold text-sm text-[#4B2E20]">
                      {CHAVE_PIX_KEH}
                    </span>
                    <Button
                      size="sm"
                      onClick={handleCopiarPix}
                      className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] text-xs font-semibold rounded-lg px-3 py-1 h-auto flex items-center gap-1.5"
                    >
                      {pixCopiado ? (
                        <>
                          <CheckCheck className="w-3.5 h-3.5 text-emerald-400" />
                          <span>Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy className="w-3.5 h-3.5 text-[#D4AF37]" />
                          <span>Copiar Chave</span>
                        </>
                      )}
                    </Button>
                  </div>
                </div>

                <div className="pt-2 text-left text-[11px] text-[#4B2E20]/70 space-y-1">
                  <p className="flex items-center gap-1">
                    <ShieldCheck className="w-3.5 h-3.5 text-emerald-700" />
                    <strong>Titular:</strong> Keh Convites
                  </p>
                  <p className="flex items-center gap-1">
                    <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <strong>Cliente:</strong> {nomeAniversariante}
                  </p>
                </div>
              </div>

              {/* Botões de navegação */}
              <div className="flex items-center justify-center gap-3 pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setEtapa('formulario')}
                  className="border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs flex items-center gap-1.5"
                >
                  <ArrowLeft className="w-3.5 h-3.5" />
                  <span>Voltar / Revisar Dados</span>
                </Button>

                <Button
                  type="button"
                  onClick={() => setEtapa('concluido')}
                  className="bg-emerald-800 hover:bg-emerald-900 text-white font-bold text-xs rounded-xl px-5 py-2.5 shadow-md flex items-center gap-2"
                >
                  <CheckCircle2 className="w-4 h-4 text-emerald-300" />
                  <span>Já Fiz o Pagamento</span>
                </Button>
              </div>
            </div>
          )}

          {/* ETAPA 3: CONCLUÍDO */}
          {etapa === 'concluido' && (
            <div className="text-center py-6 space-y-4 animate-fade-in">
              <div className="w-16 h-16 rounded-full bg-emerald-100 text-emerald-800 mx-auto flex items-center justify-center border border-emerald-300">
                <CheckCircle2 className="w-8 h-8" />
              </div>

              <h3 className="text-xl font-serif font-bold text-[#4B2E20]">
                Pedido Registrado com Sucesso!
              </h3>

              <p className="text-xs text-[#4B2E20]/80 max-w-md mx-auto leading-relaxed">
                Muito obrigada, <strong>{nomeAniversariante}</strong>! Seu pedido já está registrado em nossa produção. Vamos conferir os detalhes e enviar a prévia personalizada no seu WhatsApp <strong>{whatsappCliente}</strong>.
              </p>

              <div className="p-3 bg-[#ecdccb]/50 rounded-2xl border border-[#D4AF37]/30 max-w-sm mx-auto text-xs font-semibold text-[#4B2E20]">
                Prazo estimado de envio da prévia: em até 24 a 48 horas úteis.
              </div>

              <div className="pt-4">
                <Button
                  onClick={handleConcluirEFechar}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl px-6 py-2.5 shadow-sm"
                >
                  Fechar Janela
                </Button>
              </div>
            </div>
          )}

        </CardContent>
      </Card>
    </div>
  );
}

