import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { Sparkles, Heart } from 'lucide-react';

export default function App() {
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Navegação
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');

  // Autenticação da administradora
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState<boolean>(false);

  // Modais de Criação e Edição
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState<boolean>(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState<boolean>(false);
  const [templateToEdit, setTemplateToEdit] = useState<InvitationTemplate | null>(null);

  // Contador de pedidos pendentes
  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente' || o.status === 'em_criacao').length;

  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string, newStatus: Order['status']) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status: newStatus } : order))
    );
  };

  const handleUpdateOrderPayment = (
    orderId: string,
    paymentStatus: Order['paymentStatus'],
    paidValue: number
  ) => {
    setOrders((prev) =>
      prev.map((order) =>
        order.id === orderId ? { ...order, paymentStatus, paidValue } : order
      )
    );
  };

  const handleSaveTemplate = (templateData: InvitationTemplate) => {
    setTemplates((prev) => {
      const exists = prev.some((t) => t.id === templateData.id);
      if (exists) {
        return prev.map((t) => (t.id === templateData.id ? templateData : t));
      }
      return [templateData, ...prev];
    });
    setTemplateToEdit(null);
  };

  const handleOpenEditTemplate = (template: InvitationTemplate) => {
    setTemplateToEdit(template);
    setIsTemplateModalOpen(true);
  };

  const handleSelectTemplateForClient = (template: InvitationTemplate) => {
    // Registra pedido e mantém usuário atualizado
    // O modal da cliente já chama onSubmitOrder
  };

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Barra de Navegação Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminModalOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => {
          setTemplateToEdit(null);
          setIsTemplateModalOpen(true);
        }}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-fade-in">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            onSelectTemplate={handleSaveOrder}
            onEditTemplate={isAdminAuthenticated ? handleOpenEditTemplate : undefined}
            isAdmin={isAdminAuthenticated}
          />
        )}

        {currentTab === 'orders' && isAdminAuthenticated && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdateOrderPayment}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}

        {currentTab === 'dashboard' && isAdminAuthenticated && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Delicado e Artesanal */}
      <footer className="mt-auto border-t border-[#D4AF37]/35 bg-[#ecdccb]/50 py-8 px-4 text-center">
        <div className="max-w-7xl mx-auto flex flex-col items-center justify-center gap-2">
          <div className="flex items-center gap-1.5 text-sm font-serif font-bold text-[#4B2E20]">
            <span>Keh Convites</span>
            <span className="text-[#D4AF37]">•</span>
            <span className="font-normal text-xs text-[#4B2E20]/80">Convites Digitais Sob Medida</span>
          </div>
          <p className="text-xs text-[#4B2E20]/70 flex items-center justify-center gap-1">
            Feito com <Heart className="w-3.5 h-3.5 text-rose-700 fill-rose-700 inline" /> para tornar celebrações inesquecíveis.
          </p>
        </div>
      </footer>

      {/* Modais Globais */}
      <AdminLoginModal
        isOpen={isAdminModalOpen}
        onClose={() => setIsAdminModalOpen(false)}
        onSuccess={() => {
          setIsAdminAuthenticated(true);
          setIsAdminModalOpen(false);
          setCurrentTab('orders');
        }}
      />

      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => setIsNewOrderModalOpen(false)}
        templates={templates}
        onSaveOrder={handleSaveOrder}
      />

      <NewTemplateModal
        isOpen={isTemplateModalOpen}
        onClose={() => {
          setIsTemplateModalOpen(false);
          setTemplateToEdit(null);
        }}
        onSaveTemplate={handleSaveTemplate}
        templateToEdit={templateToEdit}
      />
    </div>
  );
}

