import React, { useState } from 'react';
import { Order, OrderStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Search,
  Eye,
  Trash2,
  Calendar,
  Clock,
  Phone,
  MessageCircle,
  FileText,
  MapPin,
  CheckCircle2,
  AlertCircle,
  Sparkles,
  Camera,
  X,
  CreditCard,
  User,
} from 'lucide-react';

export interface OrdersManagerProps {
  orders: Order[];
  onUpdateStatus?: (orderId: string, newStatus: OrderStatus) => void;
  onDeleteOrder: (orderId: string) => void;
  onOpenNewOrder?: () => void;
}

export function OrdersManager({
  orders,
  onUpdateStatus,
  onDeleteOrder,
  onOpenNewOrder,
}: OrdersManagerProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<string>('todos');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [pedidoParaExcluir, setPedidoParaExcluir] = useState<Order | null>(null);

  const safeOrders = orders || [];

  const pedidosFiltrados = safeOrders.filter((order) => {
    const matchBusca =
      order.clientName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.templateTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      order.clientWhatsapp?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (order.theme && order.theme.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchStatus = filtroStatus === 'todos' || order.status === filtroStatus;
    return matchBusca && matchStatus;
  });

  const getStatusBadge = (status: OrderStatus) => {
    switch (status) {
      case 'pendente':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-semibold bg-amber-100 text-amber-800 border border-amber-200">
            Pendente
          </span>
        );
      case 'em_criacao':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-semibold bg-blue-100 text-blue-800 border border-blue-200">
            Em Criação
          </span>
        );
      case 'aprovacao':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-semibold bg-purple-100 text-purple-800 border border-purple-200">
            Aguardando Aprovação
          </span>
        );
      case 'concluido':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-semibold bg-emerald-100 text-emerald-800 border border-emerald-200">
            Concluído
          </span>
        );
      case 'cancelado':
        return (
          <span className="px-2.5 py-1 rounded-full text-[11px] font-semibold bg-red-100 text-red-800 border border-red-200">
            Cancelado
          </span>
        );
      default:
        return null;
    }
  };

  const handleConfirmarExclusao = () => {
    if (pedidoParaExcluir) {
      onDeleteOrder(pedidoParaExcluir.id);
      if (selectedOrder?.id === pedidoParaExcluir.id) {
        setSelectedOrder(null);
      }
      setPedidoParaExcluir(null);
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Cabeçalho da Gestão de Pedidos */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-[#fdfbf7] p-6 rounded-3xl border border-[#D4AF37]/30 shadow-sm">
        <div>
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#ecdccb] text-[#4B2E20] text-xs font-semibold mb-2 border border-[#D4AF37]/30">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Gerenciamento de Pedidos • Keh Convites</span>
          </div>
          <h2 className="text-2xl font-serif font-bold text-[#4B2E20]">
            Pedidos dos Clientes
          </h2>
          <p className="text-xs text-[#4B2E20]/75 mt-0.5">
            Abra as informações completas para ver o que a cliente deseja ou exclua pedidos finalizados/antigos.
          </p>
        </div>

        {onOpenNewOrder && (
          <Button
            onClick={onOpenNewOrder}
            className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl shadow border border-[#D4AF37]/40"
          >
            + Registrar Pedido Manual
          </Button>
        )}
      </div>

      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white p-4 rounded-2xl border border-[#D4AF37]/25 shadow-sm">
        <div className="relative flex-1">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
          <input
            type="text"
            placeholder="Buscar por cliente, tema, WhatsApp ou modelo..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-xs rounded-xl border border-[#D4AF37]/35 bg-[#fdfbf7] text-[#4B2E20] focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
          {[
            { id: 'todos', label: 'Todos' },
            { id: 'pendente', label: 'Pendentes' },
            { id: 'em_criacao', label: 'Em Criação' },
            { id: 'concluido', label: 'Concluídos' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setFiltroStatus(item.id)}
              className={`px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                filtroStatus === item.id
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-[#fcf8f3] text-[#4B2E20]/70 hover:bg-[#ecdccb]/50'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>

      {/* Lista de Pedidos */}
      {pedidosFiltrados.length === 0 ? (
        <Card className="bg-white/95 border-[#D4AF37]/30 rounded-3xl p-12 text-center shadow-sm">
          <FileText className="w-12 h-12 text-[#D4AF37]/60 mx-auto mb-3" />
          <h3 className="font-serif font-bold text-lg text-[#4B2E20]">
            Nenhum pedido encontrado
          </h3>
          <p className="text-xs text-[#4B2E20]/70 mt-1 max-w-sm mx-auto">
            Quando os clientes preencherem o pedido no catálogo ou quando você registrar manualmente, eles aparecerão aqui.
          </p>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-3.5">
          {pedidosFiltrados.map((order) => (
            <Card
              key={order.id}
              className="bg-white hover:bg-[#fdfbf7] border-[#D4AF37]/30 rounded-2xl p-4 sm:p-5 shadow-sm transition-all hover:shadow-md flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"
            >
              <div className="space-y-1.5 flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <h3 className="font-serif font-bold text-base text-[#4B2E20] truncate">
                    {order.clientName}
                  </h3>
                  {getStatusBadge(order.status)}
                  {order.includeDigitalPhotoshoot && (
                    <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-[#D4AF37]/20 text-[#4B2E20] border border-[#D4AF37]/40 flex items-center gap-1">
                      <Camera className="w-3 h-3 text-[#D4AF37]" /> + Ensaio Digital
                    </span>
                  )}
                </div>

                <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-[#4B2E20]/75">
                  <span className="font-medium">
                    Modelo: <strong className="text-[#4B2E20]">{order.templateTitle}</strong>
                  </span>
                  {order.theme && (
                    <span>
                      Tema: <strong className="text-[#4B2E20]">{order.theme}</strong>
                    </span>
                  )}
                  {order.clientWhatsapp && (
                    <span className="flex items-center gap-1">
                      <Phone className="w-3 h-3 text-emerald-600" />
                      {order.clientWhatsapp}
                    </span>
                  )}
                  {order.eventDate && (
                    <span className="flex items-center gap-1">
                      <Calendar className="w-3 h-3 text-[#D4AF37]" />
                      Data: {order.eventDate}
                    </span>
                  )}
                </div>
              </div>

              {/* Valores e Ações */}
              <div className="flex items-center justify-between sm:justify-end gap-3 w-full sm:w-auto pt-2 sm:pt-0 border-t sm:border-t-0 border-[#D4AF37]/15">
                <div className="text-left sm:text-right">
                  <span className="text-[11px] text-[#4B2E20]/60 block font-medium">Valor Total</span>
                  <span className="font-serif font-bold text-base text-[#4B2E20]">
                    R$ {Number(order.totalValue || 0).toFixed(2)}
                  </span>
                </div>

                <div className="flex items-center gap-1.5">
                  {/* Botão Ver Informações Completas */}
                  <Button
                    size="sm"
                    onClick={() => setSelectedOrder(order)}
                    className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs px-3 py-1.5 rounded-xl border border-[#D4AF37]/35 flex items-center gap-1.5 shadow-sm"
                  >
                    <Eye className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <span>Ver Informações</span>
                  </Button>

                  {/* Botão Excluir Pedido */}
                  <button
                    onClick={() => setPedidoParaExcluir(order)}
                    title="Excluir este pedido"
                    className="p-2 rounded-xl text-red-500 hover:text-red-700 hover:bg-red-50 border border-transparent hover:border-red-200 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}

      {/* MODAL DETALHADO: "O que a cliente quer" */}
      {selectedOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
            <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/90 to-[#f7ebdd]/90 shrink-0">
              <div className="flex items-center gap-2.5">
                <div className="w-9 h-9 rounded-xl bg-[#4B2E20] flex items-center justify-center text-[#D4AF37] shadow-sm">
                  <User className="w-5 h-5" />
                </div>
                <div>
                  <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                    Detalhes do Pedido: {selectedOrder.clientName}
                  </CardTitle>
                  <p className="text-[11px] text-[#4B2E20]/75 font-medium">
                    Todas as informações fornecidas para confecção do convite
                  </p>
                </div>
              </div>
              <button
                onClick={() => setSelectedOrder(null)}
                className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </CardHeader>

            <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-4 text-xs text-[#4B2E20]">
              {/* Informações Principais */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 rounded-2xl bg-white border border-[#D4AF37]/25">
                <div>
                  <span className="text-[10px] text-[#4B2E20]/60 uppercase tracking-wider font-bold block">
                    Nome no Convite / Anfitrião
                  </span>
                  <span className="text-sm font-serif font-bold text-[#4B2E20] block mt-0.5">
                    {selectedOrder.clientName}
                  </span>
                </div>

                <div>
                  <span className="text-[10px] text-[#4B2E20]/60 uppercase tracking-wider font-bold block">
                    WhatsApp da Cliente
                  </span>
                  <a
                    href={`https://wa.me/55${selectedOrder.clientWhatsapp.replace(/\D/g, '')}`}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-flex items-center gap-1.5 text-xs font-bold text-emerald-700 hover:underline mt-0.5"
                  >
                    <MessageCircle className="w-3.5 h-3.5" />
                    {selectedOrder.clientWhatsapp}
                  </a>
                </div>

                <div>
                  <span className="text-[10px] text-[#4B2E20]/60 uppercase tracking-wider font-bold block">
                    Modelo Escolhido
                  </span>
                  <span className="font-semibold text-[#4B2E20] block mt-0.5">
                    {selectedOrder.templateTitle}
                  </span>
                </div>

                <div>
                  <span className="text-[10px] text-[#4B2E20]/60 uppercase tracking-wider font-bold block">
                    Tema da Festa
                  </span>
                  <span className="font-semibold text-[#4B2E20] block mt-0.5">
                    {selectedOrder.theme || 'Não informado'}
                  </span>
                </div>
              </div>

              {/* Data, Horário e Local */}
              <div className="p-4 rounded-2xl bg-white border border-[#D4AF37]/25 space-y-2">
                <h4 className="font-bold text-xs text-[#4B2E20] border-b border-[#D4AF37]/20 pb-1 flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5 text-[#D4AF37]" />
                  Dados do Evento
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1">
                  <div>
                    <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Data do Evento:</span>
                    <span className="font-medium text-[#4B2E20]">{selectedOrder.eventDate || 'A combinar'}</span>
                  </div>
                  <div>
                    <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Horário / Turno:</span>
                    <span className="font-medium text-[#4B2E20]">{selectedOrder.eventTime || 'Não especificado'}</span>
                  </div>
                  <div className="sm:col-span-2">
                    <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Local do Evento / Salão:</span>
                    <span className="font-medium text-[#4B2E20]">{selectedOrder.mapsLocation || 'Não especificado'}</span>
                  </div>
                  {selectedOrder.specialPhrase && (
                    <div className="sm:col-span-2">
                      <span className="text-[10px] text-[#4B2E20]/60 block font-semibold">Frase ou Versículo Solicitado:</span>
                      <span className="font-medium italic text-[#4B2E20]">"{selectedOrder.specialPhrase}"</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Botões do Convite / Interação */}
              {selectedOrder.hasInteraction && (
                <div className="p-4 rounded-2xl bg-[#ecdccb]/30 border border-[#D4AF37]/30 space-y-2">
                  <h4 className="font-bold text-xs text-[#4B2E20] border-b border-[#D4AF37]/20 pb-1 flex items-center gap-1.5">
                    <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Botões Clicáveis do Convite Interativo
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 pt-1 text-[11px]">
                    <div>
                      <span className="font-semibold block text-[#4B2E20]">RSVP (Confirmação):</span>
                      <span className="text-[#4B2E20]/80">{selectedOrder.rsvpContact || 'WhatsApp padrão'}</span>
                    </div>
                    <div>
                      <span className="font-semibold block text-[#4B2E20]">Localização / GPS:</span>
                      <span className="text-[#4B2E20]/80">{selectedOrder.mapsLocation || 'Definir link'}</span>
                    </div>
                    <div>
                      <span className="font-semibold block text-[#4B2E20]">Lista de Presentes:</span>
                      <span className="text-[#4B2E20]/80">{selectedOrder.giftList || 'Sem lista'}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Ensaio Digital Incluso */}
              {selectedOrder.includeDigitalPhotoshoot && (
                <div className="p-4 rounded-2xl bg-amber-50/70 border border-amber-200 space-y-1">
                  <div className="flex items-center gap-1.5 font-bold text-amber-900 text-xs">
                    <Camera className="w-4 h-4 text-[#D4AF37]" />
                    <span>Ensaio Digital Adicionado (+ R$ 25,00)</span>
                  </div>
                  <p className="text-[11px] text-amber-800">
                    Estilo escolhido:{' '}
                    <strong>{selectedOrder.photoshootDetails || 'Ensaio Temático'}</strong>
                  </p>
                </div>
              )}

              {/* Foto enviada pelo cliente */}
              {selectedOrder.photoUrl && (
                <div className="p-4 rounded-2xl bg-white border border-[#D4AF37]/25 space-y-2">
                  <h4 className="font-bold text-xs text-[#4B2E20] border-b border-[#D4AF37]/20 pb-1 flex items-center gap-1.5">
                    <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Foto enviada pela Cliente para o Convite / Ensaio
                  </h4>
                  <div className="pt-2 flex items-center gap-4">
                    <img
                      src={selectedOrder.photoUrl}
                      alt="Foto do cliente"
                      className="w-24 h-24 sm:w-32 sm:h-32 object-cover rounded-xl border border-[#D4AF37]/40 shadow-sm"
                    />
                    <div className="text-xs text-[#4B2E20]/80">
                      <p className="font-medium">Imagem anexada pela cliente no momento do pedido.</p>
                      <a
                        href={selectedOrder.photoUrl}
                        download={`foto-cliente-${selectedOrder.clientName}.jpg`}
                        target="_blank"
                        rel="noreferrer"
                        className="inline-block mt-2 text-xs font-bold text-[#4B2E20] underline hover:text-[#D4AF37]"
                      >
                        Abrir imagem em tamanho original
                      </a>
                    </div>
                  </div>
                </div>
              )}

              {/* Notas e Histórico de Pagamento */}
              {selectedOrder.notes && (
                <div className="p-3.5 rounded-2xl bg-[#ecdccb]/20 border border-[#D4AF37]/20 text-[11px] text-[#4B2E20]/80 leading-relaxed">
                  <strong className="block text-[#4B2E20] mb-0.5">Resumo Técnico do Pedido:</strong>
                  {selectedOrder.notes}
                </div>
              )}

              {/* Atualização de Status */}
              {onUpdateStatus && (
                <div className="pt-2 border-t border-[#D4AF37]/20 flex flex-wrap items-center justify-between gap-3">
                  <span className="font-bold text-xs text-[#4B2E20]">Status do Pedido:</span>
                  <div className="flex flex-wrap items-center gap-1.5">
                    {(['pendente', 'em_criacao', 'aprovacao', 'concluido', 'cancelado'] as OrderStatus[]).map((st) => (
                      <button
                        key={st}
                        onClick={() => {
                          onUpdateStatus(selectedOrder.id, st);
                          setSelectedOrder({ ...selectedOrder, status: st });
                        }}
                        className={`px-2.5 py-1 rounded-xl text-[11px] font-semibold transition-all ${
                          selectedOrder.status === st
                            ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                            : 'bg-white border border-[#D4AF37]/30 text-[#4B2E20]/70 hover:bg-[#ecdccb]/40'
                        }`}
                      >
                        {st === 'pendente'
                          ? 'Pendente'
                          : st === 'em_criacao'
                          ? 'Em Criação'
                          : st === 'aprovacao'
                          ? 'Aprovação'
                          : st === 'concluido'
                          ? 'Concluído'
                          : 'Cancelado'}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {/* Botões do Rodapé do Modal */}
              <div className="pt-4 flex items-center justify-between border-t border-[#D4AF37]/20">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setPedidoParaExcluir(selectedOrder)}
                  className="border-red-300 text-red-600 hover:bg-red-50 hover:text-red-700 text-xs rounded-xl flex items-center gap-1.5"
                >
                  <Trash2 className="w-3.5 h-3.5 text-red-500" />
                  <span>Excluir este Pedido</span>
                </Button>

                <Button
                  onClick={() => setSelectedOrder(null)}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl px-5"
                >
                  Fechar
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* MODAL DE CONFIRMAÇÃO DE EXCLUSÃO */}
      {pedidoParaExcluir && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/75 backdrop-blur-sm animate-fade-in">
          <Card className="max-w-md w-full bg-[#fdfbf7] border-red-300 shadow-2xl rounded-3xl overflow-hidden p-6 text-center space-y-4">
            <div className="w-12 h-12 rounded-full bg-red-100 text-red-600 flex items-center justify-center mx-auto">
              <Trash2 className="w-6 h-6" />
            </div>

            <div>
              <h3 className="font-serif font-bold text-lg text-[#4B2E20]">
                Excluir Pedido?
              </h3>
              <p className="text-xs text-[#4B2E20]/75 mt-1 leading-relaxed">
                Tem certeza que deseja excluir o pedido de{' '}
                <strong className="text-[#4B2E20]">{pedidoParaExcluir.clientName}</strong>?
                Essa ação removerá o pedido da sua lista administrativa.
              </p>
            </div>

            <div className="flex items-center justify-center gap-3 pt-2">
              <Button
                variant="ghost"
                onClick={() => setPedidoParaExcluir(null)}
                className="text-[#4B2E20] text-xs rounded-xl hover:bg-[#ecdccb]/50"
              >
                Cancelar
              </Button>
              <Button
                onClick={handleConfirmarExclusao}
                className="bg-red-600 hover:bg-red-700 text-white font-semibold text-xs rounded-xl shadow-sm px-4"
              >
                Sim, Excluir Pedido
              </Button>
            </div>
          </Card>
        </div>
      )}
    </div>
  );
}

