import React, { useState } from 'react';
import { InvitationTemplate, InvitationCategory, DigitalFormat } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ClientOrderModal } from '@/components/ClientOrderModal';
import {
  Sparkles,
  Heart,
  Check,
  Tag,
  ArrowRight,
  Filter,
  CheckCircle2,
  Video,
  FileText,
  FileCheck2,
  Camera,
  Play,
  X,
  Edit3,
} from 'lucide-react';

interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onSelectTemplate: (template: InvitationTemplate) => void;
  onEditTemplate?: (template: InvitationTemplate) => void;
  isAdmin?: boolean;
}

export const EXEMPLOS_ENSAIOS_CATALOGO = [
  {
    id: 'ensaio-cat-1',
    titulo: 'Ensaio Infantil Temático',
    tema: 'Safári, Bosque & Realeza',
    descricao: 'Transformamos a foto do seu filho(a) em um cenário de conto de fadas para o convite.',
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
    destaque: 'Ideal para 1º Aninho & Festas',
  },
  {
    id: 'ensaio-cat-2',
    titulo: 'Ensaio Princesa & Contos',
    tema: 'Vestido de Gala & Flores',
    descricao: 'Edição artística refinada com brilho suave e cores mágicas.',
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
    destaque: 'Muito pedido para 15 Anos',
  },
  {
    id: 'ensaio-cat-3',
    titulo: 'Ensaio Casal Pré-Wedding',
    tema: 'Pôr do Sol, Praia ou Campo',
    descricao: 'Retrato romântico e delicado em alta resolução para os noivos brilharem no convite.',
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
    destaque: 'Perfeito para Casamentos',
  },
];

export function TemplatesCatalog({
  templates,
  onSelectTemplate,
  onEditTemplate,
  isAdmin = false,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<InvitationCategory | 'Todas'>('Todas');
  const [selectedFormat, setSelectedFormat] = useState<DigitalFormat | 'Todos'>('Todos');
  const [searchTerm, setSearchTerm] = useState('');

  // Modal para a cliente preencher o formulário
  const [modalTemplate, setModalTemplate] = useState<InvitationTemplate | null>(null);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);

  // Modal para assistir vídeo demonstrativo
  const [videoModalUrl, setVideoModalUrl] = useState<string | null>(null);
  const [videoModalTitle, setVideoModalTitle] = useState<string>('');

  const categories: (InvitationCategory | 'Todas')[] = [
    'Todas',
    'Casamento',
    '15 Anos',
    'Infantil',
    'Batizado',
    'Corporativo',
  ];

  const formats: { value: DigitalFormat | 'Todos'; label: string }[] = [
    { value: 'Todos', label: 'Todos os Formatos' },
    { value: 'imagem_card', label: 'Card Simples (WhatsApp)' },
    { value: 'interativo_pdf', label: 'Interativo (Botões Clicáveis)' },
    { value: 'animado_video', label: 'Vídeo Animado' },
    { value: 'save_the_date', label: 'Save The Date' },
    { value: 'site_rsvp', label: 'Página Web' },
  ];

  const filteredTemplates = templates.filter((template) => {
    const matchesCategory =
      selectedCategory === 'Todas' || template.category === selectedCategory;
    const matchesFormat =
      selectedFormat === 'Todos' || template.format === selectedFormat;
    const matchesSearch =
      template.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      template.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      template.tags.some((t) => t.toLowerCase().includes(searchTerm.toLowerCase()));
    return matchesCategory && matchesFormat && matchesSearch;
  });

  const handleOpenClientOrder = (template: InvitationTemplate) => {
    setModalTemplate(template);
    setIsClientModalOpen(true);
  };

  const getFormatBadge = (template: InvitationTemplate) => {
    if (template.videoUrl || template.format === 'animado_video') {
      return {
        label: 'Vídeo Animado',
        color: 'bg-rose-100 text-[#4B2E20] border-rose-300 font-semibold',
        icon: Video,
      };
    }
    if (template.hasInteraction || template.format === 'interativo_pdf' || template.format === 'site_rsvp') {
      return {
        label: 'Interativo com Botões',
        color: 'bg-[#D4AF37]/20 text-[#4B2E20] border-[#D4AF37]/50 font-semibold',
        icon: FileCheck2,
      };
    }
    return {
      label: 'Convite Simples',
      color: 'bg-[#ecdccb]/80 text-[#4B2E20] border-[#D4AF37]/30 font-medium',
      icon: FileText,
    };
  };

  return (
    <div className="space-y-12">
      {/* Apresentação Inicial */}
      <section className="text-center max-w-3xl mx-auto pt-2 pb-2">
        <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-[#fcf8f3] border border-[#D4AF37]/45 text-[#4B2E20] text-xs font-serif font-medium mb-4 shadow-sm">
          <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
          <span>Convites Digitais Prontos para Enviar no WhatsApp</span>
        </div>

        <h1 className="text-3xl sm:text-4xl md:text-5xl font-serif font-bold text-[#4B2E20] tracking-tight leading-tight">
          Escolha seu Modelo Favorito
        </h1>

        <p className="mt-3 text-sm sm:text-base text-[#4B2E20]/80 leading-relaxed font-normal">
          Clique no modelo que você mais gostou para personalizar os dados do seu evento. 
          Criamos modelos <strong className="text-[#4B2E20]">simples em imagem</strong>, <strong className="text-[#4B2E20]">vídeos com música</strong> ou <strong className="text-[#4B2E20]">interativos com botões clicáveis</strong> de confirmação e localização!
        </p>
      </section>

      {/* Barra de Filtros */}
      <div className="bg-[#fcf8f3] p-4 sm:p-5 rounded-2xl border border-[#D4AF37]/35 shadow-sm space-y-3">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          {/* Categorias */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3.5 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                  selectedCategory === cat
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                    : 'bg-white text-[#4B2E20]/80 hover:bg-[#ecdccb]/50 border border-[#D4AF37]/25'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Formato */}
          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-[#D4AF37] shrink-0" />
            <select
              value={selectedFormat}
              onChange={(e) => setSelectedFormat(e.target.value as DigitalFormat | 'Todos')}
              className="text-xs bg-white border border-[#D4AF37]/35 rounded-xl px-3 py-1.5 text-[#4B2E20] font-medium focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
            >
              {formats.map((fmt) => (
                <option key={fmt.value} value={fmt.value}>
                  {fmt.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Campo de Busca Rápida */}
        <div>
          <input
            type="text"
            placeholder="Buscar por tema (ex: Realeza, Safári, Floral, Casamento, 15 Anos)..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full text-xs bg-white border border-[#D4AF37]/30 rounded-xl px-3.5 py-2 text-[#4B2E20] placeholder:text-[#4B2E20]/50 focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
          />
        </div>
      </div>

      {/* Grid de Modelos de Convites */}
      <div>
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-2">
            <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
              Catálogo de Convites
            </h2>
            <span className="text-xs font-semibold px-2.5 py-0.5 rounded-full bg-[#ecdccb] text-[#4B2E20]">
              {filteredTemplates.length} disponíveis
            </span>
          </div>
          <span className="text-xs text-[#4B2E20]/70 italic hidden sm:inline">
            Clique no modelo para personalizar
          </span>
        </div>

        {filteredTemplates.length === 0 ? (
          <div className="text-center py-12 bg-white/70 rounded-3xl border border-[#D4AF37]/30 p-8">
            <p className="text-base text-[#4B2E20] font-serif font-bold">Nenhum convite encontrado</p>
            <p className="text-xs text-[#4B2E20]/70 mt-1">Tente trocar a categoria ou limpar a busca.</p>
            <Button
              onClick={() => {
                setSelectedCategory('Todas');
                setSelectedFormat('Todos');
                setSearchTerm('');
              }}
              variant="outline"
              size="sm"
              className="mt-3 border-[#D4AF37]/50 text-xs text-[#4B2E20]"
            >
              Ver todos os modelos
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredTemplates.map((template) => {
              const badge = getFormatBadge(template);
              const BadgeIcon = badge.icon;
              const hasVideo = Boolean(template.videoUrl);

              return (
                <Card
                  key={template.id}
                  className="group bg-white rounded-3xl border border-[#D4AF37]/35 overflow-hidden shadow-sm hover:shadow-xl hover:border-[#D4AF37] transition-all duration-300 flex flex-col relative"
                >
                  {/* Selo de Promoção */}
                  {template.isPromotion && (
                    <div className="absolute top-3 right-3 z-10 bg-rose-600 text-white text-[11px] font-bold px-2.5 py-1 rounded-full shadow-md flex items-center gap-1">
                      <Tag className="w-3 h-3" />
                      PROMOÇÃO
                    </div>
                  )}

                  {/* Botão de Edição Rápida para o Administrador */}
                  {isAdmin && onEditTemplate && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onEditTemplate(template);
                      }}
                      className="absolute top-3 left-3 z-10 bg-[#4B2E20]/90 hover:bg-[#382015] text-[#F7EBDD] text-[11px] font-semibold px-2.5 py-1 rounded-xl shadow-md flex items-center gap-1.5 transition-all"
                    >
                      <Edit3 className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Editar Modelo</span>
                    </button>
                  )}

                  {/* Imagem de Capa e Prévia */}
                  <div
                    onClick={() => handleOpenClientOrder(template)}
                    className="relative aspect-[4/5] overflow-hidden bg-[#ecdccb]/30 cursor-pointer"
                  >
                    <img
                      src={template.imageUrl}
                      alt={template.title}
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                      loading="lazy"
                    />

                    {/* Botão Assistir Vídeo quando tiver vídeo cadastrado */}
                    {hasVideo && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setVideoModalUrl(template.videoUrl || null);
                          setVideoModalTitle(template.title);
                        }}
                        className="absolute bottom-3 right-3 bg-[#4B2E20]/85 hover:bg-[#382015] text-[#F7EBDD] text-[11px] font-semibold px-3 py-1.5 rounded-full backdrop-blur-md shadow-lg flex items-center gap-1.5 transition-all hover:scale-105 border border-[#D4AF37]/40"
                      >
                        <Play className="w-3.5 h-3.5 text-[#D4AF37] fill-[#D4AF37]" />
                        <span>Ver Vídeo</span>
                      </button>
                    )}

                    {/* Overlay suave com botão Escolher */}
                    <div className="absolute inset-0 bg-[#4B2E20]/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                      <span className="bg-[#4B2E20] text-[#F7EBDD] text-xs font-bold px-4 py-2 rounded-xl shadow-lg border border-[#D4AF37]/50 flex items-center gap-1.5">
                        <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                        Escolher Este Modelo
                      </span>
                    </div>
                  </div>

                  {/* Informações do Convite */}
                  <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-3">
                    <div>
                      {/* Tipo e Categoria */}
                      <div className="flex items-center justify-between gap-2 mb-1.5">
                        <span className={`inline-flex items-center gap-1 text-[11px] px-2.5 py-0.5 rounded-md border ${badge.color}`}>
                          <BadgeIcon className="w-3 h-3" />
                          {badge.label}
                        </span>
                        <span className="text-[11px] text-[#4B2E20]/70 font-medium">
                          {template.category}
                        </span>
                      </div>

                      {/* Título */}
                      <h3
                        onClick={() => handleOpenClientOrder(template)}
                        className="font-serif font-bold text-[#4B2E20] text-base hover:text-[#784628] cursor-pointer line-clamp-1"
                      >
                        {template.title}
                      </h3>

                      {/* Descrição curta */}
                      <p className="text-xs text-[#4B2E20]/75 mt-1 line-clamp-2">
                        {template.description || 'Convite digital personalizado com alta qualidade.'}
                      </p>
                    </div>

                    {/* Preço e Botão de Ação */}
                    <div className="pt-2 border-t border-[#D4AF37]/25 flex items-center justify-between gap-2">
                      <div>
                        {template.originalPrice && template.isPromotion && (
                          <span className="text-[11px] line-through text-[#4B2E20]/50 block">
                            R$ {template.originalPrice.toFixed(2)}
                          </span>
                        )}
                        <span className="text-lg font-serif font-bold text-[#4B2E20]">
                          R$ {template.price.toFixed(2)}
                        </span>
                      </div>

                      <Button
                        size="sm"
                        onClick={() => handleOpenClientOrder(template)}
                        className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-semibold text-xs px-3.5 py-1.5 rounded-xl shadow-sm border border-[#D4AF37]/40 flex items-center gap-1 group-hover:scale-105 transition-transform"
                      >
                        <span>Escolher Modelo</span>
                        <ArrowRight className="w-3.5 h-3.5 text-[#D4AF37]" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      {/* SEÇÃO DE ENSAIOS DIGITAIS NO FINAL DA PÁGINA (OPCIONAL) */}
      <section className="pt-8 border-t border-[#D4AF37]/35">
        <div className="bg-gradient-to-r from-[#ecdccb]/60 via-[#fcf8f3] to-[#ecdccb]/60 p-6 sm:p-8 rounded-3xl border border-[#D4AF37]/40 text-center max-w-4xl mx-auto shadow-sm">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-white border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold mb-3">
            <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Serviço Adicional Especial</span>
          </div>
          <h3 className="text-2xl sm:text-3xl font-serif font-bold text-[#4B2E20]">
            Ensaios Fotográficos Digitais
          </h3>
          <p className="mt-2 text-xs sm:text-sm text-[#4B2E20]/80 max-w-2xl mx-auto">
            Além do convite, você também pode transformar a foto do aniversariante ou casal em um ensaio temático profissional (Princesa, Safári, Smash Cake ou Pré-Wedding) para colocar com destaque no seu convite!
          </p>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mt-6 text-left">
            {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
              <div
                key={ensaio.id}
                className="bg-white rounded-2xl p-3 border border-[#D4AF37]/30 shadow-xs flex flex-col justify-between"
              >
                <div className="aspect-[4/3] rounded-xl overflow-hidden mb-2.5 bg-[#ecdccb]/50">
                  <img
                    src={ensaio.foto}
                    alt={ensaio.titulo}
                    className="w-full h-full object-cover"
                  />
                </div>
                <div>
                  <span className="text-[10px] text-[#4B2E20]/60 font-bold uppercase tracking-wider block">
                    {ensaio.destaque}
                  </span>
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20] mt-0.5">
                    {ensaio.titulo}
                  </h4>
                  <p className="text-[11px] text-[#4B2E20]/75 mt-1 leading-snug">
                    {ensaio.descricao}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <p className="mt-5 text-[11px] text-[#4B2E20]/75 italic">
            💡 Dica: Você pode marcar a opção de incluir o Ensaio Digital diretamente ao preencher o formulário do convite!
          </p>
        </div>
      </section>

      {/* MODAL PARA ASSISTIR VÍDEO DO MODELO */}
      {videoModalUrl && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#4B2E20]/80 backdrop-blur-sm animate-fade-in">
          <div className="max-w-lg w-full bg-[#fdfbf7] rounded-3xl border border-[#D4AF37]/50 shadow-2xl overflow-hidden flex flex-col">
            <div className="flex items-center justify-between p-4 bg-[#ecdccb]/80 border-b border-[#D4AF37]/30">
              <div className="flex items-center gap-2">
                <Video className="w-4 h-4 text-[#D4AF37]" />
                <span className="font-serif font-bold text-sm text-[#4B2E20]">
                  Prévia em Vídeo • {videoModalTitle}
                </span>
              </div>
              <button
                onClick={() => setVideoModalUrl(null)}
                className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20]"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-4 bg-black flex items-center justify-center">
              <video
                src={videoModalUrl}
                controls
                autoPlay
                className="max-h-[60vh] w-full rounded-xl object-contain shadow-md"
              />
            </div>
            <div className="p-4 flex justify-end bg-[#fdfbf7] border-t border-[#D4AF37]/20">
              <Button
                onClick={() => setVideoModalUrl(null)}
                className="bg-[#4B2E20] text-[#F7EBDD] text-xs font-semibold rounded-xl"
              >
                Fechar Vídeo
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Pedido da Cliente */}
      {modalTemplate && (
        <ClientOrderModal
          isOpen={isClientModalOpen}
          template={modalTemplate}
          onClose={() => setIsClientModalOpen(false)}
          onSubmitOrder={(newOrder) => {
            onSelectTemplate(modalTemplate);
          }}
        />
      )}
    </div>
  );
}

