  },
];

export interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  isAdmin?: boolean;
  onSubmitClientOrder?: (newOrder: Order) => void;
  onEditTemplate?: (template: InvitationTemplate) => void;
  onDeleteTemplate?: (templateId: string) => void;
}

export function TemplatesCatalog({
  templates,
  isAdmin = false,
  onSubmitClientOrder,
  onEditTemplate,
  onDeleteTemplate,
}: TemplatesCatalogProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>('todos');
  const [selectedTemplateForOrder, setSelectedTemplateForOrder] = useState<InvitationTemplate | null>(null);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);

  const categories: { label: string; value: string }[] = [
    { label: 'Todos os Convites', value: 'todos' },
    { label: 'Casamento', value: 'Casamento' },
    { label: '15 Anos', value: '15 Anos' },
    { label: 'Infantil', value: 'Infantil' },
    { label: 'Batizado', value: 'Batizado' },
    { label: 'Bodas', value: 'Bodas' },
    { label: 'Corporativo', value: 'Corporativo' },
  ];

  const filteredTemplates = templates.filter((tpl) => {
    if (selectedCategory === 'todos') return true;
    return tpl.category === selectedCategory;
  });

  const handleOpenOrder = (template: InvitationTemplate) => {
    setSelectedTemplateForOrder(template);
    setIsClientModalOpen(true);
  };

  const handleCreateOrderFromModal = (newOrder: Order) => {
    if (onSubmitClientOrder) {
      onSubmitClientOrder(newOrder);
    }
  };

  return (
    <div className="space-y-12">
      {/* Banner Principal Delicado */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-[#ecdccb] via-[#f7ebdd] to-[#f4e4d4] border border-[#D4AF37]/30 p-8 sm:p-12 shadow-sm">
        <div className="max-w-2xl relative z-10 space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#4B2E20]/10 border border-[#4B2E20]/20 text-[#4B2E20] text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Convites Digitais Exclusivos & Personalizados</span>
          </div>
          <h1 className="text-3xl sm:text-4xl font-serif font-bold text-[#4B2E20] leading-tight">
            Seu momento especial começa com um convite inesquecível ✨
          </h1>
          <p className="text-sm sm:text-base text-[#4B2E20]/80 font-normal leading-relaxed">
            Convites em cartões digitais, interativos com botões clicáveis para WhatsApp e vídeos animados com música.
          </p>
        </div>
      </div>

      {/* Categorias de Filtro */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20] flex items-center gap-2">
            <Heart className="w-5 h-5 text-[#D4AF37]" />
            <span>Catálogo de Modelos</span>
          </h2>
          <span className="text-xs text-[#4B2E20]/70 font-medium">
            {filteredTemplates.length} {filteredTemplates.length === 1 ? 'modelo encontrado' : 'modelos encontrados'}
          </span>
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-none">
          {categories.map((cat) => (
            <button
              key={cat.value}
              onClick={() => setSelectedCategory(cat.value)}
              className={`px-4 py-2 rounded-2xl text-xs font-semibold whitespace-nowrap transition-all duration-200 ${
                selectedCategory === cat.value
                  ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                  : 'bg-white/80 text-[#4B2E20] hover:bg-[#ecdccb]/60 border border-[#D4AF37]/30'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Modelos */}
      {filteredTemplates.length === 0 ? (
        <Card className="bg-white/90 border-[#D4AF37]/30 p-12 text-center rounded-3xl">
          <p className="text-sm text-[#4B2E20]/70">Nenhum modelo cadastrado nesta categoria no momento.</p>
        </Card>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredTemplates.map((template) => {
            const hasDiscount = Boolean(template.isPromotion && template.originalPrice);

            return (
              <Card
                key={template.id}
                className="group overflow-hidden rounded-3xl border border-[#D4AF37]/35 bg-white/95 hover:shadow-xl transition-all duration-300 flex flex-col justify-between"
              >
                <div>
                  {/* Mídia: Foto ou Vídeo */}
                  <div className="relative aspect-[4/5] overflow-hidden bg-[#ecdccb]/30">
                    {template.videoUrl ? (
                      <video
                        src={template.videoUrl}
                        poster={template.imageUrl}
                        controls
                        playsInline
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      />
                    ) : (
                      <img
                        src={template.imageUrl}
                        alt={template.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        loading="lazy"
                      />
                    )}

                    {/* Tag de Categoria */}
                    <div className="absolute top-3 left-3 flex flex-col gap-1.5 z-10 pointer-events-none">
                      <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-[#4B2E20]/90 text-[#F7EBDD] backdrop-blur-md shadow-sm">
                        {template.category}
                      </span>
                      {template.videoUrl && (
                        <span className="px-2.5 py-0.5 rounded-full text-[10px] font-semibold bg-[#D4AF37] text-[#4B2E20] flex items-center gap-1 shadow-sm">
                          <Play className="w-3 h-3 fill-current" /> Vídeo com Áudio
                        </span>
                      )}
                    </div>

                    {/* Badge de Promoção */}
                    {hasDiscount && (
                      <div className="absolute top-3 right-3 z-10 pointer-events-none">
                        <span className="px-2.5 py-1 rounded-full text-[10px] font-bold bg-rose-600 text-white shadow-sm flex items-center gap-1">
                          <Tag className="w-3 h-3" /> PROMOÇÃO
                        </span>
                      </div>
                    )}

                    {/* Badge de Interativo */}
                    {template.hasInteraction && (
                      <div className="absolute bottom-3 left-3 z-10 pointer-events-none">
                        <span className="px-2.5 py-1 rounded-full text-[10px] font-semibold bg-emerald-800/90 text-white backdrop-blur-sm shadow flex items-center gap-1">
                          <Smartphone className="w-3 h-3" /> Botões Clicáveis
                        </span>
                      </div>
                    )}
                  </div>

                  {/* Informações */}
                  <div className="p-5 space-y-3">
                    <div>
                      <h3 className="font-serif font-bold text-lg text-[#4B2E20] group-hover:text-[#6d432e] transition-colors line-clamp-1">
                        {template.title}
                      </h3>
                      <p className="text-xs text-[#4B2E20]/75 line-clamp-2 mt-1 leading-relaxed">
                        {template.description || 'Convite digital sob medida, pronto para encantar seus convidados via WhatsApp.'}
                      </p>
                    </div>

                    {/* Tags */}
                    {template.tags && template.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1.5 pt-1">
                        {template.tags.slice(0, 3).map((tag, idx) => (
                          <span
                            key={idx}
                            className="text-[10px] px-2 py-0.5 rounded-lg bg-[#f7ebdd] text-[#4B2E20] font-medium border border-[#D4AF37]/20"
                          >
                            #{tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Rodapé do Card com Valores e Ações */}
                <div className="p-5 pt-0 border-t border-[#D4AF37]/15 mt-2">
                  <div className="flex items-baseline justify-between py-3">
                    <div>
                      {hasDiscount && (
                        <span className="text-xs text-[#4B2E20]/50 line-through mr-2 font-medium">
                          R$ {template.originalPrice?.toFixed(2)}
                        </span>
                      )}
                      <span className="text-2xl font-serif font-bold text-[#4B2E20]">
                        R$ {template.price.toFixed(2)}
                      </span>
                    </div>

                    <span className="text-[11px] text-[#4B2E20]/70 font-medium">
                      {template.hasInteraction ? 'Interativo' : 'Digital'}
                    </span>
                  </div>

                  {isAdmin ? (
                    <div className="grid grid-cols-2 gap-2 pt-1">
                      <Button
                        size="sm"
                        onClick={() => onEditTemplate && onEditTemplate(template)}
                        className="bg-[#ecdccb] hover:bg-[#dfcbba] text-[#4B2E20] text-xs font-semibold rounded-xl flex items-center justify-center gap-1.5"
                      >
                        <Pencil className="w-3.5 h-3.5 text-[#D4AF37]" />
                        <span>Editar</span>
                      </Button>

                      <Button
                        size="sm"
                        variant="destructive"
                        onClick={() => onDeleteTemplate && onDeleteTemplate(template.id)}
                        className="bg-rose-100 hover:bg-rose-200 text-rose-800 text-xs font-semibold rounded-xl flex items-center justify-center gap-1.5 border border-rose-200"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                        <span>Excluir</span>
                      </Button>
                    </div>
                  ) : (
                    <Button
                      onClick={() => handleOpenOrder(template)}
                      className="w-full bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs py-2.5 rounded-xl shadow border border-[#D4AF37]/40 flex items-center justify-center gap-2 transition-all hover:scale-[1.01]"
                    >
                      <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                      <span>Pedir Este Convite</span>
                    </Button>
                  )}
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* SEÇÃO FINAL: ENSAIOS DIGITAIS COMO ADICIONAL (FOCO CONTINUA NOS CONVITES) */}
      <section className="pt-8 border-t border-[#D4AF37]/30 space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-3">
          <div>
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#D4AF37]/20 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold mb-1.5">
              <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Serviço Opcional Adicional</span>
            </div>
            <h2 className="text-2xl font-serif font-bold text-[#4B2E20]">
              Ensaios Digitais para o seu Convite
            </h2>
            <p className="text-xs sm:text-sm text-[#4B2E20]/80">
              Quer a foto do seu pequeno ou do casal tratada no tema perfeito da festa? Veja alguns exemplos que podem ser incluídos ao pedir seu convite:
            </p>
          </div>
          <span className="text-xs font-semibold text-[#D4AF37] bg-[#4B2E20] px-3 py-1.5 rounded-xl shrink-0">
            Apenas + R$ 25,00 no pedido
          </span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
            <Card
              key={ensaio.id}
              className="overflow-hidden rounded-2xl border border-[#D4AF37]/30 bg-white/95 shadow-sm hover:shadow-md transition-all group flex flex-col justify-between"
            >
              <div>
                <div className="relative aspect-square overflow-hidden bg-[#ecdccb]/40">
                  <img
                    src={ensaio.foto}
                    alt={ensaio.titulo}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                    loading="lazy"
                  />
                  <span className="absolute top-2 left-2 text-[10px] font-bold px-2 py-0.5 rounded-full bg-[#4B2E20]/85 text-[#F7EBDD] backdrop-blur-xs">
                    {ensaio.tag}
                  </span>
                </div>

                <div className="p-3.5 space-y-1">
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20]">
                    {ensaio.titulo}
                  </h4>
                  <p className="text-[11px] font-medium text-[#4B2E20]/75">
                    {ensaio.subtitulo}
                  </p>
                  <p className="text-[11px] text-[#4B2E20]/65 leading-tight pt-1">
                    {ensaio.descricao}
                  </p>
                </div>
              </div>

              <div className="p-3.5 pt-0 border-t border-[#D4AF37]/15 mt-2 flex items-center justify-between text-xs">
                <span className="font-bold text-[#4B2E20]">R$ {ensaio.preco.toFixed(2)}</span>
                <span className="text-[10px] text-emerald-800 font-semibold bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-200">
                  Adicione ao finalizar
                </span>
              </div>
            </Card>
          ))}
        </div>
      </section>

      {/* Modal de Pedido do Cliente */}
      <ClientOrderModal
        isOpen={isClientModalOpen}
        template={selectedTemplateForOrder}
        onClose={() => {
          setIsClientModalOpen(false);
          setSelectedTemplateForOrder(null);
        }}
        onSubmitOrder={handleCreateOrderFromModal}
      />
    </div>
  );
}

