  CheckCircle2,
  QrCode,
  Copy,
  ArrowRight,
  ArrowLeft,
  ShieldCheck,
  CheckCheck,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque ou Circo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala e Castelo',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol e Cenário Floral',
    preco: 29,
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake e Balões',
    preco: 25,
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
  },
];

const CHAVE_PIX_KEH = '32998040080';

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  const [etapa, setEtapa] = useState<'formulario' | 'pagamento_pix' | 'concluido'>('formulario');

  // Campos do formulário
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [temaFesta, setTemaFesta] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos para modelo com botões
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Foto enviada pelo cliente
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Ensaio Digital Opcional
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);

  // Estado de cópia do PIX
  const [pixCopiado, setPixCopiado] = useState(false);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCopiarPix = () => {
    navigator.clipboard.writeText(CHAVE_PIX_KEH);
    setPixCopiado(true);
    setTimeout(() => setPixCopiado(false), 3000);
  };

  // Ao clicar em Ir para Pagamento
  const handleAvancarParaPix = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do aniversariante ou homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o número de WhatsApp para contato.');
      return;
    }

    // Registra imediatamente o pedido na base administrativa
    const notasFormatadas = [
      'Pedido feito pelo Catálogo Online',
      temaFesta ? `Tema: ${temaFesta}` : '',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples (sem botões)',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
      `PIX Keh Convites: R$ ${valorTotalFinal.toFixed(2)} (Chave: ${CHAVE_PIX_KEH})`,
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      theme: temaFesta || undefined,
      templateId: template.id,
      templateTitle: template.title,
      category: template.category,
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: valorTotalFinal,
      eventDate: dataEvento || new Date().toISOString().split('T')[0],
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pago',
      includeDigitalPhotoshoot: querEnsaioDigital,
      photoshootDetails: querEnsaioDigital ? ensaioEscolhido : undefined,
      photoUrl: fotoPreview || undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);
    setEtapa('pagamento_pix');
  };

  const handleConcluirEFechar = () => {
    setEtapa('formulario');
    setPixCopiado(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">

        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/80 to-[#f7ebdd]/80 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] border border-[#D4AF37]/50 flex items-center justify-center text-[#D4AF37] shadow-sm">
              {etapa === 'pagamento_pix' ? (
                <QrCode className="w-5 h-5" />
              ) : etapa === 'concluido' ? (
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
              ) : (
                <Sparkles className="w-5 h-5" />
              )}
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                {etapa === 'pagamento_pix'
                  ? 'Pagamento via PIX'
                  : etapa === 'concluido'
                  ? 'Pedido Confirmado com Sucesso!'
                  : 'Personalize seu Convite Digital'}
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                {etapa === 'pagamento_pix'
                  ? 'Efetue a transferência para iniciarmos a criação'
                  : etapa === 'concluido'
                  ? 'Recebemos as informações com sucesso'
                  : `Modelo escolhido: ${template.title}`}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* Conteúdo Dinâmico por Etapa */}
        <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-5 text-xs text-[#4B2E20]">

          {/* ETAPA 1: FORMULÁRIO DO CONVITE */}
          {etapa === 'formulario' && (
            <form onSubmit={handleAvancarParaPix} className="space-y-5">
              {/* Resumo do Modelo */}
              <div className="flex items-center gap-3 bg-[#ecdccb]/40 p-3 rounded-2xl border border-[#D4AF37]/30">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-12 h-14 object-cover rounded-xl border border-[#D4AF37]/40 shadow-xs"
                />
                <div className="flex-1 min-w-0">
                  <span className="text-[10px] uppercase font-bold text-[#4B2E20]/70 tracking-wider">
                    {temInteracao ? 'Convite Interativo com Botões' : 'Convite Simples'}
                  </span>
                  <p className="font-serif font-bold text-sm text-[#4B2E20] truncate">
                    {template.title}
                  </p>
                  <p className="text-xs font-semibold text-[#4B2E20]">
                    R$ {template.price.toFixed(2)}
                  </p>
                </div>
              </div>

              {/* Informações Principais */}
              <div className="space-y-3">
                <h4 className="font-serif font-bold text-sm text-[#4B2E20] border-b border-[#D4AF37]/25 pb-1 flex items-center gap-1.5">
                  <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                  Dados do Evento
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1">
                      Nome do Aniversariante ou Homenageado *
                    </label>
                    <Input
                      required
                      placeholder="Ex: Valentina, Arthur, Amanda & Thiago"
                      value={nomeAniversariante}
                      onChange={(e) => setNomeAniversariante(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1">
                      Tema da Festa / Estilo
                    </label>
                    <Input
                      placeholder="Ex: Princesas, Safári, Rústico Chic, Boteco"
                      value={temaFesta}
                      onChange={(e) => setTemaFesta(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                      <Calendar className="w-3 h-3 text-[#D4AF37]" />
                      Data do Evento
                    </label>
                    <Input
                      type="date"
                      value={dataEvento}
                      onChange={(e) => setDataEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1">
                      Dia da Semana
                    </label>
                    <Input
                      placeholder="Ex: Sábado, Domingo"
                      value={diaSemana}
                      onChange={(e) => setDiaSemana(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                      <Clock className="w-3 h-3 text-[#D4AF37]" />
                      Horário
                    </label>
                    <Input
                      placeholder="Ex: Às 19h30"
                      value={horarioEvento}
                      onChange={(e) => setHorarioEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-3">
                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-[#D4AF37]" />
                      Local e Endereço da Festa
                    </label>
                    <Input
                      placeholder="Ex: Buffet Estrela Mágica - Rua das Flores, 120, Bairro Jardim"
                      value={localEvento}
                      onChange={(e) => setLocalEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                      <Heart className="w-3 h-3 text-[#D4AF37]" />
                      Frase Especial ou Idade (Opcional)
                    </label>
                    <Input
                      placeholder='Ex: "Venha comemorar meu 1º aninho!" ou idade a completar'
                      value={fraseEspecial}
                      onChange={(e) => setFraseEspecial(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>
              </div>

              {/* Se o modelo for interativo, exibe os campos de botões clicáveis */}
              {temInteracao && (
                <div className="p-3.5 bg-gradient-to-r from-[#ecdccb]/50 to-[#f7ebdd]/50 rounded-2xl border border-[#D4AF37]/35 space-y-3">
                  <span className="font-serif font-bold text-xs text-[#4B2E20] flex items-center gap-1.5">
                    <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Configuração dos Botões Clicáveis do Convite
                  </span>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div>
                      <label className="block font-semibold text-[#4B2E20] text-[11px] mb-1">
                        WhatsApp para Confirmação de Presença
                      </label>
                      <Input
                        placeholder="Ex: (11) 99999-8888"
                        value={confirmacaoPresenca}
                        onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>

                    <div>
                      <label className="block font-semibold text-[#4B2E20] text-[11px] mb-1">
                        Link de Localização (Google Maps ou Waze)
                      </label>
                      <Input
                        placeholder="Cole o link do Maps ou o nome do local"
                        value={linkLocalizacao}
                        onChange={(e) => setLinkLocalizacao(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block font-semibold text-[#4B2E20] text-[11px] mb-1 flex items-center gap-1">
                      <Gift className="w-3 h-3 text-[#D4AF37]" />
                      Lista de Presentes ou Sugestão de Roupa (Opcional)
                    </label>
                    <Input
                      placeholder="Ex: Loja Camicado, Pix da lista ou sugestão de presente"
                      value={listaPresentes}
                      onChange={(e) => setListaPresentes(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                    />
                  </div>
                </div>
              )}

              {/* Upload da Foto do Aniversariante */}
              <div className="p-3 bg-white rounded-2xl border border-[#D4AF37]/30 space-y-2">
                <div className="flex items-center justify-between">
                  <label className="font-semibold text-[#4B2E20] text-xs flex items-center gap-1.5">
                    <Upload className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Foto para colocar no convite (Opcional)
                  </label>
                  {fotoPreview && (
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="text-red-700 hover:text-red-900 text-[11px] font-medium"
                    >
                      Remover foto
                    </button>
                  )}
                </div>

                <input
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
                  onChange={handleFotoChange}
                  className="hidden"
                />

                <div className="flex items-center gap-3">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => fileInputRef.current?.click()}
                    className="border-[#D4AF37]/50 bg-[#ecdccb]/30 text-[#4B2E20] hover:bg-[#ecdccb]/60 text-xs rounded-xl"
                  >
                    <Upload className="w-3.5 h-3.5 mr-1 text-[#D4AF37]" />
                    {fotoPreview ? 'Trocar Foto' : 'Escolher Foto do Dispositivo'}
                  </Button>

                  {fotoPreview && (
                    <div className="flex items-center gap-2">
                      <img
                        src={fotoPreview}
                        alt="Preview"
                        className="w-10 h-10 object-cover rounded-lg border border-[#D4AF37]"
                      />
                      <span className="text-[11px] text-emerald-800 font-semibold flex items-center gap-1">
                        <CheckCircle2 className="w-3.5 h-3.5" /> Foto anexada
                      </span>
                    </div>
                  )}
                </div>
              </div>

              {/* Oferta Adicional: Ensaio Fotográfico Digital */}
              <div className="p-4 bg-gradient-to-r from-[#ecdccb]/50 to-[#fdfbf7] rounded-2xl border border-[#D4AF37]/40 space-y-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Camera className="w-4 h-4 text-[#D4AF37]" />
                    <div>
                      <p className="font-serif font-bold text-xs text-[#4B2E20]">
                        Deseja incluir um Ensaio Fotográfico Digital?
                      </p>
                      <p className="text-[10px] text-[#4B2E20]/75">
                        Criamos um cenário temático encantador com a foto da criança ou casal
                      </p>
                    </div>
                  </div>
                  <label className="inline-flex items-center gap-1.5 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={querEnsaioDigital}
                      onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                      className="w-4 h-4 rounded text-[#4B2E20] focus:ring-[#D4AF37]"
                    />
                    <span className="text-xs font-bold text-[#4B2E20]">
                      + R$ 25,00
                    </span>
                  </label>
                </div>

                {querEnsaioDigital && (
                  <div className="pt-2 border-t border-[#D4AF37]/25 space-y-2 animate-fade-in">
                    <label className="block text-[11px] font-semibold text-[#4B2E20]">
                      Escolha o Estilo do Ensaio Digital:
                    </label>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                      {EXEMPLOS_ENSAIOS_DIGITAIS.map((item) => (
                        <div
                          key={item.id}
                          onClick={() => setEnsaioEscolhido(item.titulo)}
                          className={`cursor-pointer rounded-xl p-2 border text-center transition-all ${
                            ensaioEscolhido === item.titulo
                              ? 'border-[#D4AF37] bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                              : 'border-[#D4AF37]/30 bg-white text-[#4B2E20] hover:bg-[#ecdccb]/40'
                          }`}
                        >
                          <img
                            src={item.foto}
                            alt={item.titulo}
                            className="w-full h-16 object-cover rounded-lg mb-1"
                          />
                          <p className="text-[10px] font-bold truncate">{item.titulo}</p>
                          <p className="text-[9px] opacity-80">{item.subtitulo}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* WhatsApp do Cliente */}
              <div>
                <label className="block font-semibold text-[#4B2E20] mb-1 flex items-center gap-1">
                  <Phone className="w-3.5 h-3.5 text-[#D4AF37]" />
                  Seu WhatsApp para Receber a Prévia e o Convite Pronto *
                </label>
                <Input
                  required
                  placeholder="Ex: (32) 99804-0080"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="bg-white border-[#D4AF37]/40 text-[#4B2E20] text-xs rounded-xl"
                />
              </div>

              {/* Totalizador e Botão de Prosseguir */}
              <div className="pt-3 border-t border-[#D4AF37]/25 flex items-center justify-between">
                <div>
                  <span className="text-[11px] text-[#4B2E20]/75 block">Valor Total:</span>
                  <span className="text-xl font-serif font-bold text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#392115] text-[#F7EBDD] font-bold text-xs rounded-xl shadow-md border border-[#D4AF37]/50 px-5 py-2.5 flex items-center gap-2"
                >
                  <span>Ir para Pagamento PIX</span>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                </Button>
              </div>
            </form>
          )}

          {/* ETAPA 2: PAGAMENTO VIA PIX */}
          {etapa === 'pagamento_pix' && (
            <div className="space-y-6 text-center animate-fade-in py-2">
              <div className="w-16 h-16 rounded-2xl bg-emerald-100 border border-emerald-300 mx-auto flex items-center justify-center text-emerald-800 shadow-sm">
                <QrCode className="w-8 h-8" />
              </div>

              <div>
                <h3 className="text-xl font-serif font-bold text-[#4B2E20]">
                  Chave PIX da Keh Convites
                </h3>
                <p className="text-xs text-[#4B2E20]/75 mt-1 max-w-md mx-auto">
                  Faça o pagamento no seu aplicativo do banco para iniciarmos a produção do seu convite com carinho!
                </p>
              </div>

              {/* Caixa com o valor e a chave */}
              <div className="bg-white p-5 rounded-2xl border border-[#D4AF37]/40 shadow-sm max-w-md mx-auto space-y-3">
                <div className="flex items-center justify-between border-b border-[#D4AF37]/20 pb-2">
                  <span className="text-xs text-[#4B2E20]/70 font-medium">Valor a Pagar:</span>
                  <span className="text-lg font-serif font-bold text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <div className="text-left space-y-1">
                  <span className="text-[11px] font-semibold text-[#4B2E20]">
                    Chave PIX (Telefone / Celular):
                  </span>
                  <div className="flex items-center justify-between bg-[#fcf8f3] p-2.5 rounded-xl border border-[#D4AF37]/30">
                    <span className="font-mono font-bold text-sm text-[#4B2E20]">
                      {CHAVE_PIX_KEH}
                    </span>
                    <Button
                      size="sm"
                      onClick={handleCopiarPix}
                      className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] text-xs font-semibold rounded-lg px-3 py-1 h-auto flex items-center gap-1.5"
                    >
                      {pixCopiado ? (
                        <>
                          <CheckCheck className="w-3.5 h-3.5 text-emerald-400" />
                          <span>Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy className="w-3.5 h-3.5 text-[#D4AF37]" />
                          <span>Copiar Chave</span>
                        </>
                      )}
                    </Button>
                  </div>
                </div>

                <div className="pt-2 text-left text-[11px] text-[#4B2E20]/70 space-y-1">
                  <p className="flex items-center gap-1">
                    <ShieldCheck className="w-3.5 h-3.5 text-emerald-700" />
                    <strong>Titular:</strong> Keh Convites
                  </p>
                  <p className="flex items-center gap-1">
                    <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                    <strong>Cliente:</strong> {nomeAniversariante}
                  </p>
                </div>
              </div>

              {/* Botões de navegação */}
              <div className="flex items-center justify-center gap-3 pt-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setEtapa('formulario')}
                  className="border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs flex items-center gap-1.5"
                >
                  <ArrowLeft className="w-3.5 h-3.5" />
                  <span>Voltar / Revisar Dados</span>
                </Button>

                <Button
                  type="button"
                  onClick={() => setEtapa('concluido')}
                  className="bg-emerald-800 hover:bg-emerald-900 text-white font-bold text-xs rounded-xl px-5 py-2.5 shadow-md flex items-center gap-2"
                >
                  <CheckCircle2 className="w-4 h-4 text-emerald-300" />
                  <span>Já Fiz o Pagamento</span>
                </Button>
              </div>
            </div>
          )}

          {/* ETAPA 3: CONCLUÍDO */}
          {etapa === 'concluido' && (
            <div className="text-center py-6 space-y-4 animate-fade-in">
              <div className="w-16 h-16 rounded-full bg-emerald-100 text-emerald-800 mx-auto flex items-center justify-center border border-emerald-300">
                <CheckCircle2 className="w-8 h-8" />
              </div>

              <h3 className="text-xl font-serif font-bold text-[#4B2E20]">
                Pedido Registrado com Sucesso!
              </h3>

              <p className="text-xs text-[#4B2E20]/80 max-w-md mx-auto leading-relaxed">
                Muito obrigada, <strong>{nomeAniversariante}</strong>! Seu pedido já está registrado em nossa produção. Vamos conferir os detalhes e enviar a prévia personalizada no seu WhatsApp <strong>{whatsappCliente}</strong>.
              </p>

              <div className="p-3 bg-[#ecdccb]/50 rounded-2xl border border-[#D4AF37]/30 max-w-sm mx-auto text-xs font-semibold text-[#4B2E20]">
                Prazo estimado de envio da prévia: em até 24 a 48 horas úteis.
              </div>

              <div className="pt-4">
                <Button
                  onClick={handleConcluirEFechar}
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs rounded-xl px-6 py-2.5 shadow-sm"
                >
                  Fechar Janela
                </Button>
              </div>
            </div>
          )}

        </CardContent>
      </Card>
    </div>
  );
}

