                        placeholder="Link ou nome do local"
                        value={linkLocalizacao}
                        onChange={(e) => setLinkLocalizacao(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                      />
                    </div>
                    <div>
                      <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                        Lista de Presentes (Link/Sugestão)
                      </label>
