                  >
                    <Upload className="w-3.5 h-3.5 mr-1 text-[#D4AF37]" />
                    {fotoFile ? 'Trocar Foto' : 'Enviar Foto'}
                  </Button>
                  {fotoFile && (
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="text-xs text-rose-600 font-semibold underline"
                    >
                      Remover
                    </button>
                  )}
                </div>
              </div>

              {/* Ensaio Digital Opcional */}
              <div className="p-3.5 rounded-2xl bg-[#ecdccb]/30 border border-[#D4AF37]/40 space-y-2">
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-2 cursor-pointer font-bold text-xs text-[#4B2E20]">
