                      type="checkbox"
                      checked={querEnsaioDigital}
                      onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                      className="w-4 h-4 rounded text-[#4B2E20] accent-[#D4AF37]"
                    />
                    <span>Incluir Ensaio Digital Fotográfico (+ R$ 25,00)</span>
                  </label>
                  {querEnsaioDigital && (
                    <span className="text-[11px] font-bold text-[#4B2E20] bg-[#D4AF37]/30 px-2 py-0.5 rounded-md">
                      + R$ 25,00
                    </span>
                  )}
                </div>
              </div>

