              <div className="pt-2 flex items-center justify-between border-t border-[#D4AF37]/30">
                <div>
                  <span className="text-[11px] text-[#4B2E20]/70 block">Valor Total:</span>
                  <span className="text-xl font-serif font-black text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs px-6 py-2.5 rounded-2xl shadow-md border border-[#D4AF37]/50 flex items-center gap-2"
                >
                  <span>Ir para o Pagamento via PIX</span>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                </Button>
              </div>
            </form>
          </CardContent>
        )}

        {/* ETAPA 2: PAGAMENTO VIA PIX */}
        {etapa === 'pagamento_pix' && (
          <CardContent className="overflow-y-auto p-6 space-y-6 text-center text-[#4B2E20]">
            <div className="max-w-md mx-auto space-y-4">
              <div className="w-16 h-16 rounded-3xl bg-emerald-100 text-emerald-800 flex items-center justify-center mx-auto shadow-inner">
                <QrCode className="w-8 h-8" />
              </div>

              <div>
                <h3 className="font-serif font-bold text-xl text-[#4B2E20]">
                  Pagamento com Chave PIX
                </h3>
                <p className="text-xs text-[#4B2E20]/75 mt-1">
                  Transfira o valor de <strong>R$ {valorTotalFinal.toFixed(2)}</strong> para Keh Convites
                </p>
              </div>

              {/* Caixa com a Chave PIX */}
              <div className="p-4 bg-white rounded-2xl border-2 border-dashed border-[#D4AF37] space-y-2">
                <span className="text-[11px] font-semibold text-[#4B2E20]/70 uppercase tracking-wider block">
                  Chave PIX (Telefone)
                </span>
                <p className="text-lg font-mono font-bold text-[#4B2E20] select-all tracking-wider">
                  {CHAVE_PIX_KEH}
                </p>
                <Button
                  type="button"
                  onClick={handleCopiarPix}
                  className={`w-full text-xs font-bold rounded-xl transition-all ${
                    pixCopiado
                      ? 'bg-emerald-700 text-white'
                      : 'bg-[#4B2E20] text-[#F7EBDD] hover:bg-[#382015]'
                  }`}
                >
                  {pixCopiado ? (
                    <>
                      <CheckCheck className="w-4 h-4 mr-1.5" />
                      Chave PIX Copiada com Sucesso!
                    </>
                  ) : (
                    <>
                      <Copy className="w-4 h-4 mr-1.5 text-[#D4AF37]" />
                      Copiar Chave PIX
                    </>
                  )}
                </Button>
              </div>

              <div className="p-3 bg-amber-50 rounded-xl border border-amber-200 text-[11px] text-[#4B2E20]/80 text-left space-y-1">
                <p className="font-bold flex items-center gap-1 text-[#4B2E20]">
                  <ShieldCheck className="w-4 h-4 text-emerald-700" />
                  Como funciona após o pagamento:
                </p>
                <p>1. Seu pedido já foi registrado na área administrativa.</p>
                <p>2. Assim que o PIX for verificado, enviaremos a prévia do convite diretamente no seu WhatsApp ({whatsappCliente}).</p>
              </div>

              <Button
                onClick={() => setEtapa('concluido')}
                className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs py-3 rounded-2xl shadow-md"
              >
                Já realizei o pagamento via PIX
              </Button>
            </div>
          </CardContent>
        )}

        {/* ETAPA 3: CONCLUÍDO */}
        {etapa === 'concluido' && (
          <CardContent className="p-8 text-center space-y-5 text-[#4B2E20]">
            <div className="w-20 h-20 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto shadow-md">
              <CheckCircle2 className="w-10 h-10" />
            </div>

            <div className="space-y-2">
              <h3 className="font-serif font-black text-2xl text-[#4B2E20]">
                Pedido Realizado com Sucesso!
              </h3>
              <p className="text-xs text-[#4B2E20]/80 max-w-sm mx-auto leading-relaxed">
                Obrigado por escolher a <strong>Keh Convites</strong>! Seu pedido já está registrado e em breve entraremos em contato pelo WhatsApp cadastrado.
              </p>
            </div>

            <Button
              onClick={handleConcluirEFechar}
              className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs px-8 py-3 rounded-2xl shadow-lg border border-[#D4AF37]/50"
            >
              Concluir e Voltar ao Início
            </Button>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

