import React, { useState } from 'react';
import { initialTemplates, initialOrders } from '@/data/initialData';
import { InvitationTemplate, Order, OrderStatus, PaymentStatus } from '@/types';
import { Navbar } from '@/components/Navbar';
import { TemplatesCatalog } from '@/components/TemplatesCatalog';
import { OrdersManager } from '@/components/OrdersManager';
import { EarningsDashboard } from '@/components/EarningsDashboard';
import { AdminLoginModal } from '@/components/AdminLoginModal';
import { NewOrderModal } from '@/components/NewOrderModal';
import { NewTemplateModal } from '@/components/NewTemplateModal';

export default function App() {
  const [templates, setTemplates] = useState<InvitationTemplate[]>(initialTemplates);
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Navegação de Abas
  const [currentTab, setCurrentTab] = useState<'dashboard' | 'orders' | 'templates'>('templates');

  // Autenticação da Área Restrita
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [isAdminAuthModalOpen, setIsAdminAuthModalOpen] = useState(false);

  // Modais de Criação & Edição
  const [isNewOrderModalOpen, setIsNewOrderModalOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [templateToEdit, setTemplateToEdit] = useState<InvitationTemplate | null>(null);

  // Salvar / Adicionar Pedido (vindo do cliente ou do admin)
  const handleSaveOrder = (newOrder: Order) => {
    setOrders((prev) => [newOrder, ...prev]);
  };

  // Excluir Pedido
  const handleDeleteOrder = (orderId: string) => {
    setOrders((prev) => prev.filter((order) => order.id !== orderId));
  };

  // Atualizar Status do Pedido
  const handleUpdateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, status } : order))
    );
  };

  // Atualizar Pagamento do Pedido
  const handleUpdatePaymentStatus = (orderId: string, status: PaymentStatus) => {
    setOrders((prev) =>
      prev.map((order) => (order.id === orderId ? { ...order, paymentStatus: status } : order))
    );
  };

  // Salvar / Editar Modelo
  const handleSaveTemplate = (savedTemplate: InvitationTemplate) => {
    setTemplates((prev) => {
      const exists = prev.some((t) => t.id === savedTemplate.id);
      if (exists) {
        return prev.map((t) => (t.id === savedTemplate.id ? savedTemplate : t));
      }
      return [savedTemplate, ...prev];
    });
    setTemplateToEdit(null);
  };

  // Abrir Modal para Editar Modelo
  const handleEditTemplate = (template: InvitationTemplate) => {
    setTemplateToEdit(template);
    setIsNewTemplateModalOpen(true);
  };

  // Excluir Modelo
  const handleDeleteTemplate = (templateId: string) => {
    if (window.confirm('Tem certeza que deseja excluir este modelo?')) {
      setTemplates((prev) => prev.filter((t) => t.id !== templateId));
    }
  };

  const pendingOrdersCount = orders.filter((o) => o.status === 'pendente').length;

  return (
    <div className="min-h-screen bg-[#F7EBDD] text-[#4B2E20] flex flex-col font-sans selection:bg-[#D4AF37]/30 selection:text-[#4B2E20]">
      {/* Navbar Superior */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        isAdminAuthenticated={isAdminAuthenticated}
        onOpenAdminAuth={() => setIsAdminAuthModalOpen(true)}
        onLogoutAdmin={() => {
          setIsAdminAuthenticated(false);
          setCurrentTab('templates');
        }}
        onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
        onOpenNewTemplate={() => {
          setTemplateToEdit(null);
          setIsNewTemplateModalOpen(true);
        }}
        pendingOrdersCount={pendingOrdersCount}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-10">
        {currentTab === 'templates' && (
          <TemplatesCatalog
            templates={templates}
            isAdmin={isAdminAuthenticated}
            onSubmitClientOrder={handleSaveOrder}
            onEditTemplate={handleEditTemplate}
            onDeleteTemplate={handleDeleteTemplate}
          />
        )}

        {currentTab === 'orders' && (
          <OrdersManager
            orders={orders}
            onUpdateStatus={handleUpdateOrderStatus}
            onUpdatePayment={handleUpdatePaymentStatus}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
            onDeleteOrder={handleDeleteOrder}
          />
        )}

        {currentTab === 'dashboard' && (
          <EarningsDashboard
            orders={orders}
            templates={templates}
            onOpenNewOrder={() => setIsNewOrderModalOpen(true)}
          />
        )}
      </main>

      {/* Rodapé Elegante */}
      <footer className="border-t border-[#D4AF37]/30 bg-[#ecdccb]/50 py-8 text-center text-xs text-[#4B2E20]/75">
        <div className="max-w-7xl mx-auto px-4 space-y-2">
          <p className="font-serif font-bold text-sm text-[#4B2E20]">Keh Convites • Convites Digitais & Afeto</p>
          <p>© {new Date().getFullYear()} Keh Convites. Todos os direitos reservados.</p>
        </div>
      </footer>

      {/* Modal de Autenticação da Área Restrita */}
      <AdminLoginModal
        isOpen={isAdminAuthModalOpen}
        onClose={() => setIsAdminAuthModalOpen(false)}
        onSuccess={() => {
          setIsAdminAuthenticated(true);
          setIsAdminAuthModalOpen(false);
          setCurrentTab('orders');
        }}
      />

      {/* Modal de Cadastro de Novo Pedido (Manual) */}
      <NewOrderModal
        isOpen={isNewOrderModalOpen}
        onClose={() => setIsNewOrderModalOpen(false)}
        templates={templates}
        onSaveOrder={handleSaveOrder}
      />

      {/* Modal de Cadastro / Edição de Modelo com Foto e Vídeo */}
      <NewTemplateModal
        isOpen={isNewTemplateModalOpen}
        onClose={() => {
          setIsNewTemplateModalOpen(false);
          setTemplateToEdit(null);
        }}
        onSaveTemplate={handleSaveTemplate}
        templateToEdit={templateToEdit}
      />
    </div>
  );
}

