import React, { useState } from 'react';
import { InvitationTemplate, DigitalFormat, Order } from '@/types';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Sparkles,
  MousePointerClick,
  Video,
  Image as ImageIcon,
  Check,
  Search,
  Filter,
  Camera,
  Heart,
  Calendar,
  Layers,
  Edit,
  Trash2,
  Clock,
  Send,
} from 'lucide-react';
import { ClientOrderModal } from './ClientOrderModal';

export const EXEMPLOS_ENSAIOS_CATALOGO = [
  {
    id: 'ensaio-cat-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque, Circo & Fazendinha',
    valor: 'R$ 25,00',
    descricao: 'Criamos a foto temática digital do seu filho(a) com cenário lindo para ilustrar com encanto o convite.',
    foto: 'https://images.unsplash.com/photo-1544126592-807ade215a0b?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-cat-2',
    titulo: 'Ensaio Princesa & Realeza',
    subtitulo: 'Vestidos de Gala, Castelos e Flores',
    valor: 'R$ 25,00',
    descricao: 'Transformação visual delicada para encantar os convidados logo na capa do convite.',
    foto: 'https://images.unsplash.com/photo-1516627145497-ae6968895b74?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-cat-3',
    titulo: 'Ensaio Casal / Pré-Wedding',
    subtitulo: 'Pôr do Sol, Praia e Cenário Romântico',
    valor: 'R$ 29,00',
    descricao: 'Foto tratada em atmosfera apaixonante pronta para compor seu convite digital interativo ou vídeo.',
    foto: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=600&q=80',
  },
  {
    id: 'ensaio-cat-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake, Balões e Cores Pastéis',
    valor: 'R$ 25,00',
    descricao: 'Cenário alegre e fofo perfeito para a primeira celebração do seu pequeno amor.',
    foto: 'https://images.unsplash.com/photo-1533227268428-f9ed0900fb3b?auto=format&fit=crop&w=600&q=80',
  },
];

export interface TemplatesCatalogProps {
  templates: InvitationTemplate[];
  onOpenOrderModal: (template: InvitationTemplate) => void;
  isAdmin?: boolean;
  onEditTemplate?: (template: InvitationTemplate) => void;
  onDeleteTemplate?: (templateId: string) => void;
  onSaveNewOrderFromClient?: (order: Order) => void;
}

const FORMATOS_BOTOES: { id: string; label: string; icon: any }[] = [
  { id: 'todos', label: 'Todos os Modelos', icon: Layers },
  { id: 'interativo_pdf', label: 'Interativos com Botões', icon: MousePointerClick },
  { id: 'imagem_card', label: 'Cards & Imagem (Simples)', icon: ImageIcon },
  { id: 'animado_video', label: 'Vídeos Animados', icon: Video },
  { id: 'save_the_date', label: 'Save The Date', icon: Calendar },
  { id: 'kit_digital', label: 'Kits Digitais', icon: Sparkles },
];

export function TemplatesCatalog({
  templates,
  onOpenOrderModal,
  isAdmin = false,
  onEditTemplate,
  onDeleteTemplate,
  onSaveNewOrderFromClient,
}: TemplatesCatalogProps) {
  const [selectedFormat, setSelectedFormat] = useState<string>('todos');
  const [searchQuery, setSearchQuery] = useState('');
  const [orderingClientTemplate, setOrderingClientTemplate] = useState<InvitationTemplate | null>(null);

  const filteredTemplates = templates.filter((template) => {
    const matchesFormat =
      selectedFormat === 'todos' || template.format === selectedFormat;
    const matchesSearch =
      template.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      template.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      template.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));

    return matchesFormat && matchesSearch;
  });

  const getFormatBadge = (template: InvitationTemplate) => {
    if (template.hasInteraction || template.format === 'interativo_pdf' || template.format === 'site_rsvp') {
      return (
        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-[#D4AF37]/20 border border-[#D4AF37]/50 text-[#4B2E20] shadow-sm backdrop-blur-md">
          <MousePointerClick className="w-3 h-3 text-[#D4AF37]" />
          Interativo com Botões
        </span>
      );
    }
    if (template.format === 'animado_video') {
      return (
        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-amber-100/90 border border-amber-300 text-[#4B2E20] shadow-sm backdrop-blur-md">
          <Video className="w-3 h-3 text-[#D4AF37]" />
          Vídeo Animado
        </span>
      );
    }
    if (template.format === 'save_the_date') {
      return (
        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-[#ecdccb] border border-[#D4AF37]/40 text-[#4B2E20] shadow-sm backdrop-blur-md">
          <Calendar className="w-3 h-3 text-[#D4AF37]" />
          Save The Date
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold bg-white/90 border border-[#D4AF37]/35 text-[#4B2E20] shadow-sm backdrop-blur-md">
        <ImageIcon className="w-3 h-3 text-[#D4AF37]" />
        Card Simples
      </span>
    );
  };

  const handleSelectTemplateForOrder = (tpl: InvitationTemplate) => {
    setOrderingClientTemplate(tpl);
  };

  const handleOrderSubmitted = (order: Order) => {
    if (onSaveNewOrderFromClient) {
      onSaveNewOrderFromClient(order);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      {/* Hero Section */}
      <div className="relative rounded-3xl overflow-hidden p-6 sm:p-10 bg-gradient-to-br from-[#ecdccb] via-[#F7EBDD] to-[#e4cfbd] border border-[#D4AF37]/40 shadow-sm text-[#4B2E20]">
        <div className="max-w-3xl space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/80 border border-[#D4AF37]/40 text-[#4B2E20] text-xs font-semibold shadow-xs">
            <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
            <span>Catálogo Exclusivo • Keh Convites Digitais</span>
          </div>

          <h1 className="text-2xl sm:text-4xl font-serif font-bold text-[#4B2E20] leading-tight">
            Convites Digitais para Enviar no WhatsApp com Elegância & Praticidade
          </h1>

          <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-sans max-w-2xl">
            Escolha o modelo digital que mais combina com seu evento: desde cards práticos para disparar no WhatsApp até convites interativos com botões clicáveis de confirmação e localização.
          </p>
        </div>

        {/* Vantagens dos Convites Digitais */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5 mt-6 pt-5 border-t border-[#D4AF37]/25 text-xs">
          <div className="flex items-center gap-2 text-[#4B2E20] font-medium">
            <div className="w-5 h-5 rounded-full bg-[#D4AF37]/25 flex items-center justify-center shrink-0">
              <Check className="w-3 h-3 text-[#4B2E20]" />
            </div>
            <span>Envio ilimitado</span>
          </div>
          <div className="flex items-center gap-2 text-[#4B2E20] font-medium">
            <div className="w-5 h-5 rounded-full bg-[#D4AF37]/25 flex items-center justify-center shrink-0">
              <Check className="w-3 h-3 text-[#4B2E20]" />
            </div>
            <span>Botões clicáveis ou Card</span>
          </div>
          <div className="flex items-center gap-2 text-[#4B2E20] font-medium">
            <div className="w-5 h-5 rounded-full bg-[#D4AF37]/25 flex items-center justify-center shrink-0">
              <Check className="w-3 h-3 text-[#4B2E20]" />
            </div>
            <span>Entrega rápida</span>
          </div>
          <div className="flex items-center gap-2 text-[#4B2E20] font-medium">
            <div className="w-5 h-5 rounded-full bg-[#D4AF37]/25 flex items-center justify-center shrink-0">
              <Check className="w-3 h-3 text-[#4B2E20]" />
            </div>
            <span>Pagamento fácil no PIX</span>
          </div>
        </div>
      </div>

      {/* Barra de Filtros e Busca por Tipo de Convite Digital */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white/70 p-3 rounded-2xl border border-[#D4AF37]/30 shadow-xs">
        {/* Filtro por Formato do Convite Digital */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
          {FORMATOS_BOTOES.map((fmt) => {
            const Icon = fmt.icon;
            const isSelected = selectedFormat === fmt.id;
            return (
              <button
                key={fmt.id}
                onClick={() => setSelectedFormat(fmt.id)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                  isSelected
                    ? 'bg-[#4B2E20] text-[#F7EBDD] shadow-sm'
                    : 'bg-[#faf4ec] text-[#4B2E20]/80 hover:bg-[#ecdccb]/70 hover:text-[#4B2E20]'
                }`}
              >
                <Icon className={`w-3.5 h-3.5 ${isSelected ? 'text-[#D4AF37]' : 'text-[#4B2E20]/60'}`} />
                <span>{fmt.label}</span>
              </button>
            );
          })}
        </div>

        {/* Campo de Busca */}
        <div className="relative min-w-[200px] sm:w-64">
          <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-[#4B2E20]/50" />
          <input
            type="text"
            placeholder="Buscar modelo de convite..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full h-8 pl-8 pr-3 text-xs rounded-xl bg-white border border-[#D4AF37]/35 text-[#4B2E20] placeholder:text-[#4B2E20]/50 focus:outline-none focus:ring-1 focus:ring-[#D4AF37]"
          />
        </div>
      </div>

      {/* Lista de Modelos de Convites */}
      <div className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <div>
            <h2 className="text-lg font-serif font-bold text-[#4B2E20] flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-[#D4AF37]" />
              <span>Modelos de Convites Digitais</span>
            </h2>
            <p className="text-xs text-[#4B2E20]/70">
              Clique no modelo desejado para personalizar com seus dados e tema
            </p>
          </div>
          <span className="text-xs font-semibold text-[#4B2E20]/75 bg-[#ecdccb]/60 px-3 py-1 rounded-full border border-[#D4AF37]/30">
            {filteredTemplates.length} modelo(s) disponível(is)
          </span>
        </div>

        {filteredTemplates.length === 0 ? (
          <div className="text-center py-12 bg-white/60 rounded-3xl border border-[#D4AF37]/30 p-8 space-y-3">
            <Layers className="w-10 h-10 text-[#D4AF37] mx-auto opacity-70" />
            <p className="text-sm font-semibold text-[#4B2E20]">Nenhum modelo encontrado</p>
            <p className="text-xs text-[#4B2E20]/60">Tente ajustar a busca ou filtro.</p>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                setSelectedFormat('todos');
                setSearchQuery('');
              }}
              className="text-xs border-[#D4AF37]/40 text-[#4B2E20]"
            >
              Ver todos os modelos
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredTemplates.map((template) => {
              const temInteracao = Boolean(
                template.hasInteraction ||
                template.format === 'interativo_pdf' ||
                template.format === 'site_rsvp'
              );

              return (
                <Card
                  key={template.id}
                  className="group bg-white/90 border-[#D4AF37]/35 rounded-3xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col hover:-translate-y-1"
                >
                  {/* Foto / Vídeo de Capa do Modelo */}
                  <div className="relative aspect-[4/3] bg-[#ecdccb]/30 overflow-hidden cursor-pointer" onClick={() => handleSelectTemplateForOrder(template)}>
                    {template.videoUrl ? (
                      <video
                        src={template.videoUrl}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        muted
                        loop
                        playsInline
                        onMouseOver={(e) => (e.target as HTMLVideoElement).play().catch(() => {})}
                        onMouseOut={(e) => (e.target as HTMLVideoElement).pause()}
                      />
                    ) : (
                      <img
                        src={template.imageUrl}
                        alt={template.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      />
                    )}

                    {/* Selos no topo */}
                    <div className="absolute top-3 left-3 right-3 flex items-start justify-between gap-2 pointer-events-none">
                      {getFormatBadge(template)}

                      {template.isPromotion && (
                        <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-600 text-white shadow-sm">
                          PROMOÇÃO
                        </span>
                      )}
                    </div>

                    {/* Indicador de clique */}
                    <div className="absolute inset-0 bg-gradient-to-t from-[#4B2E20]/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-4">
                      <span className="text-white text-xs font-semibold flex items-center gap-1.5 drop-shadow">
                        <MousePointerClick className="w-3.5 h-3.5 text-[#D4AF37]" />
                        Clique para escolher este modelo
                      </span>
                    </div>
                  </div>

                  {/* Conteúdo do Card */}
                  <CardContent className="p-5 flex-1 flex flex-col justify-between space-y-4">
                    <div className="space-y-2">
                      <h3
                        onClick={() => handleSelectTemplateForOrder(template)}
                        className="font-serif font-bold text-base text-[#4B2E20] hover:text-[#855729] cursor-pointer transition-colors leading-snug"
                      >
                        {template.title}
                      </h3>

                      <p className="text-xs text-[#4B2E20]/75 line-clamp-2 leading-relaxed">
                        {template.description}
                      </p>

                      {/* Diferencial do formato */}
                      <div className="pt-1">
                        <span className="text-[11px] font-medium text-[#4B2E20]/90 bg-[#faf5ee] px-2.5 py-1 rounded-lg border border-[#D4AF37]/25 inline-flex items-center gap-1.5">
                          {temInteracao ? (
                            <>
                              <MousePointerClick className="w-3 h-3 text-[#D4AF37]" />
                              <span>Com botões clicáveis (RSVP, Mapa e Presentes)</span>
                            </>
                          ) : template.format === 'animado_video' ? (
                            <>
                              <Video className="w-3 h-3 text-[#D4AF37]" />
                              <span>Vídeo com música de fundo</span>
                            </>
                          ) : (
                            <>
                              <ImageIcon className="w-3 h-3 text-[#D4AF37]" />
                              <span>Convite simples para envio direto</span>
                            </>
                          )}
                        </span>
                      </div>
                    </div>

                    {/* Preço e Botão de Ação */}
                    <div className="pt-3 border-t border-[#D4AF37]/20 flex items-center justify-between gap-2">
                      <div>
                        {template.originalPrice && template.originalPrice > template.price && (
                          <span className="text-[11px] line-through text-[#4B2E20]/50 block">
                            R$ {template.originalPrice.toFixed(2)}
                          </span>
                        )}
                        <span className="text-lg font-serif font-black text-[#4B2E20]">
                          R$ {template.price.toFixed(2)}
                        </span>
                      </div>

                      {isAdmin ? (
                        <div className="flex items-center gap-1.5">
                          {onEditTemplate && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => onEditTemplate(template)}
                              className="text-xs rounded-xl border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ecdccb]"
                            >
                              <Edit className="w-3.5 h-3.5 mr-1 text-[#D4AF37]" />
                              Editar
                            </Button>
                          )}
                          {onDeleteTemplate && (
                            <button
                              onClick={() => onDeleteTemplate(template.id)}
                              title="Excluir Modelo"
                              className="p-2 rounded-xl text-rose-600 hover:bg-rose-50 border border-rose-200 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          )}
                        </div>
                      ) : (
                        <Button
                          size="sm"
                          onClick={() => handleSelectTemplateForOrder(template)}
                          className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-semibold text-xs rounded-xl border border-[#D4AF37]/40 shadow-xs flex items-center gap-1.5 px-3.5"
                        >
                          <span>Quero Este Modelo</span>
                          <Send className="w-3 h-3 text-[#D4AF37]" />
                        </Button>
                      )}
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      {/* SEÇÃO FINAL: ENSAIOS DIGITAIS OPCIONAIS (CONFORME PEDIDO) */}
      <section className="mt-14 pt-10 border-t border-[#D4AF37]/30 space-y-6">
        <div className="bg-gradient-to-r from-[#ecdccb]/60 via-[#F7EBDD] to-[#ecdccb]/60 p-6 sm:p-8 rounded-3xl border border-[#D4AF37]/35 shadow-xs">
          <div className="max-w-2xl space-y-2">
            <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-white/80 border border-[#D4AF37]/30 text-[#4B2E20] text-xs font-semibold">
              <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
              <span>Serviço Adicional Opcional</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-serif font-bold text-[#4B2E20]">
              Ensaios Digitais para Ilustrar seu Convite
            </h2>
            <p className="text-xs sm:text-sm text-[#4B2E20]/80 leading-relaxed font-sans">
              Você pode transformar uma foto do aniversariante ou do casal em um ensaio digital temático de altíssima qualidade para compor a capa do seu convite! Você pode incluir essa opção ao preencher os dados do seu modelo.
            </p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-6">
            {EXEMPLOS_ENSAIOS_CATALOGO.map((ensaio) => (
              <div
                key={ensaio.id}
                className="bg-white/95 border border-[#D4AF37]/30 rounded-2xl overflow-hidden shadow-xs hover:shadow-md transition-all flex flex-col"
              >
                <div className="relative aspect-[4/3] overflow-hidden">
                  <img
                    src={ensaio.foto}
                    alt={ensaio.titulo}
                    className="w-full h-full object-cover"
                  />
                  <span className="absolute bottom-2 right-2 bg-[#4B2E20]/85 text-[#F7EBDD] font-bold text-[11px] px-2.5 py-0.5 rounded-lg border border-[#D4AF37]/40">
                    {ensaio.valor}
                  </span>
                </div>
                <div className="p-3.5 flex-1 flex flex-col justify-between space-y-1.5">
                  <div>
                    <h3 className="font-serif font-bold text-xs text-[#4B2E20]">
                      {ensaio.titulo}
                    </h3>
                    <p className="text-[11px] text-[#4B2E20]/70 font-medium">
                      {ensaio.subtitulo}
                    </p>
                  </div>
                  <p className="text-[10px] text-[#4B2E20]/75 leading-relaxed pt-1">
                    {ensaio.descricao}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Modal de Pedido e Personalização para o Cliente */}
      {orderingClientTemplate && (
        <ClientOrderModal
          isOpen={Boolean(orderingClientTemplate)}
          template={orderingClientTemplate}
          onClose={() => setOrderingClientTemplate(null)}
          onSubmitOrder={handleOrderSubmitted}
        />
      )}
    </div>
  );
}

