import React, { useState, useRef } from 'react';
import { InvitationTemplate, Order } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  X,
  Sparkles,
  Calendar,
  Clock,
  MapPin,
  Heart,
  Gift,
  Upload,
  Phone,
  Camera,
  CheckCircle2,
  QrCode,
  Copy,
  ArrowRight,
  ShieldCheck,
  CheckCheck,
} from 'lucide-react';

interface ClientOrderModalProps {
  isOpen: boolean;
  template: InvitationTemplate | null;
  onClose: () => void;
  onSubmitOrder: (newOrder: Order) => void;
}

const EXEMPLOS_ENSAIOS_DIGITAIS = [
  {
    id: 'ensaio-1',
    titulo: 'Ensaio Infantil Temático',
    subtitulo: 'Safári, Bosque ou Circo',
    preco: 25,
  },
  {
    id: 'ensaio-2',
    titulo: 'Ensaio Princesa / Realeza',
    subtitulo: 'Vestido de Gala e Castelo',
    preco: 25,
  },
  {
    id: 'ensaio-3',
    titulo: 'Ensaio Casal Romântico',
    subtitulo: 'Pôr do Sol e Cenário Floral',
    preco: 29,
  },
  {
    id: 'ensaio-4',
    titulo: 'Ensaio 1º Aninho Digital',
    subtitulo: 'Smash Cake e Balões',
    preco: 25,
  },
];

const CHAVE_PIX_KEH = '32998040080';

export function ClientOrderModal({
  isOpen,
  template,
  onClose,
  onSubmitOrder,
}: ClientOrderModalProps) {
  if (!isOpen || !template) return null;

  const temInteracao = Boolean(
    template.hasInteraction ||
    template.format === 'interativo_pdf' ||
    template.format === 'site_rsvp'
  );

  const [etapa, setEtapa] = useState<'formulario' | 'pagamento_pix' | 'concluido'>('formulario');

  // Campos do formulário
  const [nomeAniversariante, setNomeAniversariante] = useState('');
  const [dataEvento, setDataEvento] = useState('');
  const [diaSemana, setDiaSemana] = useState('');
  const [horarioEvento, setHorarioEvento] = useState('');
  const [localEvento, setLocalEvento] = useState('');
  const [fraseEspecial, setFraseEspecial] = useState('');
  const [whatsappCliente, setWhatsappCliente] = useState('');

  // Campos para modelo com botões
  const [confirmacaoPresenca, setConfirmacaoPresenca] = useState('');
  const [linkLocalizacao, setLinkLocalizacao] = useState('');
  const [listaPresentes, setListaPresentes] = useState('');

  // Foto enviada pelo cliente
  const [fotoFile, setFotoFile] = useState<File | null>(null);
  const [fotoPreview, setFotoPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Ensaio Digital Opcional
  const [querEnsaioDigital, setQuerEnsaioDigital] = useState(false);
  const [ensaioEscolhido, setEnsaioEscolhido] = useState<string>(EXEMPLOS_ENSAIOS_DIGITAIS[0].titulo);

  // Cópia do PIX
  const [pixCopiado, setPixCopiado] = useState(false);

  const valorEnsaio = querEnsaioDigital ? 25 : 0;
  const valorTotalFinal = template.price + valorEnsaio;

  const handleFotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFotoFile(file);
      setFotoPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoverFoto = () => {
    setFotoFile(null);
    setFotoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCopiarPix = () => {
    navigator.clipboard.writeText(CHAVE_PIX_KEH);
    setPixCopiado(true);
    setTimeout(() => setPixCopiado(false), 3000);
  };

  const handleAvancarParaPix = (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeAniversariante.trim()) {
      alert('Por favor, informe o nome do anfitrião/homenageado.');
      return;
    }

    if (!whatsappCliente.trim()) {
      alert('Por favor, informe o seu número de WhatsApp.');
      return;
    }

    const notasFormatadas = [
      'Pedido via Catálogo Keh Convites',
      diaSemana ? `Dia: ${diaSemana}` : '',
      horarioEvento ? `Horário: ${horarioEvento}` : '',
      localEvento ? `Local: ${localEvento}` : '',
      fraseEspecial ? `Frase: "${fraseEspecial}"` : '',
      temInteracao
        ? `Interativo: RSVP (${confirmacaoPresenca || 'Sim'}) | Local (${linkLocalizacao || 'Sim'}) | Presentes (${listaPresentes || 'Sim'})`
        : 'Convite Simples',
      querEnsaioDigital ? `Ensaio Digital Incluso: Sim (${ensaioEscolhido})` : 'Sem Ensaio Digital',
      fotoFile ? `Foto Anexada: Sim (${fotoFile.name})` : 'Sem foto anexada',
      `PIX Keh Convites: R$ ${valorTotalFinal.toFixed(2)} (Chave: ${CHAVE_PIX_KEH})`,
    ]
      .filter(Boolean)
      .join(' | ');

    const novoPedido: Order = {
      id: `ped-${Date.now()}`,
      clientName: nomeAniversariante,
      clientWhatsapp: whatsappCliente,
      templateId: template.id,
      templateTitle: template.title,
      category: 'Convite Digital',
      digitalFormat: template.format,
      hasInteraction: temInteracao,
      rsvpContact: temInteracao ? confirmacaoPresenca : undefined,
      mapsLocation: temInteracao ? (linkLocalizacao || localEvento) : localEvento,
      giftList: temInteracao ? listaPresentes : undefined,
      totalValue: valorTotalFinal,
      paidValue: valorTotalFinal,
      eventDate: dataEvento || new Date().toISOString().split('T')[0],
      deadlineDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
      status: 'pendente',
      paymentStatus: 'pago',
      includeDigitalPhotoshoot: querEnsaioDigital,
      photoshootDetails: querEnsaioDigital ? ensaioEscolhido : undefined,
      photoUrl: fotoPreview || undefined,
      notes: notasFormatadas,
      createdAt: new Date().toISOString().split('T')[0],
    };

    onSubmitOrder(novoPedido);
    setEtapa('pagamento_pix');
  };

  const handleConcluirEFechar = () => {
    setEtapa('formulario');
    setPixCopiado(false);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-[#4B2E20]/70 backdrop-blur-sm animate-fade-in">
      <Card className="max-w-2xl w-full bg-[#fdfbf7] border-[#D4AF37]/50 shadow-2xl rounded-3xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Topo do Modal */}
        <CardHeader className="border-b border-[#D4AF37]/25 flex flex-row items-center justify-between pb-4 bg-gradient-to-r from-[#ecdccb]/80 to-[#f7ebdd]/80 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-[#4B2E20] border border-[#D4AF37]/50 flex items-center justify-center text-[#D4AF37] shadow-sm">
              {etapa === 'pagamento_pix' ? (
                <QrCode className="w-5 h-5" />
              ) : etapa === 'concluido' ? (
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
              ) : (
                <Sparkles className="w-5 h-5" />
              )}
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-serif font-bold text-[#4B2E20]">
                {etapa === 'pagamento_pix'
                  ? 'Pagamento via PIX'
                  : etapa === 'concluido'
                  ? 'Pedido Confirmado com Sucesso!'
                  : 'Personalize seu Convite Digital'}
              </CardTitle>
              <p className="text-xs text-[#4B2E20]/75 font-medium">
                {etapa === 'pagamento_pix'
                  ? 'Efetue o PIX para confirmação imediata'
                  : etapa === 'concluido'
                  ? 'Seu convite já entrou em produção na Keh Convites'
                  : `Modelo: ${template.title}`}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-xl hover:bg-[#ecdccb] text-[#4B2E20] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </CardHeader>

        {/* ETAPA 1: FORMULÁRIO DE DADOS */}
        {etapa === 'formulario' && (
          <CardContent className="overflow-y-auto p-5 sm:p-6 space-y-5 text-xs text-[#4B2E20]">
            <form onSubmit={handleAvancarParaPix} className="space-y-5">
              {/* Resumo do Convite */}
              <div className="flex items-center gap-3 p-3.5 rounded-2xl bg-[#ecdccb]/40 border border-[#D4AF37]/30">
                <img
                  src={template.imageUrl}
                  alt={template.title}
                  className="w-14 h-16 object-cover rounded-xl border border-[#D4AF37]/40 shadow-sm shrink-0"
                />
                <div className="flex-1">
                  <h4 className="font-serif font-bold text-sm text-[#4B2E20]">{template.title}</h4>
                  <p className="text-[11px] text-[#4B2E20]/75">
                    {temInteracao ? 'Convite Interativo com botões' : 'Convite Digital para WhatsApp'}
                  </p>
                  <span className="font-bold text-[#4B2E20] text-sm mt-0.5 block">
                    R$ {template.price.toFixed(2)}
                  </span>
                </div>
              </div>

              {/* Informações Principais */}
              <div className="space-y-3">
                <h4 className="font-bold text-[#4B2E20] text-xs uppercase tracking-wider flex items-center gap-1.5">
                  <Heart className="w-3.5 h-3.5 text-[#D4AF37]" />
                  <span>Informações do Convite</span>
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                      Nome no Convite *
                    </label>
                    <Input
                      required
                      placeholder="Ex: Beatriz Lima"
                      value={nomeAniversariante}
                      onChange={(e) => setNomeAniversariante(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                      Seu WhatsApp para Receber o Convite *
                    </label>
                    <Input
                      required
                      placeholder="Ex: (32) 99804-0080"
                      value={whatsappCliente}
                      onChange={(e) => setWhatsappCliente(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                      Data do Evento
                    </label>
                    <Input
                      type="date"
                      value={dataEvento}
                      onChange={(e) => setDataEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                      Dia da Semana
                    </label>
                    <Input
                      placeholder="Ex: Sábado"
                      value={diaSemana}
                      onChange={(e) => setDiaSemana(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                      Horário
                    </label>
                    <Input
                      placeholder="Ex: 19:30h"
                      value={horarioEvento}
                      onChange={(e) => setHorarioEvento(e.target.value)}
                      className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                    Local do Evento / Salão / Endereço
                  </label>
                  <Input
                    placeholder="Ex: Espaço Jardins, Rua das Flores, 120"
                    value={localEvento}
                    onChange={(e) => setLocalEvento(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-[#4B2E20] mb-1">
                    Frase de Efeito ou Versículo (Opcional)
                  </label>
                  <Input
                    placeholder="Ex: Venha comemorar esse dia tão especial conosco!"
                    value={fraseEspecial}
                    onChange={(e) => setFraseEspecial(e.target.value)}
                    className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl"
                  />
                </div>
              </div>

              {/* Botões Clicáveis (se interativo) */}
              {temInteracao && (
                <div className="p-4 rounded-2xl bg-amber-50/70 border border-[#D4AF37]/40 space-y-3">
                  <span className="font-bold text-[#4B2E20] flex items-center gap-1.5 text-xs">
                    <Sparkles className="w-3.5 h-3.5 text-[#D4AF37]" />
                    Botões Clicáveis do Convite Interativo
                  </span>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div>
                      <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                        WhatsApp Confirmação (RSVP)
                      </label>
                      <Input
                        placeholder="(32) 99804-0080"
                        value={confirmacaoPresenca}
                        onChange={(e) => setConfirmacaoPresenca(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                      />
                    </div>
                    <div>
                      <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                        Link do Google Maps
                      </label>
                      <Input
                        placeholder="Link ou nome do local"
                        value={linkLocalizacao}
                        onChange={(e) => setLinkLocalizacao(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                      />
                    </div>
                    <div>
                      <label className="block text-[11px] font-semibold text-[#4B2E20] mb-1">
                        Lista de Presentes (Link/Sugestão)
                      </label>
                      <Input
                        placeholder="Ex: P/M ou link da lista"
                        value={listaPresentes}
                        onChange={(e) => setListaPresentes(e.target.value)}
                        className="bg-white border-[#D4AF37]/40 text-[#4B2E20] rounded-xl text-xs"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* Anexar Foto do Celular */}
              <div className="p-3.5 rounded-2xl bg-white border border-[#D4AF37]/35 space-y-2">
                <span className="font-semibold text-xs text-[#4B2E20] flex items-center gap-1.5">
                  <Camera className="w-3.5 h-3.5 text-[#D4AF37]" />
                  Foto para o Convite (Opcional)
                </span>
                <input
                  type="file"
                  ref={fileInputRef}
                  accept="image/*"
                  onChange={handleFotoChange}
                  className="hidden"
                />
                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => fileInputRef.current?.click()}
                    className="text-xs border-[#D4AF37]/50 text-[#4B2E20] hover:bg-[#ecdccb]/40 rounded-xl"
                  >
                    <Upload className="w-3.5 h-3.5 mr-1 text-[#D4AF37]" />
                    {fotoFile ? 'Trocar Foto' : 'Enviar Foto'}
                  </Button>
                  {fotoFile && (
                    <button
                      type="button"
                      onClick={handleRemoverFoto}
                      className="text-xs text-rose-600 font-semibold underline"
                    >
                      Remover
                    </button>
                  )}
                </div>
              </div>

              {/* Ensaio Digital Opcional */}
              <div className="p-3.5 rounded-2xl bg-[#ecdccb]/30 border border-[#D4AF37]/40 space-y-2">
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-2 cursor-pointer font-bold text-xs text-[#4B2E20]">
                    <input
                      type="checkbox"
                      checked={querEnsaioDigital}
                      onChange={(e) => setQuerEnsaioDigital(e.target.checked)}
                      className="w-4 h-4 rounded text-[#4B2E20] accent-[#D4AF37]"
                    />
                    <span>Incluir Ensaio Digital Fotográfico (+ R$ 25,00)</span>
                  </label>
                  {querEnsaioDigital && (
                    <span className="text-[11px] font-bold text-[#4B2E20] bg-[#D4AF37]/30 px-2 py-0.5 rounded-md">
                      + R$ 25,00
                    </span>
                  )}
                </div>
              </div>

              {/* Totalizador e Botão de Avanço */}
              <div className="pt-2 flex items-center justify-between border-t border-[#D4AF37]/30">
                <div>
                  <span className="text-[11px] text-[#4B2E20]/70 block">Valor Total:</span>
                  <span className="text-xl font-serif font-black text-[#4B2E20]">
                    R$ {valorTotalFinal.toFixed(2)}
                  </span>
                </div>

                <Button
                  type="submit"
                  className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs px-6 py-2.5 rounded-2xl shadow-md border border-[#D4AF37]/50 flex items-center gap-2"
                >
                  <span>Ir para o Pagamento via PIX</span>
                  <ArrowRight className="w-4 h-4 text-[#D4AF37]" />
                </Button>
              </div>
            </form>
          </CardContent>
        )}

        {/* ETAPA 2: PAGAMENTO VIA PIX */}
        {etapa === 'pagamento_pix' && (
          <CardContent className="overflow-y-auto p-6 space-y-6 text-center text-[#4B2E20]">
            <div className="max-w-md mx-auto space-y-4">
              <div className="w-16 h-16 rounded-3xl bg-emerald-100 text-emerald-800 flex items-center justify-center mx-auto shadow-inner">
                <QrCode className="w-8 h-8" />
              </div>

              <div>
                <h3 className="font-serif font-bold text-xl text-[#4B2E20]">
                  Pagamento com Chave PIX
                </h3>
                <p className="text-xs text-[#4B2E20]/75 mt-1">
                  Transfira o valor de <strong>R$ {valorTotalFinal.toFixed(2)}</strong> para Keh Convites
                </p>
              </div>

              {/* Caixa com a Chave PIX */}
              <div className="p-4 bg-white rounded-2xl border-2 border-dashed border-[#D4AF37] space-y-2">
                <span className="text-[11px] font-semibold text-[#4B2E20]/70 uppercase tracking-wider block">
                  Chave PIX (Telefone)
                </span>
                <p className="text-lg font-mono font-bold text-[#4B2E20] select-all tracking-wider">
                  {CHAVE_PIX_KEH}
                </p>
                <Button
                  type="button"
                  onClick={handleCopiarPix}
                  className={`w-full text-xs font-bold rounded-xl transition-all ${
                    pixCopiado
                      ? 'bg-emerald-700 text-white'
                      : 'bg-[#4B2E20] text-[#F7EBDD] hover:bg-[#382015]'
                  }`}
                >
                  {pixCopiado ? (
                    <>
                      <CheckCheck className="w-4 h-4 mr-1.5" />
                      Chave PIX Copiada com Sucesso!
                    </>
                  ) : (
                    <>
                      <Copy className="w-4 h-4 mr-1.5 text-[#D4AF37]" />
                      Copiar Chave PIX
                    </>
                  )}
                </Button>
              </div>

              <div className="p-3 bg-amber-50 rounded-xl border border-amber-200 text-[11px] text-[#4B2E20]/80 text-left space-y-1">
                <p className="font-bold flex items-center gap-1 text-[#4B2E20]">
                  <ShieldCheck className="w-4 h-4 text-emerald-700" />
                  Como funciona após o pagamento:
                </p>
                <p>1. Seu pedido já foi registrado na área administrativa.</p>
                <p>2. Assim que o PIX for verificado, enviaremos a prévia do convite diretamente no seu WhatsApp ({whatsappCliente}).</p>
              </div>

              <Button
                onClick={() => setEtapa('concluido')}
                className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs py-3 rounded-2xl shadow-md"
              >
                Já realizei o pagamento via PIX
              </Button>
            </div>
          </CardContent>
        )}

        {/* ETAPA 3: CONCLUÍDO */}
        {etapa === 'concluido' && (
          <CardContent className="p-8 text-center space-y-5 text-[#4B2E20]">
            <div className="w-20 h-20 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto shadow-md">
              <CheckCircle2 className="w-10 h-10" />
            </div>

            <div className="space-y-2">
              <h3 className="font-serif font-black text-2xl text-[#4B2E20]">
                Pedido Realizado com Sucesso!
              </h3>
              <p className="text-xs text-[#4B2E20]/80 max-w-sm mx-auto leading-relaxed">
                Obrigado por escolher a <strong>Keh Convites</strong>! Seu pedido já está registrado e em breve entraremos em contato pelo WhatsApp cadastrado.
              </p>
            </div>

            <Button
              onClick={handleConcluirEFechar}
              className="bg-[#4B2E20] hover:bg-[#382015] text-[#F7EBDD] font-bold text-xs px-8 py-3 rounded-2xl shadow-lg border border-[#D4AF37]/50"
            >
              Concluir e Voltar ao Início
            </Button>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

